t.guides["forever/alliance/02-westfall"] = (function() return {
		["Back to {area:108}"] = "{area:108}(으)로 돌아가기",
		["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon."] = "데피아즈단 정찰병과 데피아즈단 복면강도가 {area:20}을(를) 돌아다니고, 데피아즈단 노상강도(17레벨)가 남쪽과 동쪽 언덕을 둘씩 순찰합니다. 떼어서 상대하십시오. 대장간 안의 {area:1581} 입구는 파티 던전입니다.",
		["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}."] = "데피아즈단 강탈자와 데피아즈단 약탈자가 해안 도로와 {area:20} 사이, {area:108} 서쪽 농장들을 차지하고 있습니다.",
		["Fill the vial at the farm's well"] = "농장 우물에서 약병 채우기",
		["Fill the vial at the well"] = "우물에서 약병 채우기",
		["Fly or ride to {zone:1453}. Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the Park (Druids). {npc:11026} works in the {object:28027}, {npc:279} in the {object:2096}."] = "{zone:1453}(으)로 날아가거나 말을 타고 가세요. 상급자: {object:2100}(전사, 도적), 대성당(성기사, 사제), {object:2101}(마법사, 흑마법사), 공원(드루이드). {npc:11026}은(는) {object:28027}에서, {npc:279}은(는) {object:2096}에서 일합니다.",
		["Fly or ride to {zone:1453}. {npc:376} is in the Cathedral of Light."] = "{zone:1453}(으)로 비행하거나 이동하십시오. {npc:376}은(는) 빛의 대성당에 있습니다.",
		["Fly or ride to {zone:1453}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "{zone:1453}(으)로 비행하거나 이동하십시오. {npc:5480}은(는) {object:2100}에서 전사를 가르치며, {npc:6089}와(과) {npc:6090}은(는) 그곳 {object:2152} 옆에 함께 있습니다. {npc:6090}이(가) 자기 잔을 걸고 결투를 합니다.",
		["Follow the road north. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west."] = "길을 따라 북쪽으로 가십시오. {npc:233}은(는) 밖에, {npc:235}은(는) 집 안에, {npc:253395}은(는) 서쪽 헛간에 있습니다.",
		["For {npc:11026} in {zone:1453}'s {object:28027}"] = "{zone:1453} {object:28027}의 {npc:11026}에게",
		["For {npc:266} in {area:69}, Redridge"] = "붉은마루 산맥 {area:69}의 {npc:266}에게",
		["Further north along the road. The Furlbrows sit by their burned farm. Collect the oats from the Sacks of Oats in the fields as you go and fill the vial at the stead's well."] = "길을 따라 더 북쪽으로 가십시오. 펄브로우 부부가 불탄 농장 옆에 앉아 있습니다. 가는 길에 밭의 귀리 부대에서 귀리를 모으고, 농장 우물에서 약병을 채우십시오.",
		["Gnoll Paws"] = "놀의 앞발",
		["Harvest Watchers"] = "허수아비골렘 보초",
		["Hearthstone on cooldown? Follow the road north-east."] = "귀환석이 재사용 대기 중이라면 북동쪽 길을 따라가십시오.",
		["Kobold Diggers"] = "코볼트 채굴꾼",
		["Level 12, 14 and 16 spells"] = "12, 14, 16레벨 주문",
		["Longshore Murloc Gills"] = "기나긴 해안 멀록 아가미",
		["Murloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time."] = "멀록 길잡이와 멀록 약탈꾼이 광산 북쪽 해변에 늘어서 있습니다. 생명력이 낮으면 도망치니 하나씩 끌어오십시오.",
		["North of Molsen Farm. Defias Trappers and Smugglers camp outside the mine, Kobold Diggers work inside. {object:290} stands by the ruined house east of the mine."] = "몰센 농장 북쪽입니다. 데피아즈단 덫사냥꾼과 데피아즈단 밀수업자가 광산 밖에 진을 치고, 코볼트 채굴꾼이 안에서 일합니다. {object:290}은(는) 광산 동쪽의 폐가 옆에 있습니다.",
		["Only if he takes the isosprings alone"] = "그가 골렘 등가용수철만 받을 때만",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "엘윈 숲에서 {item:1972}을(를) 획득한 경우에만: 오른쪽 클릭하십시오",
		["Ride to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "{zone:1453}(으)로 가십시오. 주술사 상급자가 없으니 {object:28027}에서 {area:2257}을(를) 타고 {zone:1455}(으)로 가서 {npc:258098}에게 수련한 뒤, 전차를 타고 돌아와 배를 타십시오.",
		["Riverpaw Gnolls and Scouts roam the hills between the coast and the {area:916}."] = "갈퀴발 놀과 갈퀴발일족 정찰병이 해안과 {area:916} 사이 언덕을 돌아다닙니다.",
		["Riverpaw Miners"] = "갈퀴발일족 광부",
		["Sacks of Oats"] = "귀리 부대",
		["Shaman training"] = "주술사 수련",
		["The gnoll hills"] = "놀 언덕",
		["The north coast"] = "북쪽 해안",
		["The western farms"] = "서쪽 농장들",
		["The {area:113}"] = "{area:113}",
		["West of Molsen Farm, toward the coast. Riverpaw Miners work the quarry."] = "몰센 농장 서쪽, 해안 방향입니다. 갈퀴발일족 광부가 채석장에서 일합니다.",
		["West of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone. Keep killing Goretusks and Fleshrippers on every leg of this loop."] = "살딘 농장 서쪽입니다. 허수아비골렘 보초와 허수아비골렘이 밭에서 일하며, 골렘 등가용수철, 허수아비골렘 회전안정기, {item:732}, 가끔 {item:255155}을(를) 떨어뜨립니다. 20레벨 희귀 몹 {npc:573}이(가) 이곳을 돌아다니니 건드리지 마십시오. 이 경로의 모든 구간에서 뿔엄니멧돼지와 식인독수리를 계속 처치하십시오.",
		["Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way back."] = "새끼 뿔엄니멧돼지와 식인독수리가 농장 주변 밭을 돌아다닙니다. 돌아가는 길에 간과 스튜용 고기를 모으기 시작하십시오.",
		["{area:20} and the Defias hills"] = "{area:20}와(과) 데피아즈단 언덕",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{zone:1439}의 약재 모으기(6123)에 필요한 {item:2449}: {npc:1313}, 연금술 용품. 약초채집가는 대신 그곳에서 채집하세요",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}, {area:20} 주변 상자에서",
		["{item:6529}, from {npc:5494}"] = "{item:6529}, {npc:5494}에게서",
		["{item:729}: Fleshrippers"] = "{item:729}: 식인독수리",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} and {npc:253092} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234}와(과) {npc:821}은(는) 돌탑 꼭대기에 있습니다. {npc:491}은(는) 탑 안에, {npc:878}와(과) {npc:253092}은(는) 언덕 남쪽의 여관과 그리폰 조련사 {npc:523} 옆에 있습니다.",
		["{npc:523}; skip the free flight it offers"] = "{npc:523}; 제공되는 무료 비행은 건너뛰십시오",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494}은(는) {object:2096} 바로 서쪽 운하를 따라 낚시 용품을 판매합니다. {npc:267118}은(는) 배로 가는 길의 항구에서 낚시를 합니다.",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}, 마법사의 성소: {quest:1861}",
		["{quest:153}: every Defias drops them"] = "{quest:153}: 모든 데피아즈단이 떨어뜨립니다",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["At the {area:2362}"] = "{area:2362}에서",
		["Back north-east into the mountains to the crystal."] = "북동쪽 산으로 돌아가 수정에게 가십시오.",
		["Back south"] = "다시 남쪽으로",
		["Back to {npc:11802}"] = "{npc:11802}에게 돌아가기",
		["Back to {npc:11802} in {area:2361}, then fly to {area:702} (by way of {area:442})."] = "{area:2361}의 {npc:11802}에게 돌아간 다음, ({area:442}을(를) 거쳐) {area:702}(으)로 날아가십시오.",
		["Bears and the Blackwood camp"] = "곰과 검은나무일족 야영지",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "검은나무일족 길잡이와 검은나무일족 풍수사가 {area:442} 남동쪽 야영지를 지키고 있습니다.",
		["Blackwood furbolgs"] = "검은나무일족 펄볼그",
		["Boat to {zone:1453}"] = "배를 타고 {zone:1453}(으)로 가십시오",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. Then fly back to {area:442} from {area:2361}."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있습니다. {item:15877}은(는) {area:2361} 아래 {area:656} 바닥의 용기 속에 있습니다. 하나를 북서쪽의 {area:2362}(으)로 가져가 그곳에서 사용하고 {npc:11799}와(과) 대화하세요. 그런 다음 {area:2361}에서 {area:442}(으)로 날아 돌아오세요.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; learn the flight path there if you do not have it."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있습니다. 비행 경로가 없다면 그곳에서 배우세요.",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "{area:447} 동쪽의 산을 오르십시오. {object:175524}은(는) 바위 턱 위에 있습니다.",
		["Crawler Legs"] = "집게다리",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "그녀를 글레이브 밖으로 호위하십시오. 제출은 {zone:1440}의 테리실에게 합니다",
		["Fill the tube at the moonwell in the village"] = "마을의 달샘에서 시험관을 채우십시오",
		["Fine Moonstalker Pelts"] = "고급 달표범 모피",
		["Fly from {area:442} to {area:702} and take the portal up to {npc:4217} in the {area:1658}."] = "{area:442}에서 {area:702}(으)로 날아간 다음, 차원문을 타고 {area:1658}의 {npc:4217}에게 올라가십시오.",
		["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them."] = "해안을 따라 북동쪽의 {area:443}(으)로 가십시오. {quest:951}은(는) 폐허 곳곳에 있고, 폭풍비늘일족 미르미돈, 폭풍비늘일족 여마법사, 폭풍비늘일족 전사가 지키고 있습니다.",
		["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}."] = "해안을 따라 {area:447}을(를) 지나 남쪽으로 가십시오. {quest:4728} 하나는 고대정령의 숲 서쪽 해안에, 또 하나는 더 남쪽 {area:450} 근처에 있습니다.",
		["Follow the hills north to the {area:456} and up to the falls. Three more beached remains lie on the north shore: near the {area:443}, north of {quest:954} and west of {quest:954}."] = "언덕을 따라 북쪽의 {area:456}까지 간 다음 폭포로 올라가십시오. 북쪽 해안에 떠밀려 온 사체가 세 개 더 있습니다: {area:443} 근처, {quest:954} 북쪽, {quest:954} 서쪽.",
		["Follow the road north."] = "길을 따라 북쪽으로 가십시오.",
		["Follow the road south. {quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "길을 따라 남쪽으로 가십시오. {quest:948}은(는) 고대정령의 숲에 있는 고대정령입니다. {npc:270269}와(과) {npc:11218}이(가) 그 곁에서 잠들어 있습니다.",
		["Grell Earrings"] = "그렐족 귀걸이",
		["Grizzled Scalps"] = "불곰 가죽",
		["Hearth to {area:442}"] = "귀환석으로 {area:442}에 가십시오",
		["Hearthstone on cooldown? Follow the coast road back south."] = "귀환석이 재사용 대기 중이라면 해안 길을 따라 남쪽으로 돌아가십시오.",
		["Highborne Relics"] = "명가의 유물",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "{area:442} 동쪽 언덕에서 광포한 엉겅퀴곰을 처치한 다음, 그 남동쪽의 펄볼그 야영지로 걸어가십시오. 아직 처치할 것은 없습니다.",
		["Moonstalker Fangs"] = "달표범 송곳니",
		["Moonstalker Sires prowl the woods around the glaive. The {object:10076} and the {object:12666} sit at the bottom of the crater; {npc:3584} stands on its north side."] = "덩치큰 달표범이 글레이브 주변 숲을 배회합니다. {object:10076}와(과) {object:12666}은(는) 구덩이 바닥에 있고, {npc:3584}은(는) 구덩이 북쪽에 서 있습니다.",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower; Grizzled Thistle Bears roam around it."] = "달표범이 {quest:954}와(과) 탑 사이의 언덕을 배회합니다. {quest:1002}은(는) 탑 서쪽 언덕에 서 있고, 그 주변을 엉겅퀴불곰이 돌아다닙니다.",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "나이트 엘프는 {area:442}에서 {area:702}(으)로 날아가십시오. 스카이본은 {area:442} 부두에서 배를 타고 가서 그곳의 루테란 비행 경로를 익히십시오. 차원문을 타고 {area:1658}의 {npc:4217}에게 올라가십시오.",
		["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins."] = "언덕을 따라 북쪽으로 가십시오. {npc:3650}은(는) {quest:954} 폐허에서 기다립니다. 폐허에는 광기어린 그렐과 비열한 마귀가 가득하고, 동쪽 끝에는 데스릴 사티로스가 있습니다. {quest:1001}은(는) 폐허 서쪽 길가에 서 있습니다.",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "신도나 암살단원이 {item:5352}을(를) 떨어뜨렸을 때만: 오른쪽 클릭하십시오",
		["Plagued bears"] = "병든 곰",
		["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "광포한 엉겅퀴곰이 {area:442} 바로 동쪽 언덕을 돌아다닙니다. 한 마리에게 {quest:2139}을(를) 사용하고 그에게 데려가십시오.",
		["Read both tablets"] = "두 석판을 모두 읽으십시오",
		["Scaber Stalks"] = "껄껄이그물버섯",
		["She gives you the {item:15826}"] = "그녀가 {item:15826}을(를) 줍니다",
		["Take the portal up to {npc:4217}, then fly back to {area:442} for the boat to {zone:1453}."] = "차원문을 타고 {npc:4217}에게 올라간 다음, {area:442}(으)로 날아가 {zone:1453}행 배를 타십시오.",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "달버섯은 {area:442} 바로 동쪽 언덕의 달빛야수 동굴에서 자랍니다. 그곳의 달빛야수는 성미가 사납습니다. {item:2449}에는 {skill:182}이(가) 필요합니다: 약초 채집가는 {zone:1439} 곳곳에서 캘 수 있고, 그 외에는 {zone:1453}({npc:1313})이나 경매장에서 구해 오십시오.",
		["The WANTED poster"] = "현상수배 포스터",
		["The WANTED poster outside the inn"] = "여관 밖의 현상수배 포스터",
		["The bay wrecks"] = "만의 난파선",
		["The beach"] = "해변",
		["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "배는 마을 서쪽에 정박합니다. 비행 조련사는 여관 남쪽 언덕에 있고, 퀘스트 제공자들은 큰길을 따라 흩어져 있습니다.",
		["The cave and the {npc:6788}"] = "동굴과 {npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls; {object:177624} lies at the satyr camp north of her."] = "동굴은 폭포 남쪽에 있습니다. {item:5271}은(는) 동굴 곳곳에 자라고, {item:5270}은(는) 맨 안쪽에 있습니다. {npc:6788}은(는) 폭포 남쪽 언덕에 둥지를 틀고 있고, {object:177624}은(는) 그 북쪽 사티로스 야영지에 놓여 있습니다.",
		["The flame burns in the south of {area:447}."] = "불꽃은 {area:447} 남쪽에서 타오르고 있습니다.",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "반쪽 펜던트는 {zone:1439}와(과) {zone:1436}에 있습니다: 경로 후반에",
		["The naga"] = "나가",
		["The red crystal"] = "붉은 수정",
		["The relics of the Barrow Dens"] = "지하굴의 유물",
		["The skeletal turtle"] = "거북 해골",
		["The southern beaches"] = "남쪽 해변",
		["The {area:443}"] = "{area:443}",
		["The {area:448}"] = "{area:448}",
		["The {object:10076}"] = "{object:10076}",
		["The {object:12666}"] = "{object:12666}",
		["The {object:16393}"] = "{object:16393}",
		["Thresher Eyes"] = "트레샤돈의 눈",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "왕바닷게는 마을 아래 해안을 따라 기어다니고, {quest:983}은(는) 부두 바로 남쪽 해변에 서 있습니다. 어둠의해안 트레샤돈은 얕은 물에서 헤엄칩니다. {object:175207}은(는) 마을 바로 남쪽 해안에 놓여 있습니다.",
		["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore."] = "{area:442} 북쪽 만의 바다 밑에 난파선 두 척이 있고, 각각 금고가 하나씩 있습니다. 이 해안에는 모래톱게와 등껍질 왕바닷게가 늘어서 있습니다.",
		["{area:450} lies on the coast south of {npc:10323}'s beach. Protect the prospector while he searches for the fossil."] = "{area:450}은(는) {npc:10323}의 해변 남쪽 해안에 있습니다. 탐사가가 화석을 찾는 동안 그를 보호하십시오.",
		["{item:12238}: fish from the pier"] = "{item:12238}: 부두에서 낚시",
		["{item:12289}, on the beach west of the docks"] = "{item:12289}, 부두 서쪽 해변",
		["{item:12349}, at the waterfall"] = "{item:12349}, 폭포에서",
		["{item:12355}, in {object:177624}"] = "{item:12355}, {object:177624} 안에",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}: 폭포 옆 동굴 입구에서",
		["{item:15851} and {item:2449}"] = "{item:15851}와(과) {item:2449}",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, 호수 안의 {object:177785}에서",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}: 폐허 서쪽, 북쪽 해안 앞바다 물속의 {object:177792}",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}: 황혼의망치단 신도와 황혼의망치단 암살단원",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: 데스릴 사티로스",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}: 암흑이교도 광신자",
		["{npc:10216}, on the pier: only with {skill:356}"] = "{npc:10216}, 부두 위: {skill:356} 기술이 있을 때만",
		["{npc:10323} camps on the beach west of the glaive: kill the murlocs at the camp fire; he comes in the third wave with his hound. Three beached remains lie on the beaches south of {area:450}."] = "{npc:10323}은(는) 글레이브 서쪽 해변에 진을 칩니다. 모닥불 옆의 멀록을 처치하면 세 번째 무리에서 사냥개와 함께 나타납니다. {area:450} 남쪽 해변에 떠밀려 온 사체가 세 개 있습니다.",
		["{npc:10323}'s beach"] = "{npc:10323}의 해변",
		["{npc:11218}: his escort to {area:413} is done on the {zone:1440} leg"] = "{npc:11218}: {area:413}까지의 호위는 {zone:1440} 구간에서 합니다",
		["{npc:11802}: the welcome from Sheldras"] = "{npc:11802}: 셸드라스 문트리의 환영 인사",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}: {item:15826}을(를) 사용하십시오. {zone:1439} 전역을 돌아다닙니다",
		["{npc:3616}, at the Grove"] = "{npc:3616}, 고대정령의 숲에서",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639}은(는) 폐허 북쪽 끝에 서 있습니다. 저주받은 명가의 원혼, 고뇌하는 명가의 원혼, {npc:2178}이(가) 폐허를 떠돕니다. {npc:3667}의 유령이 그 사이를 거닐고, 올빼미 {npc:270196}이(가) 폐허 동쪽을 맴돕니다. 두 석판은 폐허 안에 있고, {quest:4722}은(는) 폐허 서쪽 해안에 있습니다.",
		["{npc:3644}, on the pier"] = "{npc:3644}, 부두 위",
		["{npc:3649}, north end of the village"] = "{npc:3649}, 마을 북쪽 끝",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}: {zone:1453}의 {npc:1646}에게",
		["{npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}."] = "{npc:3661}은(는) 탑 아래 암흑이교도 광신자들 사이에 숨어 있습니다. 그의 편지는 {zone:1440}의 수호자 델그렌에게 줄 수 있게 간직하십시오.",
		["{npc:3666}, by the inn"] = "{npc:3666}, 여관 옆",
		["{npc:3692} hides in the hills east of the {area:449}. Help him back to the road; he fights on his way out."] = "{npc:3692}은(는) {area:449} 동쪽 언덕에 숨어 있습니다. 그가 길로 돌아가도록 도우십시오. 나가는 길에 그도 싸웁니다.",
		["{npc:3694}: for {npc:3691} in {area:415}, on the later {zone:1440} leg"] = "{npc:3694}: 나중의 {zone:1440} 구간에서 {area:415}의 {npc:3691}에게",
		["{npc:6667} hides on the little island off the ruins; Stormscale Beastmistresses walk the shore. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667}은(는) 폐허 앞바다의 작은 섬에 숨어 있고, 폭풍비늘 야수조련사가 해안을 거닙니다. 열쇠 조각은 거대한 숲타조(윗부분), 잿빛안개멀록(가운데), 사나운 모래톱게(아랫부분)에게서 떨어집니다.",
		["{quest:1003} stands west of the Grove."] = "{quest:1003}은(는) 고대정령의 숲 서쪽에 서 있습니다.",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}: {area:445}에서 채집기를 채우십시오",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394}(나이트 엘프)와(과) {npc:272054}(스카이본)이(가) {area:493} 남쪽에서 기다립니다. 세 유물은 그 동쪽의 {area:2363}에 있습니다. 첫 몇 주의 제보에 따르면 다른 플레이어가 유물을 획득하는 중에는 아무것도 나오지 않습니다: 잠시 기다렸다가 다시 시도하십시오.",
} end)()
t.guides["forever/alliance/04-redridge-mountains"] = (function() return {
		["Back to {area:69}"] = "{area:69}(으)로 돌아가기",
		["Cross the long bridge north into town. {npc:341} and {npc:382} stand at the north end of the bridge, {npc:900} in the town hall, {npc:381} and {npc:266} on the docks, {npc:343} at the inn, {npc:342} in her garden at the west end."] = "긴 다리를 건너 북쪽 마을로 들어가세요. {npc:341}와(과) {npc:382}은(는) 다리 북쪽 끝에, {npc:900}은(는) 마을 회관에, {npc:381}와(과) {npc:266}은(는) 부두에, {npc:343}은(는) 여관에, {npc:342}은(는) 서쪽 끝 자기 정원에 있습니다.",
		["East past the mill and across the river. Shadowhide gnolls fill the valley; {npc:703} (26, well above you) leads them at its north end: clear his escort first and fight him at full health. Stay out of {area:2099} to the south: its orcs are elite."] = "방앗간을 지나 동쪽으로 강을 건너세요. 계곡에는 잿빛가죽 놀이 가득합니다. {npc:703}(26레벨, 당신보다 훨씬 높음)이 계곡 북쪽 끝에서 그들을 이끕니다. 호위병을 먼저 처치하고 생명력이 가득 찬 상태로 싸우세요. 남쪽의 {area:2099}에는 들어가지 마세요. 그곳의 오크는 정예입니다.",
		["Fly to {area:108} and ride north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then ride east along the road through Elwynn to Redridge."] = "{area:108}(으)로 날아가 북서쪽 해안으로 가세요. {object:177790}은(는) 해안 앞바다의 바닥에 있습니다. 그런 다음 길을 따라 동쪽으로 엘윈 숲을 지나 붉은마루 산맥으로 가세요.",
		["Follow the road along the south shore of {area:68} to the gryphon master. {npc:1070} and {npc:903} stand by the road next to her."] = "{area:68}의 남쪽 기슭을 따라 길을 가면 그리폰 조련사가 있습니다. {npc:1070}와(과) {npc:903}은(는) 그녀 옆 길가에 서 있습니다.",
		["For {npc:3649}, on the return to {area:442} (06-ashenvale)"] = "{npc:3649}에게, {area:442}로 돌아갈 때 (06-ashenvale)",
		["Gnolls toward {area:1002}"] = "{area:1002} 쪽의 놀",
		["Greater Tarantulas crawl on the slopes around the mill north-east of the lake; Blackrock Renegades hold the mill itself."] = "거대한 타란툴라는 호수 북동쪽 방앗간 주변 비탈을 기어다니고, 검은바위부족 보초병은 방앗간 자체를 차지하고 있습니다.",
		["Head north out of {area:69} up the {area:95} to {area:997}. Blackrock Champions camp in the valley."] = "{area:69}에서 북쪽으로 나가 {area:95}을(를) 올라 {area:997}(으)로 가세요. 검은바위부족 용사가 계곡에 진을 치고 있습니다.",
		["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "키샨은 계곡 맨 북쪽 끝, {zone:1428} 경계 근처에 숨어 있습니다. 그를 호위하여 {area:69}까지 내려가세요. 가는 길에 검은바위부족 오크가 습격합니다.",
		["Lake murlocs"] = "호수 멀록",
		["Level 18 and 20 spells"] = "18레벨과 20레벨 주문",
		["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin."] = "멀록 청소부와 파도술사는 다리 동쪽 남쪽 기슭에 늘어서 있습니다. 누구든 {item:1467}이나 지느러미를 지니고 있을 수 있습니다.",
		["Redridge Mongrels and other gnolls hold the hills east of {area:1002}, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Dire Condors and Great Goretusks roam the same hills."] = "붉은마루일족 싸움꾼과 다른 놀들은 {area:1002} 동쪽, 길 북쪽의 언덕을 차지하고 있습니다. 붉은마루일족 약탈자가 그 사이를 배회하고, 밀렵꾼은 길 남쪽에 진을 치고 있습니다. 광포한 대머리수리와 큰 뿔엄니멧돼지도 같은 언덕을 돌아다닙니다.",
		["Shaman training"] = "주술사 훈련",
		["Swim east from the bridge into {area:68}; the chest lies on the lake bed."] = "다리에서 동쪽으로 헤엄쳐 {area:68}(으)로 가세요. 상자는 호수 바닥에 있습니다.",
		["The Wanted poster by the inn: {npc:703}, in {area:1000}"] = "여관 옆 현상수배 게시판: {npc:703}, {area:1000}에 있음",
		["The road from Elwynn enters Redridge at {area:1002}. {npc:464} stands where the roads to Redridge and {zone:1431} meet."] = "엘윈 숲에서 오는 길은 {area:1002}에서 붉은마루 산맥으로 들어갑니다. {npc:464}은(는) 붉은마루 산맥과 {zone:1431}(으)로 가는 길이 만나는 곳에 서 있습니다.",
		["The {area:442} boat docks at {area:17203}. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {zone:1429}."] = "{area:442}행 배는 {area:17203}에 정박합니다. 도시로 올라가 훈련을 받고 {npc:1646}을(를) 만난 뒤, 정문으로 나가 길을 따라 동쪽으로 {zone:1429}을(를) 지나가세요.",
		["{item:1075}: any Shadowhide gnoll"] = "{item:1075}: 아무 잿빛가죽 놀",
		["{item:15882}: the {object:177790}"] = "{item:15882}: {object:177790}",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}: 붉은마루일족 약탈자",
		["{item:3014}: any Blackrock orc"] = "{item:3014}: 아무 검은바위부족 오크",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}: {area:442}에서 온 툰드리스의 편지",
		["{npc:266}, by the docks"] = "{npc:266}, 부두 옆",
		["{npc:332} is at SI:7 in {object:2100}, {npc:6122} in the {object:2164}'s cellar in the {object:2101}, {npc:376} in the Cathedral of Light."] = "{npc:332}은(는) {object:2100}의 SI:7에, {npc:6122}은(는) {object:2101}에 있는 {object:2164}의 지하실에, {npc:376}은(는) 빛의 대성당에 있습니다.",
		["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}"] = "{npc:332}: {zone:1436}의 {npc:7024}에게 제출합니다. {zone:1431} 진행 막바지에",
		["{npc:344}, in the town hall"] = "{npc:344}, 마을 회관 안",
		["{npc:345} (level 24) roots around the pen just west of {area:69}. Pull him away from the other boars and fight at full health."] = "{npc:345}(24레벨)는 {area:69} 바로 서쪽 우리에서 땅을 파헤칩니다. 다른 멧돼지들과 떨어뜨려 끌어온 뒤 생명력이 가득 찬 상태로 싸우세요.",
		["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}: {zone:1457}의 {npc:11401}에게 제출합니다. 나중에",
		["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}: {zone:1455}의 {npc:11406}에게 제출합니다. 나중에",
		["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}: {zone:1455}의 {npc:258785}에게 제출합니다. 나중에",
		["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}: {zone:1413}의 {npc:6244}에게 제출합니다. 나중에",
		["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}, 다리 남쪽 그리폰 옆",
		["{zone:1431} is next: follow the road west to {area:1002}, then south to {area:42}."] = "다음은 {zone:1431}입니다. 길을 따라 서쪽으로 {area:1002}까지 간 뒤, 남쪽으로 {area:42}까지 가세요.",
		["{zone:1453} class quests"] = "{zone:1453} 직업 퀘스트",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453}에는 주술사 상급자가 없습니다. {object:28027}에서 {area:2257}을(를) 타고 {zone:1455}(으)로 가서 {npc:258098}에게 훈련을 받은 뒤, 지하철을 타고 돌아오세요.",
} end)()
t.guides["forever/alliance/05-duskwood"] = (function() return {
		["/lay down beside {npc:7207}"] = "{npc:7207} 옆에서 /lay down",
		["Back to {area:42}"] = "{area:42}(으)로 돌아가기",
		["Continue west to {area:94}. The {object:673515} glows by the ruined house south of the road."] = "서쪽 {area:94}(으)로 계속 가십시오. {object:673515}은(는) 길 남쪽 무너진 집 옆에서 빛나고 있습니다.",
		["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters."] = "{area:492} 북쪽 절반의 모든 구울이 해골을 떨어뜨릴 수 있습니다: 굶주린 시체, 뼈만남은 시체, 역병걸린 시체, 걸신들린 시체.",
		["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "묘지를 지나 길을 따라 북서쪽으로, 숲 서쪽 끝의 {npc:311}의 야영지까지 가십시오. {npc:893}은(는) {npc:311} 옆에 서 있습니다.",
		["Follow the road south from {area:1002} into {zone:1431}; {area:42} lies on the east side of the forest."] = "{area:1002}에서 길을 따라 남쪽 {zone:1431}(으)로 가십시오. {area:42}은(는) 숲 동쪽에 있습니다.",
		["Ghoul Ribs"] = "구울 해골",
		["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "그녀의 집은 {area:42} 남동쪽 언덕 위, {area:121} 위쪽에 있습니다.",
		["Level 22 and 24 spells"] = "레벨 22, 24 주문",
		["Next: {zone:1453} for training, then the boat from {area:17203} to {area:442} for {zone:1440}."] = "다음: 수련을 위해 {zone:1453}(으)로 간 뒤, {area:17203}에서 배를 타고 {area:442}(으)로 가서 {zone:1440}(으)로 향합니다.",
		["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang."] = "광포한 그늘숲늑대는 묘지와 {npc:289} 주변 숲을, 굶주린 그늘숲늑대는 그의 북동쪽 언덕을 돌아다닙니다. 새끼 그물독거미는 묘지 동쪽을 기어다니며 독을 떨어뜨립니다. 묘지 북쪽 절반의 모든 구울이 송곳니를 떨어뜨릴 수 있습니다.",
		["Ride back east along the road to the {area:245}."] = "길을 따라 동쪽 {area:245}(으)로 돌아가십시오.",
		["Ride back east to {area:42}."] = "동쪽 {area:42}(으)로 돌아가십시오.",
		["Ride north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "엘윈 숲을 지나 북쪽 {zone:1453}(으)로 달려가십시오. 마티아스 쇼는 {object:2100}의 SI:7에 있습니다.",
		["Ride west along the road once more."] = "다시 한 번 길을 따라 서쪽으로 가십시오.",
		["Ride west along the road out of {area:94} into {zone:1436}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "길을 따라 서쪽으로 {area:94}을(를) 벗어나 {zone:1436}(으)로 가십시오. {npc:7024}은(는) 경계 바로 안쪽 언덕에서 {npc:7053}의 탑을 감시합니다. 탑을 지키는 {npc:7051}(레벨 23)이(가) 열쇠를 가지고 있으며, 클라벤의 일지는 꼭대기의 상자에 있습니다.",
		["Ride west to the hermit once more."] = "다시 한 번 서쪽의 은둔자에게 가십시오.",
		["Rot Blossoms"] = "{item:1598}",
		["Shaman training"] = "주술사 수련",
		["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "{npc:202}은(는) {area:42}와(과) 마을 남동쪽 {area:121} 사이의 언덕을 돌아다니며, {item:1598}을(를) 떨어뜨립니다.",
		["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {zone:1431} can drop a {item:2378}."] = "해골 전사와 해골 마법사가 {area:42} 남동쪽, 언덕 위 {npc:302}의 집 아래 무덤 사이를 돌아다닙니다. {zone:1431}의 모든 해골이 {item:2378}을(를) 떨어뜨릴 수 있습니다.",
		["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "묘지는 마을 북쪽에 있습니다. 묘지 남쪽 절반에는 해골 병사와 해골 악령이 돌아다닙니다. 정예인 {npc:522}이(가) 무덤 사이를 배회하니 멀리하십시오.",
		["The hermit's shack stands in the woods north-east of the {area:492}."] = "은둔자의 오두막은 {area:492} 북동쪽 숲속에 있습니다.",
		["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "대충 덮인 흙무더기는 농가 남쪽, 오래된 그루터기 옆에 있습니다.",
		["Train in {zone:1453}, north through {zone:1429}. Then take the boat from {area:17203} to {area:442}."] = "{zone:1429}을(를) 지나 북쪽 {zone:1453}에서 수련하십시오. 그다음 {area:17203}에서 배를 타고 {area:442}(으)로 가십시오.",
		["Wolves, spiders and ghouls"] = "늑대, 거미, 구울",
		["{area:492}, south"] = "{area:492}, 남쪽",
		["{item:281046}, from the {object:673515}"] = "{object:673515}에서 {item:281046}",
		["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372}: {npc:1313}, 연금술 용품",
		["{item:4371}, from {npc:3133}: limited stock. Sold out? {npc:1448} in {area:150} sells it too."] = "{npc:3133}에게서 {item:4371}: 재고 한정. 매진되었다면 {area:150}의 {npc:1448}도 팝니다.",
		["{item:7908}, in the chest"] = "상자 안의 {item:7908}",
		["{npc:2409}, at the north end of town"] = "{npc:2409}, 마을 북쪽 끝",
		["{npc:264}, in the town hall"] = "{npc:264}, 마을 회관",
		["{npc:265}, in her house by the tavern"] = "{npc:265}, 주점 옆 그녀의 집",
		["{npc:267}, in the town hall"] = "{npc:267}, 마을 회관",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, 마을 회관 뒤 집",
		["{npc:273}, in the tavern"] = "{npc:273}, 주점",
		["{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "{npc:276}의 집은 마을 동쪽 끝에 있습니다. 그 옆집에서 {npc:3133}이(가) 기계공학 용품을 팝니다.",
		["{npc:288} hides in the house at the west end of {area:94}."] = "{npc:288}은(는) {area:94} 서쪽 끝의 집에 숨어 있습니다.",
		["{npc:332}: Poisons, and {item:18160}"] = "{npc:332}: 독, {item:18160}",
		["{npc:633}, at the south end of town"] = "{npc:633}, 마을 남쪽 끝",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, 주점",
		["{npc:888} stands south of the road, at the {area:245}."] = "{npc:888}은(는) 길 남쪽 {area:245}에 서 있습니다.",
		["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607}: {npc:7207}, 병영 지하실",
		["{quest:337}: a rare drop from {zone:1431}'s mobs"] = "{quest:337}: {zone:1431} 몹이 드물게 떨어뜨림",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the {area:442} boat."] = "{zone:1453}에는 주술사 상급자가 없습니다: {object:28027}에서 {area:2257}을(를) 타고 {zone:1455}(으)로 가서 {npc:258098}에게 수련한 뒤, 지하철로 돌아와 {area:442}행 배를 타십시오.",
} end)()
t.guides["forever/alliance/06-ashenvale"] = (function() return {
		["Back to the Cathedral of Light: {npc:928} stands inside."] = "빛의 대성당으로 돌아가세요. {npc:928}이(가) 안에 서 있습니다.",
		["Black Oozes"] = "검은 수액괴물",
		["Black Oozes creep through the marsh north of the {area:1025} road, west of {npc:2093}'s camp. Any ooze may hold {npc:2111}'s bag."] = "검은 수액괴물은 {area:1025} 길 북쪽, {npc:2093}의 야영지 서쪽 늪을 기어다닙니다. 어느 수액괴물이든 {npc:2111}의 가방을 지니고 있을 수 있습니다.",
		["Boat to {area:150}"] = "배를 타고 {area:150}(으)로",
		["Cathedral of Light"] = "빛의 대성당",
		["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site."] = "긴다리동굴거미와 긴다리흡혈거미가 발굴 현장 남동쪽 동굴인 {area:1021}에 가득합니다.",
		["Dragonmaw camp"] = "용아귀부족 야영지",
		["Escort Kerlonian to {area:413} in {zone:1440}."] = "케를로니안을 {zone:1440}의 {area:413}까지 호위하세요.",
		["Fen Creepers"] = "수렁이끼괴물",
		["Fen Creepers hide in the marsh pools north-west of the {area:1025}."] = "수렁이끼괴물은 {area:1025} 북서쪽 늪 웅덩이에 숨어 있습니다.",
		["Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; {npc:1259} walks with a pack in the middle of it."] = "해안을 따라 북쪽으로 메네실 항구를 나가세요. 푸른아가미멀록이 늪에 가득하고, {npc:1259}은(는) 그 한가운데에서 무리와 함께 돌아다닙니다.",
		["Follow the coast north to the {area:414}. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "해안을 따라 북쪽으로 {area:414}까지 가세요. {npc:3846}은(는) 해변에 진을 치고 있고, 해안에는 성난지느러미일족 나가가 가득합니다.",
		["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "길을 따라 동쪽으로 {area:419}까지 가세요. {npc:3916}은(는) 달샘 옆에 서 있습니다.",
		["Follow the road east. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "길을 따라 동쪽으로 가세요. {npc:1417}은(는) 발굴 현장 북쪽 웅덩이에 숨어 있습니다.",
		["Follow the road north to {area:205}, at the foot of the {area:881}. {npc:1071} stands in the dwarves' camp."] = "길을 따라 북쪽으로 {area:881} 기슭의 {area:205}까지 가세요. {npc:1071}은(는) 드워프 야영지에 서 있습니다.",
		["Follow the road south-east to {area:415}, on the island in the lake."] = "길을 따라 남동쪽으로 호수 섬에 있는 {area:415}까지 가세요.",
		["For Bolvar Fordragon in {object:2117}: keep it"] = "{object:2117}의 볼바르 폴드라곤에게: 보관하세요",
		["For the giant crocolisks of the north coast, on your next visit"] = "북쪽 해안의 거대한 습지악어는 다음 방문 때",
		["For {npc:2228} in {area:271}: keep it"] = "{area:271}의 {npc:2228}에게: 보관하세요",
		["From {area:17203} take the boat to {area:442}; {npc:3649} stands at the north end of the village. Then ride south along the road through {zone:1439}."] = "{area:17203}에서 배를 타고 {area:442}(으)로 가세요. {npc:3649}은(는) 마을 북쪽 끝에 서 있습니다. 그런 다음 길을 따라 남쪽으로 {zone:1439}을(를) 지나가세요.",
		["Hearth to Menethil"] = "메네실로 귀환",
		["Hearthstone on cooldown? Ride back north through the {area:1276}."] = "귀환석이 재사용 대기 중인가요? {area:1276}을(를) 지나 북쪽으로 돌아가세요.",
		["Kerlonian sleeps at the {area:448} in southern {zone:1439}. Use the {item:13536} to wake him and lead him south along the road into {zone:1440} to {npc:11219} at {area:413}; blow the horn again whenever he falls asleep."] = "케를로니안은 {zone:1439} 남부의 {area:448}에서 잠들어 있습니다. {item:13536}을(를) 사용해 그를 깨우고, 길을 따라 남쪽으로 {zone:1440}에 들어가 {area:413}의 {npc:11219}에게 데려가세요. 그가 잠들 때마다 뿔피리를 다시 부세요.",
		["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "정령을 처치해 {item:12220} 5개를 모은 뒤 {item:5456}을(를) 사용하세요",
		["Mosshide Fenrunners and Mistweavers roam the riverbanks just west and south of {npc:1244}; almost every one drops flint."] = "이끼가죽일족 길잡이와 안개마술사가 {npc:1244} 바로 서쪽과 남쪽 강둑을 돌아다닙니다. 거의 모두가 부싯돌을 떨어뜨립니다.",
		["Mosshide Gnolls and Mongrels hold the hills south-east of the {area:1025}."] = "이끼가죽 놀과 이끼가죽일족 싸움꾼이 {area:1025} 남동쪽 언덕을 차지하고 있습니다.",
		["Mottled Raptors and Screechers roam the hills west of the excavation site."] = "줄무늬랩터와 긴송곳니 줄무늬랩터가 발굴 현장 서쪽 언덕을 돌아다닙니다.",
		["Next: fly to {area:42}."] = "다음: {area:42}(으)로 날아가세요.",
		["North of Maestra's Post, plant bundles lie around the ruins of {area:411}. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "마에스트라 주둔지 북쪽, {area:411} 폐허 주변에 식물 꾸러미가 놓여 있습니다. 암흑이교도는 그 바로 남쪽 폐허를 차지하고 있으며, 누구든 {item:5366}을(를) 떨어뜨릴 수 있습니다.",
		["Only if you looted {quest:337} in {zone:1431}"] = "{zone:1431}에서 {quest:337}을(를) 획득한 경우에만",
		["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "{zone:1439}에서 얻은 {item:5352}이(가) 있을 때만: {npc:2786}, {object:32383}",
		["Raptor valley"] = "랩터 계곡",
		["Ride east along the {zone:1437} road, south through {area:836} into {zone:1432} and west through the tunnel into {zone:1426} to {area:1537}."] = "{zone:1437} 길을 따라 동쪽으로 가서 남쪽으로 {area:836}을(를) 지나 {zone:1432}에 들어간 뒤, 서쪽 굴을 지나 {zone:1426}의 {area:1537}(으)로 가세요.",
		["Ride south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}. {npc:4080} and {npc:4077} camp on the {area:1076} south-west of the crag."] = "{area:421}을(를) 지나 남쪽으로 {area:1276} 굴에 들어가세요. 굴은 돌발톱 산맥의 {area:461}(으)로 이어집니다. {npc:4080}와(과) {npc:4077}은(는) 바위산 남서쪽 {area:1076}에 진을 치고 있습니다.",
		["Ride west to the shore of {area:441}. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "서쪽으로 {area:441} 기슭까지 가세요. 테로니스는 소금거품멀록들 사이에 쓰러져 있습니다. 어느 멀록이든 {item:5463}을(를) 떨어뜨릴 수 있습니다.",
		["South of the murlocs, {npc:3585} waits at the {area:416}."] = "멀록들 남쪽, {area:416}에서 {npc:3585}이(가) 기다립니다.",
		["Take the boat from {area:17203} to {area:442} and fly to {area:702}; {npc:11401} is in the Temple of the Moon. Then fly back to {area:442}."] = "{area:17203}에서 배를 타고 {area:442}(으)로 간 뒤 {area:702}(으)로 날아가세요. {npc:11401}은(는) 달의 신전에 있습니다. 그런 다음 {area:442}(으)로 날아 돌아오세요.",
		["Take the boat from {area:17203} to {area:442}. Join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then fly to {area:702} (by way of {area:442})."] = "{area:17203}에서 배를 타고 {area:442}(으)로 가세요. 반쪽 펜던트 두 개를 합쳐 {item:15885}을(를) 만들고 {spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있습니다. 그런 다음 ({area:442}을(를) 거쳐) {area:702}(으)로 날아가세요.",
		["Take the portal up to the {area:1658}, then fly back to {area:442}."] = "차원문을 타고 {area:1658}(으)로 올라간 뒤, {area:442}(으)로 날아 돌아오세요.",
		["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "{object:171524}에서 {area:2257}을(를) 타고 {zone:1453}의 {object:28027}(으)로 간 뒤, {object:2098}까지 걸어가세요.",
		["The Bluegill hovels"] = "푸른아가미 오두막",
		["The Dragonmaw camp lies south of the road, just west of the {area:1025}: Raiders, Swamprunners and Bonewarders. {npc:2092}'s quest in {zone:1426} needs level 28."] = "용아귀부족 야영지는 {area:1025} 바로 서쪽, 길 남쪽에 있습니다. 약탈자, 늪길잡이, 해골감시자가 있습니다. {zone:1426}에서 {npc:2092}의 퀘스트는 28레벨이 필요합니다.",
		["The Foulweald"] = "썩은나무 숲",
		["The Foulweald furbolgs live in the woods south of the road, south-east of {area:415}. The Den Watcher and the Ursas guard the den."] = "썩은나무일족 펄볼그는 길 남쪽, {area:415} 남동쪽 숲에 삽니다. 썩은나무일족 보초와 썩은나무일족 펄볼그가 굴을 지킵니다.",
		["The Mosshide gnolls"] = "이끼가죽 놀",
		["The Venture Co. clear the forest of {area:461}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "투자개발회사가 {area:461}의 숲을 베어내고 있습니다. 나무꾼과 벌채꾼이 곳곳에서 일하고, 운전수가 벌목기를 몰며 그중 하나가 설계도를 지니고 있습니다.",
		["The bigger raptors hunt in the valley just west of the dig."] = "더 큰 랩터는 발굴지 바로 서쪽 계곡에서 사냥합니다.",
		["The excavation site sits on the hill south of the road."] = "발굴 현장은 길 남쪽 언덕 위에 있습니다.",
		["The raptor hills"] = "랩터 언덕",
		["The tears glow on the small isle east of {area:415}."] = "눈물은 {area:415} 동쪽의 작은 섬에서 빛납니다.",
		["Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "멀록 오두막의 상자 세 개, 남쪽에서 북쪽 순서: {object:261}, 그다음 {object:142151}, 그다음 북쪽 끝의 {object:259}.",
		["Timber and iron piles lie around the keep and along the harbor's walls."] = "목재와 철 더미가 성채 주변과 항구 성벽을 따라 놓여 있습니다.",
		["To {area:150}"] = "{area:150}(으)로",
		["Venture Co. loggers"] = "투자개발회사 나무꾼",
		["West of Mystral Lake, the stardust bushes grow among the ruins."] = "미스트랄 호수 서쪽, 폐허 사이에 별가루 덤불이 자랍니다.",
		["Young crocolisks"] = "새끼 악어",
		["grind on Dragonmaw Raiders and Swamprunners at the Dragonmaw camp, {zone:1437}"] = "{zone:1437}의 용아귀부족 야영지에서 용아귀부족 약탈자와 늪길잡이를 사냥하세요",
		["{item:15885}: join the two halves"] = "{item:15885}: 반쪽 두 개를 합치기",
		["{item:5424}, in the ruins on the shore"] = "{item:5424}, 해안의 폐허 안",
		["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406}와(과) {npc:258785}은(는) {object:32362}의 {object:32386}에 있습니다.",
		["{npc:1239}, in the inn"] = "{npc:1239}, 여관 안",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}, 여관 북쪽 부두 위",
		["{npc:1242}: for {npc:2104} in the keep"] = "{npc:1242}: 성채 안의 {npc:2104}에게",
		["{npc:1440}, in the Royal Library"] = "{npc:1440}, 왕실 도서관 안",
		["{npc:1444}, in the {object:2098}"] = "{npc:1444}, {object:2098}",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, {object:32372} 안",
		["{npc:2086}, by the keep"] = "{npc:2086}, 성채 옆",
		["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093}은(는) 길가에 진을 치고 있고, {npc:1244}은(는) 더 동쪽 강가에 서 있습니다.",
		["{npc:2094}, by the north gate"] = "{npc:2094}, 북문 옆",
		["{npc:2096}, by the north gate"] = "{npc:2096}, 북문 옆",
		["{npc:2097}, by the north gate"] = "{npc:2097}, 북문 옆",
		["{npc:2104} stands in {area:2103}, a short walk from {npc:1242}."] = "{npc:2104}은(는) {npc:1242}에게서 조금 걸어가면 나오는 {area:2103}에 서 있습니다.",
		["{npc:3649}: Alexston's reply"] = "{npc:3649}: 알렉스톤의 답장",
		["{npc:3664} and his voidwalkers hold the {area:412} south of the shrine. Pull his guards first."] = "{npc:3664}와(과) 그의 공허방랑자들은 성소 남쪽의 {area:412}을(를) 차지하고 있습니다. 경비병을 먼저 끌어오세요.",
		["{npc:3691}, in the inn"] = "{npc:3691}, 여관 안",
		["{npc:3885} stands at the {area:420} on the east shore of {area:421}; {npc:210995} camps on its west shore. Befouled Water Elementals wade in the lake between them."] = "{npc:3885}은(는) {area:421} 동쪽 기슭의 {area:420}에 서 있고, {npc:210995}은(는) 서쪽 기슭에 진을 치고 있습니다. 타락한 물의 정령이 그 사이 호수를 걸어다닙니다.",
		["{npc:3987} (25) leads the Thistlefur gnolls at the camp north of {area:415}. Clear his guards first, one at a time."] = "{npc:3987}(25레벨)이 {area:415} 북쪽 야영지에서 엉겅퀴일족 놀을 이끕니다. 경비병을 하나씩 먼저 처치하세요.",
		["{npc:4201}, in the hut north of them"] = "{npc:4201}, 그들 북쪽의 오두막 안",
		["{npc:4276} mines in the {area:2160} at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines."] = "{npc:4276}은(는) 바위산 동쪽 끝의 {area:2160}에서 채광합니다. 그에게 말을 걸고, 그가 채광하는 동안 투자개발회사 습격자를 막아내세요.",
		["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}, {object:2096}의 치즈 가게",
		["{npc:4959} and {npc:482}"] = "{npc:4959}와(과) {npc:482}",
		["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}, 빛의 대성당 안",
		["{object:2164} is in the {object:2101}."] = "{object:2164}은(는) {object:2101}에 있습니다.",
		["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009}은(는) 성난지느러미일족 경비병과 함께 {area:414}의 북쪽 끝을 돌아다닙니다.",
		["{quest:1010}, from the plant bundles"] = "{quest:1010}, 식물 꾸러미에서",
		["{zone:1455} priests"] = "{zone:1455} 사제",
} end)()
t.guides["forever/alliance/07-thousand-needles"] = (function() return {
		["Back to Menethil"] = "메네실로 돌아가기",
		["Back to {area:42}"] = "{area:42}(으)로 돌아가기",
		["Bluegill Raiders"] = "{npc:1418}",
		["Dragonmaw camp"] = "용아귀부족 야영지",
		["Dragonmaw catapult"] = "용아귀부족 투석기",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "협곡을 따라 동쪽의 소금 평원으로 가세요. {area:2240}의 고블린과 노움은 중립이며 양 진영 모두에게 퀘스트를 줍니다.",
		["Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; {npc:1159} stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it."] = "해안을 따라 북쪽의 난파선으로 가세요. {npc:1157}은(는) 해변을, {npc:1158}은(는) 갑판을 걸어다니고, {npc:1159}은(는) 뱃머리 옆 해변에 서 있습니다. {npc:2089}은(는) 그 바로 북쪽 해안에 숨어 있습니다.",
		["Follow the coast north-east past the wreck: the Bluegill Raiders hold the marsh beyond the Giant Crocolisks."] = "난파선을 지나 해안을 따라 북동쪽으로 가세요. {npc:1418}은(는) 거대한 습지악어 너머 습지를 차지하고 있습니다.",
		["Follow the road east to the excavation site."] = "길을 따라 동쪽의 발굴 현장으로 가세요.",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "다음 가이드에서 {zone:1453}의 {npc:1212}에게",
		["For {npc:1284} in {zone:1453}, in the next guide"] = "다음 가이드에서 {zone:1453}의 {npc:1284}에게",
		["For {npc:4048} in {zone:1444}, much later"] = "한참 뒤에 {zone:1444}의 {npc:4048}에게",
		["For {npc:482} in {zone:1453}, in the next guide"] = "다음 가이드에서 {zone:1453}의 {npc:482}에게",
		["For {quest:5762} in Stranglethorn, later"] = "나중에 가시덤불 골짜기에서 {quest:5762}에게",
		["From Theramore follow the road west out of Dustwallow into the {zone:1413} and south along it; give {area:378} a wide berth. {area:485} at the {zone:1413}' south end takes you down into {zone:1441}. The journal lies at the foot of the lift."] = "테라모어에서 길을 따라 서쪽으로 먼지진흙 습지대를 빠져나와 {zone:1413}에 들어간 뒤, 길을 따라 남쪽으로 가세요. {area:378}은(는) 멀리 돌아가세요. {zone:1413} 남쪽 끝의 {area:485}을(를) 타면 {zone:1441}(으)로 내려갑니다. 일지는 승강장 아래에 있습니다.",
		["From {npc:352} in {zone:1453}"] = "{zone:1453}의 {npc:352}에게서",
		["Her house stands on the hill south-east of {area:42}."] = "그녀의 집은 {area:42} 남동쪽 언덕 위에 있습니다.",
		["Nightbane Dark Runners"] = "{npc:205}",
		["Nightbane Shadow Weavers"] = "{npc:533}",
		["Nightbane Vile Fangs and the {npc:511}"] = "{npc:206}와(과) {npc:511}",
		["No {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too."] = "{quest:174}에 쓸 {item:4371}이(가) 없나요? {npc:276} 옆집의 {npc:3133}이(가) 한정 수량으로 팔고, {area:150}의 {npc:1448}도 팝니다.",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "{zone:1413}을(를) 지나 남쪽으로 가는 길에서, {npc:6244}은(는) 길 동쪽, {area:378} 북동쪽에 진을 치고 있습니다. 동쪽에서 접근하고 호드 경비병을 피하세요.",
		["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "{npc:272273}이(가) {quest:96138}을(를) 떨어뜨렸을 때만: 오른쪽 클릭하세요",
		["Plague Spreaders"] = "{npc:604}",
		["Ride back west along the road to {area:150}."] = "길을 따라 서쪽으로 {area:150}까지 돌아가세요.",
		["Ride east again; the catapult stands at the Dragonmaw camp south of the road."] = "다시 동쪽으로 가세요. 투석기는 길 남쪽의 용아귀부족 야영지에 있습니다.",
		["Ride east to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "동쪽의 오우거 소굴로 가세요. {object:119}은(는) 입구의 야영지에 있으며 망치주먹 오우거가 지킵니다.",
		["Ride west along the road; the hermit's shack stands north-east of the {area:492}."] = "길을 따라 서쪽으로 가세요. 은둔자의 오두막은 {area:492} 북동쪽에 있습니다.",
		["Skeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp."] = "{npc:1110}, 해골 치료사, 해골 문지기가 {npc:311}의 야영지 바로 동쪽, 묘지 서쪽 구역을 차지하고 있습니다.",
		["Take the boat from Menethil's pier to {area:513} in {zone:1445}."] = "메네실 부두에서 배를 타고 {zone:1445}의 {area:513}(으)로 가세요.",
		["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "암흑길잡이는 {area:42} 서쪽, 길 남쪽 숲을 어슬렁거립니다.",
		["The Defias camp lies in the south-west of {zone:1431}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "데피아즈단 야영지는 {zone:1431} 남서쪽, {area:94} 남쪽의 {zone:1436} 경계 근처에 있습니다. 금고는 천막들 사이에 있습니다.",
		["The Dragonmaw orcs camp east of the excavation site. Raiders and Swamprunners carry the war banners."] = "용아귀부족 오크는 발굴 현장 동쪽에 진을 치고 있습니다. 약탈자와 늪길잡이가 전투 깃발을 가지고 있습니다.",
		["The Plague Spreaders walk the northern half of the {area:492}. {npc:522}, an elite, wanders the graves: keep away from him."] = "{npc:604}은(는) {area:492} 북쪽 절반을 걸어다닙니다. 정예인 {npc:522}이(가) 무덤 사이를 배회하니 가까이 가지 마세요.",
		["The captain walks the deck of the wrecked ship; his strongbox sits in the hold."] = "선장은 난파선 갑판을 걸어다니고, 그의 금고는 선창에 있습니다.",
		["The dig and {npc:1353}"] = "발굴지와 {npc:1353}",
		["The next step, Defeat Nek'rosh, pits you against an elite chieftain: skip it."] = "다음 단계인 네크로쉬 처치는 정예 족장과 싸워야 합니다. 건너뛰세요.",
		["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it."] = "유물은 발굴지 안에 있습니다. 커다란 무쇠턱 랩터인 {npc:1353}은(는) 그 바로 서쪽의 랩터 계곡을 어슬렁거립니다.",
		["The salt flats"] = "소금 평원",
		["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}. The {npc:511} hides in the small crypt by the cemetery."] = "가장 강한 늑대인간은 {area:42} 남쪽, {area:121}의 서쪽과 남쪽 숲을 돌아다닙니다. {npc:511}은(는) 묘지 옆 작은 납골당에 숨어 있습니다.",
		["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "늑대인간이 {area:42} 서쪽, 길 북쪽의 밝은나무 숲을 차지하고 있습니다. 하나씩 끌어오세요.",
		["The wreck of the Third Fleet"] = "제3함대 난파선",
		["To Theramore"] = "테라모어로",
		["Wait a moment, then speak with her again"] = "잠시 기다렸다가 그녀와 다시 대화하세요",
		["{area:492}, west"] = "{area:492}, 서쪽",
		["{item:2594}, from {npc:1464}"] = "{item:2594}, {npc:1464}에게서",
		["{item:2661}: the {object:331}"] = "{item:2661}: {object:331}",
		["{item:4371}, from {npc:3133}, if you have none"] = "{item:4371}, 없다면 {npc:3133}에게서",
		["{npc:1078} and Whelgar"] = "{npc:1078}와(과) 웰가르",
		["{npc:1217}, upstairs in the inn"] = "{npc:1217}, 여관 위층",
		["{npc:1239}, in the inn"] = "{npc:1239}, 여관 안",
		["{npc:2104}, by the keep"] = "{npc:2104}, 성채 옆",
		["{npc:263}, in the town hall"] = "{npc:263}, 마을 회관 안",
		["{npc:267}, in the town hall"] = "{npc:267}, 마을 회관 안",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, 마을 회관 뒤 집",
		["{npc:276}, at the east end of town"] = "{npc:276}, 마을 동쪽 끝",
		["{npc:311}'s Camp"] = "{npc:311}의 야영지",
		["{npc:4454}: for Martek in the {zone:1418}, later"] = "{npc:4454}: 나중에 {zone:1418}의 마르텍에게",
		["{npc:661}, by {npc:633}'s house"] = "{npc:661}, {npc:633}의 집 옆",
		["{npc:663}, by the town hall"] = "{npc:663}, 마을 회관 옆",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, 여관",
		["{npc:840}, at the north entrance of town"] = "{npc:840}, 마을 북쪽 입구",
		["{object:19868} lies all over the flats. Scorpid Reavers, Sparkleshell Tortoises and Saltstone Basilisks roam the north half, Crystalhides, Scorpid Terrors and Snappers the middle, and the Gazers (34-35, five levels above you: one at a time) the far south. Vultures circle over all of it."] = "{object:19868}은(는) 평원 곳곳에 흩어져 있습니다. {npc:4140}, {npc:4142}, {npc:4147}은(는) 북쪽 절반을, 소금바위 수정바실리스크, {npc:4139}, 무쇠턱 소금껍질거북은 가운데를, 소금바위 큰눈바실리스크(34-35, 당신보다 5레벨 높음: 하나씩)는 맨 남쪽을 돌아다닙니다. 독수리는 그 모든 곳 위를 맴돕니다.",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: {zone:1443}(으)로 가는 길에 {zone:1440}에서",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: 서큐버스 옆의 인큐버스. {item:190309}은(는) {quest:1738} 근처에 있습니다",
} end)()
t.guides["forever/alliance/30-40/01-hillsbrad-foothills"] = (function() return {
		["A new {item:279996}, for the four titan watchers around the {zone:1437}"] = "새 {item:279996}, {zone:1437} 주변 티탄 감시자 넷을 위한 것",
		["A report for {object:2117}"] = "{object:2117}에 보낼 보고서",
		["Back south down the road to the excavation site."] = "길을 따라 남쪽 발굴 현장으로 돌아가십시오.",
		["Back to the same murlocs; not every one drops a head."] = "같은 멀록에게 돌아가십시오. 모두 머리를 떨어뜨리지는 않습니다.",
		["Boat to {area:271}"] = "{area:271}행 배",
		["Cathedral of Light"] = "빛의 대성당",
		["Daggerspine naga"] = "비수가시일족 나가",
		["Destroy the four sets of Attack Plans in the camp for {quest:98221}."] = "{quest:98221}을(를) 위해 야영지의 공격 계획 네 묶음을 파괴하십시오.",
		["Druid training"] = "드루이드 수련",
		["Farren"] = "파렌",
		["Fly to {zone:1453}"] = "{zone:1453}로 비행",
		["Follow the road east to {area:118}."] = "길을 따라 동쪽 {area:118}(으)로 가십시오.",
		["Follow the road north-east into the {area:1025}: {npc:270637} camps beside it, {npc:1244} a short way east."] = "길을 따라 북동쪽 {area:1025}로 가십시오. {npc:270637}은(는) 그 옆에 야영하고 있고, {npc:1244}은(는) 조금 동쪽에 있습니다.",
		["For King Magni in {zone:1455}, at the end of this guide"] = "{zone:1455}의 국왕 마그니 브론즈비어드에게, 이 가이드 마지막에",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "{zone:1455}의 {npc:2916}에게, 이 가이드 마지막에",
		["From {npc:2432} in {area:271}"] = "{area:271}의 {npc:2432}에게서",
		["Level 30 and 32 spells"] = "30, 32레벨 주문",
		["Murloc heads"] = "멀록 머리",
		["North along the road to {area:205}. {npc:271460} stands in the ruins (use the {item:279996}); the {npc:271481} is held on the west side: lead it out to {npc:1072}."] = "길을 따라 북쪽 {area:205}(으)로 가십시오. {npc:271460}은(는) 폐허 안에 있습니다({item:279996} 사용). {npc:271481}은(는) 서쪽에 갇혀 있으니 {npc:1072}에게 데려가십시오.",
		["North-east to the {area:1038}: the {npc:271373} are held there, and {npc:271338} stands at the gates (use the {item:279996})."] = "북동쪽 {area:1038}(으)로 가십시오. {npc:271373}이(가) 그곳에 갇혀 있으며, {npc:271338}이(가) 성문에 있습니다({item:279996} 사용).",
		["Pick up everything in town before heading out. Off the boat, {npc:251493} is the first you meet, north-west of the flight master; {npc:2381} and {npc:2438} stand between the flight master and the inn, Farren and {npc:2366} at the inn, Maleb in the town hall."] = "출발 전에 마을의 퀘스트를 모두 수락하십시오. 배에서 내리면 비행 조련사 북서쪽의 {npc:251493}을(를) 먼저 만납니다. {npc:2381}와(과) {npc:2438}은(는) 비행 조련사와 여관 사이에, 파렌과 {npc:2366}은(는) 여관에, 말레브는 마을 회관에 있습니다.",
		["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; {npc:271458} stands in the north-east (use the {item:279996}).\n{quest:98283} is elite: grouping up is advised."] = "새끼 붉은용이 성문 서쪽 언덕에, 광기에 물든 썩은발톱이 {area:1025}에, 무쇠턱 랩터가 북쪽 비탈에 가득합니다. {npc:271458}은(는) 북동쪽에 있습니다({item:279996} 사용).\n{quest:98283}은(는) 정예이므로 파티를 권장합니다.",
		["Snapjaws"] = "무쇠턱거북",
		["South to the Dragonmaw's {area:1036}; the {object:671518} lies in the camp."] = "남쪽의 용아귀부족 {area:1036}(으)로 가십시오. {object:671518}은(는) 야영지 안에 있습니다.",
		["Syndicate camp"] = "비밀결사대 야영지",
		["Take the {area:2257} from the {object:28027} to {zone:1455}."] = "{object:28027}에서 {area:2257}을(를) 타고 {zone:1455}(으)로 가십시오.",
		["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one."] = "Goaz Warder들은 웰가의 야영지 바로 서쪽에 있습니다. 그 중 하나 옆에서 그가 준 {item:279996}을(를) 사용하십시오.",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "무쇠턱거북이 {area:271} 동쪽, {area:272}(호드) 남쪽 강을 따라 햇볕을 쬡니다.",
		["The Syndicate camp sits on the Alterac border in northern {area:287}, west of {area:272} (Horde); the documents lie in the camp."] = "비밀결사대 야영지는 {area:272}(호드) 서쪽, {area:287} 북부의 알터랙 경계에 있습니다. 문서는 야영지 안에 있습니다.",
		["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}."] = "너덜지느러미멀록이 {area:271} 남서쪽 {area:295}에 몰려 있습니다.",
		["The Villards"] = "빌라드 남매",
		["The cheese shop in the {object:2096}."] = "{object:2096}의 치즈 가게입니다.",
		["The naga hold the shore south-east of {area:271}."] = "나가가 {area:271} 남동쪽 해안을 차지하고 있습니다.",
		["The yetis live in the cave in the hills north of {area:271}, on your way back south."] = "설인은 {area:271} 북쪽 언덕의 동굴에 삽니다. 남쪽으로 돌아가는 길에 있습니다.",
		["Torn Fin murlocs"] = "너덜지느러미멀록",
		["West along the road to Menethil."] = "길을 따라 서쪽 메네실 항구로 가십시오.",
		["West to the farms of {area:287}: place the {item:279386} on the bookkeeping table in the town hall, where {npc:2335} and the councilmen stand."] = "서쪽 {area:287} 농장으로 가십시오. {npc:2335}와(과) 원로들이 있는 마을 회관의 장부 탁자에 {item:279386}을(를) 놓으십시오.",
		["Whelps, raptors and {npc:271458}"] = "새끼 용, 랩터, {npc:271458}",
		["Yeti cave"] = "설인 동굴",
		["{area:287} town hall"] = "{area:287} 마을 회관",
		["{area:287}'s town hall"] = "{area:287} 마을 회관",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, {npc:2381}에게서",
		["{npc:1244}: {quest:98283}, an elite raptor"] = "{npc:1244}: {quest:98283}, 정예 랩터",
		["{npc:2104} stands in {area:2103}; {npc:2094} and {npc:270844} stand together by the north gate."] = "{npc:2104}은(는) {area:2103}에 있으며, {npc:2094}와(과) {npc:270844}은(는) 북문 옆에 함께 있습니다.",
		["{npc:2104}: for {npc:270637}"] = "{npc:2104}: {npc:270637}에게",
		["{npc:2366}, in the inn: for {area:35} (04-stranglethorn-vale)"] = "{npc:2366}, 여관 안: {area:35}용 (04-stranglethorn-vale)",
		["{npc:2382}: the lions come later"] = "{npc:2382}: 사자는 나중에",
		["{npc:2438} also wants a {item:3719}, a {item:2997} and {item:2321}: crafted or bought; the cloak is turned in when you are back in {area:271} later."] = "{npc:2438}은(는) {item:3719}, {item:2997}, {item:2321}도 원합니다. 제작하거나 구매하십시오. 망토는 나중에 {area:271}에 돌아와서 제출합니다.",
		["{npc:270844}: for {npc:3649} in {area:442} (02-desolace)"] = "{npc:270844}: {area:442}의 {npc:3649}에게 (02-desolace)",
		["{npc:2708} is in the {object:2164}; {npc:211033} near the canal; {npc:5081} south of the {object:2101}."] = "{npc:2708}은(는) {object:2164}에, {npc:211033}은(는) 운하 근처에, {npc:5081}은(는) {object:2101} 남쪽에 있습니다.",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}: 그의 흔적은 아라시 고원으로 이어집니다",
		["{npc:271462} stands in the south-eastern hills: use the {item:279996} beside it."] = "{npc:271462}은(는) 남동쪽 언덕에 있습니다. 그 옆에서 {item:279996}을(를) 사용하십시오.",
		["{npc:2784}, the {object:171709}"] = "{npc:2784}, {object:171709}",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961}은(는) {object:2100}의 돼지와 휘파람 선술집에서 기다립니다. 그와 부하 둘이 덤벼들지만 쓰러뜨리면 멈춥니다.",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479}은(는) {object:2100}의 돼지와 휘파람 선술집 옆에서 전사를 가르칩니다. {npc:6236}은(는) {zone:1413}의 {area:720}에서 기다립니다. 한참 뒤 {area:392}(으)로 가는 길에 있습니다(40-50/01).",
		["{npc:5683} waits north of {area:205} by the {area:881}; {npc:271322} a short walk further north-east."] = "{npc:5683}은(는) {area:205} 북쪽 {area:881} 옆에서 기다리고, {npc:271322}은(는) 조금 더 북동쪽에 있습니다.",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: {npc:2104}에게",
		["{zone:1455} has no druid trainer: train with {npc:5504} in {zone:1453} before the tram."] = "{zone:1455}에는 드루이드 상급자가 없습니다. 전차를 타기 전에 {zone:1453}의 {npc:5504}에게 수련하십시오.",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort the caravan"] = "대상단 호위",
		["Escort {npc:5644}"] = "{npc:5644} 호위",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "길을 따라 서쪽으로 {area:460}(호드)을(를) 지나, 남서쪽 {area:465}을(를) 거쳐 {zone:1443}(으)로 가십시오. {area:608}은(는) 고개 꼭대기에 있습니다.",
		["From {area:415} head south-west to the {area:1276}, a tunnel through the mountains into Stonetalon."] = "{area:415}에서 남서쪽 {area:1276}(으)로 가십시오. 산을 뚫고 돌발톱 산맥으로 이어지는 터널입니다.",
		["From {area:415} ride north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then back past {area:415} to the {area:1276}."] = "{area:415}에서 북서쪽 언덕으로 가십시오. {quest:1738}은(는) {area:413}(으)로 가는 길 북쪽의 빛나는 나무입니다. {quest:65602}을(를) 수락했다면 {item:190309}은(는) {area:413} 북쪽 나무 사이의 집 안에 있습니다(26.6,22.0). 그다음 {area:415}을(를) 지나 {area:1276}(으)로 돌아가십시오.",
		["From {zone:1455}'s {npc:1573}"] = "{zone:1455}의 {npc:1573}에게서",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building."] = "그녀의 오빠 {npc:5643}(36)는 불타는 칼날단 사교도(30-33)와 함께 요새를 돌아다닙니다. 그만 따로 끌어오세요. {npc:13019}은(는) 요새 본관에 홀을 가지고 있습니다.",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "{npc:5644}을(를) 요새 밖으로 데려가십시오. 요새를 벗어나면 그녀가 떠납니다. 가이드 마지막에 {area:608}에서 {npc:5642}에게 완료 보고를 하십시오.",
		["Malem chest"] = "말렘의 궤짝",
		["Out of Thunder Axe Fortress"] = "천둥도끼 요새 밖으로",
		["Scorpashi venom"] = "스콜파시 독",
		["Take the boat to {area:442} from Menethil's docks. {npc:3649} stands in {area:442}, north of the flight master."] = "메네실 항구의 부두에서 {area:442}행 배를 타십시오. {npc:3649}은(는) {area:442}의 비행 조련사 북쪽에 있습니다.",
		["The Gizelton Caravan waits at {area:2407}."] = "기젤톤 대상단은 {area:2407}에서 기다립니다.",
		["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}."] = "서릿발분노 사티로스가 {area:608} 동쪽 {area:603} 폐허를 차지하고 있습니다.",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "콜카르일족이 {area:609} 주변 평원을 돌아다닙니다. 귀는 {npc:5752}에게 가져가십시오.",
		["The Scorpashi scorpids hunt the hills around {area:2407} on the road south."] = "스콜파시 전갈이 남쪽 길의 {area:2407} 주변 언덕에서 사냥합니다.",
		["The chest lies in the ruins south-west of {area:608}."] = "궤짝은 {area:608} 남서쪽 폐허에 있습니다.",
		["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp, five times; Aged Kodos also drop the hides."] = "{npc:11596}의 {item:13892}을(를) {npc:4700}에게 사용하고 길들인 코도를 그의 야영지로 데려가십시오. 다섯 번 반복합니다. 늙은 코도는 가죽도 떨어뜨립니다.",
		["Walk with the caravan south past {area:609}; Kolkar ambushers jump it on the way. Stay close until it stops at {area:2617}. The ambushers are 34-35 and come in waves: skip it if you are below 33."] = "대상단과 함께 {area:609}을(를) 지나 남쪽으로 걸어가십시오. 도중에 콜카르일족 매복병이 습격합니다. {area:2617}에서 멈출 때까지 가까이 있으십시오. 매복병은 34-35레벨이며 여러 차례 몰려오니, 33레벨 미만이면 건너뛰십시오.",
		["{item:190309}, north of {area:413}"] = "{item:190309}, {area:413} 북쪽",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "{npc:11596}의 야영지는 {area:609} 남쪽 길가, {area:596} 옆에 있습니다.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "{npc:11863}의 탑은 {area:599} 서쪽 언덕에 있습니다. 먼저 그의 퀘스트를 수락하십시오. 그가 원하는 홀은 요새 안에 있습니다.",
		["{npc:3649}: {item:279915}, from Sylessa in Menethil"] = "{npc:3649}: {item:279915}, 메네실 항구의 Sylessa에게서",
		["{npc:5643} and the Seer"] = "{npc:5643}와(과) 현자",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644}은(는) {area:608} 남서쪽에 있는 불타는칼날단의 요새 안에 숨어 있습니다.",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Back west along the road to the satyr camps of {area:429}."] = "길을 따라 서쪽으로 {area:429}의 사티로스 야영지에 돌아가십시오.",
		["Dartol's Rod"] = "다르톨의 변신마법봉",
		["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "길을 따라 동쪽으로 {area:429}의 사티로스 야영지까지 가십시오. {npc:3920}은(는) 야영지 가장자리에 숨어 있습니다.",
		["Follow the road west out of {area:415}; {area:413} lies north of it."] = "길을 따라 {area:415} 서쪽으로 나가십시오. {area:413}은(는) 길 북쪽에 있습니다.",
		["From {area:608}"] = "{area:608}에서",
		["Insane druids"] = "미치광이 드루이드",
		["Lightforge Ingots"] = "라이트포지 주괴",
		["Melyria and {npc:3901}"] = "파수꾼 멜리리아 프로스트섀도와 {npc:3901}",
		["Rusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel."] = "포세이큰 야영지 서쪽의 그늘덤불 야영지 주변에 녹슨 궤짝이 있습니다. 철제 머리장식이 나올 때까지 열어 보십시오.",
		["Take the boat to {area:150} from {area:442}'s docks."] = "{area:442} 부두에서 {area:150}행 배를 타십시오.",
		["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end."] = "굴을 지나 {area:419}(으)로 들어가십시오. 마법책은 서쪽 끝 폐허에 있습니다.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "메네실 항구 남서쪽 해변의 푸른아가미멀록들이 주괴를 지니고 있습니다.",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "달샘 북쪽의 광기어린 고대정령과 부패한 고대정령이 {item:5475}을(를) 지니고 있습니다. 그 열쇠로 여는 낡은 궤짝은 그들 사이에 있습니다.",
		["The Forsaken's camp lies in the woods south of {area:2358}."] = "포세이큰 야영지는 {area:2358} 남쪽 숲에 있습니다.",
		["The moonwell lies in the hills north-east of {area:415}."] = "달샘은 {area:415} 북동쪽 언덕에 있습니다.",
		["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "두 번째 {object:19901}은(는) 서쪽으로 가는 길, {area:428} 골짜기에 있습니다.",
		["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "제단은 달샘 바로 남동쪽 언덕 위에 있습니다. 구불구불한 길을 따라 올라가십시오.",
		["The three druids stand together at the Forsaken camp south of {area:2358}."] = "세 드루이드는 {area:2358} 남쪽 포세이큰 야영지에 함께 있습니다.",
		["The two stand together at the western end of the road."] = "두 사람은 길 서쪽 끝에 함께 서 있습니다.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "Flying Osprey의 난파선은 성채 남쪽 얕은 물에 있습니다.",
		["The {npc:3931} walks the shore of {quest:1035}, south-west of the chests; the {object:669176} lies north of the lake, on the way."] = "{npc:3931}은(는) 궤짝 남서쪽의 {quest:1035} 호숫가를 걷습니다. {object:669176}은(는) 가는 길, 호수 북쪽에 있습니다.",
		["The {object:19901} stands in the satyr camp of {area:430}, further east along the road."] = "{object:19901}은(는) 길을 따라 더 동쪽, {area:430}의 사티로스 야영지에 있습니다.",
		["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} and {npc:221269} stand there."] = "길 동쪽 끝의 나이트 엘프 전초기지 {area:2358}: {npc:3848}와(과) {npc:221269}이(가) 그곳에 있습니다.",
		["{area:429} satyrs"] = "{area:429} 사티로스",
		["{npc:1217} stands on the upper floor of Menethil's keep."] = "{npc:1217}은(는) 메네실 항구 성채의 위층에 있습니다.",
		["{npc:3696} and his guards camp just east of {npc:3897}."] = "{npc:3696}와(과) 그의 경비병들은 {npc:3897} 바로 동쪽에 진을 치고 있습니다.",
		["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below {area:421}."] = "타락하지 않은 펄볼그 {npc:3897}은(는) {area:421} 아래 길 남쪽에 앉아 있습니다.",
		["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide"] = "{npc:3970}: 이 가이드 끝에서 메네실 항구의 {npc:1480}에게",
		["{npc:4619} leads the {area:429} satyrs; he carries the branch."] = "{npc:4619}은(는) {area:429} 사티로스의 우두머리이며 나뭇가지를 지니고 있습니다.",
		["{npc:5082}, {npc:4963} and Tapoke Jahn are all at Menethil's inn; {npc:4962} fights you when you talk to {npc:4963}, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn."] = "{npc:5082}, {npc:4963}, {npc:4962}은(는) 모두 메네실 항구 여관에 있습니다. {npc:4963}와(과) 대화하면 타포케가 덤벼들지만, 쓰러뜨리면 포기합니다. {npc:1480}은(는) 여관에서 북동쪽으로 조금 걸어간 곳에 있습니다.",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}: {area:415}의 {npc:3961}에게",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "네싱워리를 지나 남쪽으로 돌아가세요. 퓨마와 {npc:685}은(는) 야영지 서쪽에서 해안 쪽 빈터를 뛰어다니고, 덩치큰 가시덤불 호랑이는 남서쪽 언덕을 차지하고 있습니다.",
		["Bloodscalp trolls"] = "붉은머리부족 트롤",
		["Both roam the grass around the camp and along the road north."] = "둘 다 야영지 주변 풀밭과 북쪽 길을 따라 돌아다닙니다.",
		["Down to {area:35}"] = "{area:35}(으)로 내려가기",
		["Druid training"] = "드루이드 수련",
		["Fly from {area:150} to {area:1537} and train."] = "{area:150}에서 {area:1537}(으)로 날아가 기술을 배우세요.",
		["Fly to {area:42}: {npc:1573} in {area:1537}'s {object:32372}, or {npc:352} in {zone:1453}'s {object:2096}."] = "{area:42}(으)로 날아가세요: {area:1537} {object:32372}의 {npc:1573}, 또는 {zone:1453} {object:2096}의 {npc:352}.",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "큰길을 따라 밀림을 끝까지 남쪽으로 가서 {object:3202} 갈림길을 지나 남쪽 곶의 {area:35}에 도착하세요.",
		["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "서쪽 해안을 따라 북쪽으로 가세요. 유령의 섬은 네싱워리 야영지 서쪽 앞바다에 있습니다. 도착만 하면 됩니다.",
		["For Archmage Ansirem in {zone:1416}"] = "{zone:1416}의 대마법사 앤자이럼 룬위버에게",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "{zone:1431}에서 길을 따라 남쪽으로 가시덤불 골짜기에 들어가세요. 사냥꾼들의 천막은 {area:99} 갈림길을 지나 길 바로 서쪽에 있습니다.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "야영지 서쪽 해안의 희귀 멀록 글루글이 {item:4614}을(를) 떨어뜨립니다. 만나면 챙기세요",
		["Gyll, on the top floor by the docks"] = "가일, 부두 옆 꼭대기 층",
		["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop."] = "쿠르젠 심리학자는 주둔지 더 안쪽에 서 있고, 쿠르젠 특전사는 은신한 채 주변과 동굴 안에 숨어 있습니다. 푸른 언덕 책장이 떨어지면 챙기세요.",
		["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "헤로드의 장부는 주둔지 서쪽 오두막에 있고, 그의 금고는 더 동쪽 동굴 입구 옆에 있습니다.",
		["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on {area:37} carries the Tumbled Crystals."] = "북쪽과 중앙의 트롤 폐허를 한 바퀴 도세요. 폐허마다 트롤 전설이 새겨진 석판이 하나씩 있습니다. {npc:684}은(는) 그 주변 밀림에서 은신한 채 어슬렁거리고, {area:37}의 투자개발회사 야영지가 {item:4106}을(를) 가지고 있습니다.",
		["Panthers, raptors and elder tigers"] = "퓨마, 랩터, 덩치큰 호랑이",
		["River Crocolisks swim the river by the {area:99}."] = "{npc:1150}은(는) {area:99} 옆 강에서 헤엄칩니다.",
		["River crocolisks"] = "민물악어",
		["Skullsplitter trolls"] = "백골가루부족 트롤",
		["Snapjaw Crocolisks"] = "{npc:1152}",
		["Snapjaw Crocolisks bask on the shore and islands along the coast north of {area:35}."] = "{npc:1152}은(는) {area:35} 북쪽 해안을 따라 물가와 섬에서 햇볕을 쬡니다.",
		["Stranglethorn Tigers"] = "{npc:682}",
		["Take the road north; {npc:738} stands on it, the camp sits in the hills to the west."] = "길을 따라 북쪽으로 가세요. {npc:738}은(는) 길 위에 서 있고, 야영지는 서쪽 언덕에 있습니다.",
		["The Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "붉은머리부족 트롤은 네싱워리 야영지 서쪽 해안의 폐허를 차지하고 있습니다.",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents."] = "쿠르젠 반란군이 {area:99} 동쪽 야영지를 차지하고 있습니다. 쿠르젠 밀림전사와 쿠르젠 약사가 서 있는 바깥쪽부터 처리하고, 천막 옆 보급품 상자를 뒤지세요.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "백골가루부족 트롤은 네싱워리와 {object:3202} 사이 길 동쪽의 폐허를 차지하고 있습니다.",
		["The adult tigers prowl the hills just south and west of the camp."] = "다 자란 호랑이는 야영지 바로 남쪽과 서쪽 언덕을 어슬렁거립니다.",
		["The elder tigers come later, on the way back from the {area:99}"] = "덩치큰 가시덤불 호랑이는 나중에 {area:99}에서 돌아오는 길에 잡습니다",
		["The haunted island"] = "유령의 섬",
		["The jungle ruins"] = "밀림의 폐허",
		["The ore drops from Drywhisker kobolds in {zone:1417}"] = "광석은 {zone:1417}의 마른수염 코볼트가 떨어뜨립니다",
		["Thorsen patrols the road north of camp, toward the {area:99}."] = "토르센은 야영지 북쪽, {area:99} 방향 길을 순찰합니다.",
		["Walk back north; the {area:310} lies west of the road in the middle of the jungle. The Crystal Spine Basilisks there drop the shards."] = "북쪽으로 걸어 돌아가세요. {area:310}은(는) 밀림 한가운데, 길 서쪽에 있습니다. 그곳의 {npc:689}이(가) 파편을 떨어뜨립니다.",
		["Young tigers and panthers"] = "새끼 호랑이와 새끼 퓨마",
		["{area:1537} has no druid trainer: take the {area:2257} from {object:171524} to {zone:1453} and train with {npc:5504}."] = "{area:1537}에는 드루이드 상급자가 없습니다. {object:171524}에서 {area:2257}을(를) 타고 {zone:1453}(으)로 가서 {npc:5504}에게 배우세요.",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, {object:263} 상자에서",
		["{npc:2495}, by the bank"] = "{npc:2495}, 은행 옆",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, 선술집 위층",
		["{npc:2832}, in the {object:56910}"] = "{npc:2832}, 뱃사공의 선술집 안",
		["{npc:469}, in the hut"] = "{npc:469}, 오두막 안",
		["{npc:715}, from {zone:1441}"] = "{zone:1441}에서 온 {npc:715}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716}이(가) {item:2755}을(를) 모읍니다. 책장은 밀림의 거의 모든 인간형 몹이 떨어뜨립니다. 모이는 대로 책장을 장(章)으로 묶으세요.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729}와(과) 채찍꼬리랩터",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "거대한 호랑이 {npc:729}은(는) 야영지 남서쪽 언덕 꼭대기에 살고, {npc:686}은(는) 그 남쪽, {area:35}(으)로 가는 길을 따라 뛰어다닙니다.",
		["{npc:737}, in the tavern"] = "{npc:737}, 선술집 안",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}: {area:35}의 {npc:773}에게",
		["{npc:773}, in the tavern"] = "{npc:773}, 선술집 안",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: 사냥꾼 야영지를 둘러보기만 하세요",
		["{quest:207}: four troll legends"] = "{quest:207}: 트롤 전설 4개",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "{npc:2434}이(가) {area:271} 외곽에 보이지 않게 숨어 있습니다. 그를 처치하고 그가 지닌 계약서를 읽으세요.",
		["Back west through {zone:1430} to {area:42}."] = "{zone:1430}을(를) 지나 서쪽으로 {area:42}까지 돌아가세요.",
		["Crushridge ogres"] = "산사태 오우거",
		["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}."] = "각 열쇠는 아라시 고원의 선돌 원 중 하나에 있습니다. 파편 동쪽, {area:320} 근처, 그리고 서쪽입니다. {object:2702}은(는) {area:320} 서쪽에 서 있습니다.",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "길을 따라 동쪽으로 {area:76}까지 가세요. {npc:256028} 몹이 수정을 떨어뜨리고, 노보루는 폐허를 돌아다니며 곤봉을 떨어뜨립니다.",
		["Ebenezer Rustlocke"] = "에벤에셀 러스트로크",
		["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves."] = "학자를 만 북쪽 해변까지 호위하고 그가 작업하는 동안 지키세요. 나가가 여러 차례 공격해 옵니다.",
		["Fly to {area:271}"] = "{area:271}(으)로 날아가세요",
		["Fly to {area:42}"] = "{area:42}(으)로 날아가세요",
		["Fly to {zone:1453}"] = "{zone:1453}(으)로 날아가세요",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "길을 따라 동쪽으로 {area:287}을(를) 나가 {area:1057}을(를) 넘어 {area:320}까지 가세요.",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "길을 따라 북쪽으로 {area:271}을(를) 나가 산으로 들어가세요. 산사자가 비탈을 돌아다니고, {area:280}의 비밀결사대가 인장 반지를 끼고 있으며, {npc:2306}은(는) 마을 북쪽 저택 부지를 돌아다닙니다.",
		["Follow the road north to the draenei of the {area:657}."] = "길을 따라 북쪽으로 {area:657}의 드레나이에게 가세요.",
		["Follow the road south over the bridge to {area:205} at the {zone:1437} end, where {npc:1075} waits."] = "길을 따라 남쪽으로 다리를 건너 {zone:1437} 쪽 끝의 {area:205}까지 가세요. 그곳에서 {npc:1075}이(가) 기다립니다.",
		["For {npc:1440} in {zone:1453}: keep it"] = "{zone:1453}의 {npc:1440}에게: 보관하세요",
		["For {npc:2487} in {area:35}: keep it"] = "{area:35}의 {npc:2487}에게: 보관하세요",
		["For {npc:2542} in {area:35}: keep it"] = "{area:35}의 {npc:2542}에게: 보관하세요",
		["For {npc:2711} in {area:271}"] = "{area:271}의 {npc:2711}에게",
		["From {area:42} follow the road east through {zone:1430} into the {zone:1435}; Biggs guards the road junction just inside it. {npc:217412} stands a short way north of him."] = "{area:42}에서 길을 따라 동쪽으로 {zone:1430}을(를) 지나 {zone:1435}에 들어가세요. 비그스는 그 입구 바로 안쪽의 갈림길을 지킵니다. {npc:217412}은(는) 그의 조금 북쪽에 서 있습니다.",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "{zone:1455}에서 동쪽 굴을 지나 {zone:1426}을(를) 거쳐 {zone:1432}에 들어간 뒤, 길을 따라 {area:144}까지 가세요.",
		["Gyll, {area:35}"] = "가일, {area:35}",
		["Head north past {area:314}; the shards glitter on the hill by the {area:333}."] = "{area:314}을(를) 지나 북쪽으로 가세요. 파편은 {area:333} 옆 언덕에서 반짝입니다.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "가시덤불 골짜기에서 글루글에게 펜던트를 받은 경우에만",
		["Phizzlethorpe"] = "피즐솔프",
		["Ride back north-east past {area:320}; {npc:2712} and {npc:2713} camp in the hills north of {area:314}."] = "{area:320}을(를) 지나 북동쪽으로 돌아가세요. {npc:2712}와(과) {npc:2713}은(는) {area:314} 북쪽 언덕에 진을 치고 있습니다.",
		["Shaman training"] = "주술사 훈련",
		["South-east along the loch to the dig site."] = "호수를 따라 남동쪽으로 발굴 현장까지 가세요.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "남서쪽으로 {area:279} 서쪽 호숫가의 키린 토 야영지로 가세요. {zone:1421} 경계를 막 넘은 곳으로, {npc:269127}이(가) 그곳에 서 있습니다. 대마법사 앤자이럼은 그 남동쪽, 돔 옆에 서 있습니다.",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way."] = "{npc:2713}이(가) {area:314}에 몰래 들어갔다 나오는 동안 곁에 있으세요. 가는 길에 호드 오크가 덤벼듭니다.",
		["Subdue the succubus"] = "서큐버스 제압",
		["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "산사태 오우거는 {area:280} 북쪽 언덕을 차지하고 있습니다. 더 북쪽의 낡은 나무 상자에 {item:3706}이(가) 들어 있고, {quest:537}의 {npc:2320}이(가) 바로 옆에 서 있습니다.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore."] = "마른수염 코볼트는 {area:321}(호드) 동쪽 협곡에서 땅을 팝니다. 마을은 북쪽으로 돌아가세요. 그들은 티끌과 크라젝의 광석을 모두 떨어뜨립니다.",
		["The Syndicate hold the farm north-west of {area:320}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off."] = "비밀결사대가 {area:320} 북서쪽 농장을 차지하고 있습니다. 농장에는 {npc:217589}이(가) 기어다닙니다. {npc:217412}의 곤충학 입문 도구로 한 마리를 잡은 뒤 목록에서 체크하세요.",
		["The Witherbark trolls live in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley."] = "마른나무껍질 트롤은 {area:314} 남쪽 언덕에 삽니다. 의술사는 마을에 서 있고, 어둠사냥꾼은 계곡 맨 끝을 지킵니다.",
		["The courier walks the road west of {area:314} with two guards; pull them off the road."] = "급사는 경비병 둘과 함께 {area:314} 서쪽 길을 걸어다닙니다. 길에서 끌어내세요.",
		["The shards lie at the far end of {area:318}."] = "파편은 {area:318}의 맨 끝에 있습니다.",
		["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins."] = "고서는 {area:280} 서쪽의 무너진 성채에 있습니다. 아르거스재림회 어둠마법사가 폐허를 차지하고 있습니다.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "난파선 두 척은 만 서쪽 바다에 있습니다. 해도와 일지는 배 안에 있고, 보석은 주변 바다 바닥에 있습니다. 비수가시일족 나가가 바다 전체를 헤엄칩니다.",
		["The western swamp"] = "서쪽 늪",
		["The wrecked caravan lies off the road near Biggs."] = "부서진 대상단 마차는 비그스 근처 길가에 있습니다.",
		["The wrecks"] = "난파선",
		["Walk back onto the span: Ebenezer lies under its Arathi end."] = "다리 위로 다시 걸어가세요. 에벤에셀은 다리의 아라시 쪽 끝 아래에 쓰러져 있습니다.",
		["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "해안을 따라 서쪽으로 고블린의 만까지 가세요. 롤로는 그 위 바위에서 망을 봅니다.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "새끼 악어, 늪그물거미, 늪지재규어가 모두 길 주변 늪을 돌아다닙니다.",
		["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{npc:2438}의 망토용 {item:2321}, 없다면 {npc:2381}에게서",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, {area:17203} 길",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, 빛의 대성당",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, 성채 안 왕실 도서관",
		["{npc:185335}, at the same circle"] = "{npc:185335}, 같은 소환진에서",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: 아라시, {zone:1443}, 가시덤불 골짜기에서 잡을 동물 세 마리",
		["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589}: {quest:93176}을(를) 위해 잡으세요",
		["{npc:252085}, in the City of Dalaran"] = "{npc:252085}, 달라란 도시 안",
		["{npc:2712} and {npc:2713}"] = "{npc:2712}와(과) {npc:2713}",
		["{npc:2713}'s errand"] = "{npc:2713}의 심부름",
		["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "오우거 마법사 {npc:2793}은(는) 마른나무껍질 계곡 남쪽 끝의 동굴을 차지하고 있습니다.",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391}은(는) 성역 북쪽 끝에 갇혀 있습니다. 그를 풀어주고 나가는 동안 살려두세요. 그 후 그의 금고가 길가에서 기다립니다.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122}이(가) 인큐버스를 당신에게 귀속시킵니다",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122}은(는) {object:2101}에 있는 {object:2164}의 지하실에서 기다립니다. 그곳 소환진에서 {item:6913}을(를) 사용하고 나타나는 서큐버스를 물리치세요. {quest:65602}을(를) 받았다면 그에게 {item:190309}도 건네고, 같은 소환진에 놓은 뒤 인큐버스를 물리치세요.",
		["{quest:65602}, if you took it"] = "{quest:65602}, 받았다면",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455} and train with {npc:258098}. {npc:1573} in the {object:32372} flies to {area:271} too."] = "{zone:1453}에는 주술사 상급자가 없습니다. {object:28027}에서 {area:2257}을(를) 타고 {zone:1455}(으)로 가서 {npc:258098}에게 훈련을 받으세요. {object:32372}의 {npc:1573}도 {area:271}(으)로 날아갑니다.",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Fly to Theramore"] = "테라모어 섬으로 비행",
		["Follow the road north to {area:608}."] = "길을 따라 북쪽 {area:608}(으)로 가십시오.",
		["Follow the road south to {area:2407}."] = "길을 따라 남쪽 {area:2407}(으)로 가십시오.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}; the wrecked ship's chest lies on the shore just west of them."] = "길을 따라 {zone:1443} 북부를 가로질러 서쪽 {area:2405} 폐허로 가십시오. 난파선의 궤짝은 그 바로 서쪽 해안에 있습니다.",
		["Greater Rock Elementals"] = "상급 바위 정령",
		["Lesser Rock Elementals"] = "하급 바위 정령",
		["Maraudine centaurs"] = "마라우돈일족 켄타우로스",
		["Ogres and buzzards"] = "오우거와 대머리수리",
		["Ride back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "서쪽 길로 돌아가 남쪽으로 따라가 고개를 지나 {zone:1432}에서 {zone:1418}(으)로 가십시오. {npc:2910}와(과) {npc:2860}은(는) 발굴 현장에 나란히 야영하고 있습니다.",
		["Ride north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "북동쪽 버려진 발굴 현장으로 가십시오. 보급품 상자는 먼지목도리 오우거들 사이에 있습니다.",
		["Ride north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "북동쪽 {zone:1418} 북부의 드워프 폐허로 가십시오. 궤짝은 어둠괴철로단 드워프들 사이에 있습니다. 근처의 {npc:2745}은(는) 정예이니 거리를 두십시오.",
		["Ride south to {area:345}."] = "남쪽 {area:345}(으)로 가십시오.",
		["Ride west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "서쪽 {area:1878}(으)로 가십시오. {npc:2921}은(는) 그 한가운데 기계 옆에서 일합니다.",
		["Rock Elementals"] = "바위 정령",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "라이돌의 다음 심부름은 {area:1517}(으)로 가니 건너뛰십시오.",
		["Shadowforge camp"] = "어둠괴철로단 야영지",
		["Take the boat to Theramore from the far pier."] = "가장 먼 부두에서 테라모어 섬행 배를 타십시오.",
		["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east."] = "먼지목도리 오우거가 골짜기 바로 남쪽에 야영하며, 누구든 고철을 떨어뜨립니다. 대머리수리는 동쪽 평원을 맴돕니다.",
		["The Greater Rock Elementals (level 42) walk the far south-west corner below {area:342}; pull them one at a time. The Dustbelcher Wyrmhunters and Maulers at {area:342} also drop scrap."] = "상급 바위 정령(42레벨)은 {area:342} 아래 남서쪽 끝을 걷습니다. 하나씩 끌어오십시오. {area:342}의 먼지목도리일족 고룡사냥꾼과 먼지목도리일족 싸움꾼도 고철을 떨어뜨립니다.",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}."] = "하급 바위 정령이 {npc:2921} 서쪽 {area:1878}을(를) 돌아다닙니다.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "마라우돈일족 켄타우로스가 무덤 서쪽 {area:607}을(를) 차지하고 있으며, 모든 종류가 토템을 떨어뜨립니다.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "{npc:92}은(는) {npc:2921}의 남동쪽을 돌아다니고, {npc:2831}와(과) {npc:2729}은(는) 그 서쪽 평원에 함께 있습니다.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "어둠괴철로단 드워프들이 발굴 현장 바로 북쪽에 야영하고 있으며, 구겨진 지도는 천막 사이에 있습니다. 어둠괴철로단 채굴꾼과 어둠괴철로단 흑마술사가 라이돌의 행운의 곡괭이를 가지고 있습니다. 바위산코요테가 주변 비탈을 돌아다닙니다.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "부서진 해골은 오우거 바로 동쪽, 바위동굴일족 트로그 야영지 가장자리에 있습니다. 주변의 바위동굴일족 뼈다귀싸움꾼과 바위동굴일족 주술사가 조각을 떨어뜨립니다. 실성한 텔두린은 더 남쪽의 폐허가 된 야영지 옆에 앉아 있습니다.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "조개는 다음 가이드의 가시덤불 골짜기 북서 해안에 있습니다. 보관하십시오",
		["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit."] = "악마들은 {zone:1443} 남부의 {area:602}에 모여 있습니다: 구덩이 주변의 지옥사냥개(마나먹는 지옥사냥개, 마법사 사냥개, 평원의 지옥사냥개), 황천의 요녀와 황천의 마녀, 파멸의경비대 부대장.",
		["The excavation crate"] = "발굴 상자",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "비행 조련사는 {area:514} 성문 옆에 있으며, {npc:5083}와(과) {npc:4964}은(는) 성채 안에 있습니다.",
		["The next guide starts in Theramore."] = "다음 가이드는 테라모어 섬에서 시작합니다.",
		["The skeleton's next task, Murdaloc, waits until the later {zone:1418} guide at 43."] = "해골의 다음 임무인 멀달록은 43레벨의 이후 {zone:1418} 가이드까지 미룹니다.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["Theramore"] = "테라모어 섬",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "언데드 약탈자가 소굴 동쪽, 마그람 마을 남쪽의 뼈 들판을 돌아다닙니다. 남동쪽 끝에서 {item:15848}을(를) 사용해 마그람일족 유령을 불러내십시오.",
		["escort {npc:12277} back toward the graveyard"] = "{npc:12277}을(를) 무덤 쪽으로 호위",
		["for the Dustwallow loop in the next guide"] = "다음 가이드의 먼지진흙 습지대 경로용",
		["for {npc:2786} in {zone:1455}: keep it"] = "{zone:1455}의 {npc:2786}에게: 보관하십시오",
		["for {npc:3980} in {area:271}: keep it"] = "{area:271}의 {npc:3980}에게: 보관하십시오",
		["for {npc:4454} in the {area:439}: the {zone:1446} guide crosses them at 45, keep it"] = "{area:439}의 {npc:4454}에게: {zone:1446} 가이드가 45레벨에 지나갑니다. 보관하십시오",
		["for {npc:5637} in {zone:1455}: keep it"] = "{zone:1455}의 {npc:5637}에게: 보관하십시오",
		["only if you carry {item:2868} (a blacksmith's craft)"] = "{item:2868}(대장기술 제작품)을 가지고 있을 때만",
		["{npc:11626}'s caravan stops on the road east of {area:606}. Take the quest and walk with the kodos past the {area:602}, killing the demons that jump them; talk to {npc:11596} at his camp east of the {area:596} afterwards."] = "{npc:11626}의 대상단은 {area:606} 동쪽 길에 멈춥니다. 퀘스트를 수락하고 코도와 함께 {area:602}을(를) 지나며 덤벼드는 악마를 처치하십시오. 그다음 {area:596} 동쪽 야영지의 {npc:11596}와(과) 대화하십시오.",
		["{npc:11863}'s tower stands on the hill east of the wreck."] = "{npc:11863}의 탑은 난파선 동쪽 언덕에 있습니다.",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard."] = "{npc:12277}은(는) 무덤 서쪽 켄타우로스 야영지에 갇혀 있습니다. 풀어 주고 나가는 동안 살려 두십시오. 무덤 옆에서 멈춥니다.",
		["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "켄타우로스 족장 {npc:12369}은(는) {npc:11863}의 탑 북쪽, 북서 해안에 야영하고 있습니다.",
		["{npc:1470}, in the inn"] = "{npc:1470}, 여관 안",
		["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}: 잡으십시오, My Little Friends용",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, {npc:2921} 옆",
		["{npc:2921}'s next test needs crafted gear: skip it."] = "{npc:2921}의 다음 실험에는 제작 장비가 필요하니 건너뛰십시오.",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618}와(과) {npc:2817}은(는) {zone:1418} 한가운데 {area:1877}에 함께 야영하고 있습니다.",
		["{npc:5638}'s next task, {item:6245}, is a drop on the far coast: skip it."] = "{npc:5638}의 다음 임무인 {item:6245}은(는) 먼 해안에서 떨어지는 아이템이니 건너뛰십시오.",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons. A {npc:217590} crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off."] = "{npc:6019}은(는) {area:2407} 남서쪽 {area:596} 가장자리에 있습니다. {object:176751}은(는) 해골들 사이에 있습니다. {npc:217590}이(가) 무덤 주변을 기어다니니 Entomology Starter Kit로 잡은 뒤 체크하십시오.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "\"말썽꾼\" 이그나츠",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. No Skyborne riding trainer is known; the Forever client files {spell:1285849} under the one Riding skill, so {npc:4732} at {area:88} in eastern {zone:1429}, the nearest trainer to {zone:1453}, should teach it (unconfirmed). The Galestriders are sold by {npc:265756} in {area:16638} on Zephras Isle; Collectibles, Mounts · Level 40 lists them."] = "40레벨에 100골드가 있으면 탈것 타기를 배울 수 있으며, 배우면 탈것도 하나 받습니다. 스카이본 탈것 상급자는 알려져 있지 않습니다. Forever 클라이언트는 {spell:1285849}을(를) 하나의 탈것 타기 기술로 분류하므로, {zone:1453}에서 가장 가까운 {zone:1429} 동부 {area:88}의 {npc:4732}이(가) 가르칠 것입니다(확인되지 않음). 돌풍타조는 제프라스 섬 {area:16638}의 {npc:265756}이(가) 팝니다. 수집품, 탈것 · 레벨 40에 나옵니다.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40레벨에 100골드가 있으면 탈것 타기를 배울 수 있으며, 배우면 탈것도 하나 받습니다. {npc:4732}은(는) {zone:1429} 동부 {area:88}의 {npc:384}의 말 옆에서 인간에게 가르칩니다. Forever에서는 어느 종족이든 아무 탈것 상급자에게 배울 수 있을지도 모릅니다(확인되지 않음). 수집품, 탈것 · 레벨 40에 모든 색상이 나옵니다.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "40레벨에 100골드가 있으면 탈것 타기를 배울 수 있으며, 배우면 탈것도 하나 받습니다. {npc:4753}은(는) {zone:1457}의 {npc:4730}의 표범 옆에서 나이트 엘프에게 가르칩니다. {area:17203}에서 배를 타고 {area:442}(으)로 간 뒤 {area:702}(으)로 날아가세요. Forever에서는 어느 종족이든 {zone:1429} {area:88}의 {npc:4732} 같은 아무 탈것 상급자에게 배울 수 있을지도 모릅니다(확인되지 않음). 수집품, 탈것 · 레벨 40에 모든 색상이 나옵니다.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40레벨에 100골드가 있으면 탈것 타기를 배울 수 있으며, 배우면 탈것도 하나 받습니다. {npc:4772}은(는) {area:131} 동쪽, {zone:1432}(으)로 가는 길의 {area:803}에서 {npc:1261}의 산양 옆에서 드워프에게 가르칩니다. Forever에서는 어느 종족이든 아무 탈것 상급자에게 배울 수 있을지도 모릅니다(확인되지 않음). 수집품, 탈것 · 레벨 40에 모든 색상이 나옵니다.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40레벨에 100골드가 있으면 탈것 타기를 배울 수 있으며, 배우면 탈것도 하나 받습니다. {npc:7954}은(는) {area:131} 바로 동쪽 {area:189}에서 {npc:7955}의 기계타조 옆에서 노움에게 가르칩니다. Forever에서는 어느 종족이든 아무 탈것 상급자에게 배울 수 있을지도 모릅니다(확인되지 않음). 수집품, 탈것 · 레벨 40에 모든 색상이 나옵니다.",
		["Back in Theramore: Tervosh waits with Lady Jaina in the tower of {area:514}."] = "테라모어로 돌아가세요. 테르보쉬는 {area:514} 탑에서 제이나와 함께 기다립니다.",
		["Bloodsail camp"] = "붉은해적단 야영지",
		["Bloodsail pirates"] = "붉은해적단 해적",
		["Boat to {area:35}"] = "배를 타고 {area:35}(으)로",
		["Cold Eye Basilisks"] = "{npc:690}",
		["Defeat the challengers and {npc:6238}"] = "도전자들과 {npc:6238} 물리치기",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "붉은해적단은 모두 코담배를 떨어뜨리고, 그중 하나가 {npc:2493}의 눈을 가지고 있습니다. 붉은해적단 칼잡이는 마을 바로 북쪽 해안을 걸어다닙니다. 해도와 명령서는 {area:35} 남쪽 {area:43}의 해적 야영지에 있습니다.",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "잔질의 추종자는 누구나 혼합물을 떨어뜨릴 수 있습니다. {npc:2537}은(는) 야영지 남쪽을 걸어다닙니다.",
		["Fly to {area:42} and ride east through {zone:1430} into the {zone:1435}; {npc:5476} stands by the road just past the border."] = "{area:42}(으)로 날아간 뒤 동쪽으로 {zone:1430}을(를) 지나 {zone:1435}에 들어가세요. {npc:5476}은(는) 경계를 막 지난 길가에 서 있습니다.",
		["Follow the road east back to Theramore. Tervosh, Lady Jaina and the officers are in the tower and {area:514}."] = "길을 따라 동쪽으로 테라모어에 돌아가세요. 테르보쉬, 제이나, 장교들은 탑과 {area:514}에 있습니다.",
		["Follow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals."] = "길을 따라 북동쪽 {area:310}의 투자개발회사 야영지로 가세요. 광부, 감시관, 현장감독이 수정을 떨어뜨립니다.",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it."] = "길을 따라 북서쪽으로 테라모어를 나가 {area:503}의 감시탑으로 가세요. {npc:4398}이(가) 그 주변 습지를 돌아다닙니다.",
		["Galestriders: {npc:265756}, in {area:16638} on Zephras Isle."] = "돌풍타조: 제프라스 섬 {area:16638}의 {npc:265756}.",
		["Gorilla hills"] = "고릴라 언덕",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "송곳니를 제출하고 그대로 있으세요. 고릴라가 세 차례 몰려오고 마지막에 {npc:1514}이(가) 나옵니다. 생명력이 가득한 상태로 싸우세요.",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "터널로 마을을 나가 해안을 따라 북쪽으로 가세요. 편지는 \"꽃미남\" 던컨이 걸어다니는 해변의 붉은해적단 야영지에 있습니다.",
		["MacKinley's next task sends you after elite ogres: skip it."] = "맥킨리의 다음 임무는 정예 오우거를 잡으러 보냅니다. 건너뛰세요.",
		["Mirefin murlocs"] = "진흙아가미멀록",
		["Mudrock tortoises"] = "진흙바위거북",
		["Naga Explorers"] = "{npc:1907}",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "{area:392}(으)로 북쪽으로 가는 길에, {area:720}은(는) 마을 남쪽 {area:391} 앞바다에 있습니다. 모래톱 얕은 물을 걸어서 건너가세요. {npc:6236}이(가) 도전자 넷을, 이어서 {npc:6238}(33레벨)을(를) 하나씩 보냅니다.",
		["Paladin: {quest:1661}"] = "성기사: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "마을로 다시 내려가세요. 겁쟁이 필립은 터널 입구에 서 있습니다.",
		["Ride back west along the road; {npc:217412} stands a short way north of Biggs."] = "길을 따라 서쪽으로 돌아가세요. {npc:217412}은(는) 빅스 조금 북쪽에 서 있습니다.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "동쪽으로 가세요. 가는 길의 {npc:766}도 평론을 떨어뜨립니다. 사원 폐허가 수면 위로 드러난 {area:74} 가장자리를 찾아보세요.",
		["Ride from Theramore west along the Dustwallow road into the {zone:1413} and north to {area:392} on the coast. Learn the flight path from {npc:16227}, then take the boat to {area:35} from the dock."] = "테라모어에서 먼지진흙 습지대 길을 따라 서쪽으로 {zone:1413}에 들어간 뒤, 북쪽으로 해안의 {area:392}까지 가세요. {npc:16227}에게서 비행 경로를 배운 뒤 부두에서 배를 타고 {area:35}(으)로 가세요.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "내륙의 안개계곡 고릴라 언덕으로 가세요. {npc:1557}이(가) 내장을 떨어뜨리며, {npc:1449}은(는) 그들 사이에 앉아 있습니다.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "북쪽으로 길 서쪽 언덕에 가세요. {npc:2535}와(과) {npc:2536}은(는) 잔질의 마을 바로 북쪽에 함께 서 있습니다.",
		["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an {npc:217588} crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off."] = "네싱워리 야영지를 지나 북동쪽으로 간 뒤 길을 따라 북쪽, 골짜기 맨 위의 야영지로 가세요. 가는 길에 네싱워리 야영지 남동쪽 밀림에 {npc:217588}이(가) 기어다닙니다. 초보 곤충학자의 도구로 하나를 잡은 뒤 체크하세요.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "광산에서 북서쪽으로 북서 해안의 만까지 가세요. 바닥에 있는 거대한 대합에 진주가 들어 있습니다. {npc:2624}이(가) 그 사이를 헤엄치며 {item:4034}을(를) 떨어뜨립니다.",
		["Ride south to the giant's hut in the middle of the marsh."] = "남쪽으로 습지 한가운데의 거인 오두막으로 가세요.",
		["Riding at 40"] = "40레벨 탈것 타기",
		["Seahorn's next errand goes back to Arathi: skip it."] = "시혼의 다음 심부름은 아라시로 돌아갑니다. 건너뛰세요.",
		["Skullsplitter ruins"] = "백골가루부족 폐허",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "이그나츠는 오두막 서쪽, {area:504} 아래 습지에서 기다립니다. 그를 늪콩 잎사귀가 있는 곳으로 데려가며 늪의 짐승들이 그를 공격하지 못하게 막으세요.",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house."] = "길을 따라 북쪽의 폐허가 된 오두막으로 가세요. 자를은 그 옆 판잣집에 살고, 흐트러진 흙은 집 모퉁이에 있습니다.",
		["Take the {area:2257} from the {object:28027}. {npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:1356} in the hall itself, {npc:2786} in the {object:32383}. The next guide flies on to {area:144}."] = "{object:28027}에서 {area:2257}을(를) 타세요. {npc:5637}은(는) {object:32356} 옆 개척자 연맹 전당에, {npc:1356}은(는) 전당 안에, {npc:2786}은(는) {object:32383}에 있습니다. 다음 가이드에서 {area:144}(으)로 날아갑니다.",
		["The Bloodsail captains"] = "붉은해적단 선장들",
		["The Cold Eye Basilisks lie on the rocks west of the mine."] = "{npc:690}은(는) 광산 서쪽 바위 위에 엎드려 있습니다.",
		["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes."] = "암흑안개 거미는 습지 북서쪽 거미굴 주변에 둥지를 틀고 있습니다. 거미는 모두 눈알을 떨어뜨립니다.",
		["The Mirefin murlocs crowd the north coast past {area:497}; finish the tongues on the tortoises beside them."] = "진흙아가미멀록은 {area:497} 너머 북쪽 해안에 모여 있습니다. 혀는 그 옆의 거북에게서 마저 모으세요.",
		["The Mudrock Tortoises and Spikeshells sun themselves on the shore north-east of the manor."] = "{npc:4396}와(과) 뾰족껍질 진흙바위거북은 오두막 북동쪽 물가에서 햇볕을 쬡니다.",
		["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do."] = "백골가루부족 트롤은 광산 바로 동쪽 폐허를 차지하고 있습니다. 누구든 엄니를 떨어뜨릴 수 있고, 그들의 퓨마는 항상 떨어뜨립니다.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes and the hoofprints are in the mud beside the inn."] = "불탄 여관은 서쪽 길, {zone:1413} 방향에 있습니다. 경비병의 휘장은 잿더미 속에, 발굽 자국은 여관 옆 진흙에 있습니다.",
		["The captains stand on the ships anchored off the {area:43}, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, {npc:2546} (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore."] = "선장들은 {area:43} 앞바다에 정박한 배 위에 있으며, 각자 42-45레벨 해적 선원을 거느립니다. 가까운 갑판에는 스틸워터(45)와 킬하울(46), 기함에는 {npc:2546}(48)이 있습니다. 42레벨이라면 파티로 하거나 가이드 끝에 할 전투입니다. 간다면 갑판마다 먼저 정리하세요. 코르텔로의 두루마리는 물가의 난파선에 있습니다.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "탈영병들은 {npc:4503}의 오두막 서쪽, 길 남쪽에 진을 치고 있습니다.",
		["The driftwood washes up along the eastern shore."] = "유목은 동쪽 해안을 따라 떠밀려 옵니다.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "나가는 붉은해적단 야영지 북쪽 해변을 뒤지고 다니며, 갈대를 떨어뜨립니다.",
		["The north-west coast"] = "북서쪽 해안",
		["The riddle's next scroll lies in western Dustwallow: skip it."] = "수수께끼의 다음 두루마리는 먼지진흙 습지대 서부에 있습니다. 건너뛰세요.",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "두루마리는 빅스 북쪽 습지에 있습니다. 그 북쪽의 늪괴물이 카드가의 평론을 떨어뜨릴 수 있습니다.",
		["The sunken temple"] = "가라앉은 사원",
		["Theramore"] = "테라모어",
		["Unbagwa's ritual"] = "운바그와의 의식",
		["Warlock: {quest:3631}"] = "흑마법사: {quest:3631}",
		["Zanzil's village"] = "잔질의 마을",
		["for Stoley in {zone:1446}: keep it"] = "{zone:1446}의 스톨리에게 줄 것: 보관하세요",
		["for the {zone:1435} later"] = "나중에 {zone:1435}에 쓸 것",
		["for {area:1438}: keep it"] = "{area:1438}에 쓸 것: 보관하세요",
		["for {npc:2616} in Theramore: keep it"] = "테라모어의 {npc:2616}에게 줄 것: 보관하세요",
		["for {npc:5635} at {area:348}: keep it"] = "{area:348}의 {npc:5635}에게 줄 것: 보관하세요",
		["for {npc:770} at the {area:99}, on the northern loop"] = "북쪽 순환 경로에서 {area:99}의 {npc:770}에게",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "{item:3853}(대장장이 제작품)을 가지고 있을 때만",
		["with the spices from Theramore"] = "테라모어에서 산 향신료를 가지고",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, \"늪지눈알\" 자를에게 줄 것",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141}은(는) {object:2169}에서 요리하고, {npc:5384}은(는) {object:28027}에 있습니다.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: 다른 색상, 20골드",
		["{npc:1356}: for {npc:1344} in {zone:1432}, keep it"] = "{npc:1356}: {zone:1432}의 {npc:1344}에게 줄 것, 보관하세요",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, {object:2117}의 왕실 도서관",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: 30-40/05-arathi-highlands에서 받은 {quest:93176}",
		["{npc:217588}: catch it, for {quest:93176}"] = "{npc:217588}: {quest:93176}을(를) 위해 잡으세요",
		["{npc:2487}, top floor"] = "{npc:2487}, 꼭대기 층",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "{npc:2498}의 다음 잔질 심부름은 {zone:1441}에서 시작합니다. 건너뛰세요.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535}와(과) {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624}은(는) 북쪽 순환 경로 중 북서쪽 해안 앞바다에서 헤엄칩니다",
		["{npc:384}: other colours, 20g"] = "{npc:384}: 다른 색상, 20골드",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, {object:2164} 안: 다음 가이드 끝에 {area:392}의 {npc:6251}이(가) 받습니다",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: 다른 색상, 20골드",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields."] = "{npc:4966}은(는) 탈영병 몇 명과 함께 탑을 지키고 있습니다. 그가 당신에게 덤벼드니 굴복할 때까지 때리세요.",
		["{npc:5694}: for {area:1438}, keep it"] = "{npc:5694}: {area:1438}에 쓸 것, 보관하세요",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, 빛의 대성당 안",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236}은(는) 다음으로 바람의감시자(1791)를 줍니다. 끝에 정예가 나오는 소용돌이 무기 퀘스트 연계는 전사 직업 가이드 소용돌이 무기에 있습니다.",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: {zone:1446}의 {quest:2864}에게 줄 것, 보관하세요",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: 다른 색상, 20골드",
		["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910}은(는) 항구 위의 높은 건물입니다. 퀘스트 제공자 대부분이 그 층들이나 아래 부두에 있습니다.",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260}은(는) 여관 근처에 서 있습니다. 몇 걸음 남쪽의 거래 물품 상인 {npc:4897}이(가) 자를이 원하는 향신료를 팝니다.",
		["{zone:1453} has no shaman trainer"] = "{zone:1453}에는 주술사 상급자가 없습니다",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "가시덤불 골짜기의 푸른 진주",
		["Fly to {area:392}; {npc:6251} teaches in the house by the bank. Fly back to Theramore afterwards."] = "{area:392}(으)로 비행하십시오. {npc:6251}은(는) 은행 옆 집에서 가르칩니다. 이후 테라모어 섬으로 돌아오십시오.",
		["Fly to {area:608}, ride south through {zone:1443} into {zone:1444} and follow the road to the dock on the {area:1108}; the boat crosses to {area:1116}, where the next guide starts."] = "{area:608}(으)로 비행한 뒤 남쪽으로 {zone:1443}을(를) 지나 {zone:1444}(으)로 가서 {area:1108}의 부두까지 길을 따라가십시오. 배가 {area:1116}(으)로 건너가며, 그곳에서 다음 가이드가 시작합니다.",
		["On to Feathermoon"] = "페더문 요새로",
		["Raleigh's next errand is in the {area:796}: skip it."] = "랄레이의 다음 심부름은 {area:796}에 있으니 건너뛰십시오.",
		["Ride back east to {area:1898}."] = "동쪽 {area:1898}(으)로 돌아가십시오.",
		["Ride north to {area:144} and fly to {area:271}. {npc:3980} preaches by the inn."] = "북쪽 {area:144}(으)로 가서 {area:271}(으)로 비행하십시오. {npc:3980}은(는) 여관 옆에서 설교합니다.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "길을 따라 북동쪽으로 {area:271}을(를) 빠져나가 {zone:1425}로 가십시오. {area:348}은(는) 경계 바로 너머에 있습니다. {npc:5635}은(는) 꼭대기에, {quest:1450}은(는) 그리핀 둥지에, {npc:7884}은(는) 여관 옆에 있습니다.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "남쪽 고개를 지나 {zone:1432}에서 {zone:1418}(으)로 가십시오. {npc:2860}은(는) 발굴 현장에 야영하고 있습니다.",
		["Ride west across the {zone:1418} to the Dustbelcher camp at {area:342}. {npc:2944} stands in its middle with Wyrmhunters and Maulers around him."] = "{zone:1418}을(를) 가로질러 서쪽 {area:342}의 먼지목도리 야영지로 가십시오. {npc:2944}은(는) 그 한가운데에 있으며 주위에 먼지목도리일족 고룡사냥꾼과 먼지목도리일족 싸움꾼이 있습니다.",
		["Ride west to the {area:1877} in the middle of the {zone:1418}; {npc:2817} camps beside Martek."] = "서쪽 {zone:1418} 한가운데의 {area:1877}(으)로 가십시오. {npc:2817}은(는) 망명자 마르텍 옆에 야영하고 있습니다.",
		["Take the boat to Theramore from the far pier."] = "가장 먼 부두에서 테라모어 섬행 배를 타십시오.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "탈론액스의 다음 임무는 이후 {zone:1425} 가이드에서 합니다.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "화염의 새끼비룡은 {npc:2888} 동쪽 협곡에 둥지를 틀고 있습니다. 화염의 수호비룡(정예)은 건드리지 마십시오. {item:4612}은(는) 드물게 떨어지니 사냥 중에 나오면 챙기십시오.",
		["The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers."] = "부서진 해골은 바위동굴일족 트로그 야영지 가장자리에 있습니다. 아그몬드를 죽인 {quest:739}은(는) 바위동굴일족 뼈다귀싸움꾼들 사이를 걷습니다.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "처음 두 우리는 {npc:5634} 남쪽 마른나무껍질 마을에 함께 있고, 세 번째는 동쪽의 다음 마을에 있습니다. 모든 마른나무껍질 트롤이 목걸이를 떨어뜨릴 수 있습니다.",
		["Theramore"] = "테라모어 섬",
		["Warlock: {quest:3631}"] = "흑마법사: {quest:3631}",
		["Witherbark villages"] = "마른나무껍질 마을",
		["grind on {npc:2725} at {area:339}, {zone:1418}"] = "{zone:1418} {area:339}에서 {npc:2725} 사냥",
		["{npc:1573}, the {object:32372}"] = "{npc:1573}, {object:32372}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616}은(는) 배가 도착하는 부두에 있습니다.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "{npc:2817}의 다음 퀘스트는 경험치를 주지 않으니 건너뛰십시오.",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888}은(는) 발굴 현장 남동쪽 {area:1898}에 홀로 야영하고 있습니다.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "{npc:2888}의 다음 임무는 정예 사냥이니 건너뛰십시오.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634}은(는) {area:348} 동쪽 길가에 야영하고 있습니다.",
		["{npc:5634}'s cocktail needs parts from Kalimdor: skip it."] = "{npc:5634}의 칵테일에는 칼림도어의 재료가 필요하니 건너뛰십시오.",
		["{npc:5636}, beside the flight master at the top"] = "{npc:5636}, 꼭대기의 비행 조련사 옆",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884}은(는) 목걸이를 계속 받습니다. 남는 것은 제출하십시오",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "{area:1117}(으)로 돌아가십시오. 그곳의 증오의갈기일족 나가는 모두 비늘을 떨어뜨릴 수 있습니다.",
		["Boat to the {area:1108} and ride east across {zone:1444} to the Grimtotem camp north of the road. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "배를 타고 {area:1108}(으)로 가서 {zone:1444}을(를) 가로질러 동쪽, 길 북쪽의 그림토템 주둔지까지 가십시오. {npc:7956}은(는) 그 밖에서 기다립니다. 한가운데 우리에서 화살요정용을 풀어 주고, {npc:7956}과 화살요정용을 적어도 여섯 마리 살려 두십시오.",
		["Boat to the {area:1108} and ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45."] = "배를 타고 {area:1108}(으)로 가서 동쪽 {area:1105}(으)로 가십시오. 해안에 있는 {npc:14637}의 퀘스트는 45레벨이 필요합니다.",
		["From Theramore, fly to {area:608} and ride south out of {zone:1443} into {zone:1444}; the road leads west to the {area:1108} dock, where the boat crosses to Feathermoon on {area:1120}."] = "테라모어 섬에서 {area:608}(으)로 날아간 다음, 남쪽으로 {zone:1443}을(를) 벗어나 {zone:1444}(으)로 가십시오. 길은 서쪽 {area:1108} 부두로 이어지고, 그곳에서 배를 타고 {area:1120}의 페더문 요새로 건너갑니다.",
		["Giants and elementals"] = "거인과 정령",
		["Gordunni ogres"] = "골두니일족 오우거",
		["Grimtotem camp"] = "그림토템 야영지",
		["Grimtotem tauren"] = "그림토템 타우렌",
		["Grind to 45"] = "45레벨까지 사냥",
		["Hatecrest naga"] = "증오의갈기일족 나가",
		["Hearth to Feathermoon."] = "귀환석으로 페더문 요새에 가십시오.",
		["Rage Scar yetis"] = "분노한 무쇠설인",
		["Ride back north-west to the {area:1108} dock and take the boat to the island."] = "북서쪽 {area:1108} 부두로 돌아가 배를 타고 섬으로 가십시오.",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "{area:1108}(으)로 돌아가십시오. 고블린은 부두 옆에 있습니다.",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "길을 따라 서쪽으로 돌아간 다음 북쪽 무쇠설인 소굴 언덕으로 가십시오. 이곳의 설인은 모두 가죽을 떨어뜨릴 수 있고, {quest:7735}이(가) 나올 수도 있습니다. 이것도 {npc:7852}이(가) 값을 쳐 줍니다.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "동쪽으로 설인 골짜기 남동쪽 언덕의 골두니 전초기지까지 가십시오. 골두니일족 흑마법사와 골두니일족 주술사가 야영지를 지키고, 골두니일족 투사는 주변 비탈과 더 북쪽을 돌아다닙니다.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "북쪽 설인 골짜기로 들어가십시오. 원시설인은 모두 두꺼운 설인 가죽을 떨어뜨릴 수 있습니다. {npc:5346}(48레벨)은(는) 한가운데를 배회합니다.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "북동쪽으로 {zone:1441} 경계의 나이트 엘프 전초기지까지 가십시오.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "남동쪽의 덩굴발일족 놀에게 가십시오. 전령의 배낭은 남쪽 야영지에 있고, 그 안의 꾸러미로 {area:489} 배달이 시작됩니다. 바로 남쪽이 고통의 구덩이입니다: 안내원 라스칼이 갇힌 고치까지 싸우며 내려가 그를 풀어 주고, 나가는 동안 살려 두십시오.",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "서쪽으로 언덕 기슭의 우호적인 산거인에게 가십시오. 주변의 평지거인과 절벽거인은 정예이니 거리를 두십시오.",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "{npc:7774}이(가) 멈춰서 헤맬 때마다 종을 울리고, 남쪽의 {npc:7765}에게 데려가십시오.",
		["Running {area:978} instead of grinding gets you there faster in a group. The troll city lies in northern {zone:1446}, the next zone on the route; come back to {npc:14637} on the {area:1108} afterwards."] = "파티로 사냥 대신 {area:978}을(를) 돌면 더 빨리 도달합니다. 트롤 도시는 경로상 다음 지역인 {zone:1446} 북쪽에 있습니다. 그 후 {area:1108}의 {npc:14637}에게 돌아오십시오.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "성큼걸이 해안거인, 성큼걸이 바다거인, 성큼걸이 파도거인(정예 거인)이 부두 북쪽 해안을 걸어다닙니다: {item:18904}(으)로 하나를 쏘고 작아진 거인을 처치하십시오. 바다 정령과 바다 물보라 정령도 같은 파도 속을 떠다닙니다.",
		["Swim south from the island to the {area:1121}. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "섬에서 남쪽으로 헤엄쳐 {area:1121}(으)로 가십시오. 증오의갈기일족 수호병과 증오의갈기일족 여마법사가 지키고 있으며, {npc:8136}(47레벨)은(는) 남쪽 끝 동굴에 있습니다. 경비병부터 끌어내십시오.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "배를 타고 {area:1108}(으)로 가서 해안을 따라 남쪽으로, 해변에 부서진 나룻배까지 가십시오.",
		["The courier's boat"] = "전령의 배",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "섬을 따라 남쪽의 나가 폐허로 걸어가십시오. 정자는 폐허 사이에 있습니다.",
		["You end at the {area:1108} dock: the {zone:1446} guide starts with the trip east from here."] = "{area:1108} 부두에서 끝납니다: {zone:1446} 가이드는 여기서 동쪽으로 가는 길로 시작합니다.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "{zone:1457}의 티란데 위스퍼윈드에게: 경로상 47레벨에 그곳에 갑니다",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "{zone:1444} {area:1105}에서 {npc:5292} 사냥",
		["if you carry {quest:1100} from {zone:1441}"] = "{zone:1441}에서 {quest:1100}을(를) 가져왔다면",
		["{area:978} instead of grinding"] = "사냥 대신 {area:978}",
		["{item:11463}, from the backpacks"] = "{item:11463}, 배낭에서",
		["{npc:14637}'s refills are level 55: skip them."] = "{npc:14637}의 재충전 퀘스트는 55레벨입니다: 건너뛰십시오.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "이어서 {npc:3936}이(가) {zone:1457}에 소식을 전해 달라고 합니다: 건너뛰십시오. 대신 {area:976}에서 그곳으로 보내 줍니다.",
		["{npc:3936}, beside him"] = "{npc:3936}, 그의 옆",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: 답장은 나중에 {area:702}에서 받습니다",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774}은(는) {npc:7765} 북쪽 언덕의 바람계곡일족 하피 사이를 떠돕니다. 샤이의 종은 그녀 옆 상자에 있습니다.",
		["{npc:7774}'s escort"] = "{npc:7774} 호위",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, 요새 꼭대기",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136}은(는) 본토를 한 바퀴 돈 뒤에 처치합니다.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Fly from {area:976} to Theramore, take the boat to {area:150} and fly to {area:1537}. Train."] = "{area:976}에서 테라모어 섬으로 날아가, 배를 타고 {area:150}(으)로 간 다음 {area:1537}(으)로 날아가십시오. 기술을 배우십시오.",
		["Fly to {area:348}. {zone:1425} guide starts here."] = "{area:348}(으)로 날아가십시오. {zone:1425} 가이드는 여기서 시작합니다.",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp."] = "해안을 따라 남쪽 해적단 소굴로 가십시오. 남쪽바다해적단이 해변과 배에 우글거립니다: 가장자리부터 하나씩 끌어내십시오. {npc:7883}은(는) 반대편에 서 있고, {npc:7881}의 도둑맞은 화물은 야영지에 있습니다.",
		["From the {area:1108} dock, boat to Feathermoon and fly to {area:489}, then ride east through {zone:1441} to the {area:2240} on the {area:439}. {npc:4454} and {npc:4630} are in the camps beside the track; {npc:4709} stands by the goblin camp."] = "{area:1108} 부두에서 배를 타고 페더문 요새로 가서 {area:489}(으)로 날아간 다음, {zone:1441}을(를) 지나 동쪽 {area:439}의 {area:2240}까지 가십시오. {npc:4454}와(과) {npc:4630}은(는) 경주로 옆 야영지에 있고, {npc:4709}은(는) 고블린 야영지 옆에 서 있습니다.",
		["Gives the {item:8585}"] = "{item:8585}을(를) 줍니다",
		["He runs off to keep Rizzle busy"] = "그는 리즐 브라스볼츠의 주의를 끌러 달려갑니다",
		["Hearth to {area:976}."] = "귀환석으로 {area:976}에 가십시오.",
		["Pool by {area:979}"] = "{area:979} 옆 웅덩이",
		["Ride back west to {area:976}."] = "서쪽 {area:976}(으)로 돌아가십시오.",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch."] = "서쪽 {area:976} 쪽으로 돌아가십시오. 가는 길의 모래언덕에는 사막유랑단 약탈자와 사막유랑단 좀도둑이 있고, 누구든 사막유랑단 물주머니를 지니고 있을 수 있습니다.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "모래언덕을 건너 동쪽, 북동쪽 해안의 고블린 항구(스팀휘들 항구)로 가십시오.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts."] = "북서쪽 모래언덕의 센티파르 둥지(맹독의 둥지)로 가십시오. 어느 센티파르든 센티파르 곤충 기관을 떨어뜨릴 수 있습니다.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "북서쪽 {area:979}의 성난모래부족 트롤 야영지로 가십시오. 웅덩이 가장자리에서 {item:8584}을(를) 사용하십시오. 트롤들이 가까이 있으니 가장 가까운 것부터 끌어내십시오.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time."] = "남쪽 {quest:3362}(으)로 가십시오. 이슬먹는 덤불나무괴물이 이슬샘을 떨어뜨리는데 일부만 가득 차 있으니 가득 찬 이슬샘을 챙기십시오. 옹이진 덤불나무괴물과 억센뿌리 덤불나무괴물도 골짜기에 있습니다. 덤불나무괴물은 48-50레벨로 당신보다 높으니 하나씩 끌어내십시오.",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside."] = "남쪽으로 {area:1938}을(를) 지나 하잘리 굴인 {area:981}으로 가십시오. 슈섕크의 측량 장비는 깊숙한 곳에 있습니다.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "남쪽 {area:1938}의 발굴 야영지로 가십시오. {npc:7771}이(가) 탐지 투구를 줍니다: 착용하면 {quest:3161} 흙더미가 보이며, 야영지 주변과 남서쪽 오우거 쪽 모래에 많이 있습니다.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "{area:439}에서 남동쪽 {zone:1446}(으)로 가십시오. {area:976}은(는) 경계 바로 안쪽에 있습니다.",
		["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first."] = "남동쪽 {area:985}(으)로 가십시오. {npc:7847}은(는) 남쪽 사막유랑단 야영지 한가운데에 서 있습니다: 주변부터 정리하십시오.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "남서쪽 모래망치 주둔지로 가십시오. 모래망치일족 투사와 모래망치일족 집행자(46-48)가 가득하고, {npc:12046}(49)은(는) 경비병에 둘러싸여 한가운데에 서 있습니다: 경비병부터 처치하십시오.",
		["Rizzle's plans"] = "아무도 지키지 않는 리즐의 설계도",
		["The Wanted poster beside him"] = "그 옆의 현상수배 포스터",
		["The Wanted poster by {npc:7882}"] = "{npc:7882} 옆의 현상수배 포스터",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "작은 거북 {npc:5955}은(는) 골짜기 북쪽 끝에 숨어 있습니다. {area:977} 바로 동쪽 물가에 있는 아내 {npc:6015}에게 데려다주십시오: 느리게 걷고 사막의 야수들이 노리니 살려 두십시오.",
		["The pool by {area:979}"] = "{area:979} 옆 웅덩이",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later."] = "더 강한 사막유랑단 도적, 사막유랑단 어둠마법사, 사막유랑단 암살자는 {area:976} 남동쪽, 약탈자들 남쪽에 진을 치고 있습니다. 남쪽 야영지 한가운데의 {npc:7847}은(는) 나중으로 미루십시오.",
		["The {area:1938}"] = "{area:1938}",
		["Wastewander bandits"] = "사막유랑단 약탈자",
		["While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "{npc:4709}이(가) 리즐 브라스볼츠와 이야기하는 동안, 경주로 건너편 노움 야영지의 설계도는 무방비 상태입니다.",
		["for {zone:1457}: the route takes you there at 47"] = "{zone:1457}용: 경로상 47레벨에 그곳에 갑니다",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, 마을 동쪽",
		["{npc:5955}'s escort"] = "{npc:5955} 호위",
		["{npc:7407}, by the water tower"] = "{npc:7407}, 급수탑 옆",
		["{npc:7408}, next to him"] = "{npc:7408}, 그의 옆",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "{npc:7583}의 다음 재료는 {zone:1425}에서 자라고, 경로상 다시 가져오지 않습니다: 건너뛰십시오.",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: 그의 상자는 나중에 {area:702}(으)로 갑니다",
		["{npc:7881}'s next delivery goes back to {area:35}: skip it."] = "{npc:7881}의 다음 배달은 {area:35}(으)로 돌아갑니다: 건너뛰십시오.",
		["{npc:7881}, in the port's tavern"] = "{npc:7881}, 항구의 선술집 안",
		["{quest:2864}, north side of town"] = "{quest:2864}, 마을 북쪽",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ashmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52."] = "잿빛갈기멧돼지와 붉은바위 바실리스크가 요새 남서쪽 비탈에 함께 있습니다. 더 남쪽의 지옥멧돼지는 52레벨이니 피하십시오.",
		["Back to {area:144}"] = "{area:144}(으)로 돌아가기",
		["Boars and basilisks"] = "멧돼지와 바실리스크",
		["Fly from {area:144} to {area:150}, take the boat to {area:442} and fly to {area:702}."] = "{area:144}에서 {area:150}(으)로 날아가, 배를 타고 {area:442}(으)로 간 다음 {area:702}(으)로 날아가십시오.",
		["Fly from {area:348} to {area:42}."] = "{area:348}에서 {area:42}(으)로 날아가십시오.",
		["Hearth to {area:144}. The {zone:1427} guide starts at {area:1446}: from here, ride south into the {zone:1418}, west past the Horde town of {area:340} and up the trail into the gorge."] = "귀환석으로 {area:144}에 가십시오. {zone:1427} 가이드는 {area:1446}에서 시작합니다: 여기서 남쪽 {zone:1418}(으)로 가서, 서쪽으로 호드 마을 {area:340}을(를) 지나 오솔길을 따라 협곡으로 올라가십시오.",
		["Hearth to {area:348}."] = "귀환석으로 {area:348}에 가십시오.",
		["Hearthstone on cooldown? Ride back north-west."] = "귀환석이 재사용 대기 중이라면 북서쪽으로 돌아가십시오.",
		["Ride back east to {area:1438} and fly to {area:144}."] = "동쪽 {area:1438}(으)로 돌아가 {area:144}(으)로 날아가십시오.",
		["Ride back north to Ironband's camp."] = "북쪽 아이언밴드의 발굴현장으로 돌아가십시오.",
		["Ride east along the south shore of the loch to Ironband's camp."] = "호수 남쪽 기슭을 따라 동쪽 아이언밴드의 발굴현장으로 가십시오.",
		["Ride east through {zone:1430} into the {zone:1435} and south down the road into the {zone:1419}. The bloodmages' camp is the first stop beside the road."] = "동쪽으로 {zone:1430}을(를) 지나 {zone:1435}(으)로 간 다음, 길을 따라 남쪽 {zone:1419}(으)로 내려가십시오. 혈법사들의 야영지가 길가 첫 번째 장소입니다.",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it."] = "북쪽으로 {zone:1425} 한가운데의 {area:351}까지 가세요. 초록 진흙괴물과 비취 수액괴물이 그 주변 곳곳을 기어다닙니다.",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "먼저 길을 따라 동쪽 요새로 가십시오: {item:6091}은(는) {area:42}에서 받은 지 1시간 후에 사라지는데, 혈법사들의 야수 사냥은 그보다 오래 걸립니다.",
		["Ride south through the pass into the {zone:1418}' northern edge: the Stonevault troggs dig outside {area:1517} there. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "고개를 지나 남쪽 {zone:1418} 북쪽 끝으로 가십시오: 그곳 {area:1517} 밖에서 바위동굴 트로그가 땅을 파고 있습니다. 돌조각 단지와 자홍버섯은 던전 밖, 트로그의 동굴과 굴에 있습니다.",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down."] = "남동쪽으로 {zone:1425} 남쪽에 있는 썩은가지부족의 계단식 신전 {area:355}(으)로 가서 꼭대기까지 올라가십시오. 문지기 퀴아가와 {npc:8636}(정예, 50)이(가) 그곳에 있습니다: 꼭대기에 닿으면 곧바로 내려오십시오.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time."] = "서쪽으로 가십시오: 굶주린 칼송곳니하이에나가 혈법사 야영지 바로 남쪽의 메마른 언덕을 돌아다니고, 스콜포크 독침전갈(50레벨)이 북쪽 한가운데를 기어다닙니다. {npc:5982} 독수리가 그 위를 맴돕니다. 하나씩 끌어내십시오.",
		["Scorpoks and snickerfangs"] = "스콜포크와 칼송곳니하이에나",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "차원문을 지나 {zone:1457}(으)로 들어가십시오. 달의 신전은 도시 남쪽에 있습니다.",
		["Temple of the Moon"] = "달의 신전",
		["The bloodmages"] = "혈법사",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "혈법사들의 두 번째 단계는 같은 재료에 경험치 없이 강화 아이템만 줍니다: 건너뛰십시오.",
		["The druid trainers stand in the Enclave; {zone:1455} has none"] = "드루이드 상급자는 세나리온 자치령에 있습니다. {zone:1455}에는 없습니다",
		["The {area:1517} dig"] = "{area:1517} 발굴지",
		["for {quest:2990} at {area:1438}, later"] = "나중에 {area:1438}의 {quest:2990}에게",
		["the book on her table"] = "그녀의 탁자 위 책",
		["the soil comes from {zone:1449}, later"] = "흙은 나중에 {zone:1449}에서 구합니다",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, 나무 꼭대기",
		["{npc:7740}, beside her"] = "{npc:7740}, 그녀의 옆",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "{npc:7907}의 다음 심부름은 {zone:1446}(으)로 갑니다: 건너뛰십시오.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}: 간직하십시오. 깃털은 {zone:1428} 가이드 끝에서 구합니다",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "{npc:8022}의 다음 임무인 {item:9471}은(는) {area:978} 퀘스트입니다: 건너뛰십시오.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, 요새 꼭대기",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, later"] = "나중에 {zone:1455}의 {npc:8256}에게",
		["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {zone:1427}. {area:1446} is the scaffolded camp on the north-west rim."] = "{area:144}에서 남쪽 {zone:1418}(으)로 간 다음, 서쪽으로 호드 마을 {area:340}을(를) 지나(거리를 두십시오) 오솔길을 따라 {zone:1427}(으)로 올라가십시오. {area:1446}은(는) 북서쪽 가장자리의 비계가 세워진 야영지입니다.",
		["Golems and elementals"] = "골렘과 정령",
		["Greater Lava Spiders"] = "거대한 용암거미",
		["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "칼라란 아래 용광로 바닥을 육중한 전투골렘이 순찰하고, 그 사이를 용암 정령이 떠다닙니다. 골렘 기름은 골렘과 정령이, 화염의 심장은 정령이 떨어뜨립니다.",
		["Kalaran stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "칼라란 윈드블레이드는 {area:1446} 남쪽, 용광로 가장자리에 서 있습니다. 그의 이야기를 들으십시오.",
		["Ride east across the Cauldron to the {area:247} in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "용광로를 가로질러 동쪽으로, 남동쪽의 {area:247}까지 가세요. 나무 변소 안의 죄수가 {item:4306} 15개와 그 주변 발굴지의 {npc:5839} 8마리 처치를 원합니다. 열쇠를 찾았다면 변소를 열쇠로 열 수도 있습니다.",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it."] = "검은무쇠단 감독관과 검은무쇠단 노예상인이 용광로 곳곳에서 노예를 부리며, 누구든 {item:10551}을(를) 지니고 있을 수 있습니다. 검은무쇠단 증기기술자는 한가운데 용광로에서 일하고({item:18959}), 검은무쇠단 망꾼은 남쪽 능선에 서 있습니다(감시병의 망원경). {object:147516} 누구든 {item:11818}을(를) 떨어뜨릴 수 있으니 간직하십시오.",
		["The Grimesilt outhouse"] = "검댕가루 간이화장실",
		["The dwarf stands by the road at the dig site. Follow him north along the road and fight off the {object:147516} ambushes. When it is over, read the {object:175704} he leaves on the road in {area:1959}."] = "드워프 도리우스 스톤텐더는 발굴현장의 길가에 서 있습니다. 그를 따라 길을 북쪽으로 가며 {object:147516}의 매복을 물리치십시오. 끝나면 {area:1959}의 길에 그가 남긴 {object:175704}을(를) 읽으십시오.",
		["The night elf stands alone west of {area:1446}. Hear his story."] = "나이트 엘프 잠마엘 룬시슬이 {area:1446} 서쪽에 홀로 서 있습니다. 그의 이야기를 들으십시오.",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "포로의 다음 임무인 {zone:1446}의 장부는 {zone:1435}와(과) {zone:1445}(으)로 보냅니다: 건너뛰십시오.",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge."] = "거미는 협곡 남서쪽의 고원과 용암 웅덩이를 돌아다닙니다.",
		["The {object:179827} board"] = "{object:179827} 게시판",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443}은(는) 용광로 북쪽에 입구가 있습니다. 비밀조제법: 불꽃 융해촉진제는 위쪽 바위 턱에 있습니다. 더 안쪽 용암 웅덩이에서 인센도사우루스가 헤엄치니 가장자리로 끌어내십시오. 깊숙한 곳의 {npc:14621}와(과) 그의 정예 경비병은 피하십시오.",
		["{object:147516} dwarves"] = "{object:147516} 드워프",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "아케소누스는 {object:171709}에서 국왕 마그니 브론즈비어드 옆에 서 있습니다.",
		["Bind and train"] = "귀환 장소 설정 및 수련",
		["Bones and equipment"] = "뼈와 장비",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "분화구 남쪽을 가로질러 비탈 옆의 {npc:9619}에게 가세요.",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "{item:11114}은(는) 남서쪽 스테고돈 사이 땅바닥에 있습니다. 스테고돈은 정예이니 그 주변의 뼈만 줍고 나머지는 디메트로돈에게서 얻으세요. 탐험대의 {item:11112}은(는) 남서쪽 밀림에 있습니다.",
		["Eastern Pylon"] = "동쪽 수정탑",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "{zone:1452}의 {npc:9298}에게서 끝납니다: 보관하세요",
		["Escort {npc:9999}"] = "{npc:9999} 호위",
		["Fly from {area:144} to {area:1537}."] = "{area:144}에서 {area:1537}(으)로 날아가세요.",
		["For {npc:7775} in {zone:1444}: keep it"] = "{zone:1444}의 {npc:7775}에게 줄 것: 보관하세요",
		["Four rune rubbings in {zone:1447}: keep it"] = "{zone:1447}의 룬 탁본 네 개: 보관하세요",
		["From {area:144} fly to {area:150}, take the boat to Theramore and fly on to {area:976}. {npc:9619}'s first quest in the crater needs level 48: finish the level here if you are short."] = "{area:144}에서 {area:150}(으)로 날아가 배를 타고 테라모어로 간 뒤, {area:976}(으)로 날아가세요. 분화구에서 {npc:9619}의 첫 퀘스트는 48레벨이 필요합니다. 부족하면 여기서 레벨을 채우세요.",
		["Grind to 50"] = "50레벨까지 사냥",
		["Grind to 51"] = "51레벨까지 사냥",
		["Gryfe"] = "그리페",
		["Lar'korwi Mates and the raft"] = "{npc:9683}와(과) 뗏목",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "{npc:9999}을(를) 북쪽 {area:541}까지 데려가세요. 그가 기절하면 {item:11804}을(를) 사용해 깨우세요.",
		["Northern Pylon"] = "북쪽 수정탑",
		["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "비탈을 내려가 분화구로 가세요. {npc:9619}은(는) 비탈 아래에 진을 치고 있습니다.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "동쪽으로 {area:537}까지 가서 올라간 뒤, 꼭대기 근처 용암 분출구에서 {npc:10541}을(를) 사용하세요.",
		["Ride north along the east side of the crater to {area:541}, the camp in the caves of the northern cliff. Give the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "분화구 동쪽을 따라 북쪽으로 북쪽 절벽 동굴 속 야영지인 {area:541}까지 가세요. 정예 데빌사우루스와 스테고돈은 멀리 피하세요. 여기서부터 지나가는 마력의 수정과 {object:157936}을(를) 모두 챙기세요.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "동쪽을 따라 북쪽의 고릴라 고원으로 가세요. 55레벨 고릴라 {npc:9622}은(는) 가장 깊은 동굴에 있습니다. 먼저 동굴 입구의 고릴라를 정리하세요.",
		["Ride north along the western jungle back to the refuge."] = "서쪽 밀림을 따라 북쪽으로 야영지에 돌아가세요.",
		["Ride north to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "북쪽으로 {area:1943}까지 가세요. 로봇은 고릴라들 사이에 서 있습니다. 그곳의 깊은 동굴에는 들어가지 마세요.",
		["Ride south along the eastern cliffs to {npc:9619} at the foot of the ramp."] = "동쪽 절벽을 따라 남쪽으로, 비탈 아래의 {npc:9619}에게 가세요.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "동쪽을 따라 남쪽으로 내려가세요. {npc:9162}은(는) 동쪽 밀림에서 풀을 뜯고, {npc:9165}은(는) 동쪽 절벽 근처를 납니다. 둘 다 {npc:9998}에게 줄 비늘을 떨어뜨립니다.",
		["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "남쪽으로 분화구 한가운데의 {area:537}까지 간 뒤 동쪽 밀림으로 가세요. 수정 무더기는 분화구 곳곳에, 특히 {area:537} 주변에 많습니다. 색깔마다 몇 개씩 더 챙기세요. {npc:6509}와(과) 덩이줄기 붉은꽃잎덩굴손이 꽃잎을 떨어뜨립니다. 탐험대의 {item:11113}은(는) 동쪽 밀림의 버려진 야영지에 있습니다.",
		["Ride west back to the refuge."] = "서쪽으로 야영지에 돌아가세요.",
		["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; {npc:9166} nest on the southern cliffs if you still need kills."] = "{npc:9619}에게서 서쪽으로 가세요. 실리시드 벌집이 분화구 남쪽을 채우고 있습니다. 유충이 매달린 방인 부화실에 긁개 유리병을 사용하세요. 병정 고리쉬와 일꾼 고리쉬가 {quest:3764}을(를) 떨어뜨립니다. 처치 수가 아직 필요하면 남쪽 절벽에 {npc:9166}이(가) 둥지를 틀고 있습니다.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "{area:976}에서 서쪽으로 나가 {zone:1449}(으)로 내려가는 긴 비탈로 가세요. {npc:9619}은(는) 분화구 남동쪽 구석, 비탈 아래에 진을 치고 있습니다.",
		["Ride west past {area:541} and south down the western side to {area:543}: {npc:10302} the goblin sits by the water."] = "서쪽으로 {area:541}을(를) 지나 서쪽을 따라 남쪽의 {area:543}까지 가세요. 고블린 {npc:10302}이(가) 물가에 앉아 있습니다.",
		["Running the {area:1417} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "파티라면 사냥 대신 {area:1417}을(를) 도는 편이 더 빠릅니다. 혼자 사냥하려면 이 단계를 건너뛰세요.",
		["Running {area:978} instead of grinding gets you there faster in a group. The troll city lies in the north-west of {zone:1446}, just north of {area:976}."] = "파티라면 사냥 대신 {area:978}을(를) 도는 편이 더 빠릅니다. 트롤 도시는 {zone:1446} 북서부, {area:976} 바로 북쪽에 있습니다.",
		["The Centipaar silithid crawl around the {area:982} in western {zone:1446}, just east of the crater ramp. The Workers are the easiest pulls."] = "센티파르 실리시드가 분화구 비탈 바로 동쪽, {zone:1446} 서부의 {area:982} 주변을 기어다닙니다. 일꾼이 가장 쉽게 끌어올 수 있습니다.",
		["The Gorishi hive"] = "고리쉬 벌집",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "{npc:9683}은(는) {npc:9619} 서쪽 밀림을 어슬렁거립니다. 부서진 뗏목은 그곳 호숫가에 있고, 작은 꾸러미는 그 옆 물속에 있습니다. 나침반, 지도, 열쇠는 {npc:8737}에게 주도록 보관하세요. 분화구의 어떤 야수든 {item:11116}을(를) 떨어뜨릴 수 있습니다. 오른쪽 클릭하세요.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "죽은 트레샤돈은 {npc:9619} 북쪽 물가에 있습니다.",
		["The east side"] = "동쪽 지역",
		["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55."] = "고릴라는 {area:541} 동쪽의 {area:1943}에 삽니다. 가죽은 {npc:9619}에게 주도록 보관하세요. 가장 깊은 동굴에는 들어가지 마세요. {npc:9622}은(는) 55레벨입니다.",
		["The gorillas of {area:1943} come in small groups and drop nothing for you yet; {npc:9619}'s pelt quest comes later. Stay out of the deepest cave: {npc:9622} is level 55."] = "{area:1943}의 고릴라는 작은 무리로 다니며 아직은 필요한 것을 떨어뜨리지 않습니다. {npc:9619}의 가죽 퀘스트는 나중에 나옵니다. 가장 깊은 동굴에는 들어가지 마세요. {npc:9622}은(는) 55레벨입니다.",
		["The pelts come after loop 2, on the gorilla plateau"] = "가죽은 두 번째 순환 이후, 고릴라 고원에서 모읍니다",
		["The pylon stands on the eastern cliffs."] = "수정탑은 동쪽 절벽 위에 서 있습니다.",
		["The pylon stands on the slope east of the refuge. {npc:9166} circle the slopes around it: they count for {npc:9997} and drop {npc:9998}'s scales."] = "수정탑은 야영지 동쪽 비탈에 서 있습니다. {npc:9166}이(가) 그 주변 비탈을 맴돕니다. {npc:9997}의 처치 수에 포함되며 {npc:9998}에게 줄 비늘을 떨어뜨립니다.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "수정탑은 서쪽 절벽 위에 서 있습니다. {npc:9167}이(가) 서쪽 전역을 날아다닙니다.",
		["The relics are in the {zone:1428}: keep it"] = "유물은 {zone:1428}에 있습니다: 보관하세요",
		["The wooden sign beside {npc:9997}"] = "{npc:9997} 옆의 나무 표지판",
		["Western Pylon"] = "서쪽 수정탑",
		["Xiggs waits in the {object:32359}."] = "시그스는 {object:32359}에서 기다립니다.",
		["grind on the Wastewanderers or Dunemaul ogres around {area:976}"] = "{area:976} 주변의 황무지유랑단이나 모래망치 오우거를 사냥하세요",
		["grind on {npc:5458} at {area:982}, {zone:1446}"] = "{zone:1446} {area:982}에서 {npc:5458} 사냥",
		["grind on {npc:6514} at {area:1943}, {zone:1449}"] = "{zone:1449} {area:1943}에서 {npc:6514} 사냥",
		["{area:537} and the eastern jungle"] = "{area:537}와(과) 동쪽 밀림",
		["{area:978} (optional)"] = "{area:978}(선택)",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: {zone:1447}의 오그틴크에게 줄 것, 보관하세요",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}, 동굴 안쪽",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: 수액괴물은 {zone:1448}에 있습니다. 보관하세요",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618}은(는) 야영지 바로 바깥에 서 있습니다.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "{npc:9684}의 굴은 {npc:9619} 북쪽, 동쪽 절벽 아래 밀림에 있습니다. 그곳에서 {item:11568}을(를) 사용하세요. {npc:9684}은(는) 56레벨이니 생명력이 가득한 상태로 시작하세요.",
		["{npc:9997}'s friend {npc:9999} has gone missing."] = "{npc:9997}의 친구 {npc:9999}이(가) 실종되었습니다.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, 야영지 입구",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, 야영지 입구",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999}은(는) 분화구 한가운데 {area:537}의 남동쪽 비탈에 앉아 있습니다.",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Climb back to {npc:8405} at the {area:1224}, above the ruins."] = "폐허 위 {area:1224}의 {npc:8405}에게 다시 올라가세요.",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "{area:249} 꼭대기에 올라가 부드러운 흙더미에 머리를 꽂으세요.",
		["Druid training"] = "드루이드 수련",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "{zone:1452} {area:2255}의 {quest:4808}에게서 끝납니다: 보관하세요",
		["Fly from {zone:1455} to {area:150} and take the boat to {area:442}."] = "{zone:1455}에서 {area:150}(으)로 날아가 배를 타고 {area:442}(으)로 가세요.",
		["Fly from {zone:1455} to {area:69}."] = "{zone:1455}에서 {area:69}(으)로 날아가세요.",
		["Fly to {area:1438}."] = "{area:1438}(으)로 날아가세요.",
		["Fly to {area:150} and take the boat to {area:442}, then the boat on to {area:702}."] = "{area:150}(으)로 날아가 배를 타고 {area:442}(으)로 간 뒤, 다시 배를 타고 {area:702}(으)로 가세요.",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "길을 따라 서쪽으로 간 뒤 북쪽으로 올라가 {area:251}의 고블린 야영지로 가세요.",
		["From the {area:442} dock, fly to {area:415}."] = "{area:442} 부두에서 {area:415}(으)로 날아가세요.",
		["Mosshoof Coursers"] = "{npc:8761}",
		["Optional: {npc:8395} wants two Undamaged Hippogryph Feathers from the hippogryphs around his camp. The data lists no experience for it."] = "선택: {npc:8395}이(가) 야영지 주변 히포그리프에게서 얻는 {item:10450} 2개를 원합니다. 데이터에는 경험치가 나와 있지 않습니다.",
		["Optional: {npc:8888}'s ghost stands on his tomb on the great chain inside {area:254}, and only the dead can see him. If you die near the mountain anyway, run your spirit to him before resurrecting."] = "선택: {npc:8888}의 유령은 {area:254} 안 거대한 사슬 위 그의 무덤에 서 있으며, 죽은 자만 그를 볼 수 있습니다. 어차피 산 근처에서 죽었다면 부활하기 전에 영혼 상태로 그에게 달려가세요.",
		["Read the tablet in the {object:147516} camp among the ruins, south-west of {area:251}, to copy the transcript."] = "{area:251} 남서쪽 폐허 사이의 {object:147516} 야영지에서 석판을 읽고 내용을 베끼세요.",
		["Ride back east along the road to the Vigil."] = "길을 따라 동쪽으로 감시초소에 돌아가세요.",
		["Ride back to {area:1438} and fly to {area:348}. The Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam; the mobs here are well below you now."] = "{area:1438}(으)로 돌아가 {area:348}(으)로 날아가세요. {item:10819}은(는) {area:348} 남쪽과 동쪽, 올빼미야수가 돌아다니는 {zone:1425} 곳곳의 땅바닥에 있습니다. 이곳 몹은 이제 당신보다 한참 낮습니다.",
		["Ride east along the road out of {zone:1440} into {zone:1447} to the Sentinels' camp at {area:3137}."] = "길을 따라 동쪽으로 {zone:1440}을(를) 벗어나 {zone:1447}에 들어가 {area:3137}의 파수꾼 야영지로 가세요.",
		["Ride north out of {area:69} through the pass into the {zone:1428}; {area:2418} sits at the top, in the south-east of the Steppes."] = "{area:69}에서 북쪽으로 고개를 넘어 {zone:1428}에 들어가세요. {area:2418}은(는) 고개 꼭대기, 초원 남동쪽에 있습니다.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "제단에서 북동쪽으로 가세요. {npc:8405}은(는) 길 위 언덕의 {area:1224}에 진을 치고 있습니다.",
		["Swim to the small island off the southern tip of {zone:1447}: {npc:8392} waits by the monument."] = "{zone:1447} 남쪽 끝 앞바다의 작은 섬까지 헤엄쳐 가세요. {npc:8392}이(가) 기념비 옆에서 기다립니다.",
		["Thaurissan Relics"] = "{object:153556}",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "불자루 오우거가 감시초소 북쪽의 큰 바위를 차지하고 있고, 불자루일족 투사는 그 동쪽에 있습니다.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "명가 유령들이 제단 주변 폐허를 떠돌고, 할다르 사티로스가 그 바로 북쪽 야영지를 차지하고 있습니다.",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "{area:1221}의 원한의꼬리일족 나가가 {item:13815}을(를) 가지고 있습니다. {npc:8507}의 룬 네 개는 폐허 사이에 서 있습니다. 각각에 그의 {item:10445}을(를) 사용하세요.",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "가장 가까운 {npc:8761}은(는) {area:1224} 북동쪽, {area:1219} 쪽 언덕에서 풀을 뜯고, 더 큰 무리는 남쪽 평지를 돌아다닙니다.",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered."] = "유물은 {area:251} 주변 {area:250}에 흩어진 조각된 돌입니다. 정보가 복구될 때까지 클릭하세요.",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "섀도송 제단은 {area:3137} 남쪽, {zone:1447} 남서쪽 구석에 있습니다.",
		["The wildkin are in {zone:1452}: keep it"] = "올빼미야수는 {zone:1452}에 있습니다: 보관하세요",
		["The {area:1221}"] = "{area:1221}",
		["The {quest:4296}"] = "{quest:4296}",
		["Use the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves."] = "{area:251} 동쪽 비탈의 {npc:7047}이(가) 죽기 직전에 {item:12284}을(를) 사용한 뒤, 남긴 정수를 획득하세요.",
		["Wildkin feathers"] = "올빼미야수 깃털",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: {npc:7864}, 약 10%",
		["{npc:7363} waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have."] = "{npc:7363}은(는) 요새 남서쪽 언덕인 {area:2517}에서 기다립니다. 가는 길의 {zone:1419} 몹이 {item:10593}을(를) 떨어뜨립니다. 가진 만큼 가져가세요.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420}은(는) 북쪽 {area:1219}에 진을 치고 있으며, 그의 장비는 바로 남동쪽 {area:1220} 곳곳에 흩어져 있습니다.",
		["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty."] = "{npc:9176}와(과) 검은바위부족 오크가 {area:251} 서쪽, {area:254} 기슭의 야영지와 요새를 차지하고 있습니다. 하나씩 끌어오세요. 오크와 늑대 모두 메달을 떨어뜨릴 수 있으니 50개가 될 때까지 처치하세요.",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}: 검은바위부족 오크가 메달을 떨어뜨립니다. 불타는 평원 내내 열어 두세요",
		["{zone:1455} has no druid trainer: take the portal up to {zone:1457} and train in the {area:1658}, then come back down to {area:702}."] = "{zone:1455}에는 드루이드 상급자가 없습니다. 차원문을 타고 {zone:1457}(으)로 올라가 {area:1658}에서 수련한 뒤 {area:702}(으)로 내려오세요.",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Ends in the {zone:1413}: keep it"] = "{zone:1413}에서 끝납니다: 보관하세요",
		["First crater"] = "첫 번째 구덩이",
		["Five feathers buy a little Timbermaw reputation"] = "깃털 5개로 나무구렁 요새 평판을 조금 얻습니다",
		["Fly from {area:1998} to the Sanctuary's end of the road, or ride south along it."] = "{area:1998}에서 길의 성소 쪽 끝으로 날아가거나, 길을 따라 남쪽으로 가세요.",
		["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "길을 따라 북쪽으로 {area:1769}의 동굴 입구까지 가세요. {npc:15395}이(가) 입구를 지킵니다.",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "길을 따라 북쪽의 구덩이 파인 골짜기로 가서 구덩이마다 들르며, 그 사이의 {npc:9878}와(과) 혼돈의 소산물을 처치하세요.",
		["Keep her alive until she is out of the cave"] = "동굴을 나갈 때까지 그녀를 살려 두세요",
		["Oozes"] = "수액괴물",
		["Ride east to the night elf camp at {area:1998}."] = "동쪽으로 {area:1998}의 나이트 엘프 야영지로 가세요.",
		["Ride north out of {area:415} into {zone:1448}. {npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "{area:415}에서 북쪽으로 {zone:1448}에 들어가세요. 펄볼그 {npc:11554}은(는) {area:2479} 바로 남쪽 길가에 서 있습니다.",
		["Ride north to {area:1769} (or fly back to {area:1998} first) and through the tunnel into {zone:1452}; follow the road east to the goblin town of {area:2255}."] = "북쪽으로 {area:1769}까지 가서(또는 먼저 {area:1998}(으)로 날아가서) 터널을 지나 {zone:1452}에 들어가세요. 길을 따라 동쪽으로 고블린 마을 {area:2255}까지 가세요.",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "살파는 터널의 {zone:1452} 쪽 끝에 서 있습니다: 보관하세요",
		["Second crater"] = "두 번째 구덩이",
		["Step into the cave: {npc:11558} and {npc:11557} stand just inside."] = "동굴에 들어가세요. {npc:11558}와(과) {npc:11557}이(가) 바로 안쪽에 서 있습니다.",
		["Take the boat from {area:702} to {area:442} and fly to {area:415}."] = "{area:702}에서 배를 타고 {area:442}(으)로 간 뒤 {area:415}(으)로 날아가세요.",
		["The Cursed and Tainted Oozes slide about the streams and fel pools around {area:1763} and {area:1765}: kill them and use Laris's Empty Ooze Jars on their remains."] = "저주받은 수액괴물과 {npc:7092}이(가) {area:1763}와(과) {area:1765} 주변의 개울과 지옥 웅덩이를 미끄러져 다닙니다. 처치한 뒤 라리스의 빈 수액괴물 단지를 그 잔해에 사용하세요.",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "마른가지일족 펄볼그는 {npc:11554} 바로 남서쪽 마을에 삽니다. 그들이 떨어뜨리는 {item:21377}은(는) 보관하세요.",
		["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. The Avengers can drop a {quest:8470}."] = "{area:1762}의 마른가지일족 펄볼그가 동굴 서쪽 언덕을 채우고 있습니다. 마른가지일족 복수자가 {quest:8470}을(를) 떨어뜨릴 수 있습니다.",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back."] = "비취불꽃의 사티로스가 길 서쪽 숲을 차지하고 있으며, {npc:9454}은(는) 그 안쪽에 있습니다.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "{area:2618} 동쪽 {area:1767}의 굽이나무정령이 {item:11503}을(를) 가지고 있습니다.",
		["The vial is filled in {zone:1457}: keep it"] = "유리병은 {zone:1457}에서 채웁니다: 보관하세요",
		["The {area:2479}"] = "{area:2479}",
		["Third crater"] = "세 번째 구덩이",
		["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}. If you freed {npc:11018}, go back into {area:1770} for the succubus {npc:9518}; Trey Lightforge's remains lie beside her."] = "{area:1763} 한가운데의 타락한 달샘에서 {item:12922}을(를) 사용하세요. {npc:11018}을(를) 풀어 주었다면 {area:1770}에 다시 들어가 서큐버스 {npc:9518}을(를) 처치하세요. 트레이 라이트포지의 유해가 그녀 옆에 있습니다.",
		["{area:1763} again"] = "다시 {area:1763}",
		["{area:1763} is the ruined temple north of the glen. Some of its cultists drop a {item:13140}, about one kill in thirty: it opens {npc:11018}'s cell in {area:1770}, the cave at the back. If it drops, clear the way out before you free her; if not, skip her quests."] = "{area:1763}은(는) 숲 북쪽의 폐허가 된 사원입니다. 일부 이교도가 약 30마리에 한 번꼴로 {item:13140}을(를) 떨어뜨립니다. 이 열쇠로 안쪽 동굴인 {area:1770}의 {npc:11018} 감옥을 엽니다. 열쇠가 나오면 그녀를 풀어 주기 전에 나가는 길을 정리하고, 안 나오면 그녀의 퀘스트는 건너뛰세요.",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618}은(는) 북서쪽의 사티로스 골짜기이며, 맨 끝에 {npc:10648}이(가) 있습니다. 그가 {quest:939}을(를) 떨어뜨리고, 비취불꽃의 사티로스는 누구나 {item:11674}을(를) 떨어뜨릴 수 있습니다.",
		["{item:13140}, a rare drop"] = "{item:13140}, 드물게 획득",
		["{npc:11016}, in {area:1770}"] = "{npc:11016}, {area:1770} 안",
		["{npc:11557}: thirty {quest:6031}, handed in when you pass through again at 57"] = "{npc:11557}: {quest:6031} 30장, 57레벨에 다시 지나갈 때 제출",
		["{npc:11558}: the Timbermaw speak to you only from Neutral"] = "{npc:11558}: 나무구렁 요새는 중립부터 대화해 줍니다",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395}은(는) {zone:1448} 북쪽 끝에서 기다립니다",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, {npc:11554} 바로 동쪽 폐허",
		["{quest:8470}, a rare drop"] = "{quest:8470}, 드물게 획득",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns. Keep killing yetis until level 54: Harlo's wildkin quests are red before that."] = "언덕으로 돌아가세요. 맹렬한 얼음엉겅퀴설인과 덩치큰 얼음엉겅퀴설인만 뿔을 지니고 있습니다. 54레벨이 될 때까지 설인을 계속 처치하세요. 그 전에는 하를로의 올빼미야수 퀘스트가 빨간색입니다.",
		["Follow the road east across the zone to the chapel."] = "길을 따라 동쪽으로 지역을 가로질러 예배당까지 가세요.",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "길을 따라 서쪽으로 온천 옆 {npc:9298}의 야영지까지 가세요.",
		["Follow the southern road east into the {zone:1423}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "남쪽 길을 따라 동쪽으로 {zone:1423}에 들어가세요. {area:2262}의 폐허는 그 남쪽에 있습니다. {npc:10926}의 유령은 남쪽 끝의 무너진 집 옆에서 놀고 있습니다.",
		["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "{npc:9298}의 안내를 따라 서리망치거인들을 지나 {area:2256} 입구로 가세요. 거인은 하나씩 지나가세요.",
		["For Kernda in {area:1769}: keep it"] = "{area:1769}의 케른다에게: 보관하세요",
		["Free Darrowshire Spirits: talk to them"] = "{npc:11064} 해방: 대화하기",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "얼음엉겅퀴설인은 {area:2244} 남쪽 언덕에, 서리바람 키메라는 {area:2255} 쪽 계곡에 삽니다.",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "보관하세요: 나중에 {zone:1444}의 그레간이 비약을 만듭니다",
		["On {npc:10978}, by the inn"] = "{npc:10978}에게, 여관 옆",
		["Optional: {area:1417}"] = "선택: {area:1417}",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "마차 주변의 보급품을 줍고, 근처 올빼미야수에게서 {npc:10301}의 목걸이를 되찾으세요.",
		["Pristine Yeti Horns"] = "온전한 설인 뿔",
		["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "북쪽으로 {area:2627}까지 가세요. {npc:12384}은(는) 무너진 오두막에 살고, 그의 영수증 장부는 근처의 무너진 여관에 있습니다.",
		["Ride north-west back to the village."] = "북서쪽으로 마을까지 돌아가세요.",
		["Ride south-east down the valley to {npc:10301}'s damaged crate in the snow at {area:2245}, with his wrecked wagon just east of it."] = "계곡을 따라 남동쪽으로 내려가 {area:2245}의 눈 속에 있는 {npc:10301}의 부서진 상자로 가세요. 부서진 마차가 그 바로 동쪽에 있습니다.",
		["Ride west along the road to the night elf village."] = "길을 따라 서쪽으로 나이트 엘프 마을까지 가세요.",
		["Ride west along the road to {npc:10301}."] = "길을 따라 서쪽으로 {npc:10301}에게 가세요.",
		["Short of level 54 after the yetis? Running the {area:1417} (50-54) instead of grinding gets you there faster in a group. Come back to {area:2255} afterwards."] = "설인 사냥 후에도 54레벨이 안 되나요? 사냥 대신 파티로 {area:1417}(50-54)을(를) 돌면 더 빨리 도달합니다. 그 후 {area:2255}(으)로 돌아오세요.",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "{zone:1448}의 마른가지일족 가마솥: 보관하세요",
		["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it."] = "예배당 서쪽, {area:2264} 주변의 스컬지는 두 종류의 스컬지석을 모두 떨어뜨립니다. 그들에게서 {npc:11064}이(가) 솟아오르니 하나하나 대화해 풀어 주세요.",
		["The Winterfall camp"] = "눈사태일족 야영지",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "눈사태일족 펄볼그 마을은 {area:2255} 동쪽에 있습니다. 주술사(56-57), 보초(55-56), 펄볼그(57-58) 모두 당신보다 높습니다. 치유하는 주술사를 먼저 처치하고, 가장자리부터 끌어오세요. 뒤쪽 동굴의 {npc:10738}은(는) 정예이니 들어가지 마세요.",
		["The next guide starts here and flies to {area:3197}."] = "다음 가이드는 여기서 시작해 {area:3197}(으)로 날아갑니다.",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "폐허는 {area:2253} 남쪽의 얼어붙은 호수 주변에 있습니다. 폐허에 놓인 유물 조각 네 개를 줍고, 올빼미야수가 돌아다니는 땅에서 달빛 깃든 깃털을 주우세요.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "인형 조각 세 개는 {area:2262}의 무너진 집들에 있습니다. 하나를 주울 때 유령이 나타날 수 있습니다. 조각을 합쳐 인형을 만드세요.",
		["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Any furbolg here can drop an {item:12771} (about one in ten) and, rarely, a {quest:8471}: right-click whichever drops. Keep the {quest:6031} the furbolgs drop for Meilosh."] = "서쪽 눈사태일족 야영지는 {npc:11556}와(과) {npc:9298} 사이의 언덕에 있습니다. 이곳의 펄볼그는 누구든 {item:12771}(약 10분의 1 확률)을, 드물게 {quest:8471}을(를) 떨어뜨릴 수 있습니다. 떨어진 것을 오른쪽 클릭하세요. 펄볼그가 떨어뜨리는 {quest:6031}은(는) 메일로쉬를 위해 보관하세요.",
		["The western Winterfall furbolgs drop the beads."] = "서쪽 눈사태일족 펄볼그가 구슬을 떨어뜨립니다.",
		["The {area:2247}"] = "{area:2247}",
		["Walk through {area:1769} to {zone:1448} and fly on to the Eastern Kingdoms ({area:442}, the boat to {area:150}). Fly to {area:271} and ride north up the road through Alterac to {area:3197}."] = "{area:1769}을(를) 지나 {zone:1448}(으)로 간 뒤 동부 왕국으로 날아가세요({area:442}, {area:150}행 배). {area:271}(으)로 날아가 알터랙을 지나는 길을 따라 북쪽으로 {area:3197}까지 가세요.",
		["grind on {npc:7460} at the {area:2247}, {zone:1452}"] = "{zone:1452}의 {area:2247}에서 {npc:7460}을(를) 사냥하세요",
		["{item:12771}, a rare drop"] = "{item:12771}, 드문 전리품",
		["{npc:10301}'s camp"] = "{npc:10301}의 야영지",
		["{npc:10301}'s supplies"] = "{npc:10301}의 보급품",
		["{npc:10431}: keep both for the Plaguelands"] = "{npc:10431}: 둘 다 역병지대를 위해 보관하세요",
		["{npc:10926}'s doll"] = "{npc:10926}의 인형",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}: {npc:7583}와(과) {npc:10977}은(는) 나중에",
		["{npc:11038}: {npc:12250} is a level 54 elite"] = "{npc:11038}: {npc:12250}은(는) 54레벨 정예입니다",
		["{npc:11556} guards the mouth of {area:1769}, north-west of {npc:9298}."] = "{npc:11556}은(는) {npc:9298} 북서쪽의 {area:1769} 입구를 지킵니다.",
		["{npc:11629}: keep it for {area:2262}"] = "{npc:11629}: {area:2262}을(를) 위해 보관하세요",
		["{npc:12250} is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "{npc:12250}은(는) 정예이니 파티를 권장합니다. 그는 지역 남서쪽의 지하실인 {area:2261}의 맨 아래에서 기다립니다.",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{quest:5152}, {zone:1422}에서: 보관하세요",
		["{quest:6031}, for Meilosh later"] = "{quest:6031}, 나중에 메일로쉬에게",
		["{quest:8471}, a rare drop"] = "{quest:8471}, 드문 전리품",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "안돌할",
		["Andorhal Watches"] = "안돌할 시계",
		["Back north to the {area:202}: the cauldron offers its own task now. The ghouls nearby drop Somatic Intensifiers."] = "북쪽 {area:202}(으)로 돌아가세요. 이제 가마솥이 직접 퀘스트를 줍니다. 근처 구울들이 체세포 강화물질을 떨어뜨립니다.",
		["Buy one {item:13320} from {npc:11056} for Felstone's cauldron, right before you go: the quickeners vanish after 30 minutes."] = "출발 직전에 펠스톤 가마솥에 쓸 {item:13320} 하나를 {npc:11056}에게서 구입하세요. 촉매제는 30분 후에 사라집니다.",
		["Buy two more Arcane Quickeners for the {area:202}'s and Dalson's cauldrons, and ride straight there: they vanish after 30 minutes."] = "{area:202} 가마솥과 달슨 가마솥에 쓸 비전 촉매제를 두 개 더 구입하고 곧장 가세요. 촉매제는 30분 후에 사라집니다.",
		["Climb the hill west of {area:190} to look down on the town."] = "{area:190} 서쪽 언덕에 올라 마을을 내려다보세요.",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "강을 건너 동쪽, 지역 남서쪽의 지하 묘지인 {area:2261}으로 가세요. {object:177667}은(는) 그 안에 있습니다. 열쇠는 북동쪽 끝의 {npc:12248}이(가) 가지고 있으며, 다음 가이드에서 처리합니다.",
		["Cross the river west to {npc:1855}'s hut."] = "강을 건너 서쪽 {npc:1855}의 오두막으로 가세요.",
		["Diseased Grizzlies"] = "오염된 불곰",
		["Diseased Wolves"] = "역병에 걸린 늑대",
		["Fly to {area:392}."] = "{area:392}(으)로 날아가세요.",
		["For the druids of {zone:1457}: keep it"] = "{zone:1457}의 드루이드용: 보관하세요",
		["For {zone:1448}: keep it"] = "{zone:1448}용: 보관하세요",
		["For {zone:1451}: keep it"] = "{zone:1451}용: 보관하세요",
		["For {zone:1453}: keep it"] = "{zone:1453}용: 보관하세요",
		["From {area:392}, fly to {area:2255} and ride south to {area:2250}."] = "{area:392}에서 {area:2255}(으)로 날아간 뒤 남쪽 {area:2250}(으)로 가세요.",
		["From {area:702}, fly to {area:1116}."] = "{area:702}에서 {area:1116}(으)로 날아가세요.",
		["Gaeriyan in {area:976}: keep it"] = "{area:976}의 개리얀: 보관하세요",
		["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "호르구스의 해골은 {area:2624}에, 마르두크의 검은 {area:2623}에 있으며, 둘 다 유령들이 싸우는 곳입니다. 다 자란 역병사냥개가 그 사이 평원을 사냥합니다.",
		["Listen to his story"] = "그의 이야기를 들으세요",
		["Mark {npc:10902} with the {item:12815}"] = "{item:12815}(으)로 {npc:10902} 표시",
		["Mark {npc:10903} with the {item:12815}"] = "{item:12815}(으)로 {npc:10903} 표시",
		["Mark {npc:10904} with the {item:12815}"] = "{item:12815}(으)로 {npc:10904} 표시",
		["Mark {npc:10905} with the {item:12815}"] = "{item:12815}(으)로 {npc:10905} 표시",
		["More watches"] = "추가 시계",
		["Radley and Durgen"] = "래들리와 드루겐",
		["Ride back south to the camp."] = "남쪽 야영지로 돌아가세요.",
		["Ride back to {area:3197} and fly to {area:150}, take the boat to {area:442} and fly to {area:702}; the portal leads up to {zone:1457}."] = "{area:3197}(으)로 돌아가 {area:150}(으)로 날아간 다음, 배를 타고 {area:442}(으)로 가서 {area:702}(으)로 날아가세요. 차원문을 타면 {zone:1457}(으)로 올라갑니다.",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "동쪽 경계의 강으로 가세요. {npc:1855}은(는) 강둑의 작은 오두막에 삽니다.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "북쪽 길을 따라 북마루 벌목지로 가세요. {npc:11610}은(는) 벌목지 가장자리에 숨어 있습니다.",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "북서쪽 달슨 농장으로 가세요. 일기는 헛간에 있고, 떠도는 해골이 옥외 화장실 열쇠를 가지고 있으며, {npc:10836}은(는) 옥외 화장실에서 진열장 열쇠를 가지고 기다립니다.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "북서쪽 {area:2277} 가장자리의 {area:2276}(으)로 가세요.",
		["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "남쪽 {area:201}(으)로 가세요. {npc:11078}이(가) 가마솥을 지킵니다.",
		["Ride south-west to the camp."] = "남서쪽 야영지로 가세요.",
		["Ride west along the road to the hot springs."] = "길을 따라 서쪽 온천으로 가세요.",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "서쪽으로 {area:2627}까지 가세요. 숲에는 {npc:8596}, {npc:8600}, {npc:8603}이(가) 돌아다닙니다. 큰 흰개미 둔덕에서 {item:15042}을(를) 채우고, 더 북쪽에서 {npc:8598}을(를) 처치하세요.",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones."] = "해골 타작꾼과 걸신들린 구울이 야영지 북쪽 들판을 배회합니다. 이곳의 스컬지는 모두 스컬지석을 떨어뜨립니다.",
		["Small lockboxes lie in the rubble all over Andorhal; each holds a watch."] = "안돌할 곳곳의 잔해 속에 작은 금고가 있고, 각각 시계가 하나씩 들어 있습니다.",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "배를 타고 본토로 건너가 북동쪽 {area:1119} 옆에 있는 {npc:14637}의 야영지로 가세요.",
		["Temple of the Moon"] = "달의 신전",
		["Ten {item:11040} from the {item:11020}"] = "{item:11020}에서 {item:11040} 10개",
		["The Andorhal watchtowers"] = "안돌할 감시탑",
		["The Scarlet Crusade"] = "붉은십자군",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "붉은십자군 의무병, 붉은십자군 사냥꾼, 붉은십자군 기사, 붉은십자군 마법사가 벌목지와 {area:190}(으)로 가는 길을 순찰합니다.",
		["The cauldron now offers its own task; the skeletons around it drop Osseous Agitators."] = "이제 가마솥이 직접 퀘스트를 줍니다. 주변 해골들이 골성 교반기를 떨어뜨립니다.",
		["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "가마솥은 {npc:10739}의 농장 옆 {area:202}에 있습니다.",
		["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "가마솥은 펠스톤 북동쪽 {area:200}에 있고, 가마솥군주가 그 옆에 서 있습니다.",
		["The fields"] = "들판",
		["The next guide starts here in {area:392} and flies on to {area:976}."] = "다음 가이드는 여기 {area:392}에서 시작해 {area:976}(으)로 날아갑니다.",
		["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "축소된 거인들은 {area:1119}을(를) 돌아다니고, 바다 정령들은 서쪽 해안을 따라 물속을 걷습니다.",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "곡물 저장고 옆에서 {item:12627}을(를) 사용해 시간의 기생충을 끌어내세요. {quest:5154}은(는) 시청에 있는 낡은 책 중 하나입니다. 마을의 모든 해골이 {quest:5537}을(를) 떨어뜨립니다.",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "야영지 북쪽, 안돌할 가장자리에 있는 네 감시탑 아래에서 각각 {item:12815}을(를) 사용하세요.",
		["Walk into {area:1769} and take the {zone:1450} branch of the tunnel to {area:2361}."] = "{area:1769}에 들어가 터널의 {zone:1450} 갈림길을 따라 {area:2361}(으)로 가세요.",
		["Zapped giants and sea elementals"] = "축소된 거인과 바다 정령",
		["grind on {npc:1796} at the {area:202}, {zone:1422}"] = "{zone:1422} {area:202}에서 {npc:1796} 사냥",
		["{area:190} overlook"] = "{area:190} 전망 지점",
		["{area:199} cauldron"] = "{area:199} 가마솥",
		["{area:200} cauldron"] = "{area:200} 가마솥",
		["{area:201} cauldron"] = "{area:201} 가마솥",
		["{area:202} cauldron"] = "{area:202} 가마솥",
		["{item:12894}, at the monument"] = "기념비의 {item:12894}",
		["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954}은(는) {npc:1855} 서쪽 {area:190}의 시청에 있습니다. 붉은십자군 경비병들이 가까이 붙어 서 있습니다.",
		["{item:12955} lies east of the barn at {area:201}."] = "{item:12955}은(는) {area:201}의 헛간 동쪽에 있습니다.",
		["{item:13320}, from {npc:11056}"] = "{npc:11056}에게서 {item:13320}",
		["{npc:10300} in {zone:1452}: keep it"] = "{zone:1452}의 {npc:10300}: 보관하세요",
		["{npc:10300}: her escort comes later on the route"] = "{npc:10300}: 호위 퀘스트는 경로 후반에 합니다",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667}은(는) 안돌할 서쪽의 무너진 여관에서 기다립니다.",
		["{npc:10739} stands by the farm at the {area:202}, north-east of the fields."] = "{npc:10739}은(는) 들판 북동쪽, {area:202}의 농장 옆에 있습니다.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "{npc:10778}의 유령은 {area:200} 서쪽, {area:199}의 농가 근처를 떠돕니다. 소포는 농가 안에 있습니다.",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878}와(과) {npc:7740}은(는) 달의 신전 옆에 있습니다. 안쪽 달샘에서 {item:11682}을(를) 채우세요.",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "{npc:10927}의 농가는 야영지 동쪽 언덕 위에 있고, {npc:10936}의 기념비는 바로 그 북쪽에 있습니다.",
		["{npc:11038}, by the graves south of the chapel"] = "예배당 남쪽 무덤 옆의 {npc:11038}",
		["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075}이(가) 안돌할 서쪽 {area:199}의 가마솥을 지킵니다.",
		["{npc:11140} stands by Augustus' hut in {area:2627}."] = "{npc:11140}은(는) {area:2627}의 아우구스투스 오두막 옆에 있습니다.",
		["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at {area:190}'s southern approach."] = "{npc:11613}은(는) {npc:11610} 동쪽의 북마루 벌목지를 돌아다니고, {npc:11611}은(는) {area:190} 남쪽 진입로의 탑을 지킵니다.",
		["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}: 흰개미는 나중에 {area:2627}에서 모읍니다",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886}은(는) 정예이므로 파티를 권장합니다",
		["{npc:1852} is a level 61 elite"] = "{npc:1852}은(는) 61레벨 정예입니다",
		["{npc:1852} is elite: grouping up is advised. He guards his phylactery in the middle of Andorhal."] = "{npc:1852}은(는) 정예이므로 파티를 권장합니다. 안돌할 중앙에서 성물함을 지킵니다.",
		["{npc:5411} in {area:976}: keep it"] = "{area:976}의 {npc:5411}: 보관하세요",
		["{npc:5901}, on the coast north of town"] = "마을 북쪽 해안의 {npc:5901}",
		["{npc:7740}: keep it for {area:976}"] = "{npc:7740}: {area:976}용으로 보관하세요",
		["{npc:7775}'s camp lies north of the {area:1119}. He sells the {item:11243} once he has his bait."] = "{npc:7775}의 야영지는 {area:1119} 북쪽에 있습니다. 미끼를 받으면 {item:11243}을(를) 팝니다.",
		["{npc:7900}: keep it for {zone:1446}"] = "{npc:7900}: {zone:1446}용으로 보관하세요",
		["{npc:8496}: keep it for Un'Goro"] = "{npc:8496}: 운고로용으로 보관하세요",
