		["{zone:1455}, where the next guide trains, has no druid trainer"] = "다음 가이드에서 훈련하는 {zone:1455}에는 드루이드 상급자가 없습니다",
} end)()
t.guides["forever/alliance/50-60/05-silithus"] = (function() return {
		["Chromie in Andorhal: keep it"] = "안돌할의 크로미: 보관하세요",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "{npc:11741}은(는) 더 서쪽을 파고, {npc:11736}, 돌꼬리채찍전갈, {npc:11739}이(가) 같은 모래밭에서 사냥합니다.",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "{npc:11740}은(는) 요새 북서쪽 모래언덕을 파고, {npc:11735}와(과) {npc:11738}은(는) 사방을 돌아다닙니다.",
		["Dredge and scorpids"] = "미늘벌레와 전갈",
		["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; {npc:9117} is up the hill behind it."] = "{area:976}에서 {area:541}(으)로 날아가세요. {npc:8737}의 오두막은 야영지 서쪽 {area:538}에 있고, {npc:9117}은(는) 그 뒤 언덕 위에 있습니다.",
		["Fly to {area:271} and ride north up the road toward Alterac: Haggerdin camps at {area:1056} beside it."] = "{area:271}(으)로 날아가 길을 따라 북쪽 알터랙 쪽으로 가세요. 해거딘은 길 옆 {area:1056}에 진을 치고 있습니다.",
		["For {area:3197}: keep it"] = "{area:3197}에 쓸 것: 보관하세요",
		["For {npc:10778}: keep it"] = "{npc:10778}에게 줄 것: 보관하세요",
		["For {zone:1448}: keep it"] = "{zone:1448}에 쓸 것: 보관하세요",
		["From {area:392}, fly to {area:976}."] = "{area:392}에서 {area:976}(으)로 날아가세요.",
		["Its jars are filled on the next Un'Goro visit"] = "단지는 다음 운고로 방문 때 채웁니다",
		["On {npc:7583}"] = "{npc:7583}에게",
		["Ride back to {area:3425} and fly to {area:392}."] = "{area:3425}(으)로 돌아가 {area:392}(으)로 날아가세요.",
		["Ride east to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "동쪽으로 {area:2738}의 {area:2742} 탑으로 가세요. 탑에 올라 딱딱한 실리시드 조각을 노리고 나타나는 잠복꾼을 처치하세요.",
		["Ride east to {npc:13220}."] = "동쪽으로 {npc:13220}에게 가세요.",
		["Ride north to the {area:2277}'s north-eastern edge."] = "북쪽으로 {area:2277}의 북동쪽 끝까지 가세요.",
		["Ride on north to {area:3197} and fly to {area:2268}."] = "계속 북쪽으로 {area:3197}까지 가서 {area:2268}(으)로 날아가세요.",
		["Ride out of the crater's north-western pass into {zone:1451} and on to {area:3425}."] = "분화구 북서쪽 고개로 나가 {zone:1451}에 들어가 {area:3425}까지 가세요.",
		["Ride south-west to the {area:2261}. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised."] = "남서쪽으로 {area:2261}까지 가세요. 흙더미는 안쪽에 있습니다. {npc:11886}은(는) 정예이니 파티를 권합니다.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "남서쪽으로 {area:1938}의 {npc:7771} 야영지로 가세요.",
		["Scourge Champions"] = "{npc:8529}",
		["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "{npc:8529}(59)은(는) {area:2268} 북쪽 {area:2270}을(를) 돌아다닙니다. 처치할 때마다 {npc:11063}의 {item:13156}을(를) 갖다 대세요. 공명하는 해골이 그가 원하는 것입니다. 하나씩 끌어오세요.",
		["Sixty {item:2592}, if you carry them"] = "{item:2592} 60장, 가지고 있다면",
		["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "{area:392}에서 배를 타고 {area:35}(으)로 간 뒤 {zone:1453}로 날아가세요.",
		["Take the {area:2257} to {zone:1455}."] = "{area:2257}을(를) 타고 {zone:1455}(으)로 가세요.",
		["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}."] = "{npc:6517}은(는) {area:538}에서 뒹굴고, 한가운데 {area:537}의 불의 정령이 재를, 남쪽 {area:540}의 고리쉬 말벌이 분비샘을 가지고 있습니다. 분화구의 모든 생물이 {item:11018}을(를) 떨어뜨릴 수 있습니다.",
		["The crater"] = "분화구",
		["The next guide starts here in {area:392}."] = "다음 가이드는 여기 {area:392}에서 시작합니다.",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "고통받는 드루이드와 고통받는 파수꾼이 {npc:13220} 남서쪽의 폐허가 된 마을을 떠돕니다.",
		["The western dunes"] = "서쪽 모래언덕",
		["The {area:2742} tower"] = "{area:2742} 탑",
		["Umber in {zone:1450}: keep it"] = "{zone:1450}의 움버: 보관하세요",
		["grind on {npc:8532} at the {area:2258}, {zone:1423}"] = "{zone:1423} {area:2258}에서 {npc:8532} 사냥",
		["{item:13155}, from the Scourge Champions"] = "{item:13155}, {npc:8529}에게서",
		["{item:14613}, from {npc:11886}"] = "{item:14613}, {npc:11886}에게서",
		["{npc:14724}, by the tram"] = "{npc:14724}, 지하철 옆",
		["{npc:332}, in SI:7"] = "{npc:332}, SI:7 안",
		["{npc:3520}, who walks the canals"] = "{npc:3520}, 운하를 걸어다님",
		["{npc:9299} waits at the graveyard just east of town; the gravestone stands nearby."] = "{npc:9299}은(는) 마을 바로 동쪽 묘지에서 기다리며, 묘비는 그 근처에 서 있습니다.",
		["{quest:3444} is in {area:392}"] = "{quest:3444}은(는) {area:392}에 있습니다",
		["{quest:6184} at {area:3197}: keep it"] = "{area:3197}의 {quest:6184}: 보관하세요",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "안돌할",
		["Angerclaw bears and Felpaw wolves"] = "성난발톱곰과 악령발늑대",
		["Araj is elite: grouping up is advised."] = "아라즈는 정예이니 파티를 권합니다.",
		["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber."] = "다시 {area:1770}(으)로: 가장 깊은 방에서 {npc:9861}와(과) {npc:9860}이(가) {npc:9517}을(를) 지킵니다.",
		["Bronzebeard's Encampment"] = "브론즈비어드 야영지",
		["Calandrath, the innkeeper"] = "여관주인 캘랜드라스",
		["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "분화구 한가운데의 {area:537}에 올라, {item:12359} 2개를 가방에 넣은 채 꼭대기 용암 호수 옆에서 {item:14644}을(를) 사용하세요. 마루 주변 웅덩이의 {npc:6557}에게 {npc:9616}의 {item:11953}을(를) 채우세요.",
		["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there."] = "{npc:1855} 동쪽의 강을 건너 {area:2627}에 들어가세요. {npc:14564}이(가) 그곳 숲을 떠돕니다.",
		["Dredge Crushers roam the dunes between {area:2743} and {area:3425}, on your way back. {npc:15181} only offers {quest:8304} from level 58."] = "{npc:11741}은(는) 돌아가는 길의 {area:2743}와(과) {area:3425} 사이 모래언덕을 돌아다닙니다. {npc:15181}은(는) 58레벨부터 {quest:8304}을(를) 줍니다.",
		["Fly to {area:3137} in {zone:1447} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "{zone:1447}의 {area:3137}(으)로 날아간 뒤 길을 따라 서쪽으로 {zone:1440} 경계를 막 넘은 {area:2358}까지 가세요.",
		["Fly to {area:976}."] = "{area:976}(으)로 날아가세요.",
		["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "길을 따라 북쪽 {area:1767}(으)로 가세요. {npc:7139}이(가) 심장을 가지고 있습니다. 발톱은 북쪽의 성난발톱불곰과 {npc:8961}에게서 마저 모으세요.",
		["Follow the road south-west out of the pass to {area:3425}."] = "고개에서 길을 따라 남서쪽 {area:3425}(으)로 가세요.",
		["Go back down to {area:702}, take the boat to {area:442} and the boat on to {area:17203}. Bring sixty Silk, sixty Mageweave and sixty {item:14047} for {npc:14722}: buy what you lack at the Auction House."] = "{area:702}(으)로 내려가 배를 타고 {area:442}(으)로, 다시 배를 타고 {area:17203}(으)로 가세요. {npc:14722}에게 줄 비단 옷감 60장, 마법 옷감 60장, {item:14047} 60장을 가져가세요. 부족한 것은 경매장에서 사세요.",
		["Grind to 58"] = "58레벨까지 사냥",
		["Grind to 59"] = "59레벨까지 사냥",
		["Grind to 60"] = "60레벨까지 사냥",
		["Hand him the ten texts you kept"] = "보관해 둔 문서 10개를 그에게 건네세요",
		["Havunth's camp sits just west of {area:3425}."] = "하분스의 야영지는 {area:3425} 바로 서쪽에 있습니다.",
		["Hearth to {area:1519} and train your level 60 spells. This is the end of the leveling route: look at the reputation and dungeon guides next."] = "{area:1519}(으)로 귀환해 60레벨 주문을 배우세요. 레벨업 경로는 여기서 끝납니다. 다음으로 평판과 던전 가이드를 보세요.",
		["Hearth to {area:392} and fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "{area:392}(으)로 귀환한 뒤 {area:976}(으)로 날아가세요. {quest:5801}에 쓸 {item:12359} 2개를 이곳 경매장에서 사세요.",
		["Into {zone:1451}"] = "{zone:1451}(으)로",
		["Irontree Stompers"] = "{npc:7139}",
		["Keep the {item:11169}, the claws and the heart he hands back"] = "그가 돌려주는 {item:11169}, 발톱, 심장은 보관하세요",
		["Keep west on the road to {npc:9298}'s camp beside the hot springs."] = "길을 따라 계속 서쪽으로 온천 옆 {npc:9298}의 야영지로 가세요.",
		["Level 60"] = "60레벨",
		["Ride back north to {area:2255} and west along the road to the night elf village."] = "북쪽으로 {area:2255}에 돌아간 뒤 길을 따라 서쪽의 나이트 엘프 마을로 가세요.",
		["Ride back south along the road to the Sanctuary."] = "길을 따라 남쪽으로 성소에 돌아가세요.",
		["Ride back south-east to the hermit."] = "남동쪽으로 은둔자에게 돌아가세요.",
		["Ride back south-west to {area:3197}."] = "남서쪽으로 {area:3197}에 돌아가세요.",
		["Ride back to {area:3137} and fly to {area:2255}."] = "{area:3137}(으)로 돌아가 {area:2255}(으)로 날아가세요.",
		["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "동쪽 언덕으로 가세요. {item:11169}을(를) 사용해 {quest:4005}을(를) 소환한 뒤 처치해 토템을 얻으세요.",
		["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "동쪽으로 {area:2738}의 폐허로 가세요. {object:179565}은(는) 무너진 건물 사이에 있으며 {npc:12179}이(가) 지키고 있습니다.",
		["Ride north along the west side to Mayna's small camp."] = "서쪽을 따라 북쪽으로 메이나의 작은 야영지에 가세요.",
		["Ride north out of {area:415} into {zone:1448} to the druids' camp on the road just past the border."] = "{area:415}에서 북쪽으로 {zone:1448}에 들어가, 경계를 막 지난 길가의 드루이드 야영지로 가세요.",
		["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "북쪽으로 {area:1769} 동굴 입구 옆 마른가지일족 펄볼그 마을로 가세요.",
		["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "북쪽으로 {area:541}까지 가세요. {npc:10977} 옆에서 {npc:10980}을(를) 사용하세요.",
		["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "길을 따라 북쪽의 제재소로 가서 한가운데에 흰개미 통을 내려놓으세요.",
		["Ride south to {area:2250}. Protect {npc:10300} while she lights the torches on the way to the {object:177404}."] = "남쪽으로 {area:2250}까지 가세요. {npc:10300}이(가) {object:177404}(으)로 가는 길에 횃불을 켜는 동안 그녀를 보호하세요.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand just south-east of the camp."] = "남서쪽으로 남쪽 산맥 근처의 드워프 야영지에 가서 {npc:15171}와(과) {npc:15170}에게 물어보세요. {npc:15190}의 가방은 야영지 바로 남동쪽 모래 속에 있습니다.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "남서쪽으로 {area:1938}의 {npc:7771} 야영지로 가세요.",
		["Ride west along the crater's northern wall to the pass in the north-west corner that climbs into {zone:1451}."] = "분화구 북쪽 벽을 따라 서쪽으로 가서, 북서쪽 구석의 {zone:1451}(으)로 올라가는 고개로 가세요.",
		["Running {area:2057} ({area:2298}, south-east {zone:1422}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "파티라면 사냥 대신 {area:2057}({zone:1422} 남동쪽 {area:2298})이나 {area:2279}을(를) 도는 편이 더 빠릅니다. 혼자 사냥하려면 이 단계를 건너뛰세요.",
		["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "파티라면 사냥 대신 {zone:1444}의 {area:2577}을(를) 도는 편이 더 빠릅니다. 혼자 사냥하려면 이 단계를 건너뛰세요.",
		["Shaman training"] = "주술사 수련",
		["Take the boat from {area:442} to {area:702}."] = "{area:442}에서 배를 타고 {area:702}(으)로 가세요.",
		["Take the flight path in {area:2361} and fly to {area:442}."] = "{area:2361}에서 비행 경로를 타고 {area:442}(으)로 날아가세요.",
		["Take the portal up to {zone:1457}."] = "차원문을 타고 {zone:1457}(으)로 올라가세요.",
		["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "길을 따라 서쪽 분화구로 내려가 남쪽의 실리시드 동굴인 {area:540}으로 가세요. {npc:10041}이(가) 가장 깊은 방에서 기다립니다.",
		["Take the {area:1769} tunnel from its {zone:1452} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "{npc:9298} 서쪽의 {zone:1452} 쪽 입구에서 {area:1769} 터널을 타고 {area:493} 갈림길을 따라 {area:2361}(으)로 가세요. {npc:11939}은(는) 호숫가에서 연구 중입니다.",
		["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each want sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: 120 of each in all, from your bags or the Auction House."] = "{area:2257}을(를) 타고 {zone:1455}(으)로 가세요. {npc:14724}와(과) {npc:14723}은(는) 각각 양모 옷감 60장, 비단 옷감 60장, 마법 옷감 60장, 그다음 {item:14047} 60장을 원합니다. 종류별로 총 120장이며, 가방에 있는 것이나 경매장에서 구하세요.",
		["Ten more for {quest:8323}"] = "{quest:8323}에 10개 더",
		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "황혼의 망치단 발굴지가 북서쪽 구석을 채우고 있습니다. 서판 조각은 땅바닥에 있고, {npc:11744}와(과) {npc:11746}도 가지고 있습니다. 이교도는 누구나 {item:20404}을(를) 떨어뜨릴 수 있습니다. 20개를 보관하세요. 10개는 {npc:15306}에게, 10개는 나중에 {npc:15194}에게 줍니다.",
		["The hermit hides among the rocks south-east of {area:2738}."] = "은둔자는 {area:2738} 남동쪽 바위 사이에 숨어 있습니다.",
		["The {area:2479}"] = "{area:2479}",
		["The {area:2739}"] = "{area:2739}",
		["The {area:3098}"] = "{area:3098}",
		["The {npc:7446} bears roam the snowy valley south of {area:2250}."] = "{npc:7446} 곰은 {area:2250} 남쪽의 눈 덮인 골짜기를 돌아다닙니다.",
		["Toward the north-west pass"] = "북서쪽 고개 방향",
		["Twilight Tablet Fragments"] = "{item:20378}",
		["Twilight's Hammer cultists"] = "황혼의 망치단 이교도",
		["Use the jars on slain oozes"] = "처치한 수액괴물에게 단지를 사용하세요",
		["Wait a moment for {npc:9116}"] = "{npc:9116}을(를) 잠시 기다리세요",
		["You start in {area:392}, where the previous guide hearthed you. Fly to {area:415}."] = "이전 가이드에서 귀환석으로 돌아온 {area:392}에서 시작합니다. {area:415}(으)로 날아가세요.",
		["grind on {npc:11741} at the dunes east of {area:2743}, {zone:1451}"] = "{zone:1451} {area:2743} 동쪽 모래언덕에서 {npc:11741} 사냥",
		["grind on {npc:14564} at {area:2627}, {zone:1423}"] = "{zone:1423} {area:2627}에서 {npc:14564} 사냥",
		["grind on {npc:7446} at the valley south of {area:2250}, {zone:1452}"] = "{zone:1452} {area:2250} 남쪽 골짜기에서 {npc:7446} 사냥",
		["{area:1770} braziers"] = "{area:1770} 화로",
		["{area:1770} is the cave at the back of {area:1763}, west of the road. Use the {item:12906} on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the {item:11172}."] = "{area:1770}은(는) 길 서쪽 {area:1763} 안쪽의 동굴입니다. 안에 있는 화로 네 개에 {item:12906}을(를) 사용하세요. 지나가며 만나는 성난발톱곰과 악령발늑대를 처치해 {item:11172}을(를) 모으세요.",
		["{area:2057} (optional)"] = "{area:2057}(선택)",
		["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057}은(는) 58-60레벨에 맞습니다. {quest:5505}은(는) 아래 {area:3197}에서 제출합니다.",
		["{area:2577} (optional)"] = "{area:2577}(선택)",
		["{area:2577} fits levels 55 to 60; the {npc:7446} grind below gets you to 59 alone."] = "{area:2577}은(는) 55-60레벨에 맞습니다. 아래의 {npc:7446} 사냥만으로도 혼자 59레벨까지 오를 수 있습니다.",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667}은(는) 야영지 북쪽의 폐허 도시 안돌할 서쪽, 무너진 여관에서 기다립니다. {npc:1852}은(는) 마을 한가운데에서 성물함을 지킵니다.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "{npc:10778}의 유령은 안돌할 서쪽 {area:199}의 농가 옆을 떠돕니다. 들판의 {npc:10801}이(가) 부적의 나머지 반쪽을 가지고 있습니다. 두 반쪽을 합치세요.",
		["{npc:10924}: ends in {zone:1452}, keep it"] = "{npc:10924}: {zone:1452}에서 끝납니다, 보관하세요",
		["{npc:11557}, if you have thirty {quest:6031}"] = "{npc:11557}, {quest:6031} 30장이 있다면",
		["{npc:11558}, just inside the cave: only from Neutral with the Timbermaw"] = "{npc:11558}, 동굴 바로 안쪽: 나무구렁 요새와 중립 이상일 때만",
		["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "{npc:11801}의 집은 {area:2361}, {npc:11939}의 동쪽에 있습니다.",
		["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803}이(가) 맨 남서쪽의 이교도 야영지를 지킵니다.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}, {object:2096} 안",
		["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp."] = "{npc:17080}은(는) 서쪽 벌집인 {area:2743} 바깥에 진을 치고 있습니다. 근처 붉은 간헐천에서 실리시스트를 집어 그의 야영지에 있는 얼라이언스 추출기로 가져가세요.",
		["{npc:17082}, at the Alliance tents"] = "{npc:17082}, 얼라이언스 천막",
		["{npc:1852} is a level 61 elite"] = "{npc:1852}은(는) 61레벨 정예입니다",
		["{npc:1855} (optional)"] = "{npc:1855}(선택)",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855}은(는) 벌목지 북동쪽, 경계 강가의 작은 오두막에 삽니다. {quest:5781}을(를) 완료했다면 제출하세요.",
		["{npc:3516}, atop the {area:1658}"] = "{npc:3516}, {area:1658} 꼭대기",
		["{npc:4155}, in the bank"] = "{npc:4155}, 은행 안",
		["{npc:7740} in {zone:1457}: keep it"] = "{zone:1457}의 {npc:7740}: 보관하세요",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740}, 달의 신전 안",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, 야영지 안쪽",
		["{npc:9598} waits in {area:1767}. Escort her out of the woods and keep her alive."] = "{npc:9598}이(가) {area:1767}에서 기다립니다. 숲 밖까지 그녀를 호위하고 살려 두세요.",
		["{object:176091}, if you found the Firewater flask in {zone:1452}"] = "{object:176091}, {zone:1452}에서 화주 병을 찾았다면",
		["{quest:5085}: {npc:9298} in {zone:1452}, keep it"] = "{quest:5085}: {zone:1452}의 {npc:9298}, 보관하세요",
		["{zone:1451}, {zone:1448}, {zone:1452} & the Plaguelands"] = "{zone:1451}, {zone:1448}, {zone:1452}와(과) 역병지대",
		["{zone:1453} has no shaman trainer"] = "{zone:1453}에는 주술사 상급자가 없습니다",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455} and train your level 60 spells with {npc:258098}."] = "{zone:1453}에는 주술사 상급자가 없습니다. {object:28027}에서 {area:2257}을(를) 타고 {zone:1455}(으)로 가서 {npc:258098}에게 60레벨 주문을 배우세요.",
} end)()
t.guides["forever/alliance/dwarf-gnome/01-dun-morogh"] = (function() return {
		["A few Frostmane Troll Whelps if you are short"] = "부족하면 {npc:706} 몇 마리",
		["A few more troggs outside if you are short"] = "모자라면 밖에서 트로그를 몇 마리 더",
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "굴을 지나 농장 위 {npc:257597}의 동굴로 돌아가세요.",
		["Back to {area:77}"] = "{area:77}(으)로 돌아가기",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "{area:77}의 {npc:257446}에게 돌아가세요. 그가 {item:6635}을(를) 줍니다. 골짜기 남쪽에서 서쪽으로 올라가는 돌무더기 표시 길을 따라 능선의 정령석까지 가서, 그 옆에서 삽타를 마시고 {npc:5891}에게 말을 건 뒤, 그 {item:6656}을(를) 테오에게 가져가세요.",
		["Back to {npc:257597}"] = "{npc:257597}에게 돌아가기",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {zone:1436} is next, west of {area:87}."] = "{npc:6122}에게 돌아가세요. {object:2164} 지하실의 소환진에서 {item:6928}을(를) 사용하고 나타나는 공허방랑자를 물리치세요. 다음은 {area:87} 서쪽의 {zone:1436}입니다.",
		["Boars and bears"] = "멧돼지와 곰",
		["Cornelius is missing in the {area:136}: find him inside, then go back to Gretchen."] = "{area:136}에서 Cornelius가 실종되었습니다. 안에서 그를 찾은 뒤 그레첸에게 돌아가세요.",
		["Crag Boars and Young Black Bears roam the fields around {area:131} and the depot."] = "멧돼지와 새끼 흑곰이 {area:131}와(과) 정거장 주변 들판을 돌아다닙니다.",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "그리프 와일드하트의 퀘스트마다 {item:15908}을(를) 줍니다. 그가 지정한 야수에게 사용한 뒤, {area:131} 대장간의 그에게 막대를 가져가세요. 큰 바위멧돼지, 눈표범, 얼음발톱흰곰 모두 {area:131} 바로 남쪽과 동쪽 들판을 돌아다닙니다.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "파르센은 서쪽에서 {area:134}을(를) 내려다보는 능선에 진을 치고 있습니다. 그에게 말을 걸어 원시를 받으세요.",
		["Feather Charms, from the Frostmane Novices"] = "깃털 부적, 서리갈기부족 견습마법사에게서",
		["Firewood"] = "장작",
		["Follow the road all the way east to the {area:806} at the {zone:1432} tunnel."] = "길을 따라 동쪽 끝까지 가서 {zone:1432} 굴 앞의 {area:806}(으)로 가세요.",
		["Follow the road east past the depot to {area:138}."] = "길을 따라 동쪽으로 정거장을 지나 {area:138}까지 가세요.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "{area:131}에서 길을 따라 북동쪽으로 {zone:1455} 길 아래의 정거장까지 가세요.",
		["Follow the road through the tunnel and north-east to {area:131}. Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. {npc:1252}, Eric and his campfire are outside the {area:2102}. {npc:6806}, {npc:1226} and {npc:1267} are inside. {npc:1872} works the forge."] = "굴을 지나 길을 따라 북동쪽으로 {area:131}까지 가세요. 가는 길에 멧돼지를 처치하세요. {npc:1267}의 퀘스트를 받기 전에도 갈비가 떨어지며 퀘스트에 포함됩니다. {npc:1252}, 에릭과 그의 모닥불은 {area:2102} 밖에 있습니다. {npc:6806}, {npc:1226}, {npc:1267}은(는) 안에 있습니다. {npc:1872}은(는) 대장간에서 일합니다.",
		["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {zone:1426} drop it, and the Auction House sells it."] = "길을 따라 {zone:1455}(으)로 올라가 {object:32362}(으)로 가세요. {npc:5149}, {npc:6179}, {npc:6178}은(는) {object:32386}에 있습니다. 거지인 {npc:6175}은(는) 도시를 돌아다닙니다. 그는 {item:2589} 10개를 요구합니다. {zone:1426}의 트로그와 트롤이 떨어뜨리고, 경매장에서도 팝니다.",
		["Follow the road up to {zone:1455} and train with your class trainer. The {area:2257} leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "길을 따라 {zone:1455}(으)로 올라가 직업 상급자에게 훈련을 받으세요. {area:2257}은(는) 도시 동쪽의 {object:171524}에서 출발합니다. 그것을 타고 {zone:1453}(으)로 가세요.",
		["From the {quest:2997} she gives you"] = "그녀가 주는 {quest:2997}에서",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "{npc:706}은(는) {npc:786}의 야영지 남쪽과 동쪽 비탈에 가득합니다.",
		["Gnomes, bears and leopards"] = "노움, 곰, 표범",
		["Go through the tunnel into {zone:1432}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "굴을 지나 {zone:1432}에 들어가세요. 굴을 지나자마자 돌로 표시된 길이 북쪽으로 가는 길 오른편 언덕을 올라 {npc:257808}의 야영지로 이어집니다.",
		["Hearth to {area:131}"] = "{area:131}(으)로 귀환",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "{item:264356}, 야영지 위 비탈의 {npc:706}에게서",
		["Inside {area:77}"] = "{area:77} 안",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "정문으로 {zone:1453}을(를) 나가 남쪽으로 {area:87}까지 간 뒤, 길을 따라 동쪽으로 {area:62}까지 가세요. {npc:881}(9레벨)은(는) 농가 옆에 서 있습니다.",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "정문으로 {zone:1453}을(를) 나가세요. {quest:1861} 폭포는 성문 남서쪽, 서쪽 {zone:1436}(으)로 가는 길에 있습니다. 폭포 아래에서 {item:7207}을(를) 채우세요.",
		["Leopards and boars"] = "표범과 멧돼지",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "브루날 마을과 {area:133} 길 주변의 오염된 노움이 톱니와 기어를 지니고 있습니다. 얼음발톱흰곰, 덩치큰 멧돼지, 눈표범이 호수 주변 언덕을 돌아다닙니다.",
		["Level 4 spells, before Gozwin's camp"] = "4레벨 주문, 고즈윈의 야영지 전에",
		["Minor Ice Elementals drift around the frozen lake by the refuge. The three rifles are in the snow around it."] = "하급 얼음 정령이 피난처 옆 얼어붙은 호수 주변을 떠다닙니다. 소총 세 자루는 그 주변 눈밭에 있습니다.",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "새끼 회색갈기늑대가 {area:77} 바로 남쪽 눈밭을 돌아다닙니다.",
		["Ride back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "{zone:1455}에서 나와 길을 따라 동쪽으로 {area:212}까지 가세요. {npc:6177}은(는) 호숫가에 죽어 있습니다. 그에게 {item:6866}을(를) 사용하세요. 호수 주변을 몰래 돌아다니는 검은무쇠단 비밀요원이 문서를 가지고 있습니다.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}."] = "채석장 북쪽 {area:212} 옆의 바위턱일족 잠복꾼과 더 동쪽의 바위턱일족 투사가 {quest:95214}을(를) 떨어뜨립니다.",
		["Rockjaw Bonesnappers prowl the quarry and {area:212}; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "{npc:1117}은(는) 채석장과 {area:212}을(를) 어슬렁거리고, 검은무쇠단 비밀요원은 호숫가를 몰래 돌아다닙니다. 비밀요원 하나가 {item:274268}을(를) 떨어뜨립니다.",
		["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by {area:212} drop the {item:268548}."] = "바위턱일족 망치잡이가 채석장에 가득하고, {area:212} 옆의 바위턱일족 잠복꾼이 {item:268548}을(를) 떨어뜨립니다.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "바위턱트로그와 힘센 바위턱트로그가 {area:77} 남쪽 골짜기 바닥 곳곳에서 땅을 팝니다.",
		["Sit by Eric's campfire (type /sit) and wait for the buff, then {npc:1699} in the distillery teaches you cooking."] = "에릭의 모닥불 옆에 앉아(/앉기 입력) 버프를 기다린 뒤, 양조장 안의 {npc:1699}에게 요리를 배우세요.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "작은 멧돼지가 {npc:714}의 야영지 주변과 골짜기 서쪽을 따라 풀을 뜯습니다.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "눈표범과 멧돼지가 농장과 채석장 사이 눈밭을 돌아다닙니다. 대장장이: 구리 주괴는 {item:2770}을(를) 제련하거나 직업용품 상인에게서 구합니다.",
		["Speak with {npc:1699}"] = "{npc:1699}에게 말을 거세요",
		["Spies and Bonesnappers"] = "첩자와 뼈다귀싸움꾼",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "가루바위일족 점쟁이(13레벨)는 {npc:257808} 남쪽, {area:923} 남부의 트로그들 사이에 서 있고, 동굴쥐일족 흙점쟁이(12레벨)는 호수 북쪽 끝의 {area:149}에서 일합니다. 트로그는 무리 지어 다니고 일부는 원거리 공격을 합니다. 하나씩 끌어오세요.",
		["Subdue the voidwalker"] = "공허방랑자 제압",
		["The Fire Spirit Stone"] = "불의 정령석",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "두르난의 뜨거운 새벽주는 5분 동안 유지됩니다. 곧장 북쪽으로 {area:77} 안의 {npc:836}에게 가세요.",
		["The ammo crate sits in the Frostmane camp on {area:802}; {npc:1243} camps south of it, by the road to Coldridge."] = "탄약 상자는 {area:802}의 서리갈기부족 야영지에 있습니다. {npc:1243}은(는) 그 남쪽, 눈마루 골짜기로 가는 길가에 진을 치고 있습니다.",
		["The boars"] = "멧돼지",
		["The cold"] = "추위",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "장작은 피난처 옆 얼어붙은 호수 주변 눈밭에 있습니다.",
		["The quarry lies south-east of the ranch."] = "채석장은 농장 남동쪽에 있습니다.",
		["The quarry troggs"] = "채석장 트로그",
		["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "지하철은 {object:28027}에 도착합니다. {npc:5480}은(는) {object:2100}에서 전사를 훈련시킵니다. {npc:6089}와(과) {npc:6090}은(는) 그곳 {object:2152} 옆에 함께 서 있습니다. {npc:6090}은(는) 자기 잔을 걸고 당신과 싸웁니다.",
		["The troggs"] = "트로그",
		["The troll cave"] = "트롤 동굴",
		["The tunnel"] = "굴",
		["The {area:2257}"] = "{area:2257}",
		["The {object:269} in the basement"] = "지하실의 {object:269}",
		["The {object:270} in the distillery"] = "양조장 안의 {object:270}",
		["Use the {item:6866} on {npc:6177}"] = "{npc:6177}에게 {item:6866}을(를) 사용하세요",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "당신은 골짜기 북쪽 끝의 석조 전당인 {area:77} 앞에서 시작합니다. {npc:658}은(는) 문 밖에서 기다립니다.",
		["Young wolves"] = "새끼 늑대",
		["{area:131} and the depot"] = "{area:131}와(과) 정거장",
		["{area:135} is the troll cave in the hills west of {area:137}. Kill Headhunters at its mouth and walk through to its far end."] = "{area:135}은(는) {area:137} 서쪽 언덕의 트롤 동굴입니다. 입구에서 인간사냥꾼을 처치하고 안쪽 끝까지 걸어가세요.",
		["{area:137} sits on the lake north-west of {area:135}."] = "{area:137}은(는) {area:135} 북서쪽 호숫가에 있습니다.",
		["{item:2676} bushes grow on the hills around {area:137}."] = "{item:2676} 덤불은 {area:137} 주변 언덕에 자랍니다.",
		["{item:2686}, from {npc:1247} in the distillery"] = "{item:2686}, 양조장 안 {npc:1247}에게서",
		["{item:277976}, in the camp"] = "{item:277976}, 야영지 안",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325}은(는) 얼어붙은 호수 옆, 얼음 정령들 사이에 있습니다.",
		["{item:2894}, from {npc:1247}"] = "{item:2894}, {npc:1247}에게서",
		["{item:5026} and the {item:6652}"] = "{item:5026}와(과) {item:6652}",
