		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: {item:15908}(으)로 길들이기",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, 마법사 상급자, 대성당 안",
		["{npc:247229}, in the library"] = "{npc:247229}, 도서관 안",
