		["{npc:927}: {npc:6171} in {zone:1453} takes it"] = "{npc:927}: {zone:1453}의 {npc:6171}이(가) 받습니다",
		["{npc:952}, upstairs"] = "{npc:952}, 위층",
		["{npc:955}: he wants your {item:247824}"] = "{npc:955}: {item:247824}을(를) 원합니다",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood."] = "{object:694855}은(는) 포도밭과 스톤필드 농장 주변 밭에서 자라며, 주변의 돌엄니멧돼지가 피를 줍니다.",
		["{quest:76}'s entrance"] = "{quest:76} 입구",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87}은(는) 언덕 위가 아니라 {area:57} 안에 있습니다. 입구로 들어가 왼쪽을 따라 광산 바닥 안쪽까지 가십시오. 위층 계단은 오르지 마십시오. 포도밭 주변의 데피아즈단 좀도둑이 가끔 {item:1972}을(를) 떨어뜨리니 오른쪽 클릭하십시오.",
		["{quest:91733} and {npc:330}"] = "{quest:91733}와(과) {npc:330}",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "{spell:1229451}을(를) 얻을 때까지 {npc:265811}의 모닥불 옆에서 /앉기 하세요",
		["Back at {area:256}"] = "{area:256}(으)로 돌아가기",
		["Back to the moonwell."] = "달샘으로 돌아가세요.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "{area:256} 꼭대기로 돌아가세요. {object:654846}은(는) 그 옆에 있습니다.",
		["Bloodfeather harpies"] = "붉은깃털일족 하피",
		["Boat to {zone:1453}"] = "배를 타고 {zone:1453}(으)로 가십시오",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "다잘라의 퀘스트마다 {item:15908}을(를) 줍니다. 그가 말한 야수에게 사용한 뒤 {area:186}의 그에게 막대를 가져가세요. 나무그물 늑대거미는 마을 주변을 기어 다니고, 긴발톱 흑호와 비명소리 스트리기드 올빼미는 마을 남쪽 숲을 돌아다닙니다.",
		["East to {area:260}"] = "동쪽 {area:260}(으)로",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "{npc:275744}을(를) 지하굴 밖으로 호위하세요. 보고는 {area:186}의 {npc:2081}에게 하세요.",
		["Fandral in {zone:1457} takes it"] = "{zone:1457}의 판드랄 스테그헬름에게 가져가세요",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}. Nightsabers and Webwood Lurkers keep roaming the road east. {object:126158} is in the house on the hill at the east end of the village."] = "악의 열매는 {area:186}와(과) {npc:2150} 주변 나무 아래 곳곳에 있습니다. 흑호와 나무그물 늑대거미는 여전히 동쪽 길을 돌아다닙니다. {object:126158}은(는) 마을 동쪽 끝 언덕 위의 집에 있습니다.",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442} for the boat."] = "한 번 더 {area:702}(으)로 날아가 차원문을 타고 {npc:4217}에게 간 뒤, 배를 타러 {area:442}(으)로 날아가세요.",
		["Follow the road south-west out of {area:188} to {area:186}."] = "{area:188}에서 남서쪽 길을 따라 {area:186}(으)로 가세요.",
		["Follow the road west into {zone:1457}. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092} and {npc:7999} are in the Temple of the Moon at the south end. {npc:7316} is in the west of the city, on the way to the pink portal down to Rut'theran."] = "길을 따라 서쪽 {zone:1457}(으)로 가세요. {npc:4241}은(는) 도시 입구 바로 안쪽 {area:1659}에 있습니다. {npc:3516}은(는) 도시 북쪽 끝 {area:1658}에, {quest:922}은(는) 그 바로 남쪽에 있으며, {npc:4092}와(과) {npc:7999}은(는) 남쪽 끝 달의 신전에 있습니다. {npc:7316}은(는) 도시 서쪽, 루테란 마을로 내려가는 분홍색 차원문 가는 길에 있습니다.",
		["From the harbour walk into {object:2100}. {npc:5480} trains warriors there; {npc:6089} and {npc:6090} stand together by the {object:2152}. {npc:6090} fights you for his mug."] = "항구에서 {object:2100}(으)로 걸어가세요. {npc:5480}이(가) 그곳에서 전사를 가르칩니다. {npc:6089}와(과) {npc:6090}은(는) {object:2152} 옆에 함께 서 있습니다. {npc:6090}은(는) 자기 머그잔을 걸고 당신과 싸웁니다.",
		["From {area:17203}, ride through the city gates into {zone:1429} and follow the road west to {zone:1436}."] = "{area:17203}에서 도시 성문을 지나 {zone:1429}(으)로 간 뒤 서쪽 길을 따라 {zone:1436}(으)로 가세요.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "나무옹이일족 복병이 {area:258} 서쪽 길을 따라 숨어 있습니다.",
		["Gnarlpine Mystics and Ferocitas camp north-east of {area:260}. Ferocitas drops the {item:8049}: open it for the jewel."] = "나무옹이일족 비술사와 꿈을 먹어치우는 페로시타스가 {area:260} 북동쪽에서 야영합니다. 페로시타스가 {item:8049}을(를) 떨어뜨리니 열어서 보석을 꺼내세요.",
		["Gnarlpine Shamans"] = "나무옹이일족 주술사",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "{area:702}(으)로 다시 내려가 {area:442}(으)로 날아가세요. {object:177525}은(는) 마을 바로 동쪽 언덕에 있습니다. 그곳에서 {item:15208}을(를) 사용하고, 초승달발톱을 물리친 뒤 {npc:12144}와(과) 대화하세요.",
		["Hearth to {area:186}"] = "귀환석으로 {area:186}에 가기",
		["Learn the {area:442} flight path on the hill south of the inn, then cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn the {area:493} flight path in {area:2361} and fly to {area:702} (by way of {area:442})."] = "여관 남쪽 언덕에서 {area:442} 비행 경로를 배운 뒤 {spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있고, {quest:5929}은(는) 북서쪽 숲에 있습니다. {area:2361}에서 {area:493} 비행 경로를 배우고 ({area:442}을(를) 거쳐) {area:702}(으)로 날아가세요.",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "{area:256} 남동쪽 길로 {area:188}을(를) 떠나세요. {area:186}(으)로 가는 길로 내려가는 곳에 {npc:6780}이(가) 서 있습니다.",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:8584} waits in the trees west of the cave mouth; {npc:1994} sits deep inside."] = "병든 흑호와 엉겅퀴멧돼지가 동굴로 가는 길인 {area:256} 북쪽에 돌아다닙니다. {npc:8584}은(는) 동굴 입구 서쪽 나무 사이에서 기다리고, {npc:1994}은(는) 동굴 깊숙이 있습니다.",
		["Nightsabers"] = "흑호",
		["Nightsabers, Strigid Owls and Webwood Lurkers live along the road east. The moonwell is at the west edge of {area:260}."] = "흑호, 스트리기드 올빼미, 나무그물 늑대거미가 동쪽 길을 따라 삽니다. 달샘은 {area:260} 서쪽 끝에 있습니다.",
		["North to {area:257}"] = "북쪽 {area:257}(으)로",
		["North-east from Ursal's den, back to {area:186}."] = "우르살의 굴에서 북동쪽으로 {area:186}에 돌아가세요.",
		["Sentinel Arynia again"] = "다시 파수꾼 아리니아 클라우드브레이크",
		["South of Zenn. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "젠 파울후프 남쪽입니다. {npc:2080}은(는) 물가에서 묘목을 돌보고 있습니다. 덩굴손 묘목과 나무괴물이 그 주변을 돌아다니고, 그 사이에 {quest:919}이(가) 자랍니다.",
		["South of the pools. The {object:6751} grows by the Hold."] = "웅덩이 남쪽입니다. {object:6751}은(는) 나무옹이 요새 옆에 자랍니다.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "돌라나르 남동쪽의 {npc:2080}에게 가세요. 덩굴손 묘목이 물가에서 그 주변을 돌아다닙니다.",
		["South-west of the barrow. The moonwell sits by the pools."] = "지하굴 남서쪽입니다. 달샘은 웅덩이 옆에 있습니다.",
		["Speak with the {quest:5929}"] = "{quest:5929}와(과) 대화하세요",
		["Speak with {npc:6286}, south of the inn"] = "여관 남쪽의 {npc:6286}와(과) 대화하세요",
		["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs."] = "차원문을 타고 {area:702}(으)로 내려가세요. {npc:10118}은(는) 부두에, {npc:3838}은(는) 히포그리프 옆에 있습니다.",
		["Take the portal up from {area:702} to {npc:4217} in the {area:1658}."] = "{area:702}에서 차원문을 타고 올라가 {area:1658}의 {npc:4217}에게 가세요.",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "다시 {area:186}에서 북서쪽 길로 가세요. 그녀는 아직 {zone:1457}(으)로 가는 길가에 누워 있습니다.",
		["Take the road north-west from {area:186} towards the {area:264}; she lies hurt beside it."] = "{area:186}에서 북서쪽 길을 따라 {area:264}(으)로 가세요. 그녀가 다친 채 길가에 누워 있습니다.",
		["The Bloodfeather harpies nest on the slopes west and north of the glade."] = "붉은깃털일족 하피는 숲 서쪽과 북쪽 비탈에 둥지를 틀고 있습니다.",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms."] = "지하굴은 길 남쪽에 있습니다. {npc:275744}이(가) 안에 갇혀 있고, {npc:7317}은(는) 가장 깊은 곳에서 잠들어 있으며, 유물 상자 4개는 아래층 방에 있습니다.",
		["The moonwell and {npc:8584}"] = "달샘과 {npc:8584}",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "달샘은 숲 한가운데에 있습니다. {object:6752}은(는) 북쪽 끝에 자랍니다.",
		["The moonwell sits north of {area:256}; {npc:8584} is a little further north-west. {quest:3522} lasts five minutes: fill the phial and go straight on to him."] = "달샘은 {area:256} 북쪽에 있고, {npc:8584}은(는) 조금 더 북서쪽에 있습니다. {quest:3522}은(는) 5분 동안만 유지되니 약병을 채우고 곧장 그에게 가세요.",
		["The named harpies"] = "이름 있는 하피",
		["The road to {zone:1457}"] = "{zone:1457}(으)로 가는 길",
		["The {area:478}"] = "{area:478}",
		["The {object:177525}"] = "{object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406}은(는) {area:257} 안쪽에 있습니다. 가운데 길로 가다가 갈림길에서 왼쪽으로 높은 바위턱까지 오르세요. {item:10639}은(는) 그렐이 떨어뜨리고, 달봉우리 백합은 {area:256} 북쪽 연못가에 자랍니다.",
		["Use the {item:5185} at the moonwell"] = "달샘에서 {item:5185}을(를) 사용하세요",
		["Use the {item:5619} at the moonwell"] = "달샘에서 {item:5619}을(를) 사용하세요",
		["Use the {item:5621} at the moonwell"] = "달샘에서 {item:5621}을(를) 사용하세요",
		["Use the {item:5623} at the moonwell"] = "달샘에서 {item:5623}을(를) 사용하세요",
		["Walk Lynessa out and keep her alive"] = "리네사를 데리고 나오며 살려 두세요",
		["Walk south along the west side of the island. Ursal prowls the far south, below the {area:478}."] = "섬 서쪽을 따라 남쪽으로 가세요. 투사 우르살은 {area:478} 아래, 남쪽 끝을 배회합니다.",
		["Webwood Lurkers"] = "나무그물 늑대거미",
		["Webwood Spiders"] = "나무그물거미",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "{area:188}의 거대한 나무 {area:256} 아래에서 시작합니다.",
		["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "새끼 흑호와 새끼 엉겅퀴멧돼지가 {area:256} 주변을 돌아다닙니다. 나무 서쪽 숲의 그렐이 {item:3297}을(를) 지니고 있으며, 그곳에 나무옹이일족 토템이 서 있습니다.",
		["{area:186} again"] = "다시 {area:186}",
		["{area:186} quests"] = "{area:186} 퀘스트",
		["{area:258}'s mouth"] = "{area:258} 입구",
		["{area:736}, outside the barrow"] = "지하굴 밖의 {area:736}",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{npc:6094}에게 줄 {item:159}, {npc:6736}에게서 구입",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{npc:6094} 옆의 {npc:3614}에게서 {item:3371}",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "달의 신전의 {npc:11401}: 별조각",
		["{npc:1992}, south of the tree"] = "나무 남쪽의 {npc:1992}",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: {item:15908}(으)로 길들이세요",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: {item:15908}(으)로 길들이세요",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038}은(는) 동굴 안 바닥이나 바위턱 위에서 기다립니다. 오른쪽으로 계속 가세요.",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: {item:15908}(으)로 길들이세요",
		["{npc:2077}, by the path"] = "길가의 {npc:2077}",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: {npc:3596}에게 줄 문장",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: {zone:1457}의 {quest:922}에게 가져가세요",
		["{npc:2082}, on the tree's ramp"] = "나무 경사로의 {npc:2082}",
		["{npc:2150} sits by the road just east of {area:186}, on the way to {area:260}."] = "{npc:2150}은(는) {area:260}(으)로 가는 길, {area:186} 바로 동쪽 길가에 앉아 있습니다.",
		["{npc:2150}, on the way back"] = "돌아오는 길의 {npc:2150}",
		["{npc:2151}, on the road west of the village"] = "마을 서쪽 길의 {npc:2151}",
		["{npc:265811}, by the campfire"] = "모닥불 옆의 {npc:265811}",
		["{npc:272034} and {npc:272044} fly just west of the moonwell, {npc:272046} further north."] = "{npc:272034}와(과) {npc:272044}은(는) 달샘 바로 서쪽에, {npc:272046}은(는) 더 북쪽에 날아다닙니다.",
		["{npc:3514}, at the top of the tree"] = "나무 꼭대기의 {npc:3514}",
		["{npc:3515}, south of the inn"] = "여관 남쪽의 {npc:3515}",
		["{npc:3516}, in the {area:1658}"] = "{area:1658}의 {npc:3516}",
		["{npc:3519}, by the moonwell"] = "달샘 옆의 {npc:3519}",
		["{npc:3567}, back in {area:186}"] = "{area:186}(으)로 돌아가 {npc:3567}",
		["{npc:3593}, the warrior trainer"] = "전사 상급자 {npc:3593}",
		["{npc:3594}, the rogue trainer"] = "도적 상급자 {npc:3594}",
		["{npc:3595}, inside the tree"] = "나무 안의 {npc:3595}",
		["{npc:3595}, the priest trainer, inside the tree"] = "나무 안의 사제 상급자 {npc:3595}",
		["{npc:3596}, the hunter trainer"] = "사냥꾼 상급자 {npc:3596}",
		["{npc:3597}, the druid trainer at {area:256}"] = "{area:256}의 드루이드 상급자 {npc:3597}",
		["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600}: {zone:1457}의 {npc:11401}에게 가져가세요",
		["{npc:3602}: {npc:4217} in {zone:1457} takes it"] = "{npc:3602}: {zone:1457}의 {npc:4217}에게 가져가세요",
		["{npc:4092}, in the Temple of the Moon"] = "달의 신전의 {npc:4092}",
		["{npc:4146} in {zone:1457} takes it"] = "{zone:1457}의 {npc:4146}에게 가져가세요",
		["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{area:1658}의 {npc:4146}: {spell:5149}",
		["{npc:4200}'s fish stall is by the docks. Then take the boat to {zone:1453}."] = "{npc:4200}의 생선 가판대는 부두 옆에 있습니다. 그다음 배를 타고 {zone:1453}(으)로 가세요.",
		["{npc:4217}, in the {area:1658}"] = "{area:1658}의 {npc:4217}",
		["{npc:7318}, in the den"] = "굴 안의 {npc:7318}",
		["{npc:7999}, above {npc:4092}"] = "{npc:4092} 위층의 {npc:7999}",
		["{npc:8583}, east of the tree"] = "나무 동쪽의 {npc:8583}",
		["{object:673378}, just west of the moonwell"] = "달샘 바로 서쪽의 {object:673378}",
		["{object:7510}, beside him"] = "그 옆의 {object:7510}",
		["{quest:488} and the Starbreeze moonwell"] = "{quest:488}와(과) 별바람 마을 달샘",
		["{quest:917} and the antidote"] = "{quest:917}와(과) 해독제",
		["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}: {spell:1259799}와(과) 그림자 숨기를 시전한 뒤 {npc:3595}에게 완료하세요",
} end)()
t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "{spell:1229451} 효과를 얻을 때까지 {npc:263664}의 모닥불 옆에 앉으세요(/앉기)",
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "알아케스 폭풍추격자와 알아케스 보병이 {npc:257944} 바로 북쪽에 야영하며 가보를 떨어뜨립니다. 그녀 서쪽의 괴성조는 깃털과 갈퀴발톱을 떨어뜨리고, {item:265105}은(는) 그녀 서쪽 개울을 따라 자랍니다.",
		["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "다시 {quest:92529}: 폭풍소환사와 {npc:251662}이(가) 마을을 메우고 있고, 폭풍소환사가 도난당한 보급품을 가지고 있으며, {npc:251966}은(는) 마을 남쪽 끝에 서 있습니다.",
		["Back to Shen'dar"] = "셴다르로 돌아가기",
		["Back to the Hermit"] = "수상한 은둔자에게 돌아가기",
		["Back to {area:16622}"] = "{area:16622}(으)로 돌아가기",
		["Back to {npc:255853} by the falls north-east of {area:16638}, on the way north to the shrine."] = "북쪽 사당으로 가는 길에, {area:16638} 북동쪽 폭포 옆의 {npc:255853}에게 돌아가세요.",
		["Bandit Highwaymen"] = "산적 노상강도",
		["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "볼바르 폴드라곤은 도시 북쪽 끝 {object:2117}의 왕좌실에 서 있습니다. 그런 다음 정문으로 나가 {zone:1436}(으)로 가세요.",
		["Cast {spell:1259705} at the {object:460002}"] = "지맥에 {spell:1259705} 시전",
		["Desperate times"] = "절박한 시기",
		["Each of Quel'ana's quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her in {area:16638}. Windsong Crawlers line the shore west of town; Vuldren Alphas and Ornery Galestriders roam the {area:16626} around the Windfield farm. Her sister {npc:254411} stands beside her."] = "퀠라나의 퀘스트는 각각 {item:15908}을(를) 줍니다. 그녀가 말한 야수에게 사용한 뒤, 막대를 {area:16638}에 있는 그녀에게 다시 가져가세요. 바람노래 집게발은 마을 서쪽 해안에 늘어서 있고, 벌드렌 우두머리와 심술궂은 돌풍타조는 윈드필드 농장 주변 {area:16626}을(를) 돌아다닙니다. 그녀의 자매 {npc:254411}이(가) 곁에 서 있습니다.",
		["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "싸우며 북쪽 {area:16629}(으)로 가세요. 알아케스 수호자, 알아케스 영혼소환사, 알아케스 검귀가 진입로를 지키고 있습니다. {npc:253576}은(는) 사당 문 앞에서, {npc:253590}은(는) 안쪽 성소에서 기다립니다.",
		["Find Fillion and his bedroll"] = "필리온과 그의 침낭을 찾으세요",
		["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "길을 따라 남쪽 {area:16624}(으)로 가세요. {npc:263664}은(는) 마을 서쪽 모닥불 옆에 야영하고, {npc:251523}와(과) {npc:251903}은(는) 마을 한가운데에 서 있습니다.",
		["For {npc:234} at {area:108}"] = "{area:108}의 {npc:234}용",
		["Havoc in Falaath"] = "팔라스의 혼란",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "북쪽 {area:16631}(으)로 가세요. {npc:257944}은(는) 그 동쪽에 야영합니다.",
		["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them."] = "북서쪽 서부 절벽의 히포그리프 둥지로 가세요. {item:263493}은(는) 둥지 주변에 있고, 히포그리프 어미가 둥지 사이를 순찰합니다.",
		["Heal 7 druids in the Nightfang Den, then find {npc:258130}"] = "Nightfang Den에서 드루이드 7명을 치유한 뒤 {npc:258130}을(를) 찾으세요",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "정문으로 {zone:1453}을(를) 나가세요. {quest:1861} 폭포는 성문 남서쪽, 서쪽 {zone:1436}(으)로 가는 길에 있습니다. 폭포 아래에서 {item:7207}을(를) 채우세요.",
		["Level 4 spells"] = "4레벨 주문",
		["Level 6 spells"] = "6레벨 주문",
		["Listen to {npc:257554}"] = "{npc:257554}의 말을 들으세요",
		["Lorthuna waits on the eastern shore of the isle, east of the {area:16629}."] = "로르투나는 {area:16629} 동쪽, 섬의 동쪽 해안에서 기다립니다.",
		["Meet Valennia at the gate"] = "성문에서 발레니아를 만나세요",
		["North of the cones: the Wind Hollows drift around the refugees' camp, the {item:266433} lie between the tents, and {npc:259013} lies at its north end."] = "솔방울 북쪽: 바람의 유령이 피난민 야영지 주변을 떠돌고, {item:266433}은(는) 천막 사이에 있으며, {npc:259013}은(는) 야영지 북쪽 끝에 쓰러져 있습니다.",
		["North-west of Valanaar along the road: {npc:273017} watches the {quest:98512}; the dead cultist lies just north of him."] = "발라나르 북서쪽 길가: {npc:273017}이(가) {quest:98512}을(를) 감시하고 있고, 죽은 광신도는 그 바로 북쪽에 쓰러져 있습니다.",
		["Prideclaws and Galestriders"] = "무리발톱과 돌풍타조",
		["Prideclaws and Galestriders roam the grasslands south of the village. Galestriders drop both the eggs and the meat."] = "무리발톱과 돌풍타조가 마을 남쪽 초원을 돌아다닙니다. 돌풍타조는 알과 고기를 모두 떨어뜨립니다.",
		["Rally Valennia, {npc:251968} (west of town) and {npc:252475}"] = "발레니아, {npc:251968}(마을 서쪽), {npc:252475}을(를) 모으세요",
		["Raw Windstones and the {npc:251404}"] = "바람석 원석과 {npc:251404}",
		["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "잘 익은 폭풍사과와 굶주린 좀도둑은 농장 옆 과수원에, {quest:92683}은(는) 농장 북동쪽 들판에 있고, 심술궂은 돌풍타조는 사방에 있습니다. {npc:250929}은(는) 농장 북동쪽 들판에 서 있습니다.",
		["Search the dead cultist"] = "죽은 광신도를 조사하세요",
		["Search the wardrobe"] = "옷장을 뒤지세요",
		["Shen'dar turn-ins"] = "셴다르 퀘스트 제출",
		["Skycutter to {area:279}"] = "비행정으로 {area:279}에 가기",
		["Skyhoppers"] = "하늘폴짝이",
		["Skyhoppers swarm the fields west of {area:16638}."] = "하늘폴짝이가 {area:16638} 서쪽 들판에 떼지어 있습니다.",
		["Speak with {npc:251903} and {npc:254089}, north-west of the village"] = "마을 북서쪽의 {npc:251903}, {npc:254089}와(과) 대화하세요",
		["Stand with {npc:252800} against {npc:252863}"] = "{npc:252800}와(과) 함께 {npc:252863}에 맞서 싸우세요",
		["Standing our ground"] = "자리를 지키며",
		["Take the road south-east. {npc:257006} and {npc:252448} stand by the road west of {area:16638}; Windsong Crawlers line the shore further west, around 51,70."] = "남동쪽 길을 따라가세요. {npc:257006}와(과) {npc:252448}은(는) {area:16638} 서쪽 길가에 서 있고, 바람노래 집게발은 더 서쪽 해안, 51,70 근처에 늘어서 있습니다.",
		["Tame it with the {item:15908}"] = "{item:15908}(으)로 길들이세요",
		["The Bandit Highwaymen hold the hills north of the farm."] = "산적 노상강도는 농장 북쪽 언덕을 점거하고 있습니다.",
		["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp."] = "고원 좀도둑은 마을 북동쪽에 야영합니다. \"사악한 바람\" 베닉은 야영지 북쪽 끝에서 기다립니다.",
		["The Highlands bandits"] = "고원 좀도둑",
		["The Novice Seers practise in the clearing west of Shen'dar."] = "수습 선견자들은 셴다르 서쪽 빈터에서 수련합니다.",
		["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "바람석 원석은 숲 바로 남쪽 땅에서 반짝입니다. {quest:92463}은(는) 더 동쪽, {npc:249363}에게 가는 길의 초원 위를 맴돕니다.",
		["The Windfield farm"] = "윈드필드 농장",
		["The Windstone Formations"] = "Windstone Formation",
		["The Windstone Formations stand on the rise west of Fillion's camp."] = "Windstone Formation은 필리온의 야영지 서쪽 언덕 위에 있습니다.",
		["The bounty board"] = "현상금 게시판",
		["The class trainers stand together in the grove"] = "직업 상급자들은 숲에 함께 모여 있습니다",
		["The dead cultist"] = "죽은 광신도",
		["The eastern watchtower"] = "동쪽 감시탑",
		["The hippogryph roost"] = "히포그리프 둥지",
		["The missing scholar"] = "사라진 학자",
		["The refugees' camp"] = "피난민 야영지",
		["The road to {area:16638}"] = "{area:16638}(으)로 가는 길",
		["The skycutter"] = "비행정",
		["The skycutter docks at the tower south of {area:16638}. It lands by the Kirin Tor camp on the lake shore west of {area:279}."] = "비행정은 {area:16638} 남쪽 탑에 정박합니다. {area:279} 서쪽 호숫가의 키린 토 야영지 옆에 내립니다.",
		["The {area:16629}"] = "{area:16629}",
		["The {item:254871}"] = "{item:254871}",
		["The {object:581822}"] = "{object:581822}",
		["The {object:581822} lies by the path west of {area:16638}; Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "{object:581822}은(는) {area:16638} 서쪽 길가에 있습니다. 필리온의 야영지는 그 북서쪽에 있고, 괴성조 어미는 야영지 바로 서쪽에 둥지를 틀고 있습니다.",
		["Use {spell:1259416}"] = "{spell:1259416} 사용",
		["Village quests"] = "마을 퀘스트",
		["Vuldren and Cirrusflies"] = "벌드렌과 구름벌레",
		["Windshaper Novice Seers"] = "바람구체자 수습 선견자",
		["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "{area:16622}에서 깨어납니다. {npc:251362}이(가) 곁에 서 있고, {npc:251361}은(는) 몇 걸음 서쪽에, {npc:251368}은(는) 숲 남쪽 가장자리에 있습니다.",
		["{area:16622} turn-ins"] = "{area:16622} 퀘스트 제출",
		["{area:16624} again"] = "다시 {area:16624}",
		["{area:16638} turn-ins"] = "{area:16638} 퀘스트 제출",
		["{area:16638}, the fate of Zephras"] = "{area:16638}, 제프라스의 운명",
		["{area:16638}, the turncoat"] = "{area:16638}, 배신자",
		["{item:262668}: by the wind shrine south of {quest:92529}"] = "{item:262668}: {quest:92529} 남쪽 바람 사당 옆",
		["{item:263993}: {npc:257196}, west of the shrine's approach"] = "{item:263993}: 사당 진입로 서쪽의 {npc:257196}",
		["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363}은(는) 숲 동쪽에서 망을 봅니다. {npc:251143}와(과) {npc:251160}이(가) 그녀 바로 북쪽에 모여 있고, 지맥은 더 북쪽에서 솟아오릅니다. 그곳에 종족 능력 {spell:1259705}을(를) 시전하세요.",
		["{npc:250873} and Pesky Cirrusflies roam the meadow just south-east of the grove."] = "{npc:250873}와(과) 성가신 구름벌레가 숲 바로 남동쪽 초원을 돌아다닙니다.",
		["{npc:250926} and {npc:251115}"] = "{npc:250926}와(과) {npc:251115}",
		["{npc:250926} prowl the woods just west of the grove; the Ursera Scavengers den further west, with {npc:251115}, the matriarch, at the back of the den."] = "{npc:250926}은(는) 숲 바로 서쪽 숲속을 배회합니다. 우르세라 청소부는 더 서쪽에 굴을 틀고 있으며, 우두머리인 {npc:251115}은(는) 굴 안쪽에 있습니다.",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: 상급자가 보낸 쪽지",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: {item:9547}을(를) 읽으세요",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "드루이드 상급자 {npc:251373}: {npc:251361} 뒤편 나무의 1층",
		["{npc:251379}, the mage trainer: read the {item:282416} first"] = "마법사 상급자 {npc:251379}: 먼저 {item:282416}을(를) 읽으세요",
		["{npc:251389}, in the watchtower"] = "감시탑 안의 {npc:251389}",
		["{npc:251964}, in the watchtower"] = "감시탑 안의 {npc:251964}",
		["{npc:252095} camps south of the Ursera den. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle."] = "{npc:252095}은(는) 우르세라 굴 남쪽에 야영합니다. 알아케스 폭력배가 그녀 남서쪽 야영지를 점거하고 있으며, {npc:256935}은(는) 그 한가운데에 서 있습니다.",
		["{npc:252155} holds the western watch, south-west of Falaath. {npc:256966} and the fallen guards lie just south of her."] = "{npc:252155}은(는) 팔라스 남서쪽의 서부 감시터를 지킵니다. {npc:256966}와(과) 쓰러진 경비병들은 그녀 바로 남쪽에 누워 있습니다.",
		["{npc:252373}, the mage trainer"] = "마법사 상급자 {npc:252373}",
		["{npc:252377}: {npc:257196} waits at the {area:16629}"] = "{npc:252377}: {npc:257196}이(가) {area:16629}에서 기다립니다",
		["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378}은(는) {area:16638} 북쪽 감시탑을 지킵니다. 알아케스 야영지는 탑 바로 서쪽에 있으며, 치유사들은 65,68과 65,65 근처에 있고 {npc:252666}은(는) 야영지 북쪽 끝에 서 있습니다. 그곳의 알아케스는 알아케스 바람석 부적을 떨어뜨립니다.",
		["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383}와(과) {npc:252476}은(는) {area:16638} 북쪽 끝에, {npc:252475}와(과) {npc:253204}은(는) 남쪽 끝에 서 있습니다.",
		["{npc:252475}: {npc:259084} waits by the Skyborne portal"] = "{npc:252475}: {npc:259084}이(가) 스카이본 차원문 옆에서 기다립니다",
		["{npc:252800} again"] = "다시 {npc:252800}",
		["{npc:252800} runs the farm in the south-west lowlands."] = "{npc:252800}은(는) 남서쪽 저지대의 농장을 운영합니다.",
		["{npc:253590}, in the sanctum"] = "성소 안의 {npc:253590}",
		["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}."] = "{npc:254151}, {npc:258130}, {npc:258134}은(는) {npc:257944} 북동쪽에 있고, {npc:253622}은(는) 그들 동쪽에 서 있습니다. 할리엔은 {quest:94490}도 떨어뜨립니다.",
		["{npc:254588}: tame it with the {item:15908}"] = "{npc:254588}: {item:15908}(으)로 길들이세요",
		["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "{npc:254589}는 돌아가는 길에, 마을 남서쪽 언덕에 숨어 있습니다. {npc:254589}은(는) 정예이므로 파티를 권장합니다.",
		["{npc:255853} waits by the falls north-east of {area:16638}. {npc:258443} prowls the {area:16623} west of {area:16638}, by the road you take next."] = "{npc:255853}은(는) {area:16638} 북동쪽 폭포 옆에서 기다립니다. {npc:258443}은(는) {area:16638} 서쪽 {area:16623}, 다음에 갈 길가를 배회합니다.",
		["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065}은(는) 셴다르 남쪽 {quest:92529} 입구에서 기다립니다. {spell:1254832}이(가) 있으면 신도들 사이로 걸어 들어갈 수 있습니다.",
		["{npc:257944} again"] = "다시 {npc:257944}",
		["{npc:257944}, the missive"] = "{npc:257944}: 전갈",
		["{npc:258443}, in the highlands south-west of the cultist"] = "광신도 남서쪽 고원의 {npc:258443}",
		["{npc:259084} stands beside the Skyborne Portal where the zeppelin lands. The portal takes you to {zone:1453}."] = "{npc:259084}은(는) 비행선이 내리는 곳의 스카이본 차원문 옆에 서 있습니다. 차원문은 {zone:1453}(으)로 연결됩니다.",
		["{npc:270459}, beside {npc:259084}: for {npc:5504} in {zone:1453}"] = "{npc:259084} 옆의 {npc:270459}: {zone:1453}의 {npc:5504}용",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497}은(는) {object:2101}의 탑인 마법사의 성소에 있습니다. 그녀는 {quest:1861} 폭포에 쓸 병을 줍니다.",
		["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{zone:1453}의 드루이드 상급자 {npc:5504}이(가) {spell:18960}을(를) 가르쳐 줍니다. {npc:11802}의 환영 인사는 {zone:1439} 끝의 {spell:499} 여정에서 기다립니다.",
		["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "{quest:93159}은(는) {npc:257944} 서쪽에 삽니다. {object:613238}은(는) 그의 오두막과 {npc:257944} 사이 숲에 있습니다.",
} end)()
t.guides["forever/class/druid/aquatic-form"] = (function() return {
		["At the {area:2362}"] = "{area:2362}에서",
		["Cast {spell:18960}. Join the two halves into the {item:15885} near the {area:2362}, on the north-west shore of the lake, then see {npc:11802} in {area:2361}. Fly to {area:702} afterwards."] = "{spell:18960}을(를) 시전하세요. 호수 북서쪽 기슭의 {area:2362} 근처에서 반쪽 두 개를 합쳐 {item:15885}을(를) 만든 뒤, {area:2361}의 {npc:11802}을(를) 만나세요. 그 후 {area:702}(으)로 날아가세요.",
		["Cast {spell:18960}. Join the two halves into the {item:15885} near the {area:2362}, on the north-west shore of the lake, then see {npc:11802} in {area:2361}. {npc:11798} flies druids to {area:1638}."] = "{spell:18960}을(를) 시전하세요. 호수 북서쪽 기슭의 {area:2362} 근처에서 반쪽 두 개를 합쳐 {item:15885}을(를) 만든 뒤, {area:2361}의 {npc:11802}을(를) 만나세요. {npc:11798}이(가) 드루이드를 {area:1638}(으)로 태워 줍니다.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있습니다. {item:15877}은(는) {area:2361} 아래 {area:656} 바닥의 용기 속에 있습니다. 하나를 북서쪽 기슭의 {area:2362}(으)로 가져가 그곳에서 사용하고 {npc:11799}와(과) 대화하세요.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있습니다. {item:15877}은(는) {area:656} 바닥에 있으며 몇 분 안에 사라집니다. 하나를 들고 북서쪽 기슭의 {area:2362}까지 곧장 헤엄쳐 가서 사용하고 {npc:11799}와(과) 대화하세요.",
		["Fly from {area:2361} to {area:442}. The {object:177792} lies under the water off the north coast, west of the {area:443}."] = "{area:2361}에서 {area:442}(으)로 날아가세요. {object:177792}은(는) {area:443} 서쪽, 북쪽 해안 앞 물속에 있습니다.",
		["Take the boat from {area:442} to {zone:1453} and fly to {area:108}. Ride north-west to the coast: the {object:177790} lies on the sea floor off the shore."] = "{area:442}에서 배를 타고 {zone:1453}(으)로 간 뒤 {area:108}(으)로 날아가세요. 북서쪽 해안으로 가면 {object:177790}이(가) 해안 앞바다 바닥에 있습니다.",
		["Take the portal up to {npc:4217} in the {area:1658}."] = "차원문을 타고 {area:1658}의 {npc:4217}에게 올라가세요.",
		["Take {npc:11798}'s flight to {zone:1456}, fly to {zone:1454} and take the zeppelin to {zone:1420}; {zone:1421} is south of the {zone:1458}. The {object:177790} lies on the coast west of the {area:240}, north of the {area:228}."] = "{npc:11798}의 비행편으로 {zone:1456}에 간 뒤, {zone:1454}(으)로 날아가 비행선을 타고 {zone:1420}(으)로 가세요. {zone:1421}은(는) {zone:1458} 남쪽에 있습니다. {object:177790}은(는) {area:228} 북쪽, {area:240} 서쪽 해안에 있습니다.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower, north of the {area:380}."] = "{object:177792}은(는) {area:380} 북쪽, {area:382} 북쪽 가장자리의 투자개발회사 탑 옆에 있습니다.",
		["Your water travel form: swim fast and breathe underwater, with a belt and an idol besides."] = "물속 이동 변신입니다. 빠르게 헤엄치고 물속에서 숨을 쉴 수 있으며, 허리띠와 우상도 얻습니다.",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, 호수의 {object:177785}에서",
		["{item:15885}: join the halves at the shrine"] = "{item:15885}: 제단에서 반쪽을 합치세요",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033}은(는) {area:1639}에 서 있습니다.",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217}은(는) {area:1658}에 서 있습니다.",
} end)()
t.guides["forever/class/druid/bear-form"] = (function() return {
		["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "10레벨에 드루이드의 부름이 옵니다: {area:222}의 {npc:3064} 또는 {zone:1456}의 {npc:6746}({zone:1454}의 {npc:6929}이(가) 보낸 편지도 됩니다). 누구든 {zone:1456} {area:1639}의 {npc:3033}에게 보냅니다.",
		["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "10레벨이 되면 드루이드의 부름이 옵니다: {area:186}의 {npc:3602}, {zone:1457}의 데나타리온, {zone:1453}의 테리드란. 누구든 다르나서스 세나리온 자치령의 {npc:4217}에게 보냅니다.",
