		["{npc:259118} waits where the airship from {zone:2521} lands, in northern {zone:1412} beside {zone:1456}."] = "{npc:259118}은(는) {zone:2521}에서 오는 비행선이 내리는 곳, {zone:1456} 옆 {zone:1412} 북부에서 기다립니다.",
		["{npc:270459} stands beside {npc:259084} and the Skyborne Portal, west of {area:279}, where the skycutter from {zone:2521} lands. {npc:2543} offers the same quest."] = "{npc:270459}은(는) {area:279} 서쪽, {zone:2521}에서 오는 비행정이 내리는 곳에 {npc:259084}, 스카이본 차원문과 함께 있습니다. {npc:2543}도 같은 퀘스트를 줍니다.",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033}은(는) {area:1639}에 있습니다.",
		["{npc:3033} trains druids on {area:1639}."] = "{npc:3033}은(는) {area:1639}에서 드루이드를 훈련합니다.",
		["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}, {area:222}. 팔라와 그리쉬카의 편지도 같은 곳으로 안내합니다",
		["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}, {area:186}. 데나타리온과 테리드란의 편지도 같은 곳으로 안내합니다",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217}은(는) {area:1658}에 있습니다.",
		["{spell:5487} and {area:493}"] = "{spell:5487}와(과) {area:493}",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of {area:17045}, north of {zone:1456}."] = "{spell:5487}은(는) {zone:2521}에서 배웁니다. 아직 섬에 있다면 건너뛰세요. 아니면 {zone:1456} 북쪽, {area:17045} 남쪽 절벽에서 하늘배를 타세요.",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the north side of {area:279}."] = "{spell:5487}은(는) {zone:2521}에서 배웁니다. 아직 섬에 있다면 건너뛰세요. 아니면 {area:279} 북쪽에서 하늘배를 타세요.",
} end)()
t.guides["forever/class/druid/bloodpetal-poison"] = (function() return {
		["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "{zone:1449} 남동쪽 구석의 {npc:9619}에게 돌아가세요.",
		["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer offers the same quest."] = "{spell:18960}을(를) 시전하세요. {npc:12042}은(는) {area:2361}에 서 있습니다. 직업 상급자도 같은 퀘스트를 줍니다.",
		["Experience in Un'Goro at 50 and two healing potions; Forever removed the Classic item choice."] = "50레벨에 운고로 경험치와 치유 물약 두 개. Forever에서는 클래식의 아이템 선택이 사라졌습니다.",
		["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "{area:976}(으)로 날아가 서쪽으로 {zone:1449}(으)로 내려가는 긴 비탈까지 가세요. {npc:9619}은(는) 그 아래, 분화구 남동쪽 구석에 진을 치고 있습니다.",
		["Gorishi Stings and {item:22434}"] = "고리쉬 독침과 {item:22434}",
		["The Gorishi wasps, workers and reavers of the hive in the south of the crater drop the stings; the Bloodpetal Sprouts that give the {item:22434} grow all over the crater's western half."] = "분화구 남쪽 벌집의 병정 고리쉬, 일꾼 고리쉬, 갈퀴발톱 고리쉬가 독침을 떨어뜨립니다. {item:22434}을(를) 주는 붉은꽃잎 씨앗은 분화구 서쪽 절반 곳곳에 자랍니다.",
		["The {area:1417}"] = "{area:1417}",
		["Use the {item:22432} on a {npc:6498}. Devilsaurs are elite (level 54-55) and roam the crater: grouping up is advised."] = "{npc:6498}에게 {item:22432}을(를) 사용하세요. 데빌사우루스는 정예(54-55레벨)이며 분화구를 돌아다닙니다. 파티를 권장합니다.",
		["{area:1477} lies in the {area:74} in the {zone:1435}. {npc:8580} guards the bottom of the temple: a dungeon boss, so bring a group."] = "{area:1477}은(는) {zone:1435}의 {area:74}에 있습니다. {npc:8580}이(가) 사원 아래층을 지킵니다. 던전 우두머리이니 파티를 데려가세요.",
		["{npc:6498}: stab it with the {item:22432}"] = "{npc:6498}: {item:22432}(으)로 찌르세요",
} end)()
t.guides["forever/class/druid/cat-form"] = (function() return {
		["Back to {npc:11802}"] = "{npc:11802}에게 돌아가기",
		["Back to {npc:11802} in {area:2361}, then fly to {area:702}."] = "{area:2361}의 {npc:11802}에게 돌아간 뒤 {area:702}(으)로 비행하십시오.",
		["Back to {npc:11802} in {area:2361}, then take {npc:11798}'s flight to {area:1638}."] = "{area:2361}의 {npc:11802}에게 돌아간 뒤 {npc:11798}의 비행편으로 {area:1638}에 가십시오.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있습니다.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; learn the flight path there if you do not have it."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있습니다. 비행 경로가 없다면 그곳에서 배우세요.",
		["Take the portal up to {npc:4217} in the {area:1658}."] = "차원문을 타고 {area:1658}의 {npc:4217}에게 올라가십시오.",
		["The relics of the Barrow Dens"] = "지하굴의 성물",
		["The {area:2363}"] = "{area:2363}",
		["Your stealth and melee form: in Forever this chain gives {spell:768} at 20, not the trainer."] = "은신과 근접 전투 변신: Forever에서는 {spell:768}을(를) 상급자가 아니라 이 연계 퀘스트로 20레벨에 얻습니다.",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033}은(는) {area:1639}에 있습니다.",
		["{npc:4217} stands in the {area:1658}. Skyborne without the Rut'theran flight path: take the boat from {area:442}."] = "{npc:4217}은(는) {area:1658}에 있습니다. 루테란 비행 경로가 없는 스카이본이라면 {area:442}에서 배를 타십시오.",
		["{quest:98342} (Tauren) waits on the southern hill above the bridge, the {npc:272054} (Skyborne) south of the twin bridges. The relics lie in the {area:2363} east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. A relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98342}(타우렌)은(는) 다리 위 남쪽 언덕에서, {npc:272054}(스카이본)은(는) 쌍둥이 다리 남쪽에서 기다립니다. 성물은 호수 동쪽 {area:2363}에 있습니다. 변신을 풀고, 입구의 석상을 클릭해 5분 동안 은신한 뒤, 안의 정령을 피해 성물을 하나씩 챙기십시오. {item:280680}은(는) 흰 고양이 석상 발치에 있습니다. 다른 플레이어가 전리품을 획득하는 동안에는 성물에서 아무것도 얻을 수 없으니 잠시 기다렸다가 다시 시도하십시오.",
		["{quest:98394} (Night Elves) waits on the southern hill above the bridge, the {npc:272054} (Skyborne) south of the twin bridges. The relics lie in the {area:2363} east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. A relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394}(나이트 엘프)은(는) 다리 위 남쪽 언덕에서, {npc:272054}(스카이본)은(는) 쌍둥이 다리 남쪽에서 기다립니다. 성물은 호수 동쪽 {area:2363}에 있습니다. 변신을 풀고, 입구의 석상을 클릭해 5분 동안 은신한 뒤, 안의 정령을 피해 성물을 하나씩 챙기십시오. {item:280680}은(는) 흰 고양이 석상 발치에 있습니다. 다른 플레이어가 전리품을 획득하는 동안에는 성물에서 아무것도 얻을 수 없으니 잠시 기다렸다가 다시 시도하십시오.",
} end)()
t.guides["forever/class/druid/cure-poison"] = (function() return {
		["Back in {area:442}."] = "{area:442}(으)로 돌아가십시오.",
		["Cast {spell:18960} and see {npc:11802}, then fly to {area:702} and take the portal up to {zone:1457}."] = "{spell:18960}을(를) 시전해 {npc:11802}을(를) 만난 뒤, {area:702}(으)로 날아가 차원문을 타고 {zone:1457}(으)로 올라가세요.",
		["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}."] = "{spell:18960}을(를) 시전해 {npc:11802}을(를) 만난 뒤, {npc:11798}의 비행편으로 {area:1638}에 가세요.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Then fly to {area:442}."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있습니다. 그런 다음 {area:442}(으)로 날아가세요.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. {npc:11798} flies druids to {area:1638}; fly on to the {area:380} from there."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있습니다. {npc:11798}이(가) 드루이드를 {area:1638}(으)로 태워 줍니다. 그곳에서 {area:380}(으)로 날아가세요.",
		["From the {area:380} ride north to {area:384} and fill the {item:15842} at the {object:19464}."] = "{area:380}에서 북쪽으로 {area:384}까지 달려가 {object:19464}에서 {item:15842}을(를) 채우십시오.",
		["Lost Barrens Kodos roam the plains north and west of the {area:380} and around the {area:388}; each drops a horn. Herbalists find {item:2449} all over the northern {zone:1413}."] = "{npc:3234}은(는) {area:380}의 북쪽과 서쪽 평원, 그리고 {area:388} 주변을 돌아다니며, 각각 뿔을 하나씩 떨어뜨립니다. 약초채집가는 {zone:1413} 북부 곳곳에서 {item:2449}을(를) 찾을 수 있습니다.",
		["Ride north-east from {area:442} to {area:445} and fill the {item:15844} at the mouth of the cave by the falls."] = "{area:442}에서 북동쪽으로 {area:445}까지 달려가, 폭포 옆 동굴 입구에서 {item:15844}을(를) 채우십시오.",
		["Sickly Gazelles"] = "병든 가젤",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else buys it from {npc:1313} (Alchemy Supplies) in {zone:1453} or on the Auction House."] = "{object:177750}은(는) {area:442} 바로 동쪽 언덕의 달빛야수 동굴에 자랍니다. 그곳 달빛야수는 공격적입니다. {item:2449}에는 {skill:182}이(가) 필요합니다. 약초채집가는 {zone:1439} 곳곳에서 채집하고, 그 외에는 {zone:1453}의 {npc:1313}(연금술 용품)이나 경매장에서 사세요.",
		["Use the {item:15826} on Sickly Gazelles: they graze north of the road that runs east and west through the {area:380}."] = "병든 가젤에게 {item:15826}을(를) 사용하십시오: {area:380}을(를) 동서로 가로지르는 길 북쪽에서 풀을 뜯고 있습니다.",
		["Use the {item:15826} on {npc:12298}. They roam {zone:1439} from the {area:456} in the north to the {zone:1440} border in the south."] = "{npc:12298}에게 {item:15826}을(를) 사용하십시오. 북쪽 {area:456}에서 남쪽 {zone:1440} 경계까지 {zone:1439}을(를) 돌아다닙니다.",
		["{item:15851} and {item:2449}"] = "{item:15851}와(과) {item:2449}",
		["{item:2449} and Kodo Horns"] = "{item:2449}와(과) 코도 뿔",
		["{item:2449}; herbalists pick it on the plains"] = "{item:2449}. 약초채집가는 평원에서 캘 수 있습니다",
		["{npc:12296}: use the salve on them"] = "{npc:12296}: 연고를 사용하십시오",
		["{npc:12298}: use the salve on them"] = "{npc:12298}: 연고를 사용하십시오",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033}은(는) {area:1639}에 있습니다.",
		["{npc:3448} stands in the {area:380}. No {skill:182}? {npc:3490}, a few steps away, sells {item:2449}, three at a time until he restocks."] = "{npc:3448}은(는) {area:380}에 있습니다. {skill:182}이(가) 없다면 몇 걸음 떨어진 {npc:3490}이(가) {item:2449}을(를) 팝니다. 재입고될 때까지 한 번에 세 개씩입니다.",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217}은(는) {area:1658}에 있습니다.",
		["{spell:8946} is no longer trained in Forever: this chain teaches it, with a medicine bag on the way."] = "Forever에서는 더 이상 {spell:8946}을(를) 수련할 수 없습니다: 이 연계 퀘스트가 가르쳐 주며, 도중에 약초 가방도 얻습니다.",
} end)()
t.guides["forever/class/hunter/rhokdelar"] = (function() return {
		["Back to the Ancients"] = "고대정령에게 돌아가기",
		["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, roams the south of {zone:1447} and drops it most of the time; the Cobalt dragonkin of {zone:1452} drop it very rarely. Skip the rest of this guide if you do not want the quiver."] = "하스타트의 화살통에는 {item:18704}이(가) 필요합니다. 공격대용 필드 우두머리인 {npc:6109}은(는) {zone:1447} 남부를 돌아다니며 대부분 이것을 떨어뜨립니다. {zone:1452}의 푸른비늘 용족은 매우 드물게 떨어뜨립니다. 화살통을 원하지 않으면 이 가이드의 나머지는 건너뛰세요.",
		["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and Vartrus then gave {item:18715} ({spell:425121})."] = "Forever에서는 확인되지 않았습니다. 클래식에서는 {item:18724}을(를) 가방에 넣고 {item:18707}을(를) 사용하면 라크델라 - 고대수호자의 장궁이 만들어졌고, 그 뒤 고대정령 바르투스가 {item:18715}({spell:425121})을(를) 주었습니다.",
		["Onyxia"] = "오닉시아",
		["Onyxia drops the {item:18705}; she is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}."] = "오닉시아가 {item:18705}을(를) 떨어뜨립니다. 오닉시아는 {zone:1445} 남부 {area:511}의 동굴인 {area:2159}의 40인 공격대 우두머리입니다.",
		["Rhok'delar and Lok'delar"] = "라크델라와 로크델라",
		["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "사냥꾼의 영웅 활 연계 퀘스트입니다. 클래식에서는 지팡이와 힘줄이 라크델라와 로크델라가 되었습니다(Forever에서는 미확인).",
		["The {item:18703}"] = "{item:18703}",
		["The {object:179703} appears in {area:2717} when {npc:12018} yields; it holds the {item:18703} about half the time. {area:2717} is a 40-player raid inside {area:254}. Right-click the leaf to start the quest."] = "{npc:12018}이(가) 항복하면 {area:2717}에 {object:179703}이(가) 나타나며, 약 절반의 확률로 {item:18703}이(가) 들어 있습니다. {area:2717}은(는) {area:254} 안의 40인 공격대 던전입니다. 나뭇잎을 오른쪽 클릭해 퀘스트를 시작하세요.",
		["Vartrus, Stoma and {npc:14526} stand together in the north of {zone:1448}. Alliance: {area:1998} is the nearest flight point; Horde: {area:1997}."] = "바르투스, 스토마, {npc:14526}은(는) {zone:1448} 북쪽에 함께 서 있습니다. 얼라이언스는 {area:1998}, 호드는 {area:1997}이(가) 가장 가까운 비행 지점입니다.",
		["from the {item:18703}"] = "{item:18703}에서",
		["{item:18704}, from {npc:6109}"] = "{item:18704}, {npc:6109}에게서",
		["{item:18705}, from Onyxia"] = "{item:18705}, 오닉시아에게서",
		["{item:18707}, by Vartrus"] = "{item:18707}, 바르투스 곁에서",
		["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}: 클래식에서는 로크델라",
		["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}: 화살통, 이 가이드의 마지막",
		["{npc:14527}, a troll, stands in the west of {zone:1449}. Talk to her and she becomes {npc:14533}, with a pet of her own. Alone, without your pet."] = "트롤인 {npc:14527}은(는) {zone:1449} 서쪽에 서 있습니다. 그녀에게 말을 걸면 자신의 소환수를 데린 {npc:14533}(으)로 변합니다. 소환수 없이 혼자 싸우세요.",
		["{npc:14529}, a human, stands in the west of the {zone:1428}. Talk to him and he becomes {npc:14534}. Alone, without your pet."] = "인간인 {npc:14529}은(는) {zone:1428} 서쪽에 서 있습니다. 그에게 말을 걸면 {npc:14534}(으)로 변합니다. 소환수 없이 혼자 싸우세요.",
		["{npc:14531}, a tauren, waits in the north-east of {zone:1452}. Talk to him and he becomes {npc:14535}. Fight every demon alone and without your pet: help of any kind makes it vanish. Loot the head."] = "타우렌인 {npc:14531}은(는) {zone:1452} 북동쪽에서 기다립니다. 그에게 말을 걸면 {npc:14535}(으)로 변합니다. 모든 악마와 소환수 없이 혼자 싸우세요. 어떤 도움이든 받으면 악마가 사라집니다. 머리를 획득하세요.",
		["{npc:14536}, a gnome, stands in the south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. Alone, without your pet; keep away from the beetles he calls."] = "노움인 {npc:14536}은(는) {zone:1451} 남서쪽에 서 있습니다. 그에게 말을 걸면 {npc:14530}(으)로 변합니다. 소환수 없이 혼자 싸우고, 그가 부르는 딱정벌레를 피하세요.",
} end)()
t.guides["forever/class/hunter/the-hunters-charm"] = (function() return {
		["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "50레벨이 되면 얼라이언스 사냥꾼 상급자 누구나 이 퀘스트를 줍니다: {zone:1453} {object:28027}의 {npc:5516}, {zone:1455} {object:32390}의 {npc:5116}, {zone:1457} 세나리온 자치령의 도리온.",
		["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "50레벨이 되면 호드 사냥꾼 상급자 누구나 이 퀘스트를 줍니다. {zone:1454} {object:172958}의 {npc:3352}, {zone:1456} {area:1641}의 {npc:3039}.",
		["Experience"] = "경험치",
		["Experience at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "50레벨에 {zone:1447}와(과) {area:1417}을(를) 통한 경험치. Forever에서는 클래식의 아이템 선택이 사라졌습니다.",
		["Morphaz in the {area:1417}"] = "{area:1417}의 몰파즈",
		["Morphaz is an elite dragon boss inside the {area:1417}, a five-player dungeon: bring a group. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance. Horde: fly to {area:75}; Alliance: fly to {area:42} or {area:1438} and ride on."] = "몰파즈는 5인 던전인 {area:1417} 안의 정예 용 우두머리입니다. 파티를 데려가세요. 사원은 {area:74} 한가운데에 있으며, 물속으로 헤엄쳐 내려가면 입구가 나옵니다. 호드는 {area:75}(으)로, 얼라이언스는 {area:42}나 {area:1438}(으)로 날아간 뒤 말을 타고 가세요.",
		["Mosshoof Coursers graze all over {zone:1447}; one in a dozen or so drops a pair of Perfect Courser Antlers."] = "{npc:8761}은(는) {zone:1447} 곳곳에서 풀을 뜯습니다. 열두 마리 중 하나꼴로 {item:20017} 한 쌍을 떨어뜨립니다.",
		["Wavethrashers crawl along {zone:1447}'s coasts: Young Wavethrashers on the north-east shore and Wavethrashers on the east coast drop the scales about twice as often as the Great Wavethrashers of the south shore."] = "폭풍히드라는 {zone:1447} 해안을 따라 기어다닙니다. 북동쪽 해안의 어린 폭풍히드라와 동쪽 해안의 폭풍히드라는 남쪽 해안의 거대한 폭풍히드라보다 비늘을 약 두 배 자주 떨어뜨립니다.",
		["{item:20019}, inside the {area:1417}"] = "{item:20019}, {area:1417} 안",
		["{npc:8405} lives atop the cliffs north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}."] = "{npc:8405}은(는) {area:1221} 북동쪽 절벽 꼭대기에 삽니다. 얼라이언스는 {area:3137}(으)로, 호드는 {area:1237}(으)로 날아가세요.",
		["{quest:8151} (Alliance)"] = "{quest:8151} (얼라이언스)",
		["{quest:8151} (Horde)"] = "{quest:8151} (호드)",
} end)()
t.guides["forever/class/mage/arcane-refreshment"] = (function() return {
		["Back to Lydros"] = "리드로스에게 돌아가기",
		["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing (or the North wing with a {item:18249})."] = "페더문 요새(얼라이언스) 또는 {area:1099}(호드)(으)로 비행한 뒤 {zone:1444} 중앙의 {area:2577}(으)로 달려가십시오. {npc:14368}은(는) 서쪽 구역(또는 {item:18249}이(가) 있으면 북쪽 구역)을 지나 도착하는 도서관에서 기다립니다.",
		["Hydrospawn"] = "히드로스폰",
		["Hydrospawn, a water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool."] = "물의 정령 히드로스폰은 굽이나무 지구(혈투의 전장 동쪽)에 있습니다. 임프 푸실린이 돌아서서 싸울 때까지 쫓은 뒤, 사티로스 방을 정리하고 나선형 경사로를 따라 웅덩이로 내려가세요.",
		["Shen'dralar reputation"] = "셴드랄라 평판",
		["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "{area:2577} 도서관에서 얻는 레벨 60 {spell:10140}: 자신과 파티원을 위한 음료.",
		["{item:18299}: Hydrospawn"] = "{item:18299}: 히드로스폰",
} end)()
t.guides["forever/class/mage/astral-knot-garment"] = (function() return {
		["A robe or a blouse for Human and Gnome mages in their late 20s."] = "20대 후반 인간과 노움 마법사를 위한 로브 또는 블라우스입니다.",
		["Back to Andromath"] = "고위마술사 안드로매스에게 돌아가기",
		["Carrion Recluses"] = "청소부그늘거미",
		["Carrion Recluses lurk in the woods of western {zone:1431} and each one drops the silk. The Black Widow Hatchlings further east drop it now and then."] = "청소부그늘거미는 {zone:1431} 서쪽 숲에 숨어 있으며, 모두 거미줄을 떨어뜨립니다. 더 동쪽의 새끼 검은과부거미도 가끔 떨어뜨립니다.",
		["Ride east through {zone:1429} into Redridge. The fallen mage's tower of Ilgalar stands in the east of the zone; the treatise is in his library."] = "{zone:1429}을(를) 지나 동쪽 붉은마루 산맥으로 가십시오. 타락한 마법사 일갈라의 탑은 지역 동쪽에 있으며, 논문은 그의 서재에 있습니다.",
		["The {area:96}"] = "{area:96}",
		["{npc:1309} works at {object:23296} in the {object:2101}."] = "{npc:1309}은(는) {object:2101}의 {object:23296}에서 일합니다.",
		["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144}은(는) {zone:1455}의 {object:32362}에서 마법사를 가르칩니다. 이후 {object:171524}에서 {area:2257}을(를) 타고 {zone:1453}(으)로 가십시오.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}."] = "{npc:5497}은(는) {object:2101}의 탑인 마법사의 성소에 있습니다.",
