t.guides["forever/class/mage/polymorph-pig"] = (function() return {
		["A new look for {spell:118}: it turns the target into a pig rather than a sheep."] = "{spell:118}의 새 모습: 대상을 양 대신 돼지로 바꿉니다.",
		["Back to {npc:8395} and up to the tower."] = "{npc:8395}에게 돌아가 탑으로 올라가십시오.",
		["Carry the {item:23250} back to the {area:1221}. Polymorph a Spitelash naga and wait a few seconds: it splits into small Polymorph Clones. Kill the clones quickly; the shell collects their essence."] = "{item:23250}을(를) {area:1221}(으)로 다시 가져가세요. 원한의꼬리일족 나가에게 변이를 걸고 몇 초 기다리면 작은 변이된 복제생물로 갈라집니다. 복제생물을 빨리 처치하세요. 껍데기가 그 정수를 모읍니다.",
		["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below {npc:8379}'s tower: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. He teleports you up to the Archmage."] = "{area:3137}(얼라이언스) 또는 {area:1237}(호드)(으)로 날아가십시오. {npc:8395}은(는) {npc:8379}의 탑 아래에서 야영합니다. {area:1221}에 있는 {zone:1447} 큰길의 갈림길에서 절벽까지 곧장 북쪽으로 가십시오. 그가 대마법사에게 순간이동시켜 줍니다.",
		["Krellian hides behind his Spitelash guards in the {area:1223}, the biggest building in the middle of the {area:1221}. He drops the {item:23250}."] = "크렐리안은 {area:1221} 한가운데 가장 큰 건물인 {area:1223}에서 원한의꼬리일족 경비병 뒤에 숨어 있습니다. {item:23250}을(를) 떨어뜨립니다.",
		["Polymorph Clones"] = "변이된 복제생물",
		["{npc:8379}: {spell:118} (pig)"] = "{npc:8379}: {spell:118}(돼지)",
} end)()
t.guides["forever/class/mage/spellfire-robes"] = (function() return {
		["A robe at 15 for Horde mages, from the {zone:1458} and {zone:1421}."] = "호드 마법사를 위한 15레벨 로브, {zone:1458}와(과) {zone:1421}에서.",
		["Algernon's alchemist shop is in the Apothecarium. Use the {item:7308} there to make the {npc:6492} visible, subdue one with your spells, then use the {item:7247} to throw down a coffer and capture it."] = "알게르논의 연금술 상점은 연금술 실험실에 있습니다. 그곳에서 {item:7308}을(를) 사용해 {npc:6492}을(를) 드러내고, 주문으로 약화시킨 뒤 {item:7247}을(를) 사용해 상자를 던져 포획하세요.",
		["Back to the {zone:1458}. {npc:4576}, {npc:11048} and {npc:11049} keep the tailor's shop."] = "{zone:1458}(으)로 돌아가세요. {npc:4576}, {npc:11048}, {npc:11049}이(가) 재봉 상점을 운영합니다.",
		["Back to {npc:4568}"] = "{npc:4568}에게 돌아가기",
		["Humanoids drop {item:2589}; the Undercity Auction House sells it."] = "인간형 몹이 {item:2589}을(를) 떨어뜨립니다. 언더시티 경매장에서도 팝니다.",
		["Leave the {zone:1458} and follow the road south through {zone:1421}. The {area:279} mages hold {area:233}, south-east of the {area:228}; every {npc:1867}, Mage, Protector, Warder, Conjuror, Watcher and Wizard can drop a {item:7293}."] = "{zone:1458}을(를) 나와 길을 따라 남쪽으로 {zone:1421}을(를) 지나가세요. {area:279} 마법사들이 {area:228} 남동쪽의 {area:233}을(를) 차지하고 있습니다. {npc:1867}, 달라란 마법사, 수호병, 보초병, 요술사, 파수꾼, 마술사 모두 {item:7293}을(를) 떨어뜨릴 수 있습니다.",
		["The alchemist shop"] = "연금술 상점",
		["{npc:2128} is the {area:159} mage trainer."] = "{npc:2128}은(는) {area:159}의 마법사 상급자입니다.",
		["{npc:4568} stands in the {object:36082}. The {item:7247} and the {item:7308} lie behind her."] = "{npc:4568}은(는) {object:36082}에 서 있습니다. {item:7247}와(과) {item:7308}은(는) 그녀 뒤에 있습니다.",
		["{npc:7311} is one of {zone:1454}'s mage trainers. Then take the zeppelin to {zone:1420} from the tower outside {zone:1454}'s main gate."] = "{npc:7311}은(는) {zone:1454}의 마법사 상급자 중 하나입니다. 그런 다음 {zone:1454} 정문 밖 탑에서 비행선을 타고 {zone:1420}(으)로 가세요.",
} end)()
t.guides["forever/class/paladin/cloak-of-the-divine-storm"] = (function() return {
		["A rare cloak at 30 from the old {spell:407778} story; for now only Alliance paladins can finish it."] = "옛 {spell:407778} 이야기에서 이어지는 30레벨 희귀 망토입니다. 지금은 얼라이언스 성기사만 완료할 수 있습니다.",
		["Back to {area:413}."] = "{area:413}(으)로 돌아가십시오.",
		["Back to {npc:5495}"] = "{npc:5495}에게 돌아가기",
		["Blackrock Summoners, Champions and Trackers camp in the north-west of Redridge; they drop the {item:209778}."] = "붉은마루 산맥 북서쪽에 진을 친 검은바위부족 소환사, 용사, 추적자가 {item:209778}을(를) 떨어뜨립니다.",
		["Climb to the top of the {area:444} in northern {zone:1439}. Loot the Strange Orb up there: it gives you the Althalaxx Orb, which starts the quest."] = "{zone:1439} 북부의 {area:444} 꼭대기로 올라가십시오. 그곳의 Strange Orb에서 Althalaxx Orb를 얻으면 퀘스트가 시작됩니다.",
		["Katherine sends you to the warlocks in the {object:2101}; {npc:5495} speaks for them."] = "캐서린은 당신을 {object:2101}의 흑마법사들에게 보냅니다. {npc:5495}이(가) 그들을 대변합니다.",
		["Motes of Mannoroth"] = "만노로스의 티끌",
		["Strange Orb atop the {area:444}: right-click the Althalaxx Orb it gives"] = "{area:444} 꼭대기의 Strange Orb: 얻은 Althalaxx Orb를 오른쪽 클릭",
		["The Strange Orb"] = "Strange Orb",
		["The {object:409311}"] = "{object:409311}",
		["The {object:409311} stands at the east end of {area:435}. Shatter the orb on it; the {object:409315} appears beside it."] = "{object:409311}은(는) {area:435} 동쪽 끝에 서 있습니다. 그 위의 구슬을 깨뜨리면 옆에 {object:409315}이(가) 나타납니다.",
		["from the {object:409315}"] = "{object:409315}에서",
		["{area:435} is in south-east {zone:1440}. The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds in it drop the Motes of Mannoroth."] = "{area:435}은(는) {zone:1440} 남동쪽에 있습니다. 그 안의 만노로크 채찍마녀, 불타는 지옥불정령, 지옥군단병, 군단 지옥사냥개가 만노로스의 티끌을 떨어뜨립니다.",
		["{npc:3663} stands at {area:413} in western {zone:1440}."] = "{npc:3663}은(는) {zone:1440} 서부의 {area:413}에 있습니다.",
		["{npc:5492} is in the Cathedral of Light."] = "{npc:5492}은(는) 빛의 대성당에 있습니다.",
} end)()
t.guides["forever/class/paladin/holy-mightstone"] = (function() return {
