		["{item:20608}, inside"] = "{item:20608}, 내부",
		["{npc:10838} commands {area:3197} in the south of the {zone:1422}."] = "{npc:10838}은(는) {zone:1422} 남쪽의 {area:3197}을(를) 지휘합니다.",
		["{npc:5149} is in the {object:32362}."] = "{npc:5149}은(는) {object:32362}에 있습니다.",
		["{npc:928} is in the Cathedral of Light."] = "{npc:928}은(는) 빛의 대성당에 있습니다.",
} end)()
t.guides["forever/class/paladin/lumina-windsinger"] = (function() return {
		["Back to the {area:228}"] = "{area:228}로 돌아가기",
		["Free her with the key, then stay close while she fights her way out of the keep."] = "열쇠로 그녀를 풀어준 뒤, 그녀가 싸우며 성채를 빠져나가는 동안 가까이 있으십시오.",
		["Free {npc:248755}"] = "{npc:248755} 풀어주기",
		["No item yet: a Forsaken paladin rescue story; its sequel, the {item:268484}, cannot be finished yet."] = "아직 아이템 없음: 포세이큰 성기사 구출 이야기입니다. 후속인 {item:268484}은(는) 아직 완료할 수 없습니다.",
		["Once she is clear of {area:235}, {npc:259620} waits for you in the {area:228}. Speak with her again to hear what really happened on the road."] = "{area:235}을(를) 벗어나면 {npc:259620}이(가) {area:228}에서 기다립니다. 다시 대화하여 길에서 실제로 무슨 일이 있었는지 들으십시오.",
		["Rescuing {quest:91862}"] = "{quest:91862} 구출",
		["Ride south through {zone:1421} to the {area:228}. {npc:248840} stands in the town; {npc:259611} keeps watch near its entrance."] = "{zone:1421}을(를) 지나 남쪽의 {area:228}로 가십시오. {npc:248840}은(는) 마을 안에 있고, {npc:259611}은(는) 입구 근처에서 경계를 섭니다.",
		["The pyre on {area:172}"] = "{area:172}의 화장단",
		["from the {object:566037}"] = "{object:566037}에서",
		["{area:172} lies in the lake east of the {area:228}. The charred remains are on its shore."] = "{area:172}은(는) {area:228} 동쪽 호수에 있습니다. 불탄 유해는 그 물가에 있습니다.",
		["{item:267412}, from the Rot Hide gnolls"] = "{item:267412}, 썩은가죽일족 놀에게서",
		["{npc:246378} leads the Paladins of Tyr's Watch from inside {area:16602}, on the bluffs north-west of the {area:156}."] = "{npc:246378}은(는) {area:156} 북서쪽 절벽 위 {area:16602} 안에서 Tyr's Watch의 성기사들을 이끕니다.",
		["{npc:259620}, the {area:228}"] = "{npc:259620}, {area:228}",
		["{quest:91862} is caged inside {area:235}, at the north end of the isle. The Rot Hide gnolls around her carry the key."] = "{quest:91862}은(는) 섬 북쪽 끝 {area:235} 안에 갇혀 있습니다. 그녀 주변의 썩은가죽일족 놀이 열쇠를 가지고 있습니다.",
		["{zone:1458} and Earthen Ring reputation"] = "{zone:1458} 및 대지 고리회 평판",
} end)()
t.guides["forever/class/paladin/tyrs-watch"] = (function() return {
		["Back to the keep"] = "요새로 돌아가기",
		["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep."] = "{area:16602}(으)로 돌아가십시오. {npc:246378}이(가) {item:6866}을(를) 주며, {npc:257655}은(는) 요새 아래층에서 기다립니다.",
		["Back to {area:16602}: Billmuth takes the plans, {npc:246378} teaches you {spell:7328}."] = "{area:16602}(으)로 돌아가십시오. Billmuth가 계획을 받고, {npc:246378}이(가) {spell:7328}을(를) 가르칩니다.",
		["Tarnished Drudges"] = "Tarnished Drudge",
		["Tarnished Zealots"] = "Tarnished Zealot",
		["The Scarlet Crusaders camped around {area:812} carry the attack plans."] = "{area:812} 주변에 진을 친 Scarlet Crusader들이 공격 계획을 가지고 있습니다.",
		["The Scarlet attack plans"] = "붉은십자군 공격 계획",
		["The Vile Fin murlocs lurk on the bluffs along the road east of the keep and in the camps around the lake to the west."] = "썩은지느러미멀록은 요새 동쪽 길가의 절벽과 서쪽 호수 주변 야영지에 숨어 있습니다.",
		["The {item:6866}"] = "{item:6866}",
		["Tyr's Watch and {spell:7328}"] = "티르의 감시단과 {spell:7328}",
		["Vile Fin Attackers"] = "Vile Fin Attacker",
		["Vile Fin Seers"] = "Vile Fin Seer",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "{area:159}에서 남쪽으로 걸어 {area:153}(으)로 간 뒤 {zone:1458}(으)로 내려가십시오. {npc:10181}은(는) {object:36126}에, {npc:257648}은(는) {object:36078}에서 구걸하고 있습니다.",
		["{area:16602} stands on the bluffs north-west of the {area:156}. {npc:246349} waits at the gate."] = "{area:16602}은(는) {area:156} 북서쪽 절벽 위에 있습니다. {npc:246349}이(가) 성문에서 기다립니다.",
		["{area:812} is at the far east end of the glades. Use the {item:6866} on {npc:257663}, then speak to him. If you lose the symbol, {npc:246378} gives you another."] = "{area:812}은(는) 숲 동쪽 끝에 있습니다. {npc:257663}에게 {item:6866}을(를) 사용한 뒤 대화하십시오. 상징을 잃어버리면 {npc:246378}이(가) 하나 더 줍니다.",
		["{npc:246152}, who trains Paladins in {area:159}, sends you to the order's keep on the west coast."] = "{area:159}에서 성기사를 가르치는 {npc:246152}이(가) 서해안에 있는 기사단의 요새로 보냅니다.",
		["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it."] = "{npc:246378}은(는) 요새 안에서 기사단을 이끌며, {npc:246393}이(가) 그 옆에 서 있습니다.",
		["{npc:246378} offers the first Lesson in Divinity at level 12."] = "{npc:246378}이(가) 12레벨에 첫 번째 신성 수업을 줍니다.",
		["{npc:257648} needs 10 {item:2589}. Scarlet Zealots and Scarlet Friars drop it about three times in ten; bring it along if you already carry some."] = "{npc:257648}에게 {item:2589} 10개가 필요합니다. 붉은십자군 광신도와 붉은십자군 수사가 열에 세 번 정도 떨어뜨립니다. 이미 가지고 있다면 챙겨 가십시오.",
		["{object:554626}, in the root cellar"] = "{object:554626}, 뿌리 저장고 안",
		["{quest:91317} hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. The {item:246213} is piled in the root cellar of one of its houses; Commander {npc:259431} walks among his Tarnished."] = "{quest:91317}이(가) 저택 남서쪽 {area:16616}의 폐허 마을 {area:16881}을(를) 차지하고 있습니다. {item:246213}은(는) 한 집의 뿌리 저장고에 쌓여 있고, 사령관 {npc:259431}이(가) 자신의 빛바랜 자들 사이를 돌아다닙니다.",
		["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "쓰러진 아군을 되살리는 {spell:7328}와(과), 새내기 포세이큰 성기사를 위한 무기와 방패입니다.",
} end)()
t.guides["forever/class/paladin/verigans-fist"] = (function() return {
		["At 20 {npc:6179} in the {object:32362} gives you the {item:6776}; it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the tram from {zone:1455} to {zone:1453}."] = "20레벨에 {object:32362}의 {npc:6179}이(가) {item:6776}을(를) 줍니다. 이것은 {zone:1453} 빛의 대성당의 {npc:6171}에게 보냅니다. {zone:1455}에서 지하철을 타고 {zone:1453}(으)로 가세요.",
		["Back to {npc:3649} in {area:442}: he purifies the gem."] = "{area:442}의 {npc:3649}에게 돌아가세요. 그가 보석을 정화합니다.",
		["Back to {npc:6241}"] = "{npc:6241}에게 돌아가기",
		["Bring the four parts to {npc:6181} outside {zone:1455}."] = "네 가지 부품을 {zone:1455} 밖의 {npc:6181}에게 가져가세요.",
		["Goblin Woodcarvers, inside"] = "고블린 목공, 던전 안",
		["Protect {npc:6182}"] = "{npc:6182} 보호",
		["The Alliance paladin's rare two-handed mace for the 20s, with a shield on the way."] = "20대 얼라이언스 성기사용 희귀 양손 둔기, 도중에 방패도 얻습니다.",
		["The Blackfathom naga by the entrance of {area:2797} on {zone:1440}'s north-west coast drop the {item:6995}. They are elite: grouping up is advised."] = "{zone:1440} 북서쪽 해안 {area:2797} 입구 옆의 검은심연 나가가 {item:6995}을(를) 떨어뜨립니다. 정예이니 파티를 권장합니다.",
		["The ore crate lies by the trees in the middle of the Mo'grosh ogre camp in north-east {zone:1432}. The Mo'grosh ogres are elite: grouping up is advised."] = "광석 상자는 {zone:1432} 북동쪽 모그로쉬 오우거 야영지 한가운데의 나무 옆에 있습니다. 모그로쉬 오우거는 정예이니 파티를 권장합니다.",
		["The {item:6995}"] = "{item:6995}",
		["The {item:7083}"] = "{item:7083}",
		["from the {item:6776}"] = "{item:6776}에서",
		["{area:1581} is a group of five under {area:20}; the instance portal is inside the {area:20} mine. The Goblin Woodcarvers in the Mast Room, with Sneed, drop the lumber."] = "{area:1581}은(는) {area:20} 아래의 5인 던전입니다. 던전 입구는 {area:20} 광산 안에 있습니다. 스니드와 함께 돛대 방에 있는 고블린 목공이 목재를 떨어뜨립니다.",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}, {area:20} 광산 안",
		["{area:236} is a level 20-30 dungeon in southern {zone:1421}. The hammer lies on a box inside the stables, at the far end of the courtyard before the ramp up."] = "{area:236}은(는) {zone:1421} 남부의 20-30레벨 던전입니다. 망치는 안뜰 끝, 오르막길 앞 마구간 안의 상자 위에 있습니다.",
		["{npc:3649} is in {area:442}."] = "{npc:3649}은(는) {area:442}에 있습니다.",
		["{npc:6171} stands in the Cathedral of Light. Right-click the {item:6776} to start its quest."] = "{npc:6171}은(는) 빛의 대성당에 서 있습니다. {item:6776}을(를) 오른쪽 클릭해 퀘스트를 시작하세요.",
		["{npc:6181} stands outside the gates of {zone:1455}. He gives you {item:6996}, which list the four parts."] = "{npc:6181}은(는) {zone:1455} 성문 밖에 서 있습니다. 그가 네 가지 부품이 적힌 {item:6996}을(를) 줍니다.",
		["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}. Waves of Defias attack it during her quest: keep her alive, and heal her if she needs it."] = "{npc:6182}의 농가는 {zone:1436} 남서쪽 해안에 있습니다. 그녀의 퀘스트 동안 데피아즈단이 여러 차례 공격해 옵니다. 그녀를 살려두고 필요하면 치유하세요.",
		["{npc:6241} is in {area:144}."] = "{npc:6241}은(는) {area:144}에 있습니다.",
		["{npc:6241} turns the ore into {item:6993}."] = "{npc:6241}이(가) 광석을 {item:6993}(으)로 만들어 줍니다.",
		["{object:91138}, inside"] = "{object:91138}, 던전 안",
		["{object:92420} crate"] = "{object:92420} 상자",
} end)()
t.guides["forever/class/priest/benediction"] = (function() return {
		["Equip {item:18646} to see {npc:14494}, a ghost on the mountainside in the north-west of the {zone:1423}. Come with full mana, Major Mana Potions and {item:8956}: if you fail, the event takes about two hours to return."] = "{item:18646}을(를) 착용하면 {zone:1423} 북서쪽 산비탈의 유령 {npc:14494}이(가) 보입니다. 마나를 가득 채우고 일급 마나 물약과 {item:8956}을(를) 챙겨 오십시오. 실패하면 이벤트가 다시 열리기까지 약 두 시간이 걸립니다.",
		["Save 50 peasants before 15 die. Kill the skeletons that attack them, cure their diseases (the purple ones first) and heal the wounded with {spell:139}. Friends may buff you beforehand but must stay out of the fight, or a demon appears and kills everyone."] = "농민 15명이 죽기 전에 50명을 구하세요. 농민을 공격하는 해골을 처치하고, 질병을 치료하고(보라색부터), 부상자는 {spell:139}(으)로 치유하세요. 친구가 미리 강화 효과를 걸어 줄 수는 있지만 전투에는 끼면 안 됩니다. 그렇지 않으면 악마가 나타나 모두를 죽입니다.",
		["With both Eyes in your bags: {item:18608}"] = "두 눈을 가방에 넣고: {item:18608}",
		["You need {item:18646} first: it comes from the {object:179703} after {npc:12018} in {area:2717}. {item:18665} drops from elite demons ({npc:12397}, a world boss, always; Doomguard Commanders and Manahounds rarely); it binds when equipped, so buying one works too."] = "먼저 {item:18646}이(가) 필요합니다. {area:2717}에서 {npc:12018} 처치 후 나오는 {object:179703}에서 얻습니다. {item:18665}은(는) 정예 악마에게서 떨어집니다(필드 우두머리 {npc:12397}은(는) 항상, 파멸의수호대 사령관과 마나사냥개는 드물게). 착용 시 귀속이므로 구매해도 됩니다.",
		["{item:18608} and Anathema"] = "{item:18608} 및 저주의 지팡이",
		["{npc:14494}'s splinter and the two Eyes make {item:18608}, the epic priest staff that turns into Anathema."] = "{npc:14494}의 조각과 두 개의 눈으로 {item:18608}을(를) 만듭니다. 저주의 지팡이로 변하는 사제 영웅 지팡이입니다.",
} end)()
t.guides["forever/class/priest/blood-of-morphaz"] = (function() return {
		["Any undead can drop it. The {npc:7864} in the {area:1221}, below {npc:8405}'s cliffs, are the nearest; Highborne Apparitions and Lichlings haunt the ruins near {area:3137}."] = "모든 언데드가 떨어뜨릴 수 있습니다. {npc:8405}의 절벽 아래 {area:1221}의 {npc:7864}이(가) 가장 가깝습니다. 명가의 유령과 명가의 망령은 {area:3137} 근처 폐허에 출몰합니다.",
		["At 50 {npc:5489} in {zone:1453}'s Cathedral of Light or {npc:11406} in {zone:1455}'s {object:32386} offers it."] = "50레벨에 {zone:1453} 빛의 대성당의 {npc:5489} 또는 {zone:1455} {object:32386}의 {npc:11406}이(가) 줍니다.",
