		["At 10 {npc:2130}, the rogue trainer in the {area:2119} in {area:159}, sends you to {quest:1885} in the {zone:1458}."] = "10레벨에 {area:159} {area:2119}의 도적 상급자 {npc:2130}이(가) {zone:1458}의 {quest:1885}에게 보냅니다.",
		["At 10 {npc:3170}, the rogue trainer in {area:362}, sends you to {quest:1859} in {zone:1454}."] = "10레벨에 {area:362}의 도적 상급자 {npc:3170}이(가) {zone:1454}의 {quest:1859}에게 보냅니다.",
		["Back to {npc:6446}"] = "{npc:6446}에게 돌아가기",
		["Back to {npc:6467}"] = "{npc:6467}에게 돌아가기",
		["The {object:36073}"] = "{object:36073}",
		["{item:7209}, once you have the key"] = "{item:7209}, 열쇠를 얻은 뒤",
		["{item:7295}, from the satchel"] = "{item:7295}, 가방에서",
		["{item:7298} (Horde)"] = "{item:7298} (호드)",
		["{npc:6446}'s reward"] = "{npc:6446}의 보상",
		["{npc:6466} drinks in the inn in the {object:172982}. Pick his pocket for {item:7208}, then open {item:7209}."] = "{npc:6466}은(는) {object:172982}의 여관에서 술을 마십니다. 소매치기로 {item:7208}을(를) 얻은 뒤 {item:7209}을(를) 여십시오.",
		["{npc:6467} and {npc:2425}"] = "{npc:6467}와(과) {npc:2425}",
		["{npc:6467} sends the ledger on to {npc:2425} in the Hall of the Dark Lady, the {object:36126}."] = "{npc:6467}이(가) 장부를 {object:36126}에 있는 {npc:2425}에게 전달하라고 합니다.",
		["{npc:6494} stands on the {zone:1413} coast south of {area:392}. Kill him for his satchel."] = "{npc:6494}은(는) {area:392} 남쪽 {zone:1413} 해안에 있습니다. 처치해서 가방을 얻으십시오.",
		["{npc:6497} stands north-east of the {area:228}. Take his Letter of Introduction from him."] = "{npc:6497}은(는) {area:228} 북동쪽에 있습니다. 그에게서 소개장을 받으십시오.",
		["{npc:6522}'s ledger sits on the bookshelf beside him."] = "{npc:6522}의 장부는 그 옆 책장에 있습니다.",
		["{quest:1859} stands in the {object:172960}, the canyon under the {object:172982}. Trolls: take {quest:1963} from him at 10."] = "{quest:1859}은(는) {object:172982} 아래 협곡인 {object:172960}에 있습니다. 트롤은 10레벨에 그에게서 {quest:1963}을(를) 수락하십시오.",
		["{quest:1885} stands in the {object:36073}."] = "{quest:1885}은(는) {object:36073}에 있습니다.",
} end)()
t.guides["forever/class/rogue/certificate-of-thievery"] = (function() return {
		["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165}, in the north of {zone:1455}."] = "16레벨에 {area:131} {area:2102}의 {npc:1234}이(가) {zone:1455} 북쪽의 {npc:5165}에게 보냅니다.",
		["At 16 {npc:3599} in {area:186} sends you to {quest:2259} in {zone:1457}."] = "16레벨에 {area:186}의 {npc:3599}이(가) {zone:1457}의 {quest:2259}에게 보냅니다.",
		["At 16 {npc:917}, the rogue trainer in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}."] = "16레벨에 {area:87} 사자무리 여관의 도적 상급자 {npc:917}이(가) {zone:1453}의 {npc:6946}에게 보냅니다.",
		["Back to {npc:6966}"] = "{npc:6966}에게 돌아가기",
		["Ride east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} waits on the west side of {area:69} and gives you {item:5060}."] = "{zone:1429}을(를) 지나 동쪽의 붉은마루 산맥으로 가거나 {area:69}(으)로 날아가십시오. {npc:6966}은(는) {area:69} 서쪽에서 기다리며 {item:5060}을(를) 줍니다.",
		["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "16레벨의 첫 자물쇠 따기 임무: {quest:2300}을(를) 위해 {quest:2282}에서 {npc:6966}의 금고를 엽니다.",
		["{npc:6946} stands beside {npc:332} at {quest:2300} in {object:2100}. Dwarves and Gnomes take the {area:2257} from {zone:1455}; Night Elves take the boat from {area:442} to {area:17203}."] = "{npc:6946}은(는) {object:2100}의 {quest:2300}에서 {npc:332} 옆에 서 있습니다. 드워프와 노움은 {zone:1455}에서 {area:2257}을(를) 타십시오. 나이트 엘프는 {area:442}에서 배를 타고 {area:17203}(으)로 가십시오.",
		["{quest:2282} stands east of {area:69}, up off the road. Open {object:121264} there."] = "{quest:2282}은(는) {area:69} 동쪽, 길에서 벗어난 언덕 위에 있습니다. 그곳에서 {object:121264}을(를) 여십시오.",
} end)()
t.guides["forever/class/rogue/plundering-the-plunderers"] = (function() return {
		["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "16레벨에 {area:362}의 도적 상급자 {npc:3170}이(가) {zone:1454}의 {npc:3401}에게 보냅니다.",
		["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "16레벨에 {object:36073}의 {npc:6467}이(가) {zone:1454}의 {npc:3401}에게 보냅니다. 그에게서 {quest:1998}도 받으십시오. 이 가이드 마지막에 {zone:1421}에서 완료합니다.",
		["Back to {npc:6467}"] = "{npc:6467}에게 돌아가기",
		["Back to {npc:7161}"] = "{npc:7161}에게 돌아가기",
		["Fly or ride to {area:392} on the {zone:1413} coast. {npc:7161} stands in town with his Gizmotronic Apparatus: buy an {item:7970} and {item:5060} from the apparatus before you go."] = "{zone:1413} 해안의 {area:392}(으)로 비행하거나 달려가십시오. {npc:7161}은(는) 마을에서 레닉스의 기계장치와 함께 서 있습니다. 떠나기 전에 기계장치에서 {item:7970}와(과) {item:5060}을(를) 구매하십시오.",
		["South along the coast from {area:392}, at the Southsea pirates' camp. If an unusually hostile parrot attacks you, use the {item:7970} on it (the quest's own advice)."] = "{area:392}에서 해안을 따라 남쪽, 남쪽바다 해적단 야영지입니다. 유난히 적대적인 앵무새가 공격하면 {item:7970}을(를) 사용하십시오(퀘스트 자체의 조언입니다).",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and ride south into Silverpine. {quest:1998} stands north-east of the {area:228}."] = "{zone:1454}에서 비행선을 타고 {zone:1458}(으)로 간 뒤 남쪽 은빛소나무 숲으로 달려가십시오. {quest:1998}은(는) {area:228} 북동쪽에 있습니다.",
		["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "16레벨 호드 자물쇠 따기 임무로 얻는 도적용 기력 음료 {item:7676} 10개.",
		["The Kirin Tor keep their reports at {area:233}, in south-east Silverpine: pick the lock on the {object:103815}."] = "키린 토는 은빛소나무 숲 남동쪽의 {area:233}에 보고서를 보관합니다: {object:103815}의 자물쇠를 따십시오.",
		["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}."] = "언데드는 {zone:1458} 밖의 탑에서 비행선을 타고 {zone:1411}(으)로 가십시오. {npc:3401}와(과) {quest:2379}은(는) {object:172982} 아래 협곡인 {object:172960}에 있습니다.",
		["{npc:3401} and {quest:2379}"] = "{npc:3401}와(과) {quest:2379}",
		["{npc:7161}: ten {item:7676}"] = "{npc:7161}: {item:7676} 10개",
} end)()
t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["/lay down"] = "/lay down",
		["At 20 {npc:332} at SI:7 in {object:2100} sends you to {npc:7024} in {zone:1436}."] = "20레벨에 {object:2100} SI:7의 {npc:332}이(가) {zone:1436}의 {npc:7024}에게 보냅니다.",
		["Back to {npc:7207}"] = "{npc:7207}에게 돌아가기",
		["Everything is in {zone:1453}: the Gumps sell {item:3421}, the {item:8431} lies in the city, and the nearest vendors sell a {item:3372} and a {item:4371}."] = "모두 {zone:1453}에 있습니다: 검프 남매가 {item:3421}을(를) 팔고, {item:8431}은(는) 도시 안에 놓여 있으며, 가까운 상인이 {item:3372}와(과) {item:4371}을(를) 팝니다.",
		["Forever teaches {spell:2842} through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever에서는 {spell:2842}을(를) 상급자가 아니라 이 연계 퀘스트로 배웁니다. {item:7676} 제조법도 함께 얻습니다.",
		["Ride north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "엘윈 숲을 지나 북쪽 {zone:1453}(으)로 달려가십시오. 마티아스 쇼는 {object:2100}의 SI:7에 있습니다.",
		["The cure's ingredients"] = "치료제 재료",
		["{item:7908}, in the {object:123214}"] = "{object:123214} 안의 {item:7908}",
		["{npc:7024} watches {npc:7053}'s tower from the hills in the far east of {zone:1436}, by the {zone:1431} border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "{npc:7024}은(는) {zone:1436} 동쪽 끝, {zone:1431} 경계 근처 언덕에서 {npc:7053}의 탑을 감시합니다. 탑을 지키는 {npc:7051}(레벨 23)이(가) 열쇠를 가지고 있으며, 클라벤의 일지는 꼭대기의 상자에 있습니다.",
		["{npc:7207} works in the cellar of SI:7, the Barracks. Type /lay down beside him to be examined."] = "{npc:7207}은(는) SI:7 병영 지하실에 있습니다. 그 옆에서 /lay down을 입력해 진찰을 받으십시오.",
		["{spell:2842} (Alliance)"] = "{spell:2842} (얼라이언스)",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/경례 {npc:3401}",
		["At 20 {npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Target him and type /salute."] = "20레벨에 {npc:3401}은(는) {object:172982} 아래 협곡인 {object:172960}에 서 있습니다. 그를 대상으로 잡고 /경례를 입력하세요.",
		["Back to {npc:3401}"] = "{npc:3401}에게 돌아가기",
		["Fly back to {zone:1454}."] = "{zone:1454}(으)로 날아 돌아가세요.",
		["Fly to the {area:380} and ride north to the Venture Co. tower north of the {area:382}. In sight of the tower, fire the {item:8051} twice, then /salute {npc:7233} before he attacks you."] = "{area:380}(으)로 날아가 북쪽으로 {area:382} 북쪽의 투자개발회사 탑까지 가세요. 탑이 보이는 곳에서 {item:8051}을(를) 두 번 쏜 뒤, {npc:7233}이(가) 공격하기 전에 /경례를 하세요.",
		["Forever teaches {spell:2842} through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever에서는 {spell:2842}을(를) 상급자가 아니라 이 연계 퀘스트로 배웁니다. {item:7676} 제조법도 함께 얻습니다.",
		["Stay stealthed. {npc:7287} carries the tower key; Gallywix (elite) and his lockbox are at the top of the tower. Kill two each of the drones, patrollers and lookouts around it."] = "은신을 유지하세요. {npc:7287}이(가) 탑 열쇠를 지니고 있습니다. 갤리윅스(정예)와 그의 금고는 탑 꼭대기에 있습니다. 주변의 일꾼, 순찰대원, 망꾼을 각각 두 명씩 처치하세요.",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and ride south through {zone:1421} to {area:272} in {area:287}. {npc:2391} stands in {area:272}; wait beside him while he brews the cure."] = "{zone:1454}에서 비행선을 타고 {zone:1458}(으)로 간 뒤, 남쪽으로 {zone:1421}을(를) 지나 {area:287}의 {area:272}까지 가세요. {npc:2391}은(는) {area:272}에 서 있습니다. 그가 해독제를 만드는 동안 옆에서 기다리세요.",
		["Wait for the cure"] = "해독제 기다리기",
		["{item:8051}, twice, in sight of the tower"] = "{item:8051}, 탑이 보이는 곳에서 두 번",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074}: {npc:7288} (정예)",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: {item:8051}을(를) 보관하세요",
		["{spell:2842} (Horde)"] = "{spell:2842} (호드)",
} end)()
t.guides["forever/class/rogue/ravenholdt"] = (function() return {
		["At 24 an {item:17126} from {npc:13936} starts this; the data gives it to you through {npc:332} or {npc:918} in {zone:1453}, or Gest or Ormok in {zone:1454}. The quest hands you the {item:17125} for {npc:6707}."] = "24레벨에 {npc:13936}에게서 온 {item:17126}(으)로 시작합니다. 데이터상으로는 {zone:1453}의 {npc:332} 또는 {npc:918}, {zone:1454}의 게스트 또는 오르묵을 통해 받습니다. 퀘스트에서 {npc:6707}에게 전할 {item:17125}을(를) 줍니다.",
		["At 36, {npc:13085} sends you after Barton's scouting report. Barton leads a Syndicate party at {area:280}, in the east of the {zone:1416}: pick his pocket, do not kill him."] = "36레벨에 {npc:13085}이(가) 바턴의 정찰 보고서를 가져오라고 보냅니다. 바턴은 {zone:1416} 동쪽의 {area:280}에서 비밀결사대 무리를 이끕니다: 죽이지 말고 소매치기하십시오.",
		["Back to {npc:13085}"] = "{npc:13085}에게 돌아가기",
		["Horde fly to {area:272}, Alliance to {area:271}. The manor hides in the hills east of {area:272}, up a path into the {zone:1416}; the Rite of Cunning is passing its way in."] = "호드는 {area:272}, 얼라이언스는 {area:271}(으)로 비행하십시오. 장원은 {area:272} 동쪽 언덕, {zone:1416}(으)로 올라가는 길 위에 숨어 있습니다. 들어가는 길에 Rite of Cunning을 통과합니다.",
		["Opens {area:3486}, the hidden rogue house in the Alterac hills, and its first jobs."] = "알터랙 언덕에 숨겨진 도적 저택 {area:3486}와(과) 첫 임무를 엽니다.",
		["Rite of Cunning"] = "Rite of Cunning",
		["The {item:17126}"] = "{item:17126}",
		["{item:275482}: pickpocket Barton"] = "{item:275482}: 바턴 소매치기",
		["{npc:13936} reputation"] = "{npc:13936} 평판",
		["{npc:266216} is inside {area:275}, the Syndicate fortress in eastern {area:287}, south of the manor. Quick and quiet, says {npc:13085}."] = "{npc:266216}은(는) 장원 남쪽, {area:287} 동부의 비밀결사대 요새인 {area:275} 안에 있습니다. {npc:13085}은(는) 빠르고 조용히 처리하라고 합니다.",
		["{npc:6766}: {quest:6701}, repeatable"] = "{npc:6766}: {quest:6701}, 반복 가능",
} end)()
t.guides["forever/class/rogue/the-azure-key"] = (function() return {
		["Alliance fly to {area:3137}, Horde to {area:1237}. The Timbermaw Shamans in {zone:1447}'s northern hills drop the bag, about one in thirty."] = "얼라이언스는 {area:3137}, 호드는 {area:1237}(으)로 비행하십시오. {zone:1447} 북쪽 언덕의 나무구렁일족 주술사가 약 30분의 1 확률로 자루를 떨어뜨립니다.",
		["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "50레벨에 {object:172960}의 {npc:3328}이(가) 줍니다. {zone:1458} {object:36073}의 {npc:4583}도 줍니다.",
		["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} and Fenthwick in {zone:1455}."] = "50레벨에 {zone:1453} {object:2100}의 {npc:918}이(가) 줍니다. {zone:1457}의 시우르나, {zone:1455}의 {npc:5165}와(과) 펜스윅도 줍니다.",
		["Back to Xylem"] = "실렘에게 돌아가기",
		["Lord Ravenholdt"] = "라벤홀트 경",
		["Morphaz in the {area:1417}"] = "{area:1417}의 몰파즈",
		["Morphaz, a green drake, is an elite boss deep in the {area:1417}, a level 50 dungeon: bring a group of five. The temple stands in the {area:74}; swim down to the entrance. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on."] = "녹색 비룡 몰파즈는 레벨 50 던전인 {area:1417} 깊은 곳의 정예 우두머리입니다: 5인 파티를 꾸리십시오. 신전은 {area:74}에 있으니 입구까지 헤엄쳐 내려가십시오. 호드는 {area:75}(으)로, 얼라이언스는 {area:1438}(으)로 비행한 뒤 달려가십시오.",
		["Ravenholdt reputation"] = "라벤홀트 암살단 평판",
		["Ravenholdt reputation and experience at 50; Forever removed the Classic item choice."] = "50레벨에 얻는 라벤홀트 암살단 평판과 경험치. Forever에서는 클래식의 아이템 선택 보상이 없어졌습니다.",
		["The Forest Oozes of southern {zone:1447} drop the fragments."] = "{zone:1447} 남부의 숲수액괴물이 페이지를 떨어뜨립니다.",
		["{area:3486} hides in the hills east of {area:272}, up a path into the {zone:1416}. Horde fly to {area:272}, Alliance to {area:271}."] = "{area:3486}은(는) {area:272} 동쪽 언덕, {zone:1416}(으)로 올라가는 길 위에 숨어 있습니다. 호드는 {area:272}, 얼라이언스는 {area:271}(으)로 비행하십시오.",
