		["An {item:12800} comes from Thorium veins, a {item:18335} from the elites of the {zone:1422}, both rarely: buy them at the auction house if you can."] = "{item:12800}은(는) 토륨 광맥에서, {item:18335}은(는) {zone:1422}의 정예 몹에게서 나오며 둘 다 드뭅니다. 가능하면 경매장에서 사세요.",
		["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds."] = "58레벨에 {object:172957}의 주술사 상급자 {npc:13417}이(가) 희귀한 다이아몬드 두 개를 요구합니다.",
		["Two diamonds"] = "다이아몬드 두 개",
		["he hands you the {item:18746}"] = "그가 {item:18746}을(를) 줍니다",
		["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. Use the {item:18746} in the heart of the {object:179746}'s basement, beat the spirits it calls, then {npc:14516}. All are elite: bring a group."] = "{area:2057}은(는) {zone:1422} 남동쪽의 섬 마을인 {area:2298} 아래에 있습니다. 거대한 납골당 지하실 중앙에서 {item:18746}을(를) 사용하고 나타나는 영혼들을 물리친 뒤 {npc:14516}을(를) 물리치세요. 모두 정예이니 파티를 데려가세요.",
		["{quest:7668} needs level 60."] = "{quest:7668}은(는) 60레벨이 필요합니다.",
} end)()
t.guides["forever/class/shaman/spirit-totem"] = (function() return {
		["At 50 {npc:13417}, the shaman trainer in the {object:172957}, sends you to {npc:6176}."] = "50레벨에 {object:172957}의 주술사 상급자 {npc:13417}이(가) {npc:6176}에게 보냅니다.",
		["At 50 {npc:3032}, a shaman trainer in {zone:1456}, sends you to {npc:6176}."] = "50레벨에 {zone:1456}의 주술사 상급자 {npc:3032}이(가) {npc:6176}에게 보냅니다.",
		["Experience and gold"] = "경험치와 골드",
		["Experience and gold at 50, ending in the {area:1417}; Forever removed the Classic item choice."] = "50레벨에 얻는 경험치와 골드이며, {area:1417}에서 끝납니다. Forever에서는 클래식의 아이템 선택 보상이 제거되었습니다.",
		["In the {zone:1422}, the Venom Mist Lurkers drop the {item:20610} and the Diseased Black Bears the {item:20611} (about one kill in five each)."] = "{zone:1422}에서 독안개 늑대거미가 {item:20610}을(를), 오염된 흑곰이 {item:20611}을(를) 떨어뜨립니다(각각 약 다섯 번에 한 번).",
		["One each of {item:7069}, Fire, Earth and Water. The Exiles of Arathi Highlands drop them, one element each, about one kill in ten: Thundering (air), Burning (fire), Rumbling (earth) and Cresting (water). Or buy them at the auction house."] = "{item:7069}, 불, 대지, 물을 하나씩 모으십시오. 아라시 고원의 떠도는 정령들이 각자 원소 하나씩을 약 열 번에 한 번 떨어뜨립니다: 떠도는 천둥 정령(공기), 떠도는 불의 정령(불), 떠도는 바위 정령(대지), 떠도는 물의 정령(물). 경매장에서 구매해도 됩니다.",
		["Spider eye and bear claw"] = "거미 눈과 곰 발톱",
		["The four elements"] = "네 가지 원소",
		["The {area:1417}"] = "{area:1417}",
		["The {area:1417} ({area:1477}) lies under the {area:74}; the arrow points at its entrance. Gasher or {npc:5716} drop the {item:20606}, Hukku or Mijan the Blue, Zolo or Loro the Green: all six are elite trolls inside. Bring a group."] = "{area:1417}({area:1477})은(는) {area:74} 아래에 있으며, 화살표가 입구를 가리킵니다. 게이셔 또는 {npc:5716}이(가) {item:20606}을(를), 후쿠 또는 마이잔이 파란색을, 졸로 또는 로로가 녹색을 떨어뜨립니다. 여섯 모두 내부의 정예 트롤입니다. 파티를 꾸리십시오.",
		["{item:7067}: Rumbling Exiles"] = "{item:7067}: 떠도는 바위 정령",
		["{item:7068}: Burning Exiles"] = "{item:7068}: 떠도는 불의 정령",
		["{item:7069}: Thundering Exiles"] = "{item:7069}: 떠도는 천둥 정령",
		["{item:7070}: Cresting Exiles"] = "{item:7070}: 떠도는 물의 정령",
		["{npc:6176} camps in the east of {zone:1416}, north-east of {area:272}."] = "{npc:6176}은(는) {area:272} 북동쪽, {zone:1416} 동부에 야영하고 있습니다.",
		["{quest:8412} and {quest:8413}"] = "{quest:8412} 및 {quest:8413}",
} end)()
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s, which {npc:6266} makes from the parts you bring her."] = "30레벨대를 위한 희귀 천 로브. 가져온 재료로 {npc:6266}이(가) 만들어 줍니다.",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "31레벨에 {object:172960}의 {npc:3326}이(가) {area:392}의 {npc:6266}에게 보냅니다.",
		["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "31레벨에 {object:36082}의 {npc:4563}이(가) {area:392}의 {npc:6266}에게 보냅니다. {zone:1420}에서 출발하는 비행선이 {zone:1411}(으)로 갑니다.",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "31레벨에 {object:2101} {object:2164}의 {npc:461}이(가) {area:392}의 {npc:6266}에게 보냅니다.",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "31레벨에 {zone:1455}의 {npc:5172}이(가) {area:392}의 {npc:6266}에게 보냅니다.",
		["Back to {npc:6266}"] = "{npc:6266}에게 돌아가기",
		["Back to {npc:6266} with the thread, the coal and a {item:6265}. Wait while she completes the robe, then speak to her again."] = "실, 석탄, {item:6265}을(를) 가지고 {npc:6266}에게 돌아가십시오. 로브를 완성할 때까지 기다린 뒤 다시 말을 거십시오.",
		["Bring {npc:6266} a {item:5770}: tailors sew it from a pattern that drops; otherwise buy one at the Auction House. Her next errand needs a {item:3577}: smelted from {item:2776}, or from the Auction House."] = "{npc:6266}에게 {item:5770}을(를) 가져가십시오: 재봉사는 몹이 떨어뜨리는 도안으로 만들 수 있고, 아니면 경매장에서 구매하십시오. 다음 심부름에는 {item:3577}이(가) 필요합니다: {item:2776}을(를) 제련하거나 경매장에서 구하십시오.",
		["The Burning Exiles, fire elementals in western {zone:1417}, drop the coal."] = "{zone:1417} 서부의 불의 정령인 떠도는 불의 정령이 석탄을 떨어뜨립니다.",
		["The Hatefury satyrs of {area:603}, in north-eastern {zone:1443}, carry the blood; the Lesser Infernals of Mannoroc Coven, in the south, the stone."] = "{zone:1443} 북동쪽 {area:603}의 서릿발분노 사티로스가 피를, 남쪽 만노로크 소굴의 하급 지옥불정령이 돌을 가지고 있습니다.",
		["Vials of Hatefury Blood"] = "서릿발분노의 사티로스 피",
		["Wait for the robe"] = "로브 완성 기다리기",
		["{npc:2670} in {area:35} has the thread for you."] = "{area:35}의 {npc:2670}이(가) 실을 가지고 있습니다.",
		["{npc:2670} sells tailoring supplies in {area:35}. Bring him the {item:3577}."] = "{npc:2670}은(는) {area:35}에서 재봉 용품을 팝니다. 그에게 {item:3577}을(를) 가져가십시오.",
		["{npc:6266} again"] = "다시 {npc:6266}에게",
		["{npc:6266} stands in the tower on the hill above {area:392}, beside {npc:6251}."] = "{npc:6266}은(는) {area:392} 위 언덕의 탑에서 {npc:6251} 옆에 서 있습니다.",
		["{zone:1443} demons"] = "{zone:1443}의 악마",
} end)()
