t.guides["forever/class/warlock/impsys-request"] = (function() return {
		["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "50대용 지팡이, 보조장비, 로브. {npc:14470}의 개인 심부름으로, 공포마 연계 퀘스트의 단계가 아닙니다.",
		["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448}."] = "50레벨에 {object:172960}의 {npc:3326}이(가) 당신을 {zone:1448}의 {npc:14470}에게 보냅니다.",
		["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448}."] = "50레벨에 {object:36082}의 {npc:4563}이(가) 당신을 {zone:1448}의 {npc:14470}에게 보냅니다.",
		["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448}."] = "50레벨에 {object:2101}에 있는 {object:2164}의 {npc:461}이(가) 당신을 {zone:1448}의 {npc:14470}에게 보냅니다.",
		["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448}."] = "50레벨에 {zone:1455}의 {npc:5172}이(가) 당신을 {zone:1448}의 {npc:14470}에게 보냅니다.",
		["The Irontree treants in northern {zone:1448} drop the {item:20613}; the Tainted Oozes around {area:1763} the {item:20614}."] = "{zone:1448} 북부의 강철나무정령이 {item:20613}을(를), {area:1763} 주변의 부패한 수액괴물이 {item:20614}을(를) 떨어뜨립니다.",
		["The six troll guardians of the {area:1417}, a level 50 dungeon, each drop a Voodoo Feather: bring a group of five. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance."] = "50레벨 던전인 {area:1417}의 트롤 수호자 여섯이 각각 부두 깃털을 떨어뜨립니다. 5인 파티를 데려가세요. 사원은 {area:74} 한가운데에 있으며, 물속으로 헤엄쳐 내려가면 입구가 나옵니다.",
		["The {area:1417}"] = "{area:1417}",
		["{item:20613} and Bloodvenom"] = "{item:20613}와(과) 피멍울",
		["{npc:14470} again"] = "다시 {npc:14470}",
		["{npc:14470} waits beside {npc:14469} in central {zone:1448}, just east of {area:1763}. This chain is {npc:14470}'s own and is not part of the Dreadsteed chain; Niby and {npc:14470} also give the {item:18762} chain here."] = "{npc:14470}은(는) {zone:1448} 중부, {area:1763} 바로 동쪽에서 {npc:14469} 옆에 있습니다. 이 연계 퀘스트는 {npc:14470}의 개인 퀘스트로 공포마 연계 퀘스트에 속하지 않습니다. 나이비와 {npc:14470}은(는) 이곳에서 {item:18762} 연계 퀘스트도 줍니다.",
		["{npc:14470} wants one {item:14256}: the Jadefire satyrs and the demons of {area:1763} drop it."] = "{npc:14470}은(는) {item:14256} 하나를 원합니다. 비취불꽃의 사티로스와 {area:1763}의 악마가 떨어뜨립니다.",
} end)()
t.guides["forever/class/warlock/incubus-alliance"] = (function() return {
		["A second seducer demon, the male sayaad, and a soul shard bag to carry your shards."] = "두 번째 유혹 악마인 남성 사야드, 그리고 영혼의 조각을 담을 영혼의 조각 가방.",
		["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}."] = "20레벨에 {object:2101} {object:2164} 지하실의 {npc:6122}이(가) {zone:1413}의 {npc:6244}에게 보냅니다.",
		["Back to {npc:6122} in the {object:2164}. Place the figurine at the summoning circle in the crypt below him and defeat the incubus it calls."] = "{object:2164}의 {npc:6122}에게 돌아가십시오. 그 아래 지하 묘지의 소환진에 조각상을 놓고, 불러낸 인큐버스를 처치하십시오.",
		["From {area:415} take the road west to {area:413}: the figurine lies in a house among the trees north of the post."] = "{area:415}에서 서쪽 길을 따라 {area:413}(으)로 가십시오: 조각상은 초소 북쪽 나무 사이 집 안에 있습니다.",
		["Incubus (Alliance)"] = "인큐버스 (얼라이언스)",
		["{npc:6122}: he binds the incubus to you"] = "{npc:6122}: 인큐버스를 당신에게 귀속시킵니다",
		["{npc:6244} camps in the southern {zone:1413}, east of the road north-east of {area:378}: come in from the east and keep clear of the Horde guards."] = "{npc:6244}은(는) {zone:1413} 남부, {area:378} 북동쪽 길의 동쪽에 야영하고 있습니다: 동쪽에서 접근하고 호드 경비병을 피하십시오.",
} end)()
t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["A second seducer demon, the male sayaad, and a soul shard bag to carry your shards."] = "두 번째 유혹 악마인 남성 사야드와, 영혼의 조각을 담을 영혼의 조각 가방입니다.",
		["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers offer the incubus, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one: this guide follows whichever {quest:1472} you took."] = "20레벨에 {object:172982} 아래 {object:172960}의 {npc:5875}이(가) 몇 걸음 떨어진 {npc:5909}에게 보냅니다. 인큐버스는 여기의 {npc:5875}과 {zone:1458}의 {npc:5675}, 두 상급자가 제공하며 하나만 수락할 수 있습니다. 이 가이드는 수락한 {quest:1472}을(를) 따라갑니다.",
		["Back to {npc:5675} in the {object:36082}. Place the hearts at the summoning circle below him and defeat the incubus they call."] = "{object:36082}의 {npc:5675}에게 돌아가십시오. 그 아래 소환진에 심장을 놓고 소환된 인큐버스를 쓰러뜨리십시오.",
		["Back to {npc:5875} in the {object:172960}. Take the scarf to the summoning circle in {npc:3216}'s tent nearby and defeat the incubus it calls."] = "{object:172960}의 {npc:5875}에게 돌아가십시오. 근처 {npc:3216}의 천막 안 소환진으로 스카프를 가져가 소환된 인큐버스를 쓰러뜨리십시오.",
		["Incubus (Horde)"] = "인큐버스 (호드)",
		["{area:422} lies in southern {zone:1440}, south of {area:431}. The Shadethicket bog beasts around the lake drop the {item:190232}, about one in twenty."] = "{area:422}은(는) {zone:1440} 남부, {area:431} 남쪽에 있습니다. 호수 주변의 그늘덤불 늪괴물이 약 스무 번에 한 번 {item:190232}을(를) 떨어뜨립니다.",
		["{npc:185333} works as a tailor for the {area:279} wizards at {area:233}, in eastern {zone:1421}. Take her heart."] = "{npc:185333}은(는) {zone:1421} 동부 {area:233}에서 {area:279} 마법사들의 재봉사로 일합니다. 그녀의 심장을 가져가십시오.",
		["{npc:185334} works in {area:392}, on the {zone:1413} coast. Take the zeppelin to {zone:1411} and ride or fly on to {area:392}."] = "{npc:185334}은(는) {zone:1413} 해안의 {area:392}에서 일합니다. 비행선을 타고 {zone:1411}(으)로 간 뒤 {area:392}까지 이동하거나 비행하십시오.",
		["{npc:3363} keeps {object:173018}, east of the {object:172960} along the main street. He asks you to look for his mate, Krilge."] = "{npc:3363}은(는) {object:172960} 동쪽 큰길가의 {object:173018}을(를) 운영합니다. 짝인 Krilge를 찾아 달라고 합니다.",
		["{npc:5675}: he binds the incubus to you"] = "{npc:5675}: 인큐버스를 속박해 줍니다",
		["{npc:5875}: he binds the incubus to you"] = "{npc:5875}: 인큐버스를 속박해 줍니다",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} in the Temple of the Damned, just north of him."] = "{npc:5875} 대신 {npc:5675}의 {quest:1472}을(를) 수락한 흑마법사를 위한 {object:1661} 버전입니다. 20레벨에 {object:36082}의 {npc:5675}이 그 바로 북쪽에 있는 {npc:5693}에게 보냅니다.",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "30대 후반에 얻는 보조장비 보주 또는 지팡이입니다. 지옥사냥개 경로와 지옥불정령 경로 중 원하는 쪽을 고르십시오.",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "35레벨에 {object:172960}의 {npc:3326}이(가) {area:392}의 {npc:6266}에게 보냅니다.",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "35레벨에 {object:36082}의 {npc:4563}이(가) {area:392}의 {npc:6266}에게 보냅니다. {zone:1420}에서 출발하는 비행선은 {zone:1411}(으)로 갑니다.",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "35레벨에 {object:2101} {object:2164}의 {npc:461}이(가) {area:392}의 {npc:6266}에게 보냅니다.",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "35레벨에 {zone:1455}의 {npc:5172}이(가) {area:392}의 {npc:6266}에게 보냅니다.",
		["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, wait while she completes the {item:15108}, then speak to her again."] = "정화된 보주를 가지고 {area:392} 위 탑의 {npc:6266}에게 돌아가십시오. 지옥사냥개 경로라면 그녀가 {item:15108}을(를) 완성할 때까지 기다린 뒤 다시 대화하십시오.",
		["Back to {npc:6266} in the tower above {area:392} with the spirit first: {npc:6546}'s cleansing follows it."] = "먼저 영혼을 가지고 {area:392} 위 탑의 {npc:6266}에게 돌아가십시오. 그다음 {npc:6546}의 정화가 이어집니다.",
		["Choose an acolyte"] = "수행사제 고르기",
		["On the infernal path, wait while {npc:6266} completes the {item:15107}, then speak to her again."] = "지옥불정령 경로라면 {npc:6266}이(가) {item:15107}을(를) 완성할 때까지 기다린 뒤 다시 대화하십시오.",
		["Orb of Orahil"] = "오라힐의 보주",
		["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, {npc:6252}'s infernal path with the Orb or {item:15105}. The guide follows the one you take."] = "수행사제 하나를 고르십시오. 퀘스트는 한 명의 것만 수락할 수 있습니다. {npc:6254}의 지옥사냥개 경로는 보주 또는 {item:15106}(으)로, {npc:6252}의 지옥불정령 경로는 보주 또는 {item:15105}(으)로 끝납니다. 가이드는 수락한 쪽을 따라갑니다.",
		["The demon's spirit"] = "악마의 영혼",
		["The demons of {area:602}, in southern {zone:1443}, have all you need. Burning Blade Summoners carry the {item:7291}. On the felhound path, use the {item:12647} on a {npc:4678}, a felhound, and kill it for its spirit; on the infernal path, use the {item:12646} on a {npc:4676} and kill it."] = "{zone:1443} 남부 {area:602}의 악마들에게서 필요한 것을 모두 얻을 수 있습니다. 불타는칼날단 소환사가 {item:7291}을(를) 가지고 있습니다. 지옥사냥개 경로라면 지옥사냥개인 {npc:4678}에게 {item:12647}을(를) 사용하고 처치해 영혼을 얻으십시오. 지옥불정령 경로라면 {npc:4676}에게 {item:12646}을(를) 사용하고 처치하십시오.",
		["The {item:15107}"] = "{item:15107}",
		["The {item:15108}"] = "{item:15108}",
		["Wait for the orb"] = "보주 기다리기",
		["{item:12648}, from a {npc:4678}"] = "{item:12648}, {npc:4678}에게서",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}, {npc:4676}에게서",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}, 불타는칼날단 소환사에게서",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252}: {item:12646}을(를) 줍니다",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254}: {item:12647}을(를) 줍니다",
		["{npc:6266} and her two acolytes stand in the tower on the hill above {area:392}, beside {npc:6251}."] = "{npc:6266}와(과) 두 수행사제는 {area:392} 위 언덕의 탑 안, {npc:6251} 옆에 있습니다.",
		["{npc:6546} lives at her farm in western {zone:1445}. She calls the {npc:6549} out of the {item:7291}; it is elite: grouping up is advised."] = "{npc:6546}은(는) {zone:1445} 서부의 농장에 삽니다. 그녀가 {item:7291}에서 {npc:6549}을(를) 불러냅니다. 정예이므로 파티를 권장합니다.",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
		["A rare off-hand orb or staff for your late 20s, for fragments from two dungeons."] = "20레벨대 후반을 위한 희귀 보조장비 보주 또는 지팡이. 두 던전에서 얻는 조각과 교환합니다.",
		["Back to {npc:6247}"] = "{npc:6247}에게 돌아가기",
		["The Shadowfang Darksouls inside {area:236}, a level 20-30 dungeon, drop the Large Fragment about one time in five: bring a group. The keep stands south of the {area:228}."] = "레벨 20-30 던전인 {area:236} 안의 그림자송곳니일족 검은영혼이 약 5분의 1 확률로 큰 소랜루크 조각을 떨어뜨립니다: 파티를 꾸리십시오. 성채는 {area:228} 남쪽에 있습니다.",
		["The Twilight Acolytes inside {area:2797}, a level 24-32 dungeon, each drop a {item:6914}: bring a group. The entrance is in the ruins on the north-west coast of {zone:1440}."] = "레벨 24-32 던전인 {area:2797} 안의 황혼의망치단 수행사제가 각각 {item:6914}을(를) 떨어뜨립니다: 파티를 꾸리십시오. 입구는 {zone:1440} 북서쪽 해안의 폐허에 있습니다.",
		["{item:6914}, from the Twilight Acolytes"] = "황혼의망치단 수행사제에게서 얻는 {item:6914}",
		["{item:6915}, from the Shadowfang Darksouls"] = "그림자송곳니일족 검은영혼에게서 얻는 {item:6915}",
		["{npc:6247} camps in the southern {zone:1413}, east of the road north-east of {area:378}."] = "{npc:6247}은(는) {zone:1413} 남부, {area:378} 북동쪽 길의 동쪽에 야영하고 있습니다.",
} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "{zone:1448}의 {npc:14469}와(과) {npc:14470}이(가) 주는 50레벨대 희귀 보조장비입니다. 임프의 부탁도 주는 곳입니다.",
		["At 50 {npc:14469} and his imp {npc:14470} wait in central {zone:1448}, just east of {area:1763}."] = "50레벨에 {npc:14469}과(와) 그의 임프 {npc:14470}이(가) {zone:1448} 중앙, {area:1763} 바로 동쪽에서 기다립니다.",
		["Back to {npc:14469}"] = "{npc:14469}에게 돌아가기",
		["The Felguard Sentries around the {area:72}, in southern {zone:1419}, carry its essence."] = "{zone:1419} 남쪽 {area:72} 주변의 지옥군단병 보초가 그 정수를 가지고 있습니다.",
		["The Jaedenar Legionnaires, a short way west of {npc:14469}, carry {area:1763}'s essence."] = "{npc:14469}의 서쪽 조금 떨어진 곳의 {npc:9862}이(가) {area:1763}의 정수를 가지고 있습니다.",
		["The Legashi satyrs of northern {zone:1447} carry {zone:1447}'s essence."] = "{zone:1447} 북쪽의 레가쉬 사티로스가 {zone:1447}의 정수를 가지고 있습니다.",
		["{item:18626}, at {object:179677}"] = "{item:18626}, {object:179677}에서",
		["{npc:14467}' remains lie in {area:1766}, north of {npc:14469}. Use the {item:18626} beside them and kill the infernal when he wakes. {npc:14467} is elite: grouping up is advised."] = "{npc:14467}의 유해는 {npc:14469} 북쪽 {area:1766}에 있습니다. 그 옆에서 {item:18626}을(를) 사용하고 깨어나는 지옥불정령을 처치하십시오. {npc:14467}은(는) 정예입니다. 파티를 권장합니다.",
} end)()
t.guides["forever/class/warlock/tome-of-sacrifice"] = (function() return {
		["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "60레벨 희귀 보조장비. {zone:1419}에서 {npc:12396}을(를) 포획한 대가로 {npc:14463}이(가) 줍니다.",
		["At 60 {npc:14463} waits in the {area:73}, in western {zone:1419}."] = "60레벨에 {npc:14463}은(는) {zone:1419} 서부의 {area:73}에서 기다립니다.",
		["Back to {npc:14463}"] = "{npc:14463}에게 돌아가기",
		["Hand both in to {npc:14463}, then find the {npc:12396} in the {area:73} and use the {item:18601} on him. He is elite and fights to escape: grouping up is advised."] = "둘 다 {npc:14463}에게 제출한 뒤, {area:73}에서 {npc:12396}을(를) 찾아 {item:18601}을(를) 사용하세요. 정예이며 도망치려고 싸웁니다. 파티를 권장합니다.",
		["The Hederine demons hold {area:2256}, in southern {zone:1452}. They are elite: grouping up is advised."] = "헤더린 악마들이 {zone:1452} 남부의 {area:2256}을(를) 차지하고 있습니다. 정예이니 파티를 권장합니다.",
		["The Wildspawn satyrs of the Warpwood Quarter, {area:2577}'s eastern wing, carry the blood. The back door at {area:2518}, north of {area:1099}, needs the {item:18249}; otherwise go in by {area:2577}'s main entrance. Bring a group."] = "{area:2577} 동쪽 구역인 굽이나무 지구의 야생혈족 사티로스가 피를 지니고 있습니다. {area:1099} 북쪽 {area:2518}의 뒷문에는 {item:18249}이(가) 필요하며, 없으면 {area:2577}의 정문으로 들어가세요. 파티를 데려가세요.",
		["{item:18601}, on the {npc:12396}"] = "{item:18601}, {npc:12396}에게",
		["{item:18603}, inside the Warpwood Quarter"] = "{item:18603}, 굽이나무 지구 안",
} end)()
t.guides["forever/class/warrior/brutal-armor"] = (function() return {
		["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "20레벨에 {zone:1456}의 전사 상급자 {npc:3041}이(가) 당신을 {area:378}의 {npc:6394}에게 보냅니다.",
		["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "20레벨에 {object:172958}의 {npc:3354}이(가) 당신을 {area:378}의 {npc:6394}에게 보냅니다.",
		["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "20레벨에 {zone:1458}의 전사 상급자 {npc:4595}이(가) 당신을 {area:378}의 {npc:6394}에게 보냅니다.",
		["Back to {npc:5878} beside the road east of the {area:380}. {quest:1848} is the first piece; he then sends you to three crafters for the rest."] = "{area:380} 동쪽 길가의 {npc:5878}에게 돌아가세요. {quest:1848}이(가) 첫 번째 부위이며, 그 후 나머지를 위해 장인 세 명에게 보냅니다.",
		["Fly to {area:378}. South of the camp the Silithid Mounds dot the {area:390}: the silithid there carry the Twitching Antennae."] = "{area:378}(으)로 날아가세요. 야영지 남쪽 {area:390}에 실리시드 흙더미가 흩어져 있으며, 그곳의 실리시드가 꿈틀거리는 더듬이를 지니고 있습니다.",
		["Four armor pieces at 30 (hauberk, helm, gauntlets, legguards) and a shield on the way."] = "30레벨에 방어구 네 부위(사슬 갑옷, 투구, 건틀릿, 다리보호구), 도중에 방패도 얻습니다.",
		["Hillsbrad Miners"] = "{npc:2269}",
		["Iron Bars"] = "철 주괴",
		["Iron Bars: {npc:8673}"] = "철 주괴: {npc:8673}",
		["Miners smelt Iron Bars from {item:2772} ({skill:186} 125); everyone else buys them at the auction house in {zone:1454}."] = "채광사는 {item:2772}을(를) 제련해 철 주괴를 만들고({skill:186} 125), 그 외에는 {zone:1454} 경매장에서 사세요.",
		["Roogug in {area:1717}"] = "{area:1717}의 루구그",
		["Roogug is an elite quilboar inside {area:1717}, the dungeon at the south end of the {zone:1413}; he drops the {item:6841}. {area:1717} is a dungeon: grouping up is advised."] = "루구그는 {zone:1413} 남쪽 끝의 던전인 {area:1717} 안의 정예 가시멧돼지족이며 {item:6841}을(를) 떨어뜨립니다. {area:1717}은(는) 던전이니 파티를 권장합니다.",
		["Smoky Iron Ingots from the Windshear kobolds"] = "칼바람 코볼트에게서 연기나는 철제 주괴",
		["Sturdy Dragonmaw Shinbones"] = "{item:7134}",
		["Take the zeppelin from {zone:1454} to {zone:1420}; the {zone:1458} lies below the {area:153}."] = "{zone:1454}에서 비행선을 타고 {zone:1420}(으)로 가세요. {zone:1458}은(는) {area:153} 아래에 있습니다.",
		["The Dragonmaw orcs camp in the middle of the {zone:1437}, south of the road; Raiders, Swamprunners, Centurions, Shadowwarders and Bonewarders all drop the Sturdy Dragonmaw Shinbones."] = "용아귀부족 오크는 {zone:1437} 한가운데, 길 남쪽에 진을 치고 있습니다. 약탈자, 늪길잡이, 백인대장, 어둠보초병, 해골감시자 모두 {item:7134}을(를) 떨어뜨립니다.",
		["The Hillsbrad Miners work the mine in the west of {zone:1424}; they drop the {item:7127}. Take the zeppelin from {zone:1454} to {zone:1420} and ride south through {zone:1421}."] = "{npc:2269}은(는) {zone:1424} 서쪽의 광산에서 일하며 {item:7127}을(를) 떨어뜨립니다. {zone:1454}에서 비행선을 타고 {zone:1420}(으)로 간 뒤 {zone:1421}을(를) 지나 남쪽으로 가세요.",
		["The {area:2160} lies at the east end of {area:461} in Stonetalon. Its kobolds drop the Smoky Iron Ingots."] = "{area:2160}은(는) 돌발톱 산맥 {area:461}의 동쪽 끝에 있습니다. 그곳 코볼트가 연기나는 철제 주괴를 떨어뜨립니다.",
		["The {area:429} satyrs camp in eastern {zone:1440}, with the Felmusk satyrs further west; both drop Uncloven Satyr Hooves."] = "{area:429} 사티로스는 {zone:1440} 동부에 진을 치고 있고, 검은유혹의 사티로스는 더 서쪽에 있습니다. 둘 다 사티로스 통발굽을 떨어뜨립니다.",
		["The {npc:6167} roams the south-west of Stonetalon near the Fledgling and Young Chimaeras; she drops the {item:6840}."] = "{npc:6167}은(는) 돌발톱 산맥 남서쪽에서 어린 키메라, 새끼 키메라 근처를 돌아다니며 {item:6840}을(를) 떨어뜨립니다.",
		["Twitching Antennae from the silithid"] = "실리시드에게서 꿈틀거리는 더듬이",
		["Uncloven {quest:1842}"] = "통발굽 {quest:1842}",
		["{item:6840} from the {npc:6167}"] = "{npc:6167}에게서 {item:6840}",
		["{item:6841}, from Roogug"] = "{item:6841}, 루구그에게서",
		["{item:7127} from the Hillsbrad Miners"] = "{item:7127}, {npc:2269}에게서",
		["{npc:5878} camps beside the road east of the {area:380}. {quest:1838} is a level 30 quest; you can take it now and gather for it on the way."] = "{npc:5878}은(는) {area:380} 동쪽 길가에 진을 치고 있습니다. {quest:1838}은(는) 30레벨 퀘스트이지만 지금 받아서 가는 길에 재료를 모을 수 있습니다.",
		["{npc:6408} is in {area:367} on the {zone:1411} coast."] = "{npc:6408}은(는) {zone:1411} 해안의 {area:367}에 있습니다.",
} end)()
t.guides["forever/class/warrior/fire-hardened-armor"] = (function() return {
		["A hauberk at 28, a coif, leggings or gauntlets by race, and a shield on the way."] = "28레벨에 사슬 갑옷, 종족에 따라 사슬 두건, 다리보호구 또는 건틀릿, 그리고 도중에 방패.",
		["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "20레벨에 {zone:1455}의 전사 상급자 {npc:5113}이(가) 붉은마루 산맥의 {quest:1698}에게 보냅니다.",
