t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Back down the beach, past the pirate camp: the crate of boots and the fragile crate with the lens sit at its south end."] = "해적 야영지를 지나 해변을 따라 다시 내려가세요. 장화 상자와 렌즈가 든 깨지기 쉬운 상자는 해변 남쪽 끝에 있습니다.",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "서슬갈기일족 야영지로 돌아가세요. 동쪽 절반은 흙점쟁이와 파수병이 차지하고 있으며, {npc:3438}은(는) 그들 사이를 돌아다닙니다.",
		["Back west along the road."] = "길을 따라 서쪽으로 돌아가세요.",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}; they drop the {item:6652}. The {item:5026} comes from the Razormane on your next visit to their camp."] = "불타는칼날단 이교도는 {zone:1411} 북부의 {area:1898}을(를) 차지하고 있으며, {item:6652}을(를) 떨어뜨립니다. {item:5026}은(는) 다음에 서슬갈기일족 야영지에 갈 때 그들에게서 얻습니다.",
		["East to the {area:1703}; {npc:9316} stands at the camp just south of it."] = "동쪽의 {area:1703}(으)로 가세요. {npc:9316}은(는) 그 바로 남쪽 야영지에 있습니다.",
		["East to {area:392}, on the coast."] = "동쪽 해안의 {area:392}(으)로 가세요.",
		["Follow the road east to the outpost above the {area:814}."] = "길을 따라 동쪽으로 가서 {area:814} 위의 전초기지로 가세요.",
		["Follow the road south-east to {area:392} on the coast."] = "길을 따라 남동쪽으로 해안의 {area:392}까지 가세요.",
		["Keep it: {quest:3923} stands outside {zone:1454}; a later guide hands it in"] = "보관하세요: {quest:3923}은(는) {zone:1454} 밖에 있으며, 나중 가이드에서 완료합니다",
		["Kolkar Wranglers and Stormers hold the camps south of {npc:3389}."] = "콜카르일족 사냥꾼과 번개술사는 {npc:3389} 남쪽 야영지를 차지하고 있습니다.",
		["Kolkar camps"] = "콜카르일족 야영지",
		["Oasis Snapjaws crawl around {area:387}, south-west of the {area:380}, and around the {area:388}."] = "오아시스 무쇠턱거북은 {area:380} 남서쪽의 {area:387}와(과) {area:388} 주변을 기어다닙니다.",
		["Plainstriders and Sunscale raptors roam the plains all around the {area:380}, thickest to the north."] = "초원타조와 열대초원랩터가 {area:380} 주변 평원 곳곳을 돌아다니며, 북쪽에 가장 많습니다.",
		["Plainstriders and raptors"] = "초원타조와 랩터",
		["Raptor nests"] = "랩터 둥지",
		["Razormane camp"] = "서슬갈기일족 야영지",
		["South to {npc:3389}'s watch post on the Kolkar border."] = "남쪽으로 콜카르일족 경계의 {npc:3389} 감시 초소로 가세요.",
		["South-east of the {area:380}. Test the seeds at the bubbling fissure on the oasis' east bank."] = "{area:380} 남동쪽입니다. 오아시스 동쪽 기슭의 부글거리는 균열에서 씨앗을 시험하세요.",
		["Southsea beach"] = "남쪽바다해적단 해변",
		["The Savannah Prowlers hunt the plains between town and the Razormane camp to the east. In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end."] = "굶주린 사바나 사자는 마을과 동쪽의 서슬갈기일족 야영지 사이 평원에서 사냥합니다. 야영지 서쪽 절반은 풍수사와 가시마술사가, 가운데는 사냥꾼이 차지하고 있으며, 보급품 상자는 동쪽 끝에 있습니다.",
		["The Witchwing Slayers hold the western {area:383}; they wear the rings."] = "칼날바람일족 암살자는 {area:383} 서부를 차지하고 있으며, 반지를 끼고 있습니다.",
		["The pirates camp on the beach south of {area:392}. The piles of complicated parts lie in the sand among them."] = "해적들은 {area:392} 남쪽 해변에 야영하고 있습니다. 복잡한 부품 더미는 그들 사이의 모래밭에 있습니다.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers."] = "웅덩이는 {npc:3389} 바로 북쪽에 있습니다. 물에 들어가 탐험하세요. 헬브림에게 줄 숙성한 버섯은 그 주변에 자랍니다. 지나가며 만나는 콜카르일족은 모두 처치해 손목보호대를 얻으세요.",
		["The three nests sit together in the {area:1697} south-west of the oasis; Sunscale Scytheclaws guard them."] = "둥지 세 개는 오아시스 남서쪽 {area:1697}에 모여 있으며, 갈퀴발톱 열대초원랩터가 지키고 있습니다.",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}, east of {npc:9316}."] = "민달팽이가 든 공구 양동이는 {npc:9316} 동쪽, {area:382}의 투자개발회사 시추 현장 주변에 있습니다.",
		["The {object:4141} stands at the Venture Co. research site west of the {area:382}. Close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471} beside it."] = "{object:4141}은(는) {area:382} 서쪽의 투자개발회사 연구 현장에 있습니다. 시추기 주변의 밸브 세 개를 잠그고 제어판을 다시 사용한 뒤, 그 옆의 {npc:3471}에게서 {item:5089}을(를) 얻으세요.",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}."] = "천둥도마뱀과 번개도마뱀은 {area:379} 아래 다리 바로 건너편에서 풀을 뜯습니다.",
		["Thunder lizards across the river"] = "강 건너편의 천둥도마뱀",
		["Walk back south to the {area:380}. The next guide starts here and takes you to {zone:1454} and the zeppelin to {zone:1420}."] = "남쪽의 {area:380}로 걸어서 돌아가세요. 다음 가이드는 여기서 시작해 {zone:1454}와(과) {zone:1420}행 비행선으로 안내합니다.",
		["Walk back west along the road to the {area:380}."] = "길을 따라 서쪽의 {area:380}로 돌아가세요.",
		["West to the {area:383}. The Witchwing harpies nest all over them; any of them can drop a talon. {quest:819} lies in their hills."] = "서쪽의 {area:383}(으)로 가세요. 칼날바람하피가 곳곳에 둥지를 틀고 있으며, 누구나 발톱을 떨어뜨릴 수 있습니다. {quest:819}은(는) 그 언덕에 있습니다.",
		["Zhevra"] = "얼룩말",
		["Zhevra Runners graze north and east of town."] = "굶주린 얼룩말은 마을 북쪽과 동쪽에서 풀을 뜯습니다.",
		["{area:1898} cultists"] = "{area:1898}의 이교도",
		["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn."] = "이 가이드에서는 {area:380}이(가) 거점입니다. 필요한 사람은 모두 여관에서 몇 걸음 거리에 있습니다.",
		["{npc:3442} in {area:392}: later, on the way"] = "{area:392}의 {npc:3442}: 나중에 가는 길에",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: 제어판은 나중에 {area:382}에서 처리합니다",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}: 하피는 나중에 {area:383}에서 처리합니다",
		["{npc:3615}, the wind rider master"] = "윈드라이더 조련사 {npc:3615}",
		["{npc:5878} camps beside the road from the {area:380} to {area:392}. The {object:58369} sits in the south of the Razormane camp just north of him."] = "{npc:5878}은(는) {area:380}에서 {area:392}(으)로 가는 길가에 야영하고 있습니다. {object:58369}은(는) 그 바로 북쪽, 서슬갈기일족 야영지 남쪽에 있습니다.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900}이(가) 타르와 주머니로 {item:6636}을(를) 만들어 줍니다. 그 옆의 화로 곁에서 사용해 {npc:5893}을(를) 드러내고, 처치해 {item:6655}을(를) 얻은 뒤 잉걸불을 화로에 넣으세요.",
		["{npc:5900} waits on the riverbank south of {area:379}, across the bridge."] = "{npc:5900}은(는) 다리 건너 {area:379} 남쪽 강기슭에서 기다립니다.",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907}은(는) 서슬갈기일족 야영지 북쪽 능선에 서 있습니다.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, {item:5176}, {item:263412}",
		["{quest:1492}, on the dock"] = "부두의 {quest:1492}",
		["{quest:3301}: the {area:228} in {zone:1421}, next guide"] = "{quest:3301}: 다음 가이드에서 {zone:1421}의 {area:228}",
		["{quest:881}, a white lion, prowls the plains north of the Razormane camp."] = "흰 사자 {quest:881}은(는) 서슬갈기일족 야영지 북쪽 평원을 돌아다닙니다.",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Cast {spell:18960}; {npc:11802} is in {area:2361}. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있습니다. 제단 구슬은 {area:656} 바닥에 있으며 몇 분 안에 사라집니다. 하나를 들고 곧장 북서쪽 기슭의 {area:2362}까지 헤엄쳐 가서 사용하고 {npc:11799}에게 말을 거세요.",
		["Fly to {area:1638}: {npc:3033} trains you on {area:1639}. Skyborne: fly back to {zone:1454} for the zeppelin afterwards."] = "{area:1638}(으)로 날아가세요. {npc:3033}이(가) {area:1639}에서 훈련시켜 줍니다. 스카이본: 그 후 비행선을 타러 {zone:1454}(으)로 날아 돌아가세요.",
		["Follow the lake shore south-east and swim out to {area:172}. Rot Hide gnolls cover the island; every type drops ichor. Stay out of {area:235} on its north side unless you go for the optional niche: the gnolls there are level 18-22."] = "호숫가를 따라 남동쪽으로 가서 {area:172}까지 헤엄쳐 가세요. 썩은가죽 놀이 섬을 뒤덮고 있으며, 모든 종류가 체액을 떨어뜨립니다. 선택 사항인 벽감에 가는 게 아니라면 섬 북쪽의 {area:235}에는 들어가지 마세요. 그곳의 놀은 18-22레벨입니다.",
		["Follow the road north out of Silverpine into {zone:1420} and east to the zeppelin towers outside the {area:153}. Take the zeppelin to {zone:1454}."] = "길을 따라 북쪽으로 은빛소나무 숲을 나가 {zone:1420}에 들어간 뒤, 동쪽으로 {area:153} 밖의 비행선 탑까지 가세요. {zone:1454}행 비행선을 타세요.",
		["Follow the road north out of Silverpine into {zone:1420} and on to {area:159}: {npc:246152} trains Paladins there. The zeppelin towers are a short walk south down the road."] = "길을 따라 북쪽으로 은빛소나무 숲을 나가 {zone:1420}에 들어간 뒤 {area:159}까지 가세요. 그곳에서 {npc:246152}이(가) 성기사를 훈련시킵니다. 비행선 탑은 길을 따라 남쪽으로 조금 걸어가면 있습니다.",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "길을 따라 북동쪽으로 {area:238}의 요릭 가족 집까지 가세요.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "길을 따라 남쪽으로 가세요. {object:1627}은(는) 장작나무 마을 북쪽 길가에 있습니다.",
		["From the {area:380}, follow the road north-east to {area:1637} and walk in by the main gate. {npc:3310}, the wind rider master, stands on the tower in the {object:172982}."] = "{area:380}에서 길을 따라 북동쪽으로 {area:1637}까지 가서 정문으로 들어가세요. 와이번 조련사 {npc:3310}은(는) {object:172982}의 탑 위에 서 있습니다.",
		["Hearth to the {area:228}"] = "{area:228}(으)로 귀환",
		["Into Silverpine"] = "은빛소나무 숲으로",
		["Keep it: Thork at the {area:380}"] = "보관하세요: {area:380}의 톨크",
		["Keep it: {npc:2216} in {area:272}, a later guide"] = "보관하세요: {area:272}의 {npc:2216}, 이후 가이드",
		["Moonrage Bloodhowlers"] = "달의분노일족 혈투사",
		["Mottled Worgs prowl the hills around the house. Then walk south along the lake shore: the Vile Fin Shredders and Tidehunters there drop the murloc eyes."] = "점박이 검은늑대가 집 주변 언덕을 배회합니다. 그런 다음 호숫가를 따라 남쪽으로 가세요. 그곳의 썩은지느러미멀록 갈퀴잡이와 바다사냥꾼이 멀록 눈알을 떨어뜨립니다.",
		["North again to the Yoricks' house. {quest:425} lurks a short walk west of it."] = "다시 북쪽으로 요릭 가족 집에 가세요. {quest:425}은(는) 그 서쪽으로 조금 걸어간 곳에 숨어 있습니다.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "{area:228} 북쪽입니다. {npc:1983}이(가) {area:240}에 출몰합니다. 처치한 뒤 들판을 가로지르세요.",
		["North-east of the refugees, the Ravenclaw Drudgers and Guardians haunt the ruins of {quest:516} in the south-east of the forest."] = "피난민 북동쪽, 숲 남동쪽에 있는 {quest:516} 폐허에 까마귀발톱 노역꾼과 수호병이 출몰합니다.",
		["Only if {npc:1938} gave you {quest:98298}: the Bloodhowlers prowl the woods south-west of {area:233}, east of Pyrewood; they drop the {item:280375}."] = "{npc:1938}이(가) {quest:98298}을(를) 준 경우에만: 혈투사는 {area:233} 남서쪽, 장작나무 마을 동쪽 숲을 배회하며 {item:280375}을(를) 떨어뜨립니다.",
		["Road to Silverpine"] = "은빛소나무 숲으로 가는 길",
		["South-east down the road to {area:233}. Protectors guard the outskirts and Mages the town; both drop pendants. Wizards and Watchers patrol the roads around it. Stay out of the middle, where {npc:2120} stands."] = "길을 따라 남동쪽으로 {area:233}까지 내려가세요. 수호병이 외곽을, 마법사가 마을을 지키며 둘 다 펜던트를 떨어뜨립니다. 마술사와 파수꾼은 주변 길을 순찰합니다. {npc:2120}이(가) 서 있는 한가운데에는 들어가지 마세요.",
		["Speak with {npc:10540}, in Grommash Hold"] = "{npc:10540}에게 말을 거세요, 그롬마쉬 요새 안",
		["Speak with {npc:3230}, in Grommash Hold"] = "{npc:3230}에게 말을 거세요, 그롬마쉬 요새 안",
		["Swim back and follow the road west to the {area:228}."] = "헤엄쳐 돌아와 길을 따라 서쪽으로 {area:228}까지 가세요.",
		["The Sickly and Haggard Refugees shamble along the road south of Pyrewood toward the {area:230}."] = "병든 피난민과 초췌한 피난민이 장작나무 마을 남쪽 길을 따라 {area:230} 쪽으로 비틀거리며 걸어갑니다.",
		["The Vile Fin Lakestalkers and Oracles sit on the lake shore south of the {area:237}, east of the {area:228}."] = "썩은지느러미멀록 술사와 점쟁이가 {area:228} 동쪽, {area:237} 남쪽 호숫가에 있습니다.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "부들과 창풀은 골목길 동쪽, {object:172958}의 물가를 따라 자랍니다.",
		["The refugees"] = "피난민",
		["The zeppelin lands at the towers outside the {area:153}. Walk west along the road past the ruins and south into {zone:1421}; follow the road to the {area:228}."] = "비행선은 {area:153} 밖의 탑에 내립니다. 길을 따라 서쪽으로 폐허를 지나 남쪽으로 {zone:1421}에 들어간 뒤, 길을 따라 {area:228}까지 가세요.",
		["The zeppelin towers stand just outside {zone:1454}'s main gate. Take the zeppelin to {zone:1420} (the other one goes to {object:3202})."] = "비행선 탑은 {zone:1454} 정문 바로 밖에 있습니다. {zone:1420}행 비행선을 타세요(다른 하나는 {object:3202}(으)로 갑니다).",
		["The {object:1593} lies at the ferry landing on the lake shore east of the {area:228}."] = "{object:1593}은(는) {area:228} 동쪽 호숫가의 나루터에 있습니다.",
		["The {object:172960} is the canyon under the {object:172982}; {npc:3216} stands at its far end."] = "{object:172960}은(는) {object:172982} 아래의 협곡입니다. {npc:3216}은(는) 그 맨 끝에 서 있습니다.",
		["The {object:177790} lies on the coast west of the {area:240}. It holds the {item:15882} for {quest:30}."] = "{object:177790}은(는) {area:240} 서쪽 해안에 있습니다. 그 안에 {quest:30}을(를) 위한 {item:15882}이(가) 들어 있습니다.",
		["To {area:1637}"] = "{area:1637}(으)로",
		["Walk in through the main gate. {npc:268701} stands in the {object:172982}; {object:173016} is a few steps north."] = "정문으로 들어가세요. {npc:268701}은(는) {object:172982}에 서 있고, {object:173016}은(는) 몇 걸음 북쪽에 있습니다.",
		["Worgs and murlocs"] = "늑대와 멀록",
		["Zeppelin to {zone:1420}"] = "{zone:1420}행 비행선",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["Zeppelin tower"] = "비행선 탑",
		["grind on {npc:1909} at {area:1338}, {zone:1421}"] = "{zone:1421}의 {area:1338}에서 {npc:1909}을(를) 사냥하세요",
		["{area:1338} shore"] = "{area:1338} 기슭",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228}은(는) 숲 한가운데에 있는 포세이큰의 지하묘지 마을입니다. 필요한 사람은 모두 지하묘지 입구 주변에 서 있습니다. 박쥐 조련사 {npc:2226}은(는) 그 바로 동쪽에 있습니다.",
		["{area:233} comes later, on the southern loop"] = "{area:233}은(는) 나중에, 남쪽 순환로에서",
		["{item:3317}: a rare drop from the gnolls"] = "{item:3317}: 놀에게서 드물게 떨어짐",
		["{npc:11798} in {area:2361} flies druids there; then fly on to {zone:1454} for the zeppelin"] = "{area:2361}의 {npc:11798}이(가) 드루이드를 그곳으로 태워 줍니다. 그 후 비행선을 타러 {zone:1454}(으)로 날아가세요",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, {area:2362}에서",
		["{npc:1938}: take it if he offers it; it may follow his {quest:98298} series, which the route does not run"] = "{npc:1938}: 제안하면 받으세요. 경로에서 진행하지 않는 그의 {quest:98298} 연계 퀘스트 다음에 나올 수 있습니다",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978}은(는) 집 북동쪽에서 기다립니다. 그를 {npc:1950}에게 호위하세요. 가는 길에 늑대가 공격합니다.",
		["{npc:2121}: {quest:516}, on the south loop"] = "{npc:2121}: {quest:516}, 남쪽 순환로에서",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152}은(는) 비행선 탑에서 길을 따라 북쪽으로 조금 걸어가면 나오는 {area:159}에서 성기사를 훈련시킵니다. 은빛소나무 숲으로 가려면 같은 길로 다시 내려오세요.",
		["{npc:268684} and {npc:268682} sit behind Grommash Hold in the {object:172957}; the Smooth Boulders lie around them. Train while you are in the city (Druids and Paladins have no trainer here). The next guide starts at {npc:3310}, the wind rider master in the {object:172982}."] = "{npc:268684}와(과) {npc:268682}은(는) {object:172957}의 그롬마쉬 요새 뒤에 앉아 있고, 매끈한 바위가 그 주변에 놓여 있습니다. 도시에 있는 동안 훈련을 받으세요(드루이드와 성기사는 이곳에 상급자가 없습니다). 다음 가이드는 {object:172982}의 와이번 조련사 {npc:3310}에게서 시작합니다.",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348}와(과) {npc:3347}은(는) 골목길의 연금술 상점을 운영합니다. {npc:11046}은(는) 그 옆집에 있습니다.",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, 그롬마쉬 요새 안",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, 호드 지도자 순방",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018}은(는) 도시 서쪽의 {object:172961}에 서 있습니다.",
		["{object:112888}, inside the keep"] = "{object:112888}, 성채 안",
		["{object:1599}, just east of the keep"] = "{object:1599}, 성채 바로 동쪽",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, 다음 가이드",
		["{zone:1454} class quests"] = "{zone:1454} 직업 퀘스트",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "{npc:261366} 돕기: {npc:261367}와(과) {area:21} 해병이 능선을 올라오면 그의 곁에 있으세요",
		["Back to the {area:380}"] = "{area:380}(으)로 돌아가기",
		["Bael'dun fortress"] = "바엘던 요새",
		["Bristleback camps"] = "뾰족털일족 야영지",
		["Cast {spell:18960}. Tauren: join the two pendant halves at the {area:2362}, on the north-west shore of the lake, before you see {npc:11802} in {area:2361}."] = "{spell:18960}을(를) 시전하세요. 타우렌: {area:2361}의 {npc:11802}을(를) 만나기 전에 호수 북서쪽 기슭 {area:2362}에서 펜던트 두 조각을 합치세요.",
		["Dogran is chained up in the quilboar camp west of the road."] = "도그란은 길 서쪽 가시멧돼지 야영지에 사슬로 묶여 있습니다.",
		["Doras, the wind rider master, stands on the tower in the {object:172982}."] = "와이번 조련사 도라스는 {object:172982}의 탑 위에 있습니다.",
		["Down the {area:458} to {area:378} again."] = "{area:458}을(를) 따라 다시 {area:378}(으)로 내려가십시오.",
		["East across the plains toward the coast: the stolen silver lies in a raptor nest north-west of {area:385}."] = "동쪽 평원을 가로질러 해안 쪽으로 가십시오. 도둑맞은 은은 {area:385} 북서쪽 랩터 둥지에 있습니다.",
		["East to the {area:382}. {npc:3439} stands inside the Venture Co. camp; {npc:3445} carries the key."] = "동쪽 {area:382}(으)로 가십시오. {npc:3439}은(는) 투자개발회사 야영지 안에 있으며, {npc:3445}이(가) 열쇠를 가지고 있습니다.",
		["Fill the {item:7766} at the quilboar watering hole"] = "가시멧돼지 물웅덩이에서 {item:7766} 채우기",
		["Fizzule runs the Venture Co. camp at the east end of the {area:382}. He attacks strangers: target him and /salute before he does."] = "피줄은 {area:382} 동쪽 끝의 투자개발회사 야영지를 운영합니다. 낯선 이를 공격하니 먼저 대상으로 지정하고 /salute를 하십시오.",
		["Fly back to the {area:380}. The next guide starts here and takes the road north to the {area:1703} and {zone:1440}."] = "{area:380}(으)로 비행해 돌아가십시오. 다음 가이드는 여기서 시작해 북쪽 길로 {area:1703}와(과) {zone:1440}(으)로 갑니다.",
		["Fly to {area:1637} to train your level 20 ranks. {npc:3354} is in the {object:172958}, {npc:5892} in the {object:172957}."] = "{area:1637}(으)로 비행해 20레벨 기술을 수련하십시오. {npc:3354}은(는) {object:172958}에, {npc:5892}은(는) {object:172957}에 있습니다.",
		["Fly to {area:1637} to train."] = "{area:1637}(으)로 비행해 수련하십시오.",
		["Fly to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}."] = "{area:1638}(으)로 비행해 20레벨 기술을 수련하십시오. {npc:3033}은(는) {area:1639}에 있습니다.",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "{area:1638}(으)로 비행해 수련하십시오. {npc:3033}은(는) {area:1639}에 있습니다.",
		["Fly to {area:392}"] = "{area:392}(으)로 비행",
		["Follow the {area:458} south to {area:378}."] = "{area:458}을(를) 따라 남쪽 {area:378}(으)로 가십시오.",
		["He gives you the {item:15826}"] = "그가 {item:15826}을(를) 줍니다",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "다음으로 {quest:1838}(1838, 30레벨)을(를) 줍니다. {area:1717}이(가) 필요하며 칼림도어와 동부 왕국 곳곳을 돌아다니게 합니다. 전사 직업 가이드 {quest:1838}에서 다룹니다.",
		["Hearth to the {area:380}"] = "{area:380}(으)로 귀환",
		["Keep it: the {object:107045} is beside {area:272}"] = "보관하십시오: {object:107045}은(는) {area:272} 옆에 있습니다",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "보관하십시오: 다음 가이드의 {zone:1440}에 있는 {npc:12696}",
		["Keep it: {npc:5875} in {zone:1454}, at the end of this guide"] = "보관하십시오: 이 가이드 마지막에 {zone:1454}의 {npc:5875}",
		["Level 20"] = "20레벨",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "북쪽 {area:383}(으)로 가십시오. {npc:3682}은(는) 언덕 아래에 야영하고 있으며, 그 뒤 능선의 은둔자 {npc:261366}은(는) {npc:3682}이 올려 보낸 뒤에만 일을 줍니다.",
		["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last {area:380} stop."] = "{area:458}을(를) 따라 {area:378}(으)로 내려가는 길에: 야영지 북쪽 길 양쪽 뾰족털일족 야영지 사이의 서슬갈기 침략자가 {item:277277}을(를) 가지고 있습니다. 마지막으로 {area:380}에 들를 때 {npc:3432}에게 건네십시오.",
		["Ride north from the {area:380} to {area:384} and fill the {item:15842} at the {object:19464}, then back to {npc:3448} in the {area:380}. No {skill:182}? {npc:3490} beside him sells {item:2449}, three at a time until he restocks."] = "{area:380}에서 북쪽 {area:384}(으)로 가서 {object:19464}에서 {item:15842}을(를) 채운 뒤, {area:380}의 {npc:3448}에게 돌아가십시오. {skill:182}이(가) 없다면 옆의 {npc:3490}이(가) {item:2449}을(를) 판매합니다. 재입고될 때까지 한 번에 세 개입니다.",
		["Savannah Patriarchs roam the plains east of the hills, and the Sprung Traps lie among them. {quest:876} leads the Witchwing harpies in the hills to the west."] = "우두머리 사바나 사자가 언덕 동쪽 평원을 돌아다니며, 용수철 덫은 그들 사이에 있습니다. {quest:876}이(가) 서쪽 언덕의 칼날바람하피를 이끕니다.",
		["South of Camp Taurajo the Silithid Mounds dot the {area:390}; the eggs lie in them, and Silithid Swarmers come out to defend them. Silithid Harvesters are rare: if you see one, kill it for its head."] = "타우라조 야영지 남쪽 {area:390}에 실리시드 흙더미가 흩어져 있습니다. 알은 그 안에 있으며, 우두머리 실리시드가 나와 지킵니다. 여왕 실리시드는 드무니 보이면 처치해 머리를 얻으십시오.",
		["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone."] = "갠 남쪽 {area:359}에서 바엘던 드워프들이 발굴하고 있습니다. 바엘던 발굴인부와 현장감독이 구덩이에서 일하며, {npc:3392}(26)이(가) 일지를 가지고 있으니 그만 따로 끌어오십시오.",
		["Stay stealthed: {npc:7287} carries the key to the tower; Gallywix and his lockbox are at the top. Gallywix is elite: grouping up is advised."] = "은신을 유지하십시오. {npc:7287}이(가) 탑 열쇠를 가지고 있으며, 갤리윅스와 금고는 꼭대기에 있습니다. 갤리윅스는 정예이므로 파티를 권장합니다.",
		["Sunscale Scytheclaws hunt the plains south of the {area:380}, around the {area:1697}; they drop the horns. Hand them in on your next pass through {area:392}."] = "갈퀴발톱 열대초원랩터가 {area:380} 남쪽, {area:1697} 주변 평원에서 사냥하며 뿔을 떨어뜨립니다. 다음에 {area:392}을(를) 지날 때 제출하십시오.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "타우렌: {npc:11957}은(는) 다리 위 남쪽 언덕에서 기다립니다. 스카이본: {npc:272054}은(는) 쌍둥이 다리 남쪽에 있습니다. 그다음 호수 동쪽 굴로 가십시오. 변신을 풀고, 입구의 석상을 클릭해 5분간 은신하고, 안의 혼령을 피해 유물을 하나씩 가져가십시오. {item:280680}은(는) 흰 살쾡이 석상 아래에 있습니다.",
		["The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them."] = "바엘던 병사, 소총병, 장교가 발굴 현장 동쪽의 요새를 지킵니다. 세 아이템 모두 그들이 떨어뜨립니다.",
		["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. Every Bristleback drops a tusk; {npc:3432}'s wife lies at the north edge. Keep one {item:5075}. {quest:883}, a grey kodo, sometimes wanders here: his hoof starts a quest."] = "뾰족털일족 가시멧돼지 야영지가 {area:378} 북쪽 평원, {area:458} 양쪽에 퍼져 있습니다. 모든 뾰족털일족이 엄니를 떨어뜨리며, {npc:3432}의 아내는 북쪽 가장자리에 쓰러져 있습니다. {item:5075} 하나를 보관하십시오. 회색 코도 {quest:883}이(가) 가끔 이곳을 돌아다니며, 그 발굽으로 퀘스트가 시작됩니다.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "지역 북동쪽 구석 광산의 투자개발회사 감독과 투자개발회사 집행자가 {item:5097}을(를) 떨어뜨립니다.",
		["The antennae vanish fifteen minutes after they drop, so gather them now, on the way back north: kill the Silithid Swarmers and Creepers at the {area:390}' mounds until you have five, then hearth to {area:378} straight away."] = "더듬이는 떨어진 지 15분 후에 사라지니 북쪽으로 돌아가는 길에 지금 모으십시오. {area:390} 흙더미의 우두머리 실리시드와 독침 실리시드를 다섯 개가 될 때까지 처치한 뒤 곧바로 {area:378}(으)로 귀환하십시오.",
		["The dwarves' flying machine sits on its platform inside the dig site."] = "드워프의 비행 기계는 발굴 현장 안 발판 위에 있습니다.",
		["The flying machine"] = "비행 기계",
		["The level-20 class quests in {zone:1454} ({npc:3354}, {npc:5892}, the Warlock and Rogue trainers) are only offered from level 20, so finish the level here before you fly. The Thunderhawk Hatchlings (18) on the plains south-west of the {area:380} and the Kolkar (14-15) at the {area:388} are the nearest mobs worth killing; you need well under a level."] = "{zone:1454}의 20레벨 직업 퀘스트({npc:3354}, {npc:5892}, 흑마법사와 도적 상급자)는 20레벨부터만 제공되니 비행하기 전에 여기서 레벨을 마치십시오. {area:380} 남서쪽 평원의 새끼 천둥매(18)와 {area:388}의 콜카르일족(14-15)이 가장 가까운 사냥감입니다. 필요한 경험치는 한 레벨보다 훨씬 적습니다.",
		["The pirates camp on the beach south of {area:392}; {npc:3467} stands at its southern end."] = "해적들은 {area:392} 남쪽 해변에 야영하며, {npc:3467}은(는) 남쪽 끝에 있습니다.",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960}은(는) {object:172982} 아래 협곡입니다.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792}은(는) {area:382} 북쪽 가장자리, 투자개발회사 탑 옆에 있습니다. {quest:30}용 {item:15883}이(가) 들어 있습니다.",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "비단천둥매가 야영지 남쪽 같은 평원 위를 맴돕니다.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "천둥꼬리도마뱀이 {area:378} 바로 남쪽 평원에서 풀을 뜯습니다. 파란 천둥꼬리도마뱀 {quest:884}이(가) 그 사이를 돌아다니며, 그 꼬리가시로 퀘스트가 시작됩니다.",
		["Twitching Antennae"] = "꿈틀거리는 더듬이",
		["Twitching Antennae from the silithid"] = "실리시드에게서 꿈틀거리는 더듬이",
		["Venture Co. tower"] = "투자개발회사 탑",
		["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {npc:3238} lizards and Hecklefang Stalkers roam the plain between {npc:3341} and the ridge. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest."] = "갠 서쪽의 {area:1701}은(는) 서슬갈기일족이 차지하고 있습니다. {npc:3436}은(는) 동쪽에, {npc:3434}은(는) 남쪽에, {npc:3435}은(는) 서쪽 끝에 있습니다. 로크(25)와 서슬갈기일족 광전사(24-25)는 몇 레벨 높습니다. 희귀 정예 {npc:5859}이(가) 가끔 능선을 걸으니 피하십시오. 서슬갈기일족 길잡이와 정찰꾼이 기습용 단검을, 점쟁이가 마법봉을, 광전사가 전투용 방패를 떨어뜨립니다. {npc:3238} 도마뱀과 긴발톱 빗송곳니하이에나가 {npc:3341}와(과) 능선 사이 평원을 돌아다닙니다. 희귀한 붉은 바람뱀 {quest:885}이(가) 능선 위를 날며, 그 깃털로 퀘스트가 시작됩니다.",
		["Wizzlecrank drives his shredder out of the camp: stay with him and kill whatever attacks him. {npc:3442} takes it in {area:392}."] = "위즐크랭크가 벌목기를 몰고 야영지를 빠져나갑니다. 함께 있으면서 공격하는 적을 처치하십시오. {area:392}의 {npc:3442}이(가) 받습니다.",
		["grind on Thunderhawk Hatchlings south-west of the {area:380}"] = "{area:380} 남서쪽에서 새끼 천둥매 사냥",
		["{area:385}, on the coast further south. The Theramore Marines and Preservers (15-16) drop the medals; {npc:3393} (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now."] = "더 남쪽 해안의 {area:385}입니다. 테라모어 해병과 테라모어 치료사(15-16)가 훈장을 떨어뜨립니다. {npc:3393}(20)와(과) 포수 둘(19)이 요새 안과 성벽 위에 있어 지금까지 미뤘습니다.",
		["{item:15852}: Lost Barrens Kodos on the plains around the Kolkar camp"] = "{item:15852}: 콜카르일족 야영지 주변 평원의 길잃은 황무지 코도",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: {area:2362}에서 조각을 사용하십시오",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{npc:3490}에게서 {item:2449}. 약초채집가는 평원에서 채집하십시오",
		["{item:2449}: herbalists pick it here"] = "{item:2449}: 약초채집가는 여기서 채집하십시오",
		["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}의 {npc:11798}이(가) 드루이드를 그곳으로 태워 줍니다",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: {npc:3033}이(가) 보낸 환영 인사",
		["{npc:12296}: use the {item:15826} on them; they roam the plains all around the {area:380}"] = "{npc:12296}: {item:15826}을(를) 사용하십시오. {area:380} 주변 평원 곳곳을 돌아다닙니다",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, {npc:3341} 바로 동쪽 나무 위",
		["{npc:209797} swims in the harbour just off {area:392}'s docks. {npc:209797} is elite: grouping up is advised."] = "{npc:209797}은(는) {area:392} 부두 바로 앞 항구에서 헤엄칩니다. {npc:209797}은(는) 정예이므로 파티를 권장합니다.",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{area:272}의 {npc:2391}이(가) 독 조제를 가르칩니다: 보관하세요",
		["{npc:246344} teaches Paladins in {area:1638}. You have no flight path there yet: fly to {area:378}, ride west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "{npc:246344}은(는) {area:1638}에서 성기사를 가르칩니다. 아직 그곳 비행 경로가 없으니 {area:378}(으)로 비행한 뒤 서쪽으로 {zone:1412}을(를) 지나 승강기를 타고 올라가, 중앙 언덕의 {npc:2995}에게서 비행 경로를 얻으십시오.",
		["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}."] = "{npc:262119}와(과) 해병들이 {npc:261366} 남쪽의 부서진 대상단을 차지하고 있습니다.",
		["{npc:3238}, on the plain between {npc:3341} and the ridge"] = "{npc:3238}, {npc:3341}와(과) 능선 사이 평원",
		["{npc:3341} waits in a small camp further south, on the road toward {area:359}."] = "{npc:3341}은(는) 더 남쪽, {area:359}(으)로 가는 길가의 작은 야영지에서 기다립니다.",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389}은(는) {area:380} 바로 서쪽의 콜카르일족 감시 초소에 있습니다.",
		["{npc:3394} stands in the Kolkar camp north-west of {npc:3389}."] = "{npc:3394}은(는) {npc:3389} 북서쪽 콜카르일족 야영지에 있습니다.",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the {area:380}."] = "{npc:3395}은(는) {area:380} 남동쪽 {area:388}의 콜카르일족 사이를 걷습니다.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. Hand his head to {npc:3389} on your last {area:380} stop."] = "{npc:3396}은(는) {npc:3389} 남쪽, {area:387} 서쪽 기슭의 콜카르일족을 이끕니다. 마지막으로 {area:380}에 들를 때 머리를 {npc:3389}에게 건네십시오.",
		["{npc:3401} stands in the {object:172960}. Target him and type /salute to finish {quest:2460}."] = "{npc:3401}은(는) {object:172960}에 있습니다. 그를 대상으로 지정하고 /salute를 입력해 {quest:2460}을(를) 완료하십시오.",
		["{npc:3428}: the eggs are in the {area:390}, later"] = "{npc:3428}: 알은 나중에 {area:390}에서",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, 탑 꼭대기",
		["{npc:3429}. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}. 보관하십시오: 다음 가이드의 {area:1703}에 있는 카드라크",
		["{npc:3430}, in the cage"] = "{npc:3430}, 우리 안",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{quest:4921}을(를) 제출하면 {npc:3432}이(가) {quest:95774}을(를) 줍니다",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, 야영지 북쪽 가장자리",
		["{npc:3442}, beside the wind rider master. Keep it: {quest:1483} is in Stonetalon, later"] = "{npc:3442}, 와이번 조련사 옆. 보관하십시오: {quest:1483}은(는) 나중에 돌발톱 산맥에서 합니다",
		["{npc:3453}, on the dock"] = "{npc:3453}, 부두",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465}은(는) 요새 안에 사슬로 묶여 있습니다. 대화해 호위를 시작하고 가까이 있으십시오. 나가는 길에 테라모어 병사가 공격합니다. 그가 {area:392}까지 함께 걸어갑니다.",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197}은(는) {npc:3389}에서 서쪽으로 가는 길 끝, 돌발톱 산맥 입구의 트롤 마을 {area:2539}에 삽니다.",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875}은(는) {object:172960}에 있습니다. 그곳 소환진에서 {item:6626}을(를) 사용하고 서큐버스를 쓰러뜨려 속박하십시오.",
		["{npc:5878} camps beside the road east of the {area:380}."] = "{npc:5878}은(는) {area:380} 동쪽 길가에 야영하고 있습니다.",
		["{npc:5899}, just west of {npc:3341}"] = "{npc:5899}, {npc:3341} 바로 서쪽",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901}은(는) 북쪽으로 가는 길, {area:392} 남쪽 언덕에서 기다립니다.",
		["{npc:5909}, a few steps away"] = "{npc:5909}, 몇 걸음 떨어진 곳",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018}은(는) 도시 서쪽 {object:172961}에 있습니다.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}: 두 가이드 뒤 {zone:1458}의 {npc:4606}",
		["{object:3972} poster"] = "{object:3972} 게시판",
		["{quest:2458}: {npc:7233}, by the {area:382}"] = "{quest:2458}: {area:382} 옆의 {npc:7233}",
		["{quest:882}, a big Sunscale raptor, hunts the plains north of the road from {area:392} to the {area:380}."] = "큰 열대초원랩터 {quest:882}이(가) {area:392}에서 {area:380}(으)로 가는 길 북쪽 평원에서 사냥합니다.",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "다시 길을 따라 남쪽으로 가세요. 길이 동쪽 {area:287}(으)로 꺾이는 곳의 {area:285}에서 {npc:2214}이(가) 기다립니다.",
		["Back to {npc:8582}"] = "{npc:8582}에게 돌아가기",
		["East of Ziz, the Venture Company is clear-cutting {area:461}; one of the Operators carries the blueprints. {npc:4276} mines in the small mine on the east side: stay with him while he mines, Venture Co. thugs come for him."] = "지즈의 동쪽에서 투자개발회사가 {area:461}의 나무를 베어내고 있습니다. 운전수 중 하나가 설계도를 지니고 있습니다. {npc:4276}은(는) 동쪽의 작은 광산에서 채굴합니다. 그가 채굴하는 동안 곁에 있으세요. 투자개발회사 불량배가 그를 노리고 옵니다.",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "전초기지 북쪽 해안을 따라 있는 성난지느러미일족 나가는 모두 머리를 떨어뜨립니다.",
		["Fly to {area:431} and ride south down the road to the {area:1703}."] = "{area:431}(으)로 날아간 뒤 길을 따라 남쪽의 {area:1703}(으)로 가세요.",
		["Follow the road east along the river, then north-east up into the hills to {area:272}."] = "길을 따라 강을 끼고 동쪽으로 간 뒤, 북동쪽 언덕을 올라 {area:272}(으)로 가세요.",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "길을 따라 북쪽의 {area:467}(으)로 가세요. 가는 길에 순록이 풀을 뜯고, 수액괴물, 황혼의 흑표범, 마룡은 봉우리 아래 숲을 돌아다니며, 세나리온 드루이드가 그곳 숲을 차지하고 있습니다.",
		["Follow the road west to {area:460}."] = "길을 따라 서쪽의 {area:460}(으)로 가세요.",
		["From the {area:380} follow the road north. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}. Open the {item:16783} he gives you."] = "{area:380}에서 길을 따라 북쪽으로 가세요. {npc:8582}은(는) 길이 {zone:1440}(으)로 들어가는 {area:1703}의 감시탑 위에 서 있습니다. 그가 주는 {item:16783}을(를) 열어 보세요.",
		["Gaea Dirt Mounds"] = "가이아 흙더미",
		["Gaea Seeds"] = "가이아 씨앗",
		["If you already know the {area:272} flight path, fly there and skip to {area:272}. Otherwise fly from the {zone:1458} to the {area:228} and ride south down the road past Pyrewood. The Ravenclaw undead haunt the ruins of {area:231} east of the road in the south-east of the forest; a {npc:1973} drops the {item:271343} that leads to the {object:645153}."] = "이미 {area:272} 비행 경로를 안다면 그곳으로 날아가 {area:272} 단계로 건너뛰세요. 아니라면 {zone:1458}에서 {area:228}(으)로 날아가 길을 따라 남쪽으로 장작나무 마을을 지나가세요. 까마귀발톱 언데드는 숲 남동쪽, 길 동쪽의 {area:231} 폐허를 떠돕니다. {npc:1973}이(가) {object:645153}(으)로 이어지는 {item:271343}을(를) 떨어뜨립니다.",
		["Keep north on the road. The {npc:12862} waits at the Warsong lumber camp, south of Splintertree."] = "길을 따라 계속 북쪽으로 가세요. {npc:12862}은(는) 토막나무 주둔지 남쪽의 전쟁노래부족 벌목기지에서 기다립니다.",
		["Naga heads"] = "나가 머리",
		["On the ride west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "서쪽으로 가는 길에, {npc:267214}이(가) {area:415} 남동쪽, 큰길 남쪽의 협곡에 갇혀 있습니다. 검은뿔순록과 잿빛골짜기곰이 주변 숲을 돌아다닙니다.",
		["Ride back down the {area:1076} to {area:2539}."] = "{area:1076}을(를) 따라 {area:2539}(으)로 돌아가세요.",
		["Ride east to the {area:380} and fly to {zone:1454}. Take the zeppelin from the towers outside {zone:1454} to {zone:1420}; the {area:1497} lies below the {area:153}. The bat handler is in the {object:36078}."] = "동쪽의 {area:380}(으)로 가서 {zone:1454}(으)로 날아가세요. {zone:1454} 밖의 탑에서 {zone:1420}행 비행선을 타세요. {area:1497}은(는) {area:153} 아래에 있습니다. 박쥐 조련사는 {object:36078}에 있습니다.",
		["Ride south to the {area:380}, then west along the road out of the {zone:1413} into Stonetalon. The troll village of {area:2539} sits at the entrance of the canyon."] = "남쪽의 {area:380}(으)로 간 뒤, 길을 따라 서쪽으로 {zone:1413}을(를) 벗어나 돌발톱 산맥으로 들어가세요. 트롤 마을 {area:2539}은(는) 협곡 입구에 있습니다.",
		["Ride west along the main road across {zone:1440}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west. Its other quests are for the next visit, at 27."] = "큰길을 따라 서쪽으로 {zone:1440}을(를) 가로질러 {area:415}(얼라이언스: 길에서 벗어나지 마세요)을(를) 지나 해안까지 가세요. {area:2897}은(는) 북서쪽 {area:414}에 있습니다. 그곳의 다른 퀘스트는 27레벨에 다음으로 올 때 처리합니다.",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "해바위 야영지 남서쪽에 불타 버린 {area:465}이(가) 있습니다. 골짜기 바닥의 흙더미에 가이아 씨앗을 심으세요. 불의 정령은 {item:16312}을(를) 떨어뜨립니다. 혈폭풍하피와 복병은 북쪽에, 암살자와 약탈자는 남쪽에 둥지를 틀고 있습니다.",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "{object:36126}의 {npc:10181}와(과) 대화하세요: {quest:93739}",
		["Sputtervalve in {area:392}: the next guide passes there"] = "{area:392}의 스퍼터밸브: 다음 가이드에서 그곳을 지납니다",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "{npc:267214}의 {npc:271181}을(를) 조종해 4분 안에 협곡에서 큰길까지 데려가세요. 정신 집중이 끊기면 {npc:267214}에게 다시 부탁하세요.",
		["The Gaea Seeds lie in the grass around the southern shore of {area:464}, north of Sun Rock."] = "가이아 씨앗은 해바위 야영지 북쪽, {area:464} 남쪽 기슭 주변의 풀밭에 있습니다.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "길은 {area:1076}(이)라는 이름으로 북쪽으로 올라갑니다. {quest:1483}의 오두막은 길이 동쪽 {area:461}(으)로 갈라지는 곳에 있습니다.",
		["The {npc:12864} patrols the road east of {area:428} toward the {area:430}."] = "{npc:12864}은(는) {area:428} 동쪽에서 {area:430} 쪽으로 길을 순찰합니다.",
		["To the {area:1497}"] = "{area:1497}(으)로",
		["Use the {npc:212753} at the {object:645153} for a willing sacrifice and kill the {npc:212753} that answers. {quest:95883} is elite: grouping up is advised."] = "{object:645153}에서 {npc:212753}을(를) 사용해 자발적인 제물로 바치고, 응답하는 {npc:212753}을(를) 처치하세요. {quest:95883}은(는) 정예 퀘스트입니다. 파티를 권장합니다.",
		["{area:431} is just north up the road."] = "{area:431}은(는) 길을 따라 바로 북쪽에 있습니다.",
		["{item:271343}, from a {npc:1973}"] = "{npc:1973}에게서 얻는 {item:271343}",
		["{item:271350}, from the Tortured Souls among the ruins"] = "폐허의 괴로워하는 영혼에게서 얻는 {item:271350}",
		["{item:277936}, from any Bloodfury harpy"] = "혈폭풍하피 누구에게서나 얻는 {item:277936}",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: 혈폭풍하피에게서 얻는 {item:277936}",
		["{npc:11860}: Grish is at the {object:19844}, in the next guide"] = "{npc:11860}: 그리쉬는 다음 가이드에서 {object:19844}에 있습니다",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11862} 옆의 {npc:11861}",
		["{npc:11862}, up on the ledge"] = "바위 턱 위의 {npc:11862}",
		["{npc:12696} stands at {area:428}, the Warsong camp just north-east of Splintertree, beside the hunt board."] = "{npc:12696}은(는) 토막나무 주둔지 바로 북동쪽의 전쟁노래부족 야영지인 {area:428}에서 사냥 게시판 옆에 서 있습니다.",
		["{npc:12696}'s hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next {zone:1440} visit, at 27."] = "{npc:12696}의 사냥 대상(우르산고우스, 샤둠브라, 뾰족발톱)은 27레벨에 다음으로 {zone:1440}에 올 때 처리합니다.",
		["{npc:12736} at Zoram'gar, at 27"] = "27레벨에 조람가르의 {npc:12736}",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: {area:272}의 다르탈리아",
		["{npc:271181}, on the road"] = "길 위의 {npc:271181}",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "{npc:4198}의 다음 퀘스트인 오르다누스는 {zone:1440}의 얼라이언스 지역에 있습니다. 건너뛰세요.",
		["{npc:4198}, outside the gate"] = "정문 밖의 {npc:4198}",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606}은(는) {object:36070}에 서 있습니다.",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Bears, creepers and lions"] = "곰, 거미, 사자",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings; open both locks."] = "드럴과 {npc:2238}은(는) {area:275} 안뜰 건물 안에 사슬로 묶여 있습니다. 자물쇠 두 개를 모두 여세요.",
		["Drull's ball and chain"] = "드럴의 족쇄",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "여관 옆의 {object:107045}에서 {item:7768}을(를) 채우세요",
		["Follow the road south to the dwarf dig site at {area:359}. {npc:3421} hides at the south edge of the dig; {object:3646} sits at the bottom of the excavation."] = "길을 따라 남쪽의 {area:359} 드워프 발굴지로 가세요. {npc:3421}은(는) 발굴지 남쪽 가장자리에 숨어 있고, {object:3646}은(는) 발굴 구덩이 바닥에 있습니다.",
		["From {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "{area:272}에서 남동쪽으로 {area:275}(으)로 가는 길의 언덕으로 가세요. 길목의 야영지에는 비밀결사대 도적과 비밀결사대 경비병이 있습니다.",
		["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:1638} and train on {area:1639}, then fly on to {area:378}."] = "{zone:1454}에서({zone:1458} 바깥 탑에서 비행선) {area:1638}(으)로 날아가 {area:1639}에서 기술을 배운 뒤 {area:378}(으)로 날아가세요.",
		["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:378}."] = "{zone:1454}에서({zone:1458} 바깥 탑에서 비행선) {area:378}(으)로 날아가세요.",
		["Hearth to {area:378} and fly to {area:392}. {quest:874} camps on the shore north of {area:392}."] = "귀환석으로 {area:378}에 간 뒤 {area:392}(으)로 날아가세요. {quest:874}은(는) {area:392} 북쪽 해안에 야영하고 있습니다.",
		["Keep it: the {area:287} coast, later on the route"] = "보관하세요: 경로 후반의 {area:287} 해안",
		["Masoj hides on the hillside above {area:290}, south of Durnholde, on the way down to the blossoms."] = "Masoj는 던홀드 남쪽, 꽃이 있는 곳으로 내려가는 길의 {area:290} 위 언덕에 숨어 있습니다.",
		["No Gallywix yet? The Class guide Poisons (Horde) runs the chain from Shenthul again, with a group for Gallywix."] = "아직 갤리윅스를 처치하지 않았나요? 직업 가이드 독 조제 (호드)에서 셴툴부터 연계 퀘스트를 다시 진행하며, 갤리윅스는 파티와 함께 처치합니다.",
		["Only if Gallywix fell in the {zone:1413} (Mission: Possible But Not Probable): {npc:2391} stands in {area:272}. Wait beside him while he brews the cure, then take your reward: Poisons."] = "{zone:1413}에서 갤리윅스를 처치했을 때만(미션 임파서블: 잘하면 가능): {npc:2391}은(는) {area:272}에 있습니다. 해독제를 만드는 동안 옆에서 기다린 뒤 보상을 받으세요: 독 조제.",
		["Peasants and skulls"] = "소작농과 해골",
		["South-west of Bael Modan, {npc:12576} waits at the top of the {area:1718}."] = "바엘 모단 남서쪽, {area:1718} 꼭대기에서 {npc:12576}이(가) 기다립니다.",
		["South-west of Durnholde, the {item:3502} grow on the hillsides above the river."] = "던홀드 남서쪽, 강 위 언덕에 {item:3502}이(가) 자랍니다.",
		["Syndicate camps"] = "비밀결사대 야영지",
		["Take the zeppelin from the towers outside the {zone:1458} to {zone:1454} and train before you fly on."] = "{zone:1458} 바깥 탑에서 비행선을 타고 {zone:1454}(으)로 가서, 다시 날아가기 전에 기술을 배우세요.",
		["The Peasants work the fields south of the farmhouses. Every {area:287} human drops skulls; the Peasants drop them most often."] = "힐스브래드 소작농은 농가 남쪽 밭에서 일합니다. {area:287}의 인간은 모두 해골을 떨어뜨리며, 힐스브래드 소작농이 가장 자주 떨어뜨립니다.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "{area:287} 마을 동쪽의 농장입니다. {npc:232}은(는) 북쪽 농가 옆 밭에서, {npc:2403}은(는) 더 남동쪽 밭에서 일합니다. 힐스브래드 농노와 힐스브래드 농부는 곳곳에 있습니다. {npc:2451}은(는) 농장 남쪽 밭을 돌봅니다.",
		["The smithy"] = "대장간",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "대장간은 {area:287} 마을 한가운데에 있습니다. {npc:2404}와(과) 견습생들이 화로에서 일하고, {object:1736}은(는) 그 옆에 쌓여 있습니다. {npc:2449}은(는) 그 북쪽 거리를 걸어 다닙니다.",
		["The town hall is on the west side of {area:287}. {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "마을 회관은 {area:287} 서쪽에 있습니다. {npc:2335} (30)와(과) {npc:2448}은(는) 힐스브래드 마을의 기록부와 함께 안에 있고, 힐스브래드 선언문은 그 옆에 붙어 있습니다. 힐스브래드 원로는 마을을 돌아다닙니다.",
		["The {area:288} lies south of {area:287} town. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "{area:288}은(는) {area:287} 마을 남쪽에 있습니다. 힐스브래드 광부가 갱도에서 일하고, {npc:2305} (30)와(과) {npc:2450} (29)은(는) 깊숙한 곳에 있습니다.",
		["The {object:1763} poster by the inn"] = "여관 옆의 {object:1763} 게시판",
		["The {quest:567} poster: its targets come up along the way"] = "{quest:567} 게시판: 대상은 가는 길에 나옵니다",
		["Town hall"] = "마을 회관",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "타렌 밀농장 서쪽, 농장으로 내려가는 길의 언덕에 회색곰, 숲이끼거미, 굶주린 산사자가 돌아다닙니다. 숲이끼거미는 {item:3477}을(를) 드물게 떨어뜨리며, 하나만 있으면 됩니다.",
		["You arrive bound at the {area:272} inn. Everyone stands around the town square."] = "{area:272} 여관에 귀환 지점을 정한 상태로 도착합니다. 모두 마을 광장 주변에 있습니다.",
		["{npc:2055}, in the Apothecarium"] = "연금술 실험실의 {npc:2055}",
		["{npc:2055}, in the {zone:1458}"] = "{zone:1458}의 {npc:2055}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}: 던홀드로 가는 길에 있는 {npc:270438}에게 전할 명령",
		["{npc:2230}, next to Lydon"] = "라이던 옆의 {npc:2230}",
		["{npc:2238}'s ball and chain"] = "{npc:2238}의 족쇄",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274}은(는) {npc:232}의 개로, {area:286}의 북쪽 농가에 있습니다.",
		["{npc:2391}: Poisons"] = "{npc:2391}: 독 조제",
		["{npc:3442}, by the docks in {area:392}"] = "{area:392} 부두 옆의 {npc:3442}",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "{npc:5899}의 오두막은 {area:378} 남쪽, {area:359}(으)로 가는 길에 있는 가시멧돼지 물웅덩이 위 능선에 있습니다.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: 파란 물주머니는 다음 가이드에서 {zone:1440}에서 채웁니다",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: {area:272}에서 채운 빨간 물주머니",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "큰 쓰레샤돈인 {quest:873}은(는) {npc:3388} 동쪽, {area:391} 앞바다 얕은 곳에서 헤엄칩니다.",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["Back south to the camp, then up into {area:1638} for the flight to {area:378}."] = "남쪽 야영지로 돌아간 뒤, {area:1638}에 올라가 {area:378}(으)로 날아가세요.",
		["Back south-west to {area:421}. Befouled Water Elementals drift around its shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "남서쪽의 {area:421}(으)로 돌아가세요. 타락한 물의 정령이 호숫가를 떠다닙니다. 정자는 얼라이언스 전초기지가 내려다보이는 섬에 있습니다.",
		["Back west to Zoram'gar before heading east for good."] = "완전히 동쪽으로 떠나기 전에 서쪽의 조람가르로 돌아가세요.",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "길을 따라 {area:2097} 꼭대기로 올라가세요. {npc:10646}은(는) {npc:10896}(29) 옆에 붙잡혀 있습니다. 먼저 경비병과 {npc:10896}을 처치한 뒤 그녀를 풀어 주고, 내려가는 동안 보호하세요. 가는 길에 그림토템부족 복병이 덤벼듭니다.",
		["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold."] = "조람가르 동쪽에서는 엉겅퀴일족 털보숭이가 마을과 소굴 주변 언덕을 가득 메우고 있습니다.",
		["Felmusk satyrs"] = "검은유혹의 사티로스",
		["Fly from {area:1638} to {area:378} and take the road south to the {area:1718} at the bottom of the {zone:1413}."] = "{area:1638}에서 {area:378}(으)로 날아가 길을 따라 남쪽, {zone:1413} 맨 아래의 {area:1718}(으)로 가세요.",
		["Fly from {area:1638} to {area:378}. {npc:5899}'s hut stands on the ridge above the quilboar watering hole south of the camp, on the road to the {area:1718}."] = "{area:1638}에서 {area:378}(으)로 날아가세요. {npc:5899}의 오두막은 야영지 남쪽, {area:1718}(으)로 가는 길가의 가시멧돼지 물웅덩이 위 능선에 있습니다.",
		["Fly from {area:392} to {area:2897} on the {zone:1440} coast."] = "{area:392}에서 {zone:1440} 해안의 {area:2897}(으)로 날아가세요.",
		["Fly to {area:1638} if you know the flight path. If not, fly to {area:378}, ride west into {zone:1412} past {area:222} to {area:1638} and take its flight path from {npc:2995} on the central rise."] = "비행 경로를 안다면 {area:1638}(으)로 날아가세요. 모른다면 {area:378}(으)로 날아가 서쪽 {zone:1412}(으)로 {area:222}을(를) 지나 {area:1638}까지 간 뒤, 중앙 고지의 {npc:2995}에게서 비행 경로를 얻으세요.",
		["Follow the canyon east out of the mesas onto the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "협곡을 따라 동쪽으로 고원을 벗어나 소금 평원으로 가세요. {area:2240}의 고블린과 노움은 중립이며 양 진영 모두에게 퀘스트를 줍니다.",
		["Follow the canyon west to {area:2237}."] = "협곡을 따라 서쪽의 {area:2237}(으)로 가세요.",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "큰길을 따라 동쪽으로 {area:415}을(를) 지나가세요(얼라이언스: 길에서 벗어나지 마세요). 커다란 회색곰 {npc:12678}은(는) 길 남쪽, {area:421} 서쪽의 {area:418}을(를) 돌아다닙니다. 그의 발이 다음 사냥 퀘스트를 시작합니다.",
		["Galak centaurs"] = "갈라크일족 켄타우로스",
		["Gazebo"] = "정자",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "{npc:264096}에게서 얻는 {item:273001}",
		["Grimtotem camps"] = "그림토템부족 야영지",
		["His crate is for Stranglethorn, later on the route"] = "그의 상자는 나중에 경로상의 가시덤불 골짜기용입니다",
		["Inside the hold, Troll Chests lie along the tunnels. {npc:12818} is held deep inside: free him and protect him all the way out, then he runs home to {area:428}."] = "소굴 안의 터널을 따라 트롤 궤짝이 있습니다. {npc:12818}은(는) 깊숙한 곳에 갇혀 있습니다. 풀어 주고 밖으로 나갈 때까지 보호하세요. 그러면 그는 {area:428}(으)로 달려갑니다.",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "길을 따라 계속 동쪽으로 가세요. {npc:12858}은(는) 전쟁노래부족 벌목기지 남서쪽에서 기다립니다. 그와 그의 부하들이 {area:2360}을(를) 습격합니다. 그들이 어그로를 끌게 하고 {npc:12860}이(가) 죽을 때까지 {npc:12858} 곁에 있으세요.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "{npc:10638}을(를) 노리고 오는 {npc:10720}을(를) 처치하세요",
		["Naga brazier"] = "나가 화로",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "야영지 북쪽에서 거미들이 {area:17044}의 매장지를 뒤덮고 있습니다. {npc:264096}에 {npc:264074}의 {item:273015}을(를) 사용하세요. 거미들은 {item:273181}을(를) 떨어뜨립니다. {npc:264082}은(는) 북쪽 끝에 있으며, 그녀의 {item:273658}이(가) {quest:96294}을(를) 시작합니다.",
		["North up the road to {area:431} and {area:428} beside it."] = "길을 따라 북쪽의 {area:431}와(과) 그 옆의 {area:428}(으)로 가세요.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "토막나무 주둔지 북서쪽 숲에 검은유혹의 사티로스가 야영하고 있습니다. 사티로스는 누구나 뿔을 떨어뜨릴 수 있습니다.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "승강기를 타고 내려가 길을 따라 동쪽으로 협곡을 지나 고원 꼭대기의 타우렌 마을인 {area:484}(으)로 가세요. 그곳 승강기는 북쪽에 있습니다.",
		["Sapphires of Aku'Mai"] = "아쿠마이의 사파이어",
		["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s."] = "먹구름 봉우리 남쪽에 {area:487}의 하피들이 있습니다. {npc:4490}(31)은(는) 그들 사이를 돌아다닙니다. 끌어오기 전에 주변 하피를 줄이세요. 그곳의 회오리 하피, 약탈자, 바람마녀는 {npc:4877}의 퀘스트 대상입니다.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "{area:1638}의 {npc:3057}와(과) 대화하세요: {quest:93739}",
		["Take a lift down from {area:1638}. The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}."] = "{area:1638}에서 승강기를 타고 내려가세요. 대지 고리회 야영지는 절벽 북쪽에 있습니다: {npc:264074}, {npc:264072}, {npc:259118}.",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "승강기를 타고 내려가세요. 알은 협곡 바닥의 둥지에 있으며, 위치는 세 곳 중 하나입니다: 고원 남동쪽(52.3,55.2), 동쪽(56.4,50.4), 남서쪽(37.6,56.1).",
		["The Earthen Ring"] = "대지 고리회",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "썩은나무일족 털보숭이는 {area:421} 동쪽, 길 남쪽의 숲을 차지하고 있습니다. {object:178206}에 {item:16972}을(를) 놓고 지키세요. 털보숭이들이 깃발을 쓰러뜨리러 옵니다. {npc:12918}은(는) 마지막에 오며, 그의 토템은 바구니에 떨어집니다.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "갈라크일족 야영지가 높새바람 봉우리 북쪽 협곡을 가득 메우고 있으며, 모든 야영지에 척후병, 사냥꾼, 바람전사가 함께 있습니다. 홀로 다니는 {npc:10617}이(가) 야영지 사이를 오갑니다. 만나면 처치하세요. 그의 쪽지가 {area:2237} 퀘스트를 시작합니다.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "사파이어는 {area:2797} 차원문으로 이어지는 터널 벽에 박힌 푸른 수정으로, 인스턴스 밖 지하에 있습니다. 구덩이에서 헤엄쳐 내려가 벽 아래를 지나 동굴로 들어가세요. 터널의 사티로스와 나가는 정예입니다. 파티를 권장합니다. 수정은 빨리 다시 생기므로 깊이 들어갈 필요는 없습니다.",
		["The Wanted poster beside {npc:10537}"] = "{npc:10537} 옆의 현상수배 게시판",
		["The fountain stands in the middle of the {area:418}: use the {item:7767} there."] = "분수는 {area:418} 한가운데에 있습니다. 그곳에서 {item:7767}을(를) 사용하세요.",
		["The next guide flies on from here to {zone:1454}."] = "다음 가이드는 여기서 {zone:1454}(으)로 날아갑니다.",
		["The salt flats"] = "소금 평원",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "사파이어로 가는 길은 해안 북쪽 끝의 가라앉은 폐허를 지납니다. 계단을 내려가 구덩이로 들어가세요.",
		["Thistlefur Hold"] = "엉겅퀴일족 소굴",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "높새바람 봉우리 서쪽, {area:2097} 아래에 그림토템부족 야영지가 있습니다. 비밀 쪽지는 남동쪽, 남서쪽, 북서쪽 야영지의 {object:176344}에 있습니다.",
		["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}."] = "백사장 야영지 서쪽, {area:482} 절벽에 와이번이 둥지를 틀고 있으며, 알은 둥지에 있습니다. {npc:10427}은(는) 둥지 동쪽에서 기다립니다. 풀어 주고 {area:2237}(으)로 돌아가는 동안 살려 두세요.",
		["for {npc:5901}, south of {area:392}: next guide"] = "{area:392} 남쪽의 {npc:5901}에게: 다음 가이드",
		["{area:2797} ruins"] = "{area:2797} 폐허",
		["{area:418} fountain"] = "{area:418} 분수",
		["{item:273181}, from Gloomrise Spinners"] = "{npc:264081}에게서 얻는 {item:273181}",
		["{item:273658}, from {npc:264082}"] = "{npc:264082}에게서 얻는 {item:273658}",
		["{npc:10079}, at the top of the lift"] = "승강기 꼭대기의 {npc:10079}",
		["{npc:10377}, by the wind rider master"] = "윈드라이더 조련사 옆의 {npc:10377}",
		["{npc:10428}'s next quest, Sacred Fire, ends in {area:1638}, off this route. Skip it."] = "{npc:10428}의 다음 퀘스트인 신성한 불은 이 경로에서 벗어난 {area:1638}에서 끝납니다. 건너뛰세요.",
		["{npc:12676}, a big nightsaber, prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest."] = "커다란 밤호랑이 {npc:12676}은(는) 전쟁노래부족 벌목기지 남동쪽 숲을 돌아다닙니다. 그녀의 발톱이 다음 사냥 퀘스트를 시작합니다.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "그림자 표범 {npc:12677}은(는) 검은유혹의 사티로스 야영지 서쪽, {area:426} 주변 숲에 숨어 있습니다. 그녀의 머리가 다음 사냥 퀘스트를 시작합니다.",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead."] = "{npc:12717}은(는) 해안을 따라 북쪽의 나가 화로로 걸어갑니다. 화로를 끄고, 보르샤가 죽을 때까지 나가의 공격을 막으며 그를 지키세요.",
		["{npc:12717}: starts his escort at once"] = "{npc:12717}: 바로 호위를 시작합니다",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: 교본 쪽지를 가지고 있을 때만",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "다음으로 {npc:12736}이(가) {area:2797} 퀘스트를 줍니다. 파티가 없다면 두세요.",
		["{npc:12759}, a corrupted water elemental, drifts in {area:421}. Her {item:16408} starts a quest for Splintertree."] = "타락한 물의 정령 {npc:12759}은(는) {area:421}을(를) 떠다닙니다. 그녀의 {item:16408}은(는) 토막나무 주둔지 퀘스트를 시작합니다.",
		["{npc:12867} stands at the lumber camp. The night elf Outrunners stalk the woods south-east of it; they stealth, so watch for them."] = "{npc:12867}은(는) 벌목기지에 서 있습니다. 나이트 엘프 정찰병은 그 남동쪽 숲에 숨어 있습니다. 은신하므로 주의하세요.",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "Forever에서 추가된 {npc:210995}은(는) {area:421} 서쪽 기슭에서 간단한 용 사냥꾼 퀘스트 세 개를 줍니다.",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986}은(는) 갈라크일족 야영지 동쪽 고원 꼭대기에 서 있습니다. {quest:1149}에서는 그 옆 널빤지 끝에서 걸어 떨어지세요. 안전하게 착지합니다.",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, around level 38"] = "{npc:4454}: 그의 편지는 38레벨쯤 {zone:1418}의 마르텍에게 전합니다",
		["{npc:4499}, a hard-hitting rock elemental, walks the cliffs of {area:482}. {npc:4499} is elite: grouping up is advised."] = "강하게 때리는 바위 정령 {npc:4499}이 {area:482} 절벽을 돌아다닙니다. {npc:4499}은(는) 정예입니다. 파티를 권장합니다.",
		["{npc:4877}, the trade supplies vendor: the Screeching harpies of {area:487}"] = "교역품 상인 {npc:4877}: {area:487}의 회오리 하피",
		["{object:176344}, north-west camp"] = "{object:176344}, 북서쪽 야영지",
		["{object:176344}, south-east camp"] = "{object:176344}, 남동쪽 야영지",
		["{object:176344}, south-west camp"] = "{object:176344}, 남서쪽 야영지",
		["{object:19868} lies all over the flats north of the raceway. Scorpid Reavers and Sparkleshell Tortoises roam the north half, Salt Flats Scavengers circle overhead, and Saltstone Basilisks graze west of the track. The Crystalhides roam the middle of the flats and the Gazers (34-35, five levels above you: one at a time) the far south."] = "{object:19868}은(는) 경주장 북쪽 평원 곳곳에 있습니다. 붉은독전갈과 소금껍질거북은 북쪽 절반을 돌아다니고, 소금 평원 청소부독수리는 하늘을 맴돌며, 소금바위 바실리스크는 경주장 서쪽에서 풀을 뜯습니다. 수정바실리스크는 평원 중앙을, 큰눈바실리스크(34-35, 나보다 다섯 레벨 높음: 한 번에 하나씩)는 남쪽 끝을 돌아다닙니다.",
} end)()
t.guides["forever/horde/30-40/01-desolace"] = (function() return {
		["Back at {area:609}, every Kolkar can drop an ear."] = "{area:609}에서는 모든 콜카르일족이 귀를 떨어뜨릴 수 있습니다.",
		["Back to {area:272}"] = "{area:272}(으)로 돌아가기",
		["Clam beds"] = "조개 서식지",
		["Daggerspine naga"] = "비수가시일족 나가",
		["Daggerspine shore"] = "비수가시일족 해안",
		["Do your shopping in the {area:1497} first, then fly to the {area:228}. The {object:113791} stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the {npc:5895} and keep the {item:7813} for {npc:5901}. Fly on to {area:272} from the {area:228}."] = "먼저 {area:1497}에서 쇼핑을 마친 뒤 {area:228}(으)로 날아가세요. {object:113791}은(는) 그 바로 남서쪽 언덕에 있습니다. 옆의 타락한 물의 현신을 쓰러뜨리고, 그 손목보호대를 화로에 넣은 뒤 {npc:5895}에게 말을 걸고, {item:7813}은(는) {npc:5901}을(를) 위해 보관하세요. {area:228}에서 {area:272}(으)로 날아가세요.",
		["Fly to the {area:1497}"] = "{area:1497}(으)로 날아가기",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Fly to {area:1638} from Shadowprey and train with {npc:3033} on {area:1639}, then fly on to {zone:1454}."] = "그늘수렵 마을에서 {area:1638}(으)로 날아가 {area:1639}의 {npc:3033}에게서 기술을 배운 뒤, {zone:1454}(으)로 날아가세요.",
		["Fly to {area:392}. {npc:5901} camps on the coast a short ride south of the town."] = "{area:392}(으)로 날아가세요. {npc:5901}은(는) 마을 남쪽으로 조금 떨어진 해안에 야영하고 있습니다.",
		["Fly to {area:460}"] = "{area:460}(으)로 날아가기",
		["Fly to {area:484}. {npc:5905} hides in a small cave in the canyon wall north-east of the post."] = "{area:484}(으)로 날아가세요. {npc:5905}은(는) 주둔지 북동쪽 협곡 벽의 작은 동굴에 숨어 있습니다.",
		["Follow the road north out of {area:272} into the Alterac foothills. {quest:535} waits by the Syndicate camp; hand him the stout."] = "길을 따라 {area:272}에서 북쪽으로 알터랙 산기슭으로 가세요. {quest:535}은(는) 비밀결사대 야영지 옆에서 기다립니다. 흑맥주를 건네세요.",
		["Follow the road south-west out of Sun Rock into {zone:1443} and on south past {area:608}. {npc:11625}'s kodo caravan waits by the road north of {area:609}; if it has already left, ride on."] = "해바위 야영지에서 길을 따라 남서쪽으로 {zone:1443}에 들어가 {area:608}을(를) 지나 계속 남쪽으로 가세요. {npc:11625}의 코도 대상단은 {area:609} 북쪽 길가에서 기다립니다. 이미 떠났다면 계속 가세요.",
		["Follow the shore west past {area:271}'s bay; the Torn Fin murlocs camp on the beaches beyond it."] = "해안을 따라 서쪽으로 {area:271}의 만을 지나가세요. 너덜지느러미멀록은 그 너머 해변에 야영하고 있습니다.",
		["From {area:484}, fly to {area:1637}."] = "{area:484}에서 {area:1637}(으)로 날아가세요.",
		["Gizelton caravan"] = "기젤톤 대상단",
		["Head west along the foot of the mountains to the violet dome of {area:279}. {npc:2411}, {npc:2412} and {npc:2413} (33-34) stand together inside the crater's eastern rim, {npc:2414} (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-32) around them drop the Worn Stone Tokens."] = "산기슭을 따라 서쪽으로 {area:279}의 보랏빛 돔으로 가세요. {npc:2411}, {npc:2412}, {npc:2413}(33-34)은(는) 분화구 동쪽 가장자리 안쪽에 함께 서 있고, {npc:2414}(35)은(는) 그 조금 서쪽에 있습니다. 각자 피의 돌 조각을 하나씩 지니고 있습니다. 주변의 수호기사와 사술사(31-32)가 닳은 돌 징표를 떨어뜨립니다.",
		["Hearth back (or ride north if it is on cooldown)."] = "귀환석으로 돌아가세요(재사용 대기 중이면 북쪽으로 달려가세요).",
		["His next errand is not on this route."] = "그의 다음 심부름은 이 경로에 없습니다.",
		["Keep north to {area:598}. The Oracles stand among the other naga at its north end; pull one at a time."] = "계속 북쪽의 {area:598}(으)로 가세요. 예언자는 북쪽 끝에 다른 나가들과 함께 있습니다. 한 번에 하나씩 끌어오세요.",
		["Kolkar ears"] = "콜카르일족 귀",
		["Leave {zone:1454} by the main gate; the zeppelin tower stands just north-east of it. Take the {area:1497} zeppelin."] = "정문으로 {zone:1454}을(를) 나가세요. 비행선 탑은 그 바로 북동쪽에 있습니다. {area:1497}행 비행선을 타세요.",
		["North along the eastern hills, the satyrs hold the ruins of {area:603}. The Shadowstalkers walk unseen; the four kinds you need do not."] = "동쪽 언덕을 따라 북쪽으로 가면 사티로스가 {area:603}의 폐허를 차지하고 있습니다. 그림자추적자는 보이지 않게 다니지만, 필요한 네 종류는 그렇지 않습니다.",
		["Place the {object:1729} on the {object:1728} beside the inn"] = "여관 옆의 {object:1728} 위에 {object:1729}을(를) 놓으세요",
		["Ride back east to {area:272}."] = "동쪽의 {area:272}(으)로 돌아가세요.",
		["Ride back north to {area:272}, keeping west of {area:271}."] = "{area:271} 서쪽으로 북쪽의 {area:272}까지 돌아가세요.",
		["Ride back south to the post."] = "남쪽의 주둔지로 돌아가세요.",
		["Ride back south to {area:272}."] = "남쪽의 {area:272}(으)로 돌아가세요.",
		["Ride north past {quest:535}'s camp to {area:280}, the Syndicate-held village (35-37). {npc:2431} carries the {item:3704}; {quest:503} sits in a cage in the house on the north side."] = "{quest:535}의 야영지를 지나 북쪽으로 비밀결사대가 차지한 마을 {area:280}(35-37)(으)로 가세요. {npc:2431}이(가) {item:3704}을(를) 지니고 있습니다. {quest:503}은(는) 북쪽 집 안의 우리에 갇혀 있습니다.",
		["Ride north up the coast. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach; open each clam in your bags for its meat."] = "해안을 따라 북쪽으로 가세요. 커다란 연갑 조개는 얕은 물에 있고, 사나운 모래톱게는 해변을 돌아다닙니다. 조개는 가방에서 열어 살을 꺼내세요.",
		["Ride north-east to {area:609}. {quest:1365} (35) walks among the tents on the east side with a Battle Lord or two (32-33): clear around him, then pull him alone at full health."] = "북동쪽의 {area:609}(으)로 가세요. {quest:1365}(35)은(는) 전투대장 한두 명(32-33)과 함께 동쪽 천막 사이를 돌아다닙니다. 주변을 정리한 뒤 생명력이 가득 찬 상태에서 그만 끌어오세요.",
		["Ride south, east of {area:271}, down to the coast. The Daggerspine naga line the shore south-east of the town."] = "{area:271} 동쪽으로 남쪽 해안까지 내려가세요. 비수가시일족 나가가 마을 남동쪽 해안에 늘어서 있습니다.",
		["Ride south-east to the post."] = "남동쪽의 주둔지로 가세요.",
		["Ride south-west to the troll village on the coast, keeping clear of the {area:606} on the way."] = "남서쪽 해안의 트롤 마을로 가세요. 가는 길에 {area:606}은(는) 피하세요.",
		["Ride south-west towards Shadowprey. The Gelkis centaurs (32-35) around their village are a good camp; fight them until level 32."] = "남서쪽의 그늘수렵 마을 쪽으로 가세요. 마을 주변의 겔키스일족 켄타우로스(32-35)는 사냥하기 좋습니다. 32레벨까지 처치하세요.",
		["Ride west to {area:599}. Beat a Burning Blade cultist down, then use the {item:6436} on it before it dies to fill one {item:6435}. They also drop a {item:20310} now and then (1-5%); if one drops, read it."] = "서쪽의 {area:599}(으)로 가세요. 불타는 칼날단 이교도를 거의 죽을 때까지 때린 뒤, 죽기 전에 {item:6436}을(를) 사용해 {item:6435}을(를) 하나 채우세요. 가끔(1-5%) {item:20310}도 떨어뜨립니다. 얻으면 읽으세요.",
		["Shadowstalker scalp"] = "그림자추적자의 머리가죽",
		["Shindigger keg"] = "신디거 흑맥주 통",
		["Slitherblade Oracles"] = "뱀갈퀴일족 예언자",
		["South-west, the Cave and Ferocious Yetis (30-31) fill the caves in the hills west of {area:272}; about one in sixteen carries the rod."] = "남서쪽, {area:272} 서쪽 언덕의 동굴에는 동굴 설인과 사나운 설인(30-31)이 가득합니다. 열여섯 마리 중 한 마리 정도가 막대를 지니고 있습니다.",
		["Syndicate missives"] = "비밀결사대 서신",
		["Thaivand's next task ends at {area:271}'s graveyard and the magus offers a dungeon errand: leave both."] = "타이반드의 다음 임무는 {area:271} 묘지에서 끝나고, 마법사는 던전 심부름을 줍니다. 둘 다 받지 마세요.",
		["The Hatefury Shadowstalkers at {area:603} walk unseen until they strike; about one in three carries a scalp."] = "{area:603}의 서릿발분노의 그림자추적자는 공격할 때까지 보이지 않습니다. 세 마리 중 한 마리 정도가 머리가죽을 지니고 있습니다.",
		["The Seer stands on the south side of {area:599}, east of {area:2405}. Clear the cultists around it first."] = "현자는 {area:2405} 동쪽, {area:599} 남쪽에 서 있습니다. 먼저 주변의 이교도를 처치하세요.",
		["The Syndicate Footpads and Thieves (32-33) around the camps west of the road carry the missives; about one in three drops one."] = "길 서쪽 야영지 주변의 비밀결사대 노상강도와 도둑(32-33)이 서신을 지니고 있습니다. 세 명 중 한 명 정도가 떨어뜨립니다.",
		["The caravan rolls south past {area:609}. Kolkar raiders ambush it in waves: kill them before they reach {npc:11625}. It stops by {area:2617}, east of {area:597}."] = "대상단은 {area:609}을(를) 지나 남쪽으로 이동합니다. 콜카르일족 약탈자가 여러 차례 습격합니다. {npc:11625}에게 닿기 전에 처치하세요. 대상단은 {area:597} 동쪽의 {area:2617} 옆에서 멈춥니다.",
		["The keg stands with a few others at the Syndicate camp on the south-east coast of {area:287}."] = "맥주 통은 {area:287} 남동쪽 해안의 비밀결사대 야영지에 다른 통 몇 개와 함께 있습니다.",
		["The next guide starts in the {area:1497}, at the {object:3202} zeppelin."] = "다음 가이드는 {area:1497}의 {object:3202}행 비행선에서 시작합니다.",
		["The {area:279} traitors"] = "{area:279}의 배신자",
		["Torn Fin beach"] = "너덜지느러미멀록 해변",
		["Torn Fin murlocs"] = "너덜지느러미멀록",
		["Train"] = "기술 배우기",
		["Train your new spells."] = "새 주문을 배우세요.",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. Five kodos, one at a time."] = "묘지의 늙은 코도, 임종의 코도, {npc:4702}에게 {npc:11596}의 {item:13892}을(를) 사용하고, 길들인 코도를 {npc:11596}에게 데려가세요. 다섯 마리를 한 번에 한 마리씩 데려갑니다.",
		["Your trainer is in {area:1638}, one flight away: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly on to {area:460} from there."] = "직업 상급자는 비행 한 번 거리의 {area:1638}에 있습니다: {area:1639}의 {npc:3033}(드루이드), {npc:246344}(성기사). 그곳에서 {area:460}(으)로 날아가세요.",
		["Zeppelin to the {area:1497}"] = "{area:1497}행 비행선",
		["Zeppelin tower"] = "비행선 탑",
		["for {npc:5901}: from Stranglethorn, next guide"] = "{npc:5901}에게: 다음 가이드에서 가시덤불 골짜기에서",
		["grind on Gelkis Stampers and Windchasers at the {area:606}, {zone:1443}"] = "{zone:1443} {area:606}에서 겔키스일족 곤봉잡이와 바람전사 사냥",
		["{area:2408} flight master"] = "{area:2408} 비행 조련사",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}: {quest:515}을(를) 위해 경매장이나 연금술사에게서",
		["{item:3703}, for {npc:2333}"] = "{npc:2333}에게 줄 {item:3703}",
		["{npc:11863} waits in the ruined tower of {area:2405}, inland to the south-east."] = "{npc:11863}은(는) 내륙 남동쪽 {area:2405}의 무너진 탑에서 기다립니다.",
		["{npc:11877}: for {npc:715} in Stranglethorn"] = "{npc:11877}: 가시덤불 골짜기의 {npc:715}에게",
		["{npc:2229}: for the {zone:1413}, later on the route"] = "{npc:2229}: 나중에 경로상의 {zone:1413}에서",
		["{npc:260093} trains Paladins in the {area:1497}."] = "{npc:260093}은(는) {area:1497}에서 성기사를 가르칩니다.",
		["{npc:2770}: for {area:321} in Arathi, later on the route"] = "{npc:2770}: 나중에 경로상의 아라시 고원 {area:321}에서",
		["{npc:4551}, the bat handler"] = "박쥐 조련사 {npc:4551}",
		["{npc:4949}, Grommash Hold, if you carry it"] = "그롬마쉬 요새의 {npc:4949}, 가지고 있다면",
		["{npc:5395} stands in the post; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395}은(는) 주둔지에 있고, {npc:5641}와(과) {npc:4498}은(는) 그 서쪽, {area:596} 위의 언덕에서 기다립니다.",
		["{npc:5639} waits in the Drag; {npc:5640} stands in the {object:172961} on the west side of the city. Skyborne: {npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:5639}은(는) 골목길에서 기다리고, {npc:5640}은(는) 도시 서쪽의 {object:172961}에 서 있습니다. 스카이본: {npc:4949}은(는) {object:172957}의 그롬마쉬 요새에서 기다립니다.",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "{npc:5641}의 다음 심부름은 정예 호위병을 거느린 악마 군주를 쫓게 합니다. 건너뛰세요.",
		["{npc:5641}'s next {quest:1431} sends you back to {zone:1454} for nothing: leave it."] = "{npc:5641}의 다음 퀘스트인 {quest:1431}은(는) 아무 소득 없이 {zone:1454}(으)로 돌려보냅니다. 받지 마세요.",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892}은(는) {object:172957}에 서 있습니다.",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905}은(는) 폭풍의 무기로 이어지는 33-40 연계 퀘스트인 정기의 도움({area:1717})도 줍니다: forever/class/shaman/call-of-air-horde.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: {item:5178}",
		["{quest:515} needs a {item:3388}, an {skill:171} item: buy one at the auction house here if you can (or ask an alchemist). No potion: skip the Elixir steps in {area:287}."] = "{quest:515}에는 {skill:171} 아이템인 {item:3388}이(가) 필요합니다. 가능하면 이곳 경매장에서 사세요(또는 연금술사에게 부탁하세요). 물약이 없으면 {area:287}의 비약 단계는 건너뛰세요.",
		["{zone:1454} class quests"] = "{zone:1454} 직업 퀘스트",
} end)()
t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "북쪽의 야영지로 돌아가세요.",
		["Back to {object:3202}"] = "{object:3202}(으)로 돌아가기",
		["Back to {object:3202}."] = "{object:3202}(으)로 돌아가세요.",
		["Basilisks and the Bloodscalp village"] = "바실리스크와 붉은머리부족 마을",
		["Bloodscalp headhunters"] = "붉은머리부족 인간사냥꾼",
		["Bloodscalp ruins"] = "붉은머리부족 폐허",
		["East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}."] = "오우거 동쪽에서는 그림자퓨마(37-38)가 공격할 때까지 보이지 않게 숨어 다닙니다. 가시덤불 암호랑이도 같은 곳을 돌아다니며 가끔 온전한 암호랑이의 송곳니를 떨어뜨립니다. 무쇠턱 악어는 정글 바로 서쪽 강을 따라 있습니다. 가죽은 {npc:2495}에게 줄 수 있도록 보관하세요.",
		["Elder tigers and Lashtail raptors"] = "덩치큰 호랑이와 채찍꼬리랩터",
		["Fly to {area:35}"] = "{area:35}(으)로 날아가기",
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "길을 따라 {object:3202}에서 북쪽으로 나가세요. 네싱워리의 사냥 야영지는 강 북동쪽 언덕에 있습니다. 지금부터 얻는 {quest:338}의 모든 쪽은 보관하세요. 나중에 {npc:716}이(가) 요구합니다.",
		["Follow the road north to the camp."] = "길을 따라 북쪽의 야영지로 가세요.",
		["Follow the road on south into {area:35}."] = "길을 따라 계속 남쪽의 {area:35}(으)로 가세요.",
		["Follow the road south to {area:35} at the southern tip of the vale and enter through the tunnel in the cliffs. Stay on the road: the jungle beside it is well above your level. {npc:2858}, the Horde flight master, waits on the upper deck."] = "길을 따라 골짜기 남쪽 끝의 {area:35}(으)로 가서 절벽의 터널로 들어가세요. 길에서 벗어나지 마세요. 길 옆 정글은 레벨이 훨씬 높습니다. 호드 비행 조련사 {npc:2858}은(는) 위층 갑판에 있습니다.",
		["Follow the road south to {object:3202}."] = "길을 따라 남쪽의 {object:3202}(으)로 가세요.",
		["Green Hills pages"] = "푸른 언덕의 쪽",
		["Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it."] = "야영지를 지나 서쪽으로 가세요. 가시덤불랩터(33-34)는 빈터에서 사냥하고, 붉은머리부족 트롤은 해안의 폐허를 차지하고 있습니다. 붉은머리부족은 누구나 붉은머리부족의 어금니를 떨어뜨릴 수 있습니다. 이들은 {item:4614}을(를) 매우 드물게 떨어뜨립니다. 얻으면 읽으세요.",
		["Hearth to {area:35}"] = "귀환석으로 {area:35}에 가기",
		["Hearth to {object:3202}"] = "귀환석으로 {object:3202}에 가기",
		["Jungle Stalkers"] = "줄무늬정글랩터",
		["Lashtail raptors"] = "채찍꼬리랩터",
		["Leave the {zone:1458} by the lift and walk up through the ruins to the zeppelin towers; the {object:3202} zeppelin is the one on the south-west tower."] = "승강기를 타고 {zone:1458}을(를) 나가 폐허를 지나 비행선 탑으로 올라가세요. {object:3202}행 비행선은 남서쪽 탑에 있습니다.",
		["Mistvale gorillas"] = "안개계곡고릴라",
		["Mosh'Ogg camp"] = "모쉬오그일족 야영지",
		["Nesingwary's camp"] = "네싱워리의 야영지",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "그롬골 북서쪽 해안 앞바다 물속에 {area:104}이(가) 있습니다. {item:4094}은(는) 가라앉은 폐허 옆 바닥에 있습니다. 숨과 멀록을 조심하세요.",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "{item:2755}의 쪽은 붉은머리부족과 백골가루부족 트롤에게서 각각 약 1% 확률로 떨어집니다. 얻은 쪽은 모두 보관하고 나머지는 경매장에서 찾아보세요. {npc:716}은(는) 이 가이드 후반에 장을 받습니다.",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; take what drops and check the Auction House for the rest."] = "{item:2755}의 쪽은 붉은머리부족과 백골가루부족 트롤에게서 각각 약 1% 확률로 떨어집니다. 떨어지는 것은 챙기고 나머지는 경매장에서 확인하세요.",
		["Raptors and the Bloodscalp trolls"] = "랩터와 붉은머리부족 트롤",
		["Ride back south to {object:3202}."] = "남쪽의 {object:3202}(으)로 돌아가세요.",
		["Ride north past Nesingwary's camp to the lake. The Venture Co. Geologists (34-36) work the camps along its western shore; they carry the Tumbled Crystals."] = "네싱워리의 야영지를 지나 북쪽 호수로 가세요. 투자개발회사 지질학자(34-36)가 서쪽 호숫가의 야영지에서 일하며, 연마된 수정을 지니고 있습니다.",
		["Ride south down the coast to {object:3202} and fly to {area:35}."] = "해안을 따라 남쪽의 {object:3202}(으)로 간 뒤 {area:35}(으)로 날아가세요.",
		["Shadowmaw jungle and the Snapjaw river"] = "그림자퓨마 정글과 무쇠턱 악어 강",
		["Shadowmaw panthers"] = "그림자퓨마",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "가시덤불 호랑이와 퓨마(32-33)는 야영지 동쪽, 호숫가를 따라 언덕을 돌아다닙니다.",
		["Take the road south towards {area:35}. The Elder Mistvale Gorillas (40-41) live in {area:1737}, east of the road; about one in twenty carries an aged sinew."] = "길을 따라 남쪽 {area:35} 방향으로 가세요. 덩치큰 안개계곡고릴라(40-41)는 길 동쪽의 {area:1737}에 살며, 약 20마리 중 1마리가 덩치큰 고릴라의 힘줄을 지니고 있습니다.",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and fly to {area:392}. {npc:5901} camps on the coast a short ride south of it."] = "{object:3202} 서쪽 탑에서 {zone:1454}행 비행선을 타고 {area:392}(으)로 날아가세요. {npc:5901}은(는) 그 남쪽으로 조금 떨어진 해안에 야영하고 있습니다.",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and train in the city before you fly on."] = "{object:3202} 서쪽 탑에서 {zone:1454}행 비행선을 타고, 다시 날아가기 전에 도시에서 기술을 배우세요.",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads."] = "해안 마을의 붉은머리부족 인간사냥꾼(36-37)이 쭈그러든 해골을 지니고 있습니다.",
		["The Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "붉은머리부족 트롤은 암초 북쪽 해안의 폐허와 그 너머 마을을 차지하고 있으며, 누구나 {item:3915}을(를) 떨어뜨릴 수 있습니다. {quest:338}의 쪽도 계속 챙기세요.",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards {object:3202}."] = "덩치큰 가시덤불 호랑이(34-35)는 야영지 남서쪽 언덕을 돌아다니고, 채찍꼬리랩터(35-36)는 더 남쪽, {object:3202} 쪽에서 사냥합니다.",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "줄무늬정글랩터(40-41)는 {object:3202} 남쪽 해안에서 사냥합니다. 레벨이 훨씬 높으니 한 마리씩 끌어오고 전투 사이에 쉬세요.",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "채찍꼬리랩터(35-36)는 {object:3202} 바로 북동쪽 정글에서 사냥합니다.",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}. Kill one Brute and one Witch Doctor (36-37); pull them one at a time."] = "모쉬오그일족 오우거는 {object:3202} 바로 동쪽 언덕에 야영하고 있습니다. 모쉬오그일족 투사와 모쉬오그일족 의술사(36-37)를 하나씩 처치하세요. 한 마리씩 끌어오세요.",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "그림자퓨마(37-38)는 모쉬오그일족 언덕 동쪽과 북동쪽 호수 방향 정글에 숨어 다니며, 은신 상태에서 공격합니다. 가는 길에 보이는 푸른 언덕의 쪽은 모두 챙기세요.",
		["The camp by the river"] = "강가의 야영지",
		["The next guide flies you north to {area:272} and into the {zone:1417}."] = "다음 가이드에서는 북쪽의 {area:272}(으)로 날아가 {zone:1417}(으)로 갑니다.",
		["The zeppelin lands at the tower on the west side of the camp."] = "비행선은 주둔지 서쪽의 탑에 도착합니다.",
		["Tigers and panthers"] = "호랑이와 퓨마",
		["Venture Co. camp"] = "투자개발회사 야영지",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear."] = "야영지를 지나 서쪽 바위 위에 수정가시 바실리스크(34-35)가 있습니다. 그 너머 마을의 붉은머리부족은 누구나 붉은머리부족의 귀를 떨어뜨릴 수 있습니다.",
		["Young Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it."] = "새끼 가시덤불 호랑이는 야영지 서쪽에, 새끼 퓨마는 남쪽과 동쪽에 돌아다닙니다.",
		["Young tigers and panthers"] = "새끼 호랑이와 퓨마",
		["Zeppelin to {object:3202}"] = "{object:3202}행 비행선",
		["Zeppelin towers"] = "비행선 탑",
		["{npc:2495}: the Snapjaw skins gathered earlier"] = "{npc:2495}: 앞서 모은 무쇠턱 악어 가죽",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: 경로 후반의 아라시 고원용",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527}와(과) {item:5177}",
		["{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp."] = "레벨 37 호랑이 {npc:729}은(는) 야영지 남서쪽 언덕 꼭대기를 돌아다닙니다.",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "{npc:773}의 실종된 사냥꾼들의 야영지는 네싱워리의 야영지입니다. 천막 사이를 걸으면 조사가 완료됩니다. 민물악어는 야영지 아래 강을 따라 있습니다.",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Back to {area:321}"] = "{area:321}(으)로 돌아가기",
		["Boulderfist camp"] = "돌주먹일족 야영지",
		["Cast {spell:18960} and take {npc:11798}'s flight to {area:1638}; {npc:3033} trains you on {area:1639}. Then fly to {zone:1454} and take the {zone:1458} zeppelin from the tower outside the main gate."] = "{spell:18960}을(를) 시전하고 {npc:11798}에게서 {area:1638}행 비행편을 타세요. {area:1639}의 {npc:3033}이(가) 기술을 가르쳐 줍니다. 그다음 {zone:1454}(으)로 날아가 정문 밖의 탑에서 {zone:1458}행 비행선을 타세요.",
		["Coyotes and buzzards"] = "코요테와 대머리수리",
		["Daggerspine shore"] = "비수가시일족 해안",
		["Each {object:180105} is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of {area:321}."] = "각 {object:180105}은(는) 선돌이 둥글게 늘어선 곳으로, 열쇠는 한가운데 돌 위에 있습니다. 동쪽 결속의 원은 {area:321} 북서쪽 언덕에 있습니다.",
		["Escort the professor down to the shore. Two Daggerspine naga ambush him on the way: stay close."] = "학자를 해안까지 호위하세요. 가는 길에 비수가시일족 나가 둘이 습격합니다. 가까이 붙어 있으세요.",
		["Fleshstalker raptors"] = "식인 고원랩터",
		["Fly to {area:272}"] = "{area:272}(으)로 날아가기",
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["Follow the road north; {npc:4618}'s camp is on the way."] = "길을 따라 북쪽으로 가세요. {npc:4618}의 야영지가 가는 길에 있습니다.",
		["From {area:35}, fly to {object:3202}. {object:1661} zeppelin leaves from the tower on the west side of the camp."] = "{area:35}에서 {object:3202}(으)로 날아가세요. {object:1661}행 비행선은 야영지 서쪽 탑에서 출발합니다.",
		["Greater Rock Elementals"] = "상급 바위 정령",
		["Hearth to {area:340}"] = "귀환석으로 {area:340}에 가기",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "식인 고원랩터(36-37)는 고원 남부에서 사냥합니다. 한 무리는 {area:316} 북쪽에, 다른 무리는 그 서쪽 평원에 있습니다. 한 번에 한 마리씩 끌어오세요.",
		["Highland Striders roam the hills all around {area:321}; both they and the Thrashers further west drop the eyes."] = "줄무늬 고원랩터는 {area:321} 주변 언덕 곳곳을 돌아다닙니다. 이들과 더 서쪽의 외뿔 고원랩터 모두 눈알을 떨어뜨립니다.",
		["Highland raptors"] = "고원랩터",
		["Into the {zone:1418}"] = "{zone:1418}(으)로",
		["Keep north on the road; the chest lies in the {area:1517} dig site, at the foot of the ruins north-west of the road."] = "길을 따라 계속 북쪽으로 가세요. 상자는 길 북서쪽 폐허 기슭의 {area:1517} 발굴지에 있습니다.",
		["Lesser Rock Elementals"] = "하급 바위 정령",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael."] = "해머폴 북동쪽 골짜기에서 마른수염 코볼트가 채굴하고 있습니다. 입구의 코볼트와 안쪽의 채굴꾼, 흙점쟁이 모두 미즈라엘의 결정 파편을 떨어뜨립니다.",
		["Ride back south down the road, past the {area:1877}."] = "길을 따라 남쪽으로 {area:1877}을(를) 지나 돌아가세요.",
		["Ride back south to the {area:380} and fly to {area:392}."] = "남쪽의 {area:380}(으)로 돌아가 {area:392}(으)로 날아가세요.",
		["Ride east out of {area:272} through {area:1857} and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south-east of {area:313}."] = "{area:272}에서 동쪽으로 {area:1857}을(를) 지나 길을 따라 동쪽으로 가세요. 돌주먹 오우거와 집행자(32-34)는 {area:313} 남동쪽, 길 남쪽에 야영하고 있습니다.",
		["Ride north back to {area:340}."] = "북쪽의 {area:340}(으)로 돌아가세요.",
		["Ride north up the road from the {area:380} to the {area:386}; {npc:3389} keeps watch on the rise above the water."] = "{area:380}에서 길을 따라 북쪽의 {area:386}(으)로 가세요. {npc:3389}은(는) 물 위쪽 언덕에서 망을 보고 있습니다.",
		["Ride north; the outer circle stands in the middle of the highlands."] = "북쪽으로 가세요. 바깥 결속의 원은 고원 한가운데에 있습니다.",
		["Ride south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "{area:392}에서 해안을 따라 남쪽의 {area:720}(으)로 가세요. {npc:6236}은(는) 투기장 옆에 서 있습니다. 쇠창살을 밟으면 싸움이 시작됩니다. 도전자가 한 명씩 나온 뒤 {npc:6238}(33)이(가) 나옵니다.",
		["Ride south-west out of Arathi over {area:880}, south through the {zone:1437} (keep clear of {area:150}) and east into {zone:1432}; the road leaves {zone:1432} to the south into the {zone:1418}. Follow it south to the goblin camp in the {area:1877}."] = "아라시 고원에서 남서쪽으로 {area:880}을(를) 건너, {zone:1437}을(를) 지나 남쪽으로 가고({area:150}은(는) 피하세요), 동쪽 {zone:1432}(으)로 들어가세요. 길은 {zone:1432}에서 남쪽 {zone:1418}(으)로 이어집니다. 길을 따라 남쪽의 {area:1877} 고블린 야영지로 가세요.",
		["Ride south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "남서쪽으로 남부 해안의 고블린 만으로 가세요. {npc:2766}은(는) 그 위 절벽에서 망을 봅니다.",
		["Ride west along the road; {npc:2921}'s camp sits in the {area:1878} halfway to {area:340}."] = "길을 따라 서쪽으로 가세요. {npc:2921}의 야영지는 {area:340}(으)로 가는 중간쯤, {area:1878}에 있습니다.",
		["Rock Elementals"] = "바위 정령",
		["Stonevault troggs"] = "바위동굴일족 트로그",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202}."] = "{object:3202} 서쪽 탑에서 {zone:1454}행 비행선을 타세요.",
		["The Boulderfist Brutes camp outside the ogres' hall south of {area:321}; the Magus stand among them. Pull them one at a time."] = "돌주먹일족 투사는 {area:321} 남쪽 오우거 전당 밖에 야영하고 있으며, 사제가 그들 사이에 있습니다. 한 번에 하나씩 끌어오세요.",
		["The Elder Crag Coyotes and Giant Buzzards roam the basin south of the {area:1878}. Coyotes drop both the jawbones and the fangs; only the buzzards drop wings and gizzards."] = "덩치큰 바위산코요테와 거대한 대머리수리는 {area:1878} 남쪽 분지를 돌아다닙니다. 코요테는 턱뼈와 송곳니를 모두 떨어뜨리고, 날개와 모래주머니는 대머리수리만 떨어뜨립니다.",
		["The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "상급 바위 정령(42-44, 레벨이 훨씬 높음)은 남서쪽 협곡을 돌아다닙니다. 손목보호대는 다섯 마리 중 한 마리 정도가 떨어뜨립니다. 한 번에 하나씩 끌어오고 전투 사이에 쉬거나, 그냥 두세요. 가는 길에 아직 필요한 코요테와 대머리수리를 계속 처치하세요.",
		["The Stonevault troggs dig around the cave mouths south of the {area:1877}, on the way to {area:345}; the Bonesnappers and Shamans drop the flakes."] = "바위동굴일족 트로그는 {area:1877} 남쪽, {area:345}(으)로 가는 길의 동굴 입구 주변을 파헤치고 있습니다. 뼈다귀싸움꾼과 주술사가 조각을 떨어뜨립니다.",
		["The Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets."] = "비밀결사대가 북서쪽의 담장 두른 저택과 농장을 차지하고 있습니다. 강도, 용병, 추적자가 혈석 아뮬렛을 지니고 있습니다.",
		["The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village."] = "마른나무껍질부족 트롤이 남동쪽 언덕의 마을을 차지하고 있습니다. 바깥 오두막은 도끼투척병이 지키고, 마을 중심부는 의술사와 인간사냥꾼이 차지하고 있습니다.",
		["The bigger Rock Elementals stand on the slopes north-west of the {area:1878}; each one drops a slab."] = "더 큰 바위 정령은 {area:1878} 북서쪽 비탈에 서 있습니다. 각각 석판을 떨어뜨립니다.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "안쪽 결속의 원은 서쪽 결속의 원 남쪽, 스트롬가드 동쪽에 있습니다.",
		["The next guide heads into {zone:1445}."] = "다음 가이드는 {zone:1445}(으)로 향합니다.",
		["The orc stronghold at the eastern end of the road. Urda, the wind rider master, stands by the gate."] = "길 동쪽 끝의 오크 요새입니다. 윈드라이더 조련사 우르다는 정문 옆에 서 있습니다.",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "작은 정령들은 {npc:2921}의 야영지 바로 서쪽 평지를 떠다닙니다. 이 지역의 바위 정령은 모두 {npc:6868}에게 줄 바위 정령 파편을 떨어뜨릴 수 있습니다. 보관하세요.",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "이 돌의 다음 임무에는 42레벨 정예인 포즈루크를 처치해야 합니다. 받지 마세요.",
		["The violet shards glow just off the road a short way west of {area:321}."] = "보랏빛 파편은 {area:321} 조금 서쪽, 길 바로 옆에서 빛나고 있습니다.",
		["The western circle is near {area:1857}, where you rode in."] = "서쪽 결속의 원은 처음 들어온 {area:1857} 근처에 있습니다.",
		["The zeppelin lands at the towers outside the {zone:1458}: ride down into the city and fly to {area:272}."] = "비행선은 {zone:1458} 밖의 탑에 도착합니다. 도시로 내려가 {area:272}(으)로 날아가세요.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2689}"] = "{object:2689}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701}은(는) 골짜기 맨 끝에 있습니다.",
		["The {object:2702}"] = "{object:2702}",
		["Theldurin sits among the dwarven ruins at {area:345}, south of the {area:1877}."] = "텔두린은 {area:1877} 남쪽, {area:345}의 드워프 폐허 사이에 앉아 있습니다.",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "{zone:1458}에 있는 동안 기술을 배우세요. 상급자는 {object:36070}, {object:36073}, {object:36082}에 있습니다(성기사: {npc:260093}).",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "만 서쪽 해안은 비수가시일족 침략자와 여마법사(38-40)가 차지하고 있습니다. 한 번에 하나씩 끌어오세요. 난파선 두 척은 앞바다 얕은 물에 있으며, 해도와 항해일지는 그 안에, 보석은 난파선 주변 해저에 있습니다.",
		["Your trainer is in {area:1638}, one flight from {zone:1454}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly on to the {area:380} from there."] = "직업 상급자는 {zone:1454}에서 비행 한 번 거리의 {area:1638}에 있습니다: {area:1639}의 {npc:3033}(드루이드), {npc:246344}(성기사). 그곳에서 {area:380}(으)로 날아가세요.",
		["Zeppelin to the {zone:1458}"] = "{zone:1458}행 비행선",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["Zeppelin tower"] = "비행선 탑",
		["for Helgrum in {area:75}, around level 42"] = "42레벨쯤 {area:75}의 헬그럼에게",
		["for {npc:2487} in {area:35}, around level 44"] = "44레벨쯤 {area:35}의 {npc:2487}에게",
		["for {npc:5395} in {zone:1443}, in the next guide"] = "다음 가이드에서 {zone:1443}의 {npc:5395}에게",
		["{area:340} is the Horde fortress built into the cliffs at the zone's western edge."] = "{area:340}은(는) 지역 서쪽 끝 절벽에 지어진 호드 요새입니다.",
		["{item:3713}, for \"Swamp Eye\" Jarl in {zone:1445}"] = "{zone:1445}의 \"늪지눈알\" 자를에게 줄 {item:3713}",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "{npc:2771}의 다음 퀘스트인 {quest:678}은(는) 돌주먹일족 정예를 상대합니다. 받지 마세요.",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}: {item:2868}을(를) 가지고 있을 때만({skill:164} 또는 경매장)",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661}에는 사냥꾼과 주술사 상급자가 없습니다. 대신 같은 탑에서 {zone:1454}행 비행선을 타고 도시에서 기술을 배운 뒤, {zone:1454} 정문 밖의 탑에서 {zone:1458}행 비행선을 타세요.",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}: {area:439}에서 받은 피즐의 편지",
		["{zone:1458} trainers"] = "{zone:1458} 상급자",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Darkfang spiders"] = "검은송곳니 거미",
		["Fly to {area:378}"] = "{area:378}(으)로 날아가기",
		["For {npc:2519} at {object:3202}, in the next guide"] = "다음 가이드에서 {object:3202}의 {npc:2519}에게",
		["Hearth to Shadowprey"] = "귀환석으로 그늘수렵 마을에 가기",
		["Hearth to {area:392}"] = "귀환석으로 {area:392}에 가기",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "자를은 {area:502} 남동쪽의 {area:497}에 삽니다.",
		["Kodo bones and ghosts"] = "코도 뼈와 유령",
		["Maraudine totems"] = "마라우돈일족 토템",
		["Mirefin murlocs"] = "진흙아가미멀록",
		["Pick up the kodo bones scattered across the graveyard, and use the {item:15848} among the bones: the ghosts it draws drop the ghost-o-plasm."] = "묘지 곳곳에 흩어진 코도 뼈를 줍고, 뼈 사이에서 {item:15848}을(를) 사용하세요. 끌려온 유령이 유령 원형질을 떨어뜨립니다.",
		["Ride back west to Brackenwall with the head."] = "머리를 가지고 서쪽의 담쟁이 마을로 돌아가세요.",
		["Ride east back to the {area:497}."] = "동쪽의 {area:497}(으)로 돌아가세요.",
		["Ride east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "{area:378}에서 길을 따라 동쪽으로 늪지대에 들어가세요. 불타 버린 {area:403}은(는) 경계를 막 지난 길가에 있습니다. 방패, 휘장, 발굽 자국은 폐허 안과 옆에 있습니다.",
		["Ride east to {area:602}. Use the Rod of Banishing by each demon portal to close six of them."] = "동쪽의 {area:602}(으)로 가세요. 악마 차원문마다 추방의 막대를 사용해 여섯 개를 닫으세요.",
		["Ride north from the coven to {npc:5412} at {area:597}."] = "소굴에서 북쪽으로 {area:597}의 {npc:5412}에게 가세요.",
		["Ride north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "북쪽의 {area:502}(으)로 가세요. 이그나츠는 언덕 기슭에 서 있습니다. 그 바로 남쪽에서 진흙콩 잎을 모으는 동안 그를 호위하세요.",
		["Ride north up the road to the hut by the road north of the graveyard."] = "길을 따라 북쪽으로 묘지 북쪽 길가의 오두막으로 가세요.",
		["Ride north-east to the {area:607}. {npc:12277} is held in the Maraudine centaur camp; free her and escort her out east of the valley."] = "북동쪽의 {area:607}(으)로 가세요. {npc:12277}은(는) 마라우돈일족 켄타우로스 야영지에 붙잡혀 있습니다. 풀어 주고 골짜기 동쪽 밖까지 호위하세요.",
		["Ride on south-west to Shadowprey."] = "계속 남서쪽의 그늘수렵 마을로 가세요.",
		["Ride south from {area:2405} into the {area:607}. The Maraudine Scouts, Wranglers, Maulers, Windchasers and Marauders (36-39) drop the {quest:93225}."] = "{area:2405}에서 남쪽의 {area:607}(으)로 가세요. 마라우돈일족 척후병, 사냥꾼, 투사, 바람전사, 약탈자(36-39)가 {quest:93225}을(를) 떨어뜨립니다.",
		["Ride west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "서쪽으로 늪지대를 가로질러 돌아가세요. 담쟁이 마을 북쪽 능선의 검은송곳니 독거미가 독주머니를 떨어뜨립니다. 테라모어 첩보원(35-36)이 같은 숲에 숨어 다닙니다. 은신 중이니 잘 살피세요.",
		["Ride west to {npc:11863}'s tower at {area:2405} on the north-west coast."] = "서쪽으로 북서쪽 해안 {area:2405}에 있는 {npc:11863}의 탑으로 가세요.",
		["Slitherblade coast"] = "뱀갈퀴일족 해안",
		["Stinky Ignatz"] = "말썽꾼 이그나츠",
		["Swamp Eye Jarl"] = "늪지눈알 자를",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "갈림길에서 북쪽 길로 가서 오우거 마을인 담쟁이 마을로 가세요.",
		["The Burning Blade hold the fortress north-west of {area:2407}. Use the {item:14523} on the {npc:11876} in the fortress to get the {item:13542}."] = "불타는 칼날단이(가) {area:2407} 북서쪽 요새를 차지하고 있습니다. 요새 안의 {npc:11876}에게 {item:14523}을(를) 사용해 {item:13542}을(를) 얻으세요.",
		["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "암흑안개 거미는 담쟁이 마을 북서쪽 동굴 입구에 몰려 있습니다. 모든 종류가 눈알을 떨어뜨립니다.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "진흙아가미멀록은 {area:502} 동쪽과 북동쪽 해안에 몰려 있습니다. 모든 종류가 머리를 떨어뜨립니다.",
		["The Slitherblade naga hold the coast north of {area:2405}, up to {area:598}. {npc:12369} guards the {quest:6027} at the far northern tip."] = "뱀갈퀴일족 나가는 {area:2405} 북쪽부터 {area:598}까지 해안을 차지하고 있습니다. {npc:12369}이(가) 북쪽 맨 끝에서 {quest:6027}을(를) 지키고 있습니다.",
		["The caravan ends at {npc:11596}'s camp on the east side of the {area:596}."] = "대상단은 {area:596} 동쪽의 {npc:11596} 야영지에서 끝납니다.",
		["The next guide takes you back to {zone:1434}."] = "다음 가이드는 다시 {zone:1434}(으)로 안내합니다.",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "{item:3853}을(를) 가지고 있을 때만({skill:164} 또는 경매장)",
		["{npc:11626}'s caravan stops on the road at the edge of {area:602}. Escort it east past the coven; demons attack it twice."] = "{npc:11626}의 대상단은 {area:602} 가장자리 길에 멈춰 있습니다. 동쪽으로 소굴을 지날 때까지 호위하세요. 악마가 두 번 습격합니다.",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "길이 들어오는 마을 남쪽 끝의 {npc:4503}",
		["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983}은(는) 마을 동쪽 {area:2302}에서 기다립니다. 그를 따라 리테에게 가서, 벌어지는 싸움에서 그를 살려 두세요.",
		["{npc:5395} and {npc:5412} stand in the post just west of {npc:11596}'s camp."] = "{npc:5395}와(과) {npc:5412}은(는) {npc:11596} 야영지 바로 서쪽의 주둔지에 서 있습니다.",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019}은(는) {area:596} 서쪽의 고블린 야영지에서 기다립니다.",
		["{object:20985}, beside the manor"] = "저택 옆의 {object:20985}",
		["{object:20985}, now that {npc:4791} has read the report"] = "{npc:4791}이(가) 보고서를 읽은 뒤의 {object:20985}",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Boat to {area:35}"] = "{area:35}행 배",
		["Draenethyst crystals"] = "드레니시스트 수정",
		["Fly to {area:392}"] = "{area:392}(으)로 날아가기",
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "해안을 따라 남쪽으로 가세요. 나가 탐험가가 물가를 걸어 다니며 갈대 묶음을 지니고 있습니다. {object:759}은(는) 그 바로 동쪽 언덕에서 솟아납니다.",
		["From {area:2408} fly to {area:392}."] = "{area:2408}에서 {area:392}(으)로 날아가세요.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals."] = "더 북쪽, 길 동쪽 광산에서 투자개발회사 고블린이 채굴하고 있습니다. 광부, 현장감독, 감시관, 땜장이 모두 수정을 떨어뜨립니다.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "운바그와에게 송곳니를 건네고 곁에 있으세요. 그가 고릴라 세 무리를 부른 뒤 {npc:1514}을(를) 부릅니다. 한 번에 하나씩 싸우세요.",
		["Hearth to {area:35}"] = "귀환석으로 {area:35}에 가기",
		["Hearth to {object:3202}"] = "귀환석으로 {object:3202}에 가기",
		["His strongbox waits at his old camp north of {area:75}."] = "그의 금고는 {area:75} 북쪽의 옛 야영지에 있습니다.",
		["Into the {zone:1435}"] = "{zone:1435}(으)로",
		["Jungle stalkers"] = "줄무늬정글랩터",
		["Keep riding north into {zone:1431}, then east along the road through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp near the way in from {zone:1430}."] = "계속 북쪽으로 {zone:1431}에 들어간 뒤, 길을 따라 동쪽으로 {zone:1430}을(를) 지나 늪으로 가세요. {npc:1776}은(는) {zone:1430}에서 들어오는 길 근처의 드레나이 야영지인 {area:657}에서 기다립니다.",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "터널로 마을을 나가세요. 쪽지는 {area:35} 바로 북쪽의 해적 만에 있습니다.",
		["Mistvale gorillas"] = "안개계곡고릴라",
		["Naga shore and the {object:759}"] = "나가 해안과 {object:759}",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "노보루는 {area:76} 남서쪽 빈터를 돌아다닙니다. 그의 곤봉이 퀘스트를 시작합니다.",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "안개계곡 골짜기 북동쪽 정글에 잔질의 추종자들이 야영하고 있습니다. 누구나 혼합물을 지니고 있을 수 있습니다.",
		["Pirate ghosts"] = "해적 유령",
		["Ride back east past {area:75} and follow the road south-east to the small Horde post on the shore."] = "동쪽으로 {area:75}을(를) 지나 길을 따라 남동쪽 해안의 작은 호드 주둔지로 가세요.",
		["Ride east to {area:75}, in the reeds south of the road."] = "동쪽으로 길 남쪽 갈대밭의 {area:75}(으)로 가세요.",
		["Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "북쪽으로 투자개발회사 광산 동쪽의 백골가루부족 폐허로 가세요. 인간사냥꾼과 광전사를 한 번에 하나씩 끌어오세요. {npc:1059}은(는) 남서쪽 폐허를 지키고, 전리품 해골 더미 하나는 폐허 북쪽에 있습니다. 백골가루부족은 누구나 엄니나 목걸이를 떨어뜨릴 수 있습니다. 목걸이가 오래 걸리니, 모두 모을 때까지 폐허 북쪽 전사 야영지에서 계속 처치하세요.",
		["Ride north up the road to the hunters' camp."] = "길을 따라 북쪽의 사냥꾼 야영지로 가세요.",
		["Ride north up the road; the hunters camp on the hill above the river."] = "길을 따라 북쪽으로 가세요. 사냥꾼들은 강 위쪽 언덕에 야영하고 있습니다.",
		["Ride north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "북동쪽의 {area:76}(으)로 가세요. 수정은 {npc:5391}의 우리로 올라가는 길을 따라 있습니다.",
		["Ride north-west to {object:3202}."] = "북서쪽의 {object:3202}(으)로 가세요.",
		["Ride south to {area:35}. Shaky Phillipe waits on the docks."] = "남쪽의 {area:35}(으)로 가세요. 겁쟁이 필립이 부두에서 기다립니다.",
		["Ride west along the road to the draenei camp at the {area:657}, near the way in from {zone:1430}."] = "길을 따라 서쪽으로 {zone:1430}에서 들어오는 길 근처, {area:657}의 드레나이 야영지로 가세요.",
		["Ride west to {object:3202}."] = "서쪽의 {object:3202}(으)로 가세요.",
		["Sawtooth crocolisks"] = "톱니악어",
		["Sawtooth snappers"] = "무쇠턱 톱니악어",
		["Skullsplitter warriors"] = "백골가루부족 전사",
		["South of Booty Bay the Bloodsail swashbucklers camp on the {area:43}; the charts and the orders lie in their tents. Any Bloodsail can carry snuff and {npc:2493}'s eye, so keep killing until you have both."] = "무법항 남쪽, {area:43}에 붉은해적단 칼잡이가 야영하고 있습니다. 해도와 명령서는 천막 안에 있습니다. 붉은해적단은 누구나 코담배와 {npc:2493}의 눈을 지니고 있을 수 있으니, 둘 다 얻을 때까지 계속 처치하세요.",
		["Take the road north out of {area:35}; Unbagwa sits on a hill in {area:1737}, east of the road."] = "길을 따라 {area:35}에서 북쪽으로 가세요. 운바그와는 길 동쪽 {area:1737}의 언덕에 앉아 있습니다.",
		["The Bloodsail ships"] = "붉은해적단 배",
		["The boat lands in {area:35}'s harbour. The quest givers stand on the boardwalks around the harbour and in the inn."] = "배는 {area:35} 항구에 도착합니다. 퀘스트 제공자는 항구 주변 판자길과 여관에 있습니다.",
		["The boat to {area:35} docks at the end of {area:392}'s pier."] = "{area:35}행 배는 {area:392} 부두 끝에 정박합니다.",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "악어는 {npc:5391}의 야영지 주변 웅덩이와 남쪽 {area:75} 쪽에서 뒹굴고 있습니다. 네 마리 중 한 마리 정도가 옆구리살을 떨어뜨립니다.",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "고릴라는 운바그와 주변 골짜기를 돌아다닙니다. 덩치큰 고릴라가 내장을 떨어뜨리고, 모든 고릴라가 송곳니를 떨어뜨릴 수 있습니다.",
		["The last skulls are in the ruins a short ride west, on the way back to {object:3202}."] = "마지막 해골은 {object:3202}(으)로 돌아가는 길에, 조금 서쪽의 폐허에 있습니다.",
		["The next guide starts here and takes you to {zone:1446}."] = "다음 가이드는 여기서 시작해 {zone:1446}(으)로 안내합니다.",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp."] = "다음 전리품 해골은 전사 야영지 바로 북쪽의 작은 폐허에 있습니다.",
		["The snappers line the strand south of the post."] = "무쇠턱 톱니악어는 주둔지 남쪽 해변에 늘어서 있습니다.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "랩터는 {object:3202} 남쪽 정글에서 서쪽 해안 쪽으로 사냥합니다.",
		["The three ghostly pirates haunt the jungle north of {area:35}, near Zanzil's camps: {npc:2535} and {npc:2536} stand together, {npc:2537} further east."] = "해적 유령 셋은 {area:35} 북쪽, 잔질의 야영지 근처 정글에 출몰합니다. {npc:2535}와(과) {npc:2536}은(는) 함께 있고, {npc:2537}은(는) 더 동쪽에 있습니다.",
		["The three ships lie off the {area:43}. The crews are 42-45, Stillwater 45, Keelhaul 46 and {npc:2546} 48: at 41 this is a fight for a group, or for the end of the guide. If you go, swim out and pull the crew to the rail one at a time. A scroll, {quest:624}, lies on the ships' decks: take it."] = "배 세 척은 {area:43} 앞바다에 있습니다. 선원은 42-45, 스틸워터는 45, 킬하울은 46, {npc:2546}은(는) 48레벨입니다. 41레벨에서는 파티용이거나 가이드 마지막에 할 싸움입니다. 간다면 헤엄쳐 가서 선원을 한 명씩 난간으로 끌어오세요. 배 갑판에 두루마리 {quest:624}이(가) 있습니다. 챙기세요.",
		["The {area:43}"] = "{area:43}",
		["Venture Co. mine"] = "투자개발회사 광산",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "원정대 서쪽, 줄쿤다의 폐허에 붉은머리부족 족장 {npc:1061}와(과) {npc:1062}이(가) 함께 서 있습니다. 먼저 호위병을 처치한 뒤 끌어오세요.",
		["Zanzil's camps"] = "잔질의 야영지",
		["Zul'Kunda"] = "줄쿤다",
		["Zul'Mamwe"] = "줄맘웨",
		["for Stoley in {zone:1446}"] = "{zone:1446}의 스톨리에게",
		["for a later stop in the {zone:1435}"] = "나중에 {zone:1435}에 들를 때",
		["for later: the {zone:1425}, around level 48"] = "나중에: 48레벨쯤 {zone:1425}",
		["the {object:2076}"] = "{object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "{npc:2497} 옆의 {object:2076}",
		["{area:392} pier"] = "{area:392} 부두",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391}은(는) 늪 북동쪽 {area:76}에 붙잡혀 있습니다. 풀어 주고 따라가며 그를 쫓는 늪 생물을 물리치세요.",
		["{npc:773}: for {quest:2864} in {area:976}"] = "{npc:773}: {area:976}의 {quest:2864}에게",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Eastern Wastewander camps"] = "동쪽 사막유랑단 야영지",
		["Fly to {area:1637}. The Droffers brothers run their shop in the Drag."] = "{area:1637}(으)로 날아가세요. 드로퍼스 형제는 골목길에서 상점을 운영합니다.",
		["Fly to {area:484}"] = "{area:484}(으)로 날아가기",
		["Fly to {area:484}, ride down the lift east of the post and across the salt flats, then south into {zone:1446}."] = "{area:484}(으)로 날아가 주둔지 동쪽 승강기를 타고 내려간 뒤, 소금 평원을 가로질러 남쪽 {zone:1446}(으)로 가세요.",
		["Fly to {area:484}, then ride west through the canyons past {area:2237}; the road climbs into the {zone:1444} jungle and on to {area:1099}."] = "{area:484}(으)로 날아간 뒤 서쪽으로 협곡을 지나 {area:2237}을(를) 지나가세요. 길은 {zone:1444} 정글로 올라가 {area:1099}까지 이어집니다.",
		["Fly to {area:75}"] = "{area:75}(으)로 날아가기",
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["Galestriders: {npc:265756}, in {area:16638} on Zephras Isle."] = "돌풍타조: 제프라스 섬 {area:16638}의 {npc:265756}",
		["Grimtotem camp"] = "그림토템부족 야영지",
		["Hearth to {area:1099}"] = "귀환석으로 {area:1099}에 가기",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "계속 서쪽 해안으로 가세요. 해변의 점쟁이 바다마크루라와 집게발 바다마크루라는 마흔 마리에 한 번꼴로 OOX-22/FE 조난 탐지기를 떨어뜨립니다. 얻으면 사용해 퀘스트를 시작하세요.",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "코도: {area:222}의 {npc:3690} 옆의 {npc:3685}",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "놀 북쪽에서 오우거들이 언덕 위 전초기지를 차지하고 있습니다. 오우거 마법사는 끌어와서 처치하세요. 코발트는 전초기지 주변 흙더미에 있고, 두루마리는 그 안의 땅에 있습니다.",
		["Only with the distress beacon: the robot sits in a small cave on the north side of {area:1105}. Escort it to the dock on the {area:1108}; yetis and gorillas ambush you on the way. Its reward waits in {area:35} for a later visit."] = "조난 탐지기가 있을 때만: 로봇은 {area:1105} 북쪽의 작은 동굴에 있습니다. {area:1108}의 부두까지 호위하세요. 가는 길에 설인과 고릴라가 습격합니다. 보상은 나중에 {area:35}에 들를 때 받습니다.",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "랩터: {area:367}의 {npc:7953} 옆의 졸니르",
		["Ride back north-west from {area:1978} to {area:75} and fly to {object:3202}."] = "{area:1978}에서 북서쪽의 {area:75}(으)로 돌아가 {object:3202}(으)로 날아가세요.",
		["Ride back west to {area:976}."] = "서쪽의 {area:976}(으)로 돌아가세요.",
		["Ride north-east to the goblin harbour on the coast."] = "북동쪽 해안의 고블린 항구로 가세요.",
		["Ride south-west to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb."] = "남서쪽으로 {area:1105} 아래의 오우거 폐허로 가세요. 주술사, 흑마법사, 싸움꾼이 가득하며, 남쪽 끝의 대마법사가 구슬을 지니고 있습니다.",
		["Ride west into the middle of {zone:1444}. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "서쪽으로 {zone:1444} 한가운데로 가세요. {npc:5308}을(를) 처치하고 시체에 {item:10699}을(를) 사용한 뒤, 떠오르는 영혼을 처치하세요.",
		["Riding at 40"] = "40레벨 탈것 타기",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is {npc:3690} in {area:222}, with {npc:3685}'s kodos (20 gold each) beside him. Forever may let any race learn from any riding trainer (not confirmed): try {npc:4752} in {zone:1454}'s {object:172958} first, as he is the nearest, and skip this step if he teaches you."] = "탈것 타기는 40레벨이 필요하고 100골드가 듭니다. 배우면 탈것을 하나 받습니다. 클래식에서는 각 종족이 자기 종족의 상급자에게서 배웁니다. 당신의 상급자는 {area:222}의 {npc:3690}이며, 그 옆에서 {npc:3685}이(가) 코도(각 20골드)를 팝니다. Forever에서는 어느 종족이든 아무 탈것 타기 상급자에게서 배울 수 있을지도 모릅니다(확인되지 않음). 가장 가까운 {zone:1454} {object:172958}의 {npc:4752}에게 먼저 시도하고, 그가 가르쳐 주면 이 단계는 건너뛰세요.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, with {npc:4731}'s skeletal horses (20 gold each) beside her. Forever may let any race learn from any riding trainer (not confirmed): try {npc:4752} in {zone:1454}'s {object:172958} first, as he is the nearest, and skip this step if he teaches you."] = "탈것 타기는 40레벨이 필요하고 100골드가 듭니다. 배우면 탈것을 하나 받습니다. 클래식에서는 각 종족이 자기 종족의 상급자에게서 배웁니다. 당신의 상급자는 {area:159}의 {npc:4773}이며, 그 옆에서 {npc:4731}이(가) 해골마(각 20골드)를 팝니다. Forever에서는 어느 종족이든 아무 탈것 타기 상급자에게서 배울 수 있을지도 모릅니다(확인되지 않음). 가장 가까운 {zone:1454} {object:172958}의 {npc:4752}에게 먼저 시도하고, 그가 가르쳐 주면 이 단계는 건너뛰세요.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is {npc:7953} in {area:367} on the {zone:1411} coast, with Zjolnir's raptors (20 gold each) beside him. Forever may let any race learn from any riding trainer (not confirmed): try {npc:4752} in {zone:1454}'s {object:172958} first, as he is the nearest, and skip this step if he teaches you."] = "탈것 타기는 40레벨이 필요하고 100골드가 듭니다. 배우면 탈것을 하나 받습니다. 클래식에서는 각 종족이 자기 종족의 상급자에게서 배웁니다. 당신의 상급자는 {zone:1411} 해안 {area:367}의 {npc:7953}이며, 그 옆에서 졸니르가 랩터(각 20골드)를 팝니다. Forever에서는 어느 종족이든 아무 탈것 타기 상급자에게서 배울 수 있을지도 모릅니다(확인되지 않음). 가장 가까운 {zone:1454} {object:172958}의 {npc:4752}에게 먼저 시도하고, 그가 가르쳐 주면 이 단계는 건너뛰세요.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel; no Skyborne riding trainer is known, so Skyborne try {npc:4752} too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "탈것 타기는 40레벨이 필요하고 100골드가 듭니다. 배우면 탈것을 하나 받습니다. {npc:4752}은(는) {object:172958}의 {npc:3362} 우리 옆에서 오크에게 가르칩니다. 스카이본 탈것 타기 상급자는 알려진 바가 없으니, 스카이본도 {npc:4752}에게 시도해 보세요. 종족의 다른 탈것은 각각 20골드입니다: 수집품, 탈것 · 40레벨에 각각의 가이드가 있습니다.",
		["Rogue Vale screechers"] = "도적의 골짜기 날카로운비명",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "해골마: {area:159}의 {npc:4773} 옆의 {npc:4731}",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often."] = "해안을 따라 남쪽으로 가면 남쪽바다해적단이 만을 차지하고 있습니다. {npc:7883}와(과) 도난당한 화물은 만 맨 끝 부두에 있습니다. 해적은 누구나 모자를 떨어뜨릴 수 있으며, 납치범이 가장 자주 떨어뜨립니다.",
		["Southern Gordunni ruins"] = "남쪽 골두니 폐허",
		["Southern Wastewander camps"] = "남쪽 사막유랑단 야영지",
		["Sprite darters and Woodpaw alphas"] = "화살요정용과 덩굴발일족 우두머리",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "그림토템부족 타우렌은 화살요정용의 숲 옆에 야영하고 있습니다. 침략자, 식물학자, 주술사 모두 뿔을 지니고 있습니다.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane."] = "덩굴발일족 놀은 모자케 야영지 바로 북서쪽 언덕에 야영하고 있습니다. 누구나 갈기를 떨어뜨릴 수 있습니다.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "주크애쉬 벌집은 야영지 남동쪽 언덕 속으로 파고들어 있습니다. {quest:7731}은(는) 가장 깊은 방에서 기다립니다.",
		["The bandits and thieves camp in the dunes east of {area:976}. Every Wastewander can carry a water pouch: keep ten, five for each of Luglunket's bounties."] = "약탈자와 좀도둑은 {area:976} 동쪽 모래언덕에 야영하고 있습니다. 사막유랑단은 누구나 물주머니를 지니고 있을 수 있습니다. 루글룬켓의 현상금 퀘스트 두 개에 다섯 개씩, 열 개를 보관하세요.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "전투 지도는 모자케 야영지 남쪽의 덩굴발일족 야영지에 있습니다.",
		["The shadow mages, rogues and assassins camp south-east of {area:976}."] = "어둠마법사, 도적, 암살자는 {area:976} 남동쪽에 야영하고 있습니다.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour."] = "화살요정용은 모자케 야영지 바로 서쪽 숲 위를 날아다닙니다. 거의 모두 날개를 떨어뜨립니다. 덩굴발일족 우두머리는 그 남서쪽 야영지를 이끌고 있습니다. 한 시간 안에 처치하세요.",
		["The {object:3202} zeppelin leaves from the tower just north-east of {zone:1454}'s main gate."] = "{object:3202}행 비행선은 {zone:1454} 정문 바로 북동쪽의 탑에서 출발합니다.",
		["The {zone:1454} zeppelin leaves from the tower beside {object:3202}; it lands just outside {zone:1454}'s main gate."] = "{zone:1454}행 비행선은 {object:3202} 옆의 탑에서 출발하며, {zone:1454} 정문 바로 밖에 도착합니다.",
		["Thysta, the flight master, stands just east of the zeppelin tower. Fly to {area:75}: the next guide starts there."] = "비행 조련사 시스타는 비행선 탑 바로 동쪽에 서 있습니다. {area:75}(으)로 날아가세요. 다음 가이드는 그곳에서 시작합니다.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "늑대: {npc:4752} 옆의 {npc:3362}",
		["Woodpaw battle map"] = "덩굴발일족 전투 지도",
		["Woodpaw north camp"] = "덩굴발일족 북쪽 야영지",
		["Your trainer is in {area:1638}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly there from {zone:1454}, then on to {area:484}."] = "직업 상급자는 {area:1638}에 있습니다: {area:1639}의 {npc:3033}(드루이드), {npc:246344}(성기사). {zone:1454}에서 그곳으로 날아간 뒤 {area:484}(으)로 날아가세요.",
		["Zeppelin to {object:3202}"] = "{object:3202}행 비행선",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["Zeppelin tower"] = "비행선 탑",
		["for the {zone:1425}, around level 48"] = "48레벨쯤 {zone:1425}에서",
		["for {area:35}, around level 50"] = "50레벨쯤 {area:35}에서",
		["for {zone:1454}, around level 45"] = "45레벨쯤 {zone:1454}에서",
		["the {object:150075} in the square"] = "광장의 {object:150075}",
		["water pouches in your bags"] = "가방 속 물주머니",
		["{area:392} for the Felsteed"] = "지옥마를 위해 {area:392}(으)로",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976}은(는) {zone:1446} 경계를 막 지나서 있는 담장 두른 고블린 마을입니다.",
		["{npc:3690}, riding trainer"] = "탈것 타기 상급자 {npc:3690}",
		["{npc:4752}, riding trainer"] = "탈것 타기 상급자 {npc:4752}",
		["{npc:4773}, riding trainer"] = "탈것 타기 상급자 {npc:4773}",
		["{npc:7953}, riding trainer"] = "탈것 타기 상급자 {npc:7953}",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: 45레벨쯤 {zone:1454}에서",
		["{npc:8579}: the screechers live in {zone:1444}"] = "{npc:8579}: 날카로운비명은 {zone:1444}에 삽니다",
		["{quest:2863}: one hour from now"] = "{quest:2863}: 지금부터 한 시간",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "{area:75}을(를) 지나 동쪽으로 돌아가세요. 아탈라이 유물은 {quest:1424}의 물속과 기슭에 있습니다.",
		["Dragon caves"] = "용 동굴",
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["Forest walkers"] = "나무정령",
		["Frayfeather hippogryphs"] = "공작날개 히포그리프",
		["Monstrous Crawlers"] = "괴물게",
		["Murlocs of the Misty Reed"] = "안개갈대 멀록",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "길을 따라 북서쪽으로 가면 언덕의 동굴 주변에 분노한 무쇠설인이 삽니다. 누구나 {quest:7738}도 떨어뜨릴 수 있으며, 이것은 별도의 퀘스트를 시작합니다.",
		["Northspring harpies"] = "바람계곡일족 하피",
		["Onyxia's eggs"] = "오닉시아의 알",
		["Rage Scar yetis"] = "분노한 무쇠설인",
		["Ride back east to the camp. Stay here: the next guide starts with the flight to {area:976}."] = "동쪽 야영지로 돌아가세요. 여기 머무르세요. 다음 가이드는 {area:976}행 비행으로 시작합니다.",
		["Ride back north to Brackenwall."] = "북쪽의 담쟁이 마을로 돌아가세요.",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "북서쪽의 {area:1108}(으)로 가세요. {npc:14637}이(가) 부두에서 기다립니다.",
		["Ride south-west to the {object:2555}, then east through the {area:511}. The Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "남서쪽의 {object:2555}(으)로 간 뒤, 동쪽으로 {area:511}을(를) 지나가세요. 화염갈기혈족 정찰병과 불꽃술사가 갓 부화한 화염 새끼용, 화염 새끼용과 함께 북쪽 가장자리를 돌아다니고, 맹독전사는 더 남동쪽의 용 동굴을 지킵니다. 모크모로크의 코담배, 그로그주, 금고는 용족 야영지에 있습니다.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "길을 따라 서쪽으로 가세요. 두루마리는 늪 맨 서쪽의 물가에 있습니다.",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "부두 주변 해안에는 바다 정령과 바다 물보라 정령이 밀려다닙니다. 거인에게는 먼저 {item:18904}을(를) 쏘세요. 작아지면 정예의 힘을 잃습니다. 성큼걸이 해안거인은 물속을 걷고, 평지거인과 절벽거인은 더 북쪽 언덕을 돌아다닙니다.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "골짜기 남쪽 비탈에 공작날개 히포그리프가 둥지를 틀고 있습니다. 거의 모두 힘줄과 금속 파편을 떨어뜨립니다.",
		["South-west, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "남서쪽 {area:1105}에 설인이 굴을 파고 삽니다. 그곳의 설인은 모두 두꺼운 가죽을 떨어뜨릴 수 있습니다.",
		["Sprite darters and forest walkers"] = "화살요정용과 나무정령",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "오닉시아의 알은 {area:511} 남동쪽의 용 동굴에 있으며, 맹독전사가 지키고 있습니다. 다섯 개를 깨부수세요.",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "늪지멀록은 주둔지 남쪽 해변에 삽니다. 먹물쟁이는 주둔지 동쪽 해안을 따라 있고, 청소부는 더 서쪽, 서쪽 해안의 오두막 주변에 있습니다.",
		["The Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "괴물게는 동쪽 해안의 해변을 드문드문 돌아다닙니다. 남쪽으로 가는 길에 보이는 대로 모두 처치하세요.",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "바람계곡일족 하피는 맨 북서쪽 능선에 둥지를 틀고 있습니다. 48-50레벨로 나보다 몇 레벨 높습니다. 바람마녀가 치유하니 먼저 처치하고, 한 번에 하나씩 끌어오세요.",
		["The same murlocs again, plus the Oracles, who stay near the huts on the western shore."] = "다시 같은 멀록에, 서쪽 해안의 오두막 근처에 머무는 점쟁이까지 더해집니다.",
		["The small Horde post on the southern shore."] = "남쪽 해안의 작은 호드 주둔지입니다.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "화살요정용은 야영지 바로 서쪽 숲 위를 날아다니며 {item:9589}을(를) 지니고 있습니다. 조금 더 서쪽의 떠도는 나무정령은 쪼개진 통나무를 지니고 있습니다.",
		["The zeppelin to {zone:1454} leaves from the tower beside {object:3202}; it lands just north-east of {zone:1454}'s main gate."] = "{zone:1454}행 비행선은 {object:3202} 옆의 탑에서 출발하며, {zone:1454} 정문 바로 북동쪽에 도착합니다.",
		["The {area:511}"] = "{area:511}",
		["You start in {area:75}. Bind here: you hearth back after the coast."] = "{area:75}에서 시작합니다. 여기에 귀환 지점을 정하세요. 해안 다음에 귀환석으로 돌아옵니다.",
		["Your trainer is in {area:1638}: fly there (no flight path there yet? fly to {area:378} and ride west through {zone:1412}), then on to {area:496}."] = "직업 상급자는 {area:1638}에 있습니다. 그곳으로 날아간 뒤(아직 비행 경로가 없다면 {area:378}(으)로 날아가 {zone:1412}을(를) 지나 서쪽으로 가세요), {area:496}(으)로 날아가세요.",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["Zeppelin tower"] = "비행선 탑",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "48레벨쯤 {zone:1425}의 {npc:5598}에게",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "이 가이드 후반에 {zone:1445}의 {object:2555}을(를) 위해",
		["for the {zone:1425} owlbeasts, around level 48"] = "48레벨쯤 {zone:1425}의 올빼미야수를 위해",
		["the {object:2555}"] = "{object:2555}",
		["{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "{npc:4500}은(는) 정예입니다. 파티를 권장합니다. 그가 항복할 때까지 때린 뒤 {npc:4501}에게 보고하세요.",
		["{npc:7875}: for {npc:7010} in {zone:1454}, around level 50"] = "{npc:7875}: 50레벨쯤 {zone:1454}의 {npc:7010}에게",
		["{object:172958}, then the {object:172960} and the {object:172961}."] = "{object:172958}, 그다음 {object:172960}와(과) {object:172961}.",
		["{quest:7738}, a rare drop"] = "드물게 떨어지는 {quest:7738}",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Boat to {area:35}"] = "{area:35}행 배",
		["Dark Iron Lookouts"] = "검은무쇠단 망꾼",
		["Fly to {area:1637} and train: the next guide's training stop is the {zone:1458}, which has no Hunter or Shaman trainer. Then fly to {area:392}."] = "{area:1637}(으)로 날아가 기술을 배우세요. 다음 가이드에서 기술을 배울 곳은 {zone:1458}인데, 그곳에는 사냥꾼과 주술사 상급자가 없습니다. 그다음 {area:392}(으)로 날아가세요.",
		["Fly to {area:1638} and train with {npc:3033} on {area:1639}, then fly to {area:392}."] = "{area:1638}(으)로 날아가 {area:1639}의 {npc:3033}에게서 기술을 배운 뒤, {area:392}(으)로 날아가세요.",
		["Fly to {area:340}"] = "{area:340}(으)로 날아가기",
		["Fly to {area:392}"] = "{area:392}(으)로 날아가기",
		["Fly to {area:976}"] = "{area:976}(으)로 날아가기",
		["From the {area:35} flight master, above the harbour."] = "항구 위쪽, {area:35}의 비행 조련사에게서",
		["From {area:1099}'s flight master."] = "{area:1099}의 비행 조련사에게서",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive."] = "더 남쪽, 센티파르 벌집 입구에 견습 측량사 스크림섕크의 장비가 있습니다.",
		["Greater Lava Spiders"] = "거대한 용암거미",
		["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it."] = "육중한 전투골렘이 칼라란 아래 용광로를 순찰하며 기름을 떨어뜨리고, 그 사이를 떠다니는 용암 정령과 이글거리는 정령이 심장을 떨어뜨립니다. 검은무쇠단 감독관과 노예상인이 길에서 노예를 부립니다. 노예상인이 {item:11818}을(를) 떨어뜨릴 수 있습니다. 보관하세요.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "그의 다음 요청에는 정예 이교도가 지닌 {item:10552}이(가) 필요합니다. 받지 마세요.",
		["Kalaran stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "칼라란은 {area:1446} 남쪽, 용광로 가장자리에 홀로 서 있습니다. 그의 이야기를 들으세요.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to {area:977}; its reward waits with Oglethorpe in {area:35}."] = "조난 탐지기가 있을 때만: OOX-17/TN은 스크림섕크의 벌집 남동쪽에 있습니다. 북쪽 {area:977}까지 호위하세요. 보상은 {area:35}의 오글소프에게서 받습니다.",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "{item:11818}이(가) 있을 때만: 동쪽 발굴지의 {object:173265}(으)로 돌아가세요.",
		["Ride back north to {area:1446}. Stay here: the next guide starts with the flight to {area:75}."] = "북쪽의 {area:1446}(으)로 돌아가세요. 여기 머무르세요. 다음 가이드는 {area:75}행 비행으로 시작합니다.",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "북서쪽으로 협곡을 가로지르세요. {area:1446}은(는) 북서쪽의 비계를 두른 야영지입니다.",
		["Ride south-west to {area:976}."] = "남서쪽의 {area:976}(으)로 가세요.",
		["Scrimshank's gear"] = "스크림섕크의 장비",
		["South down the road again."] = "다시 길을 따라 남쪽으로 가세요.",
		["South of the {area:982} the Dunemaul ogres hold their compound, with {npc:12046} at its eastern end. Dig up {quest:3161} ornaments between the fights."] = "{area:982} 남쪽에서 모래망치 오우거가 거주지를 차지하고 있으며, 동쪽 끝에 {npc:12046}이(가) 있습니다. 싸우는 사이사이에 {quest:3161} 장식품을 파내세요.",
		["South-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp."] = "가젯잔 남동쪽 모래언덕에 사막유랑단 약탈자가 야영하고 있습니다. {npc:7847}은(는) 동쪽 야영지에 서 있습니다.",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south-west to the dig site. The {object:173265} stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 {item:4306} (the Auction House sells it)."] = "{area:340} 서쪽의 고갯길로 {zone:1427}에 들어간 뒤 남서쪽의 발굴지로 가세요. {object:173265}은(는) 발굴지 남쪽 끝에 있고, 검은무쇠단 지질학자는 그 바로 북쪽에서 땅을 팝니다. {item:4306} 15개를 가져오세요(경매장에서 팝니다).",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "검은무쇠단 망꾼은 용광로 남쪽 감시탑 주변 능선에 서 있습니다. 열 명 중 한 명 정도가 {item:18960}을(를) 지니고 있습니다.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "검은무쇠단 증기기술자는 용광로 한가운데의 화로에서 일합니다. 절반은 {item:10551}을(를), 열 명 중 한 명은 {item:18959}을(를) 지니고 있습니다. 노예, 노예상인, 감독관도 단검을 지니고 있습니다.",
		["The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge."] = "거대한 용암거미는 협곡 남서쪽의 고원과 용암 웅덩이를 돌아다닙니다.",
		["The Steamsmiths' furnaces"] = "증기기술자의 용광로",
		["The boat to {area:35} docks at {area:392}'s pier, below the flight master's hill."] = "{area:35}행 배는 비행 조련사가 있는 언덕 아래, {area:392} 부두에 정박합니다.",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "{object:179827} 게시판",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "길을 따라 서쪽으로, 남쪽 방향으로 가세요. {npc:7771}은(는) {area:1938}의 폐허 옆에 야영하고 있습니다. 그의 {item:9978}을(를) 착용하면 이곳과 {area:983} 주변에 묻힌 장식품이 보입니다.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "가젯잔 서쪽, 트롤 야영지의 물웅덩이 옆에서 {item:8584}을(를) 사용하세요.",
		["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one."] = "거주지 서쪽 골짜기에는 선인장 괴물이 가득합니다. 이슬먹는 덤불나무괴물만 이슬샘을 지니고 있습니다. {zone:1446}의 몬스터 대부분이 드물게 OOX-17/TN 조난 탐지기를 떨어뜨릴 수 있습니다. 얻으면 보관하세요.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts."] = "서쪽에서는 센티파르 곤충이 벌집 주변에 몰려 있습니다. 누구나 부품을 떨어뜨립니다.",
		["for {npc:7010} in {area:1637}, around level 50"] = "50레벨쯤 {area:1637}의 {npc:7010}에게",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526}은(는) 48레벨쯤 {zone:1425}에서 자랍니다",
		["the {object:150075} in the square"] = "광장의 {object:150075}",
		["the {object:173265}"] = "{object:173265}",
		["{area:1443} opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge."] = "{area:1443}은(는) 용광로 북쪽에 있습니다. 인센도사우루스가 용암 웅덩이에서 헤엄칩니다. 가장자리로 끌어오세요. 비밀 설계도는 구덩이 위쪽 바위 턱에 있습니다.",
		["{area:392} pier"] = "{area:392} 부두",
		["{item:11818}, a rare drop"] = "드물게 떨어지는 {item:11818}",
		["{item:8623}, a rare drop"] = "드물게 떨어지는 {item:8623}",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955}은(는) 골짜기에서 기다립니다. 사막을 가로질러 북동쪽 {area:977}에 있는 그의 아내 {npc:6015}에게까지 데려가세요. 가까이 붙어 그의 속도에 맞추고, 그를 공격하는 적을 물리치세요. 그에게서 멀리 떨어진 채 탈것에 오르거나 귀환석을 쓰지 마세요. {npc:8579}도 항구에 있습니다.",
		["{npc:5955}'s escort"] = "{npc:5955} 호위",
		["{npc:7876}, beside the wind rider master"] = "윈드라이더 조련사 옆의 {npc:7876}",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "서쪽의 {area:350}(으)로 돌아가세요. 순찰대와 명사수는 산장 근처에, 정찰대와 길잡이는 그 남쪽 비탈에 있습니다.",
		["East of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south."] = "길 동쪽 비탈에서는 잿빛갈기멧돼지와 꿀꿀이가 붉은바위 바실리스크 옆에서 땅을 뒤집니다. 더 남쪽의 52레벨 지옥멧돼지는 피하세요.",
		["East of the village, the violet flower grows in the hills."] = "마을 동쪽 언덕에 보라색 꽃이 자랍니다.",
		["Fly to the {area:1497}"] = "{area:1497}(으)로 날아가기",
		["Fly to {area:272}"] = "{area:272}(으)로 날아가기",
		["Fly to {area:75}"] = "{area:75}(으)로 날아가기",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "길을 따라 동쪽으로 {zone:1425}을(를) 가로질러 동쪽 해안의 트롤 마을로 가세요.",
		["From {area:1446}'s flight master."] = "{area:1446}의 비행 조련사에게서",
		["Grind to 48"] = "48레벨까지 사냥",
		["Highvale"] = "깊은골짜기",
		["His next request, going on to the {area:355}, is for a group."] = "그의 다음 요청인 {area:355} 진입은 파티용입니다.",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. Keep to the paths: the trolls inside are elite."] = "사냥꾼 마코르의 해골은 썩은가지부족 폐허 아래 더미에, 뼈는 {area:354} 기슭의 더미에 있습니다. 오염된 피가 담긴 용기는 아래쪽 계단식 단에 있고, {npc:14757}은(는) 꼭대기에 갇혀 있습니다. 길에서 벗어나지 마세요. 안쪽의 트롤은 정예입니다.",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "해안을 따라 북쪽으로 가면 작은 섬에 {npc:14731}의 소풍 바구니가 있습니다. {npc:14748}이(가) 지키고 있습니다.",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the way back east, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps."] = "동쪽으로 돌아가는 길에, 중앙 언덕 남쪽의 트롤 사원인 {area:355}을(를) 썩은가지부족 예언자가 차지하고 있습니다. 퀴아가와 {npc:8636}(정예, 50)은(는) 꼭대기에 있습니다. 아래 계단의 예언자를 상대하세요.",
		["Only if you are not level 48 yet."] = "아직 48레벨이 아닐 때만",
		["Only with the distress beacon: the robot sits at the head of the river west of {area:351}. Escort it east to the shore beyond the {area:307}; its reward waits with Oglethorpe in {area:35}."] = "조난 탐지기가 있을 때만: 로봇은 {area:351} 서쪽 강의 상류에 있습니다. 동쪽으로 {area:307} 너머 해안까지 호위하세요. 보상은 {area:35}의 오글소프에게서 받습니다.",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "서쪽 끝까지 가서 와일드해머 마을 {area:348}에 들어가 중앙 우물 옆에 전갈을 놓으세요. 마을에는 얼라이언스 경비병이 가득합니다. 들어가서 놓고 바로 나오세요.",
		["Ride back north to the bloodmages."] = "북쪽의 피의 마법사에게 돌아가세요.",
		["Ride north back to {area:75} and fly to the {area:1497}."] = "북쪽의 {area:75}(으)로 돌아가 {area:1497}(으)로 날아가세요.",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "{area:272}에서 북동쪽 {zone:1425}로 들어가 길을 따라 동쪽으로 가세요. {npc:7801}은(는) 엘프의 {area:350} 남쪽 언덕에 야영하고 있습니다.",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "{area:75}에서 서쪽으로 나가 협곡을 지나 남쪽 {zone:1419}(으)로 가세요. 피의 마법사 둘은 들어가자마자 길가에 서 있습니다.",
		["Saltwater Snapjaws"] = "무쇠턱바다거북",
		["Silvermane Howlers"] = "긴울음 은빛갈기늑대",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "산장 남쪽에서 마른나무껍질부족 트롤이 마을을 차지하고 있습니다. 모두 해골을 지니고 있습니다. 스무 개를 모아 {item:15002}을(를) 사용해 님보야의 무거운 창을 만든 뒤 마을 안에 꽂으세요.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "다시 남서쪽으로 가면 추방자가 {area:353} 폐허 옆에 숨어 있습니다.",
		["South-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "남서쪽, 마른나무껍질부족 마을 동쪽 언덕에 긴울음 은빛갈기늑대가 돌아다닙니다.",
		["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way."] = "깊은골짜기 엘프는 {area:350} 주변에 야영하고 있습니다. 그들의 야영지에서 보고서, 쪽지, 기록을 불태우세요. {npc:7780}은(는) 산장 안에 갇혀 있습니다. 밖으로 데리고 나오며 도중의 매복을 물리치세요.",
		["The Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and {area:351}. Use the {item:9618} on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for {npc:14738}'s second message."] = "긴발톱 은빛갈기늑대, 포악한 올빼미야수, 우두머리 뾰족부리그리핀이 사원과 {area:351} 사이 언덕에 함께 있습니다. 처치한 올빼미야수에 {item:9618}을(를) 사용하세요. 우두머리 뾰족부리그리핀은 길고 고운 깃털도 떨어뜨립니다. {npc:14738}의 두 번째 전갈을 위해 열 개를 보관하세요.",
		["The Vilebranch temples"] = "썩은가지부족 사원",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "큰 거북은 마을 북쪽 해변을 기어다닙니다. {npc:2491}의 포트와인 병도 이 해변에 있지만, 그의 퀘스트는 이 경로에 없습니다. 무쇠턱바다거북이 드물게 OOX-09/HL 조난 탐지기를 떨어뜨릴 수 있습니다. 보관하세요.",
		["The bloodmages"] = "피의 마법사",
		["The central hills"] = "중앙 언덕",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "{item:8684} 상자는 {area:351}의 버려진 호드 야영지 주변, 수액괴물 사이에 있습니다.",
		["The eastern slopes"] = "동쪽 비탈",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills."] = "퀘스트 다섯 개가 같은 재료를 요구합니다. 한 번에 모두 모으세요. 길 서쪽 언덕에는 {npc:5982}, 굶주린 칼송곳니하이에나, 스콜포크 독침전갈, 죽음의 눈 바실리스크가 함께 있습니다.",
		["The next guide starts here, at {area:3317}."] = "다음 가이드는 여기 {area:3317}에서 시작합니다.",
		["The northern beasts"] = "북쪽의 짐승들",
		["The secret lies on the {area:307}, above the beach."] = "비밀은 해변 위쪽 {area:307}에 있습니다.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "후속 퀘스트는 강화 아이템을 위해 같은 재료를 다시 요구하며 경험치를 주지 않습니다. 받지 마세요.",
		["Vilebranch soothsayers"] = "썩은가지부족 예언자",
		["Vulture hills"] = "대머리수리 언덕",
		["West of the island, the Vilebranch scalpers hold the temples of {area:1884} and {area:1917}. Slagtree's tools lie at one of the temples."] = "섬 서쪽에서 썩은가지부족 무두장이가 {area:1884}와(과) {area:1917}의 사원을 차지하고 있습니다. 슬래그트리의 도구는 사원 중 한 곳에 있습니다.",
		["for {npc:6986} in {zone:1454}, around level 50"] = "50레벨쯤 {zone:1454}의 {npc:6986}에게",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "50레벨쯤 {zone:1458}의 {npc:7825}에게",
		["grind on {npc:5982} at the northern hills, {zone:1419}"] = "{zone:1419} 북쪽 언덕에서 {npc:5982} 사냥",
		["{area:348} well"] = "{area:348} 우물",
		["{item:8704}, a rare drop"] = "드물게 떨어지는 {item:8704}",
		["{npc:14731}'s lunch"] = "{npc:14731}의 점심",
		["{npc:14757}, at the top of {area:354}"] = "{area:354} 꼭대기의 {npc:14757}",
		["{npc:6741}: for {zone:1456}, around level 50"] = "{npc:6741}: 50레벨쯤 {zone:1456}에서",
		["{npc:7801}'s camp"] = "{npc:7801}의 야영지",
		["{npc:7825}, the {object:36126}"] = "{object:36126}의 {npc:7825}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "북동쪽 {npc:8420}에게 돌아가세요.",
		["Back to {area:1099}"] = "{area:1099}(으)로 돌아가기",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "제단의 {npc:11548}에게 돌아가세요. {area:3137} 경비병의 서쪽으로 다니세요.",
		["Back to {object:3202}"] = "{object:3202}(으)로 돌아가기",
		["Continue south to {area:35}. {npc:7406} has his workshop on the upper ring of the bay."] = "계속 남쪽 {area:35}(으)로 가세요. {npc:7406}의 작업장은 항구 위층 둘레에 있습니다.",
		["Fly from {area:1237} to {zone:1454}, walk out of the main gate to the zeppelin towers and take the zeppelin to {object:3202}."] = "{area:1237}에서 {zone:1454}(으)로 날아간 뒤, 정문으로 나가 비행선 탑에서 {object:3202}행 비행선을 타세요.",
		["Fly to the {area:1497}"] = "{area:1497}(으)로 비행",
		["Fly to {area:1638}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and {npc:4046} are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "{area:1638}(으)로 날아가세요. {area:1099}(으)로 가는 길목입니다. 아직 비행 경로가 없다면 {area:378}(으)로 날아가 {zone:1412}을(를) 지나 서쪽으로 가세요. 하뮬과 {npc:4046}은(는) {area:1639}에 있습니다. 드루이드와 성기사는 여기서 기술을 배웁니다({npc:3033}, {npc:246344}).",
		["Follow the road north to {area:1237}, the Horde camp."] = "길을 따라 북쪽의 호드 야영지 {area:1237}(으)로 가세요.",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "길을 따라 남쪽으로 가세요. 바실리스크는 정글 한가운데, 길 동쪽 바위 위에서 햇볕을 쬡니다. 조각은 자주 나옵니다.",
		["Frayfeather Hippogryphs"] = "공작날개 히포그리프",
		["From {area:3317}'s flight master, fly to the {area:1497}."] = "{area:3317}의 비행 조련사에게서 {area:1497}(으)로 날아가세요.",
		["Highborne and Haldarr satyrs"] = "명가 유령과 할다르 사티로스",
		["Ironjaw Basilisks"] = "무쇠턱 바실리스크",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "{npc:4046}, {npc:8659}, {npc:6522}에게 줄 배달품은 보관하세요. 나중에 {zone:1456}, {zone:1454}, {zone:1458}을(를) 지나갑니다.",
		["Keep {area:1417} for {npc:7771} in {zone:1446}."] = "{area:1417}은(는) {zone:1446}의 {npc:7771}을(를) 위해 보관하세요.",
		["Keep {npc:8659}'s payment and Ag'tor's {quest:3504}: they go back to {area:1237} on a later visit."] = "{npc:8659}의 대금과 아그토르의 {quest:3504}은(는) 보관하세요. 나중에 {area:1237}에 다시 갈 때 가져갑니다.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "{quest:3444}은(는) 보관하세요. {npc:7771}의 상자는 나중에 다시 와서 엽니다.",
		["Only once all three robots are home"] = "로봇 세 대가 모두 돌아온 뒤에만",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "토막나무 주둔지에서 길을 따라 동쪽으로 가세요. {npc:11548}은(는) 길에서 조금 벗어난 {area:1235}, 얼라이언스의 {area:3137} 바로 서쪽에서 기다립니다. 서쪽에서 접근하고 아즈샤라 파수꾼과 자로데누스(정예)를 피하세요.",
		["Ride into {zone:1447}"] = "{zone:1447}(으)로 이동",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}."] = "북동쪽 {area:1227} 위 절벽의 고블린 야영지로 가세요.",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "북서쪽 {area:1108}(으)로 가세요. {npc:14637}이(가) 부두에서 기다립니다.",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "길을 따라 남쪽 {area:1938}(으)로 가세요. {npc:7771}이(가) 그 옆에 있습니다. 여기서 서쪽 길을 따라 내려가면 다음 가이드가 시작되는 {zone:1449}입니다.",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "남서쪽 폐허로 가세요. 석판 네 개가 폐허 곳곳에 있고 원한의꼬리일족 나가가 지킵니다. 원한의꼬리일족 세이렌이나 원한의꼬리일족 미르미돈 누구나 {npc:8420}의 룬을 지니고 있을 수 있습니다.",
		["Ride west back to {area:1237}."] = "서쪽 {area:1237}(으)로 돌아가세요.",
		["Sea elementals"] = "바다 정령",
		["Sprite Darters"] = "화살요정용",
		["Take the zeppelin back to {zone:1454}."] = "비행선을 타고 {zone:1454}(으)로 돌아가세요.",
		["Take the zeppelin to {zone:1454} from the tower outside the {zone:1458}, then fly to {area:431}."] = "{zone:1458} 밖의 탑에서 비행선을 타고 {zone:1454}(으)로 간 뒤 {area:431}(으)로 날아가세요.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "명가 유령은 제단 바로 북쪽의 폐허를 떠돌고, 할다르 사티로스는 조금 더 북쪽에 진을 치고 있습니다.",
		["The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "평지거인과 절벽거인이 부두 북쪽 언덕을 돌아다닙니다. 먼저 각각에게 {item:18904}을(를) 쏘세요. 줄어들면 더 이상 정예가 아닙니다. 축소된 거인은 모두 잔여물을 떨어뜨립니다. 시체에 뮤세크 단지도 사용하세요.",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock."] = "바다 정령과 바다 물보라 정령이 부두 주변 해안을 따라 밀려다닙니다.",
		["The Thunderhead Hippogryphs fly over the hills just south of {area:1237}."] = "천둥뿔 히포그리프가 {area:1237} 바로 남쪽 언덕 위를 날아다닙니다.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "블러드 엘프 야영지는 {npc:8420} 바로 남쪽에 있습니다. 그의 장비 네 개는 야영지 주변 상자에 있습니다.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "요정용은 야영지 바로 서쪽 숲을 날아다닙니다. 처치할 때마다 단지를 사용하세요.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "히포그리프는 야영지 남서쪽 언덕에 둥지를 틉니다. 하나를 처치한 뒤 시체에 뮤세크 단지를 사용하세요.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "나무정령은 야영지와 {zone:1444} 중앙 사이의 숲길을 떠돕니다. 수가 적으니 길을 따라 찾아보세요.",
		["The {object:2076} beside {npc:2519}"] = "{npc:2519} 옆의 {object:2076}",
		["To {object:3202}"] = "{object:3202}(으)로",
		["Undamaged Hippogryph Feathers"] = "온전한 히포그리프 깃털",
		["Wandering Forest Walkers"] = "떠도는 나무정령",
		["Xylem's tower stands on the cliff just north of {area:1237}; the path winds up its north side."] = "실렘의 탑은 {area:1237} 바로 북쪽 절벽 위에 있습니다. 길은 북쪽 면을 따라 구불구불 올라갑니다.",
		["Zapped giants"] = "축소된 거인",
		["Zeppelin to {zone:1454}"] = "비행선 타고 {zone:1454}(으)로",
		["{npc:6986}, the Drag"] = "골목길의 {npc:6986}",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}: 곰은 {zone:1448}에 있음",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825}은(는) {object:36082}에 있습니다.",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "{npc:7876}의 타르와 페슬저그의 표본은 {zone:1449}에서 구합니다.",
		["{npc:7876}, beside the wind rider master"] = "와이번 조련사 옆의 {npc:7876}",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "야영지 동쪽 끝의 {npc:8395}: 경험치 없음, 아즈샤라 탑으로 순간이동만 가능",
		["{npc:8659}, the {object:172960}"] = "{object:172960}의 {npc:8659}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761}은(는) 다음 가이드에서 모읍니다. {npc:4046}의 대금은 나중에 {npc:8587}에게 가져갑니다.",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back north-east to {area:251}."] = "북동쪽 {area:251}(으)로 돌아가세요.",
		["Back to {area:2268}"] = "{area:2268}(으)로 돌아가기",
		["Black Broodlings"] = "검은 새끼용",
		["Black Broodlings nest in the hills just east of {area:251}. Use {npc:10267}'s {item:12284} on a broodling when it is almost dead to capture its essence."] = "검은 새끼용은 {area:251} 바로 동쪽 언덕에 둥지를 틉니다. 새끼용이 거의 죽었을 때 {npc:10267}의 {item:12284}을(를) 사용해 정수를 포획하세요.",
		["Bloodpetal Flayers"] = "칼날가시 붉은꽃잎덩굴손",
		["Bridge into {area:254}"] = "{area:254}(으)로 가는 다리",
		["Cross the south of the crater to the pylon on the western cliffs."] = "분화구 남쪽을 가로질러 서쪽 절벽의 수정탑으로 가세요.",
		["Darrowshire Spirits"] = "다로우샤이어 영혼",
		["Eastern Pylon"] = "동쪽 수정탑",
		["Escort {npc:9999}"] = "{npc:9999} 호위",
		["Fly to {area:1637} and train before the {object:3202} zeppelin: the {zone:1458} stop later in this guide has no Hunter or Shaman trainer."] = "{object:3202}행 비행선을 타기 전에 {area:1637}(으)로 날아가 기술을 배우세요. 이 가이드 후반의 {zone:1458}에는 사냥꾼과 주술사 상급자가 없습니다.",
		["Fly to {area:1637}, take the zeppelin to {object:3202} and fly from there to {area:340}, built into the cliffs on the {zone:1418}' west edge."] = "{area:1637}(으)로 날아가 {object:3202}행 비행선을 탄 뒤, 그곳에서 {zone:1418} 서쪽 끝 절벽에 지어진 {area:340}(으)로 날아가세요.",
		["Fly to {area:1638} and train with {npc:3033} on {area:1639}, then fly to {area:1637} for the {object:3202} zeppelin."] = "{area:1638}(으)로 날아가 {area:1639}의 {npc:3033}에게 기술을 배운 뒤, {area:1637}(으)로 날아가 {object:3202}행 비행선을 타세요.",
		["Fly to {area:340}"] = "{area:340}(으)로 비행",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "절벽을 따라 남쪽, 불자루 오우거의 언덕인 {quest:3821}(으)로 가세요. {npc:9136}의 유해는 언덕 기슭에 있습니다.",
		["Follow the road east through the {zone:1422} and across the river into the {zone:1423}; leave it north for {area:2627}, the ruined town in the north-west. {npc:12384} sits in a hut at its edge."] = "길을 따라 동쪽으로 {zone:1422}을(를) 지나 강을 건너 {zone:1423}(으)로 가세요. 북서쪽의 폐허 마을 {area:2627}(으)로 가려면 길에서 북쪽으로 벗어나세요. {npc:12384}은(는) 마을 가장자리의 오두막에 있습니다.",
		["Free Darrowshire Spirits: talk to them"] = "다로우샤이어 영혼 해방: 말 걸기",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "지금부터 지나가는 마력의 수정(파랑, 초록, 빨강, 노랑)과 {quest:3761} 더미를 모두 챙기세요. 흙은 모두 25개로, 하뮬에게 20개, 페슬저그에게 5개입니다.",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "{area:1938}에서 서쪽으로 가 {zone:1449}(으)로 구불구불 내려가는 긴 비탈길을 타고, 분화구 북쪽 벽을 따라 절벽 동굴 속 야영지인 {area:541}(으)로 가세요. 이곳 주민은 모두 중립입니다.",
		["Gorillas"] = "고릴라",
		["Into the {zone:1427}"] = "{zone:1427}(으)로",
		["Into {zone:1449}"] = "{zone:1449}(으)로",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "미끼는 보관하세요. {npc:9684}은(는) 레벨 56이며, 두 번째 순회 때 그 소굴을 지납니다.",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "{npc:10267}의 편지는 보관하세요. {quest:4808}은(는) {zone:1452}의 {area:2255}에 있습니다.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "{npc:9118}의 {quest:4147}과(와) {npc:8737}의 편지는 이후 가이드를 위해 보관하세요.",
		["Keep {quest:5152}: Marlene lives at {area:197} in the {zone:1422}."] = "{quest:5152}은(는) 보관하세요. 말레네는 {zone:1422}의 {area:197}에 삽니다.",
		["Lar'korwi Mates"] = "라르코르위의 짝",
		["Lashers and Threshers"] = "채찍줄기와 덩이줄기",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "{npc:9999}을(를) 북쪽 {area:541}(으)로 데려가세요. 기절하면 {item:11804}을(를) 사용해 깨우세요.",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "{zone:1458}을(를) 나와 길을 따라 동쪽으로 {zone:1420}을(를) 지나 경계의 포세이큰 요새인 {area:152}로 가세요.",
		["North of Torwa, a dead Threshadon lies by the water."] = "토르와 북쪽 물가에 죽은 트레샤돈이 있습니다.",
		["Northern Pylon"] = "북쪽 수정탑",
		["Out of the refuge"] = "야영지 밖으로",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "페슬저그의 다음 퀘스트는 정예 우두머리 {npc:10041}이(가) 필요합니다. 건너뛰세요.",
		["Power Crystals and soil"] = "마력의 수정과 흙",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "분화구 동쪽을 따라 내려가 동쪽 절벽의 수정탑으로 가세요.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "동쪽 {area:537}(으)로 가서 올라가 정상 근처 용암 분출구에서 {npc:10541}을(를) 사용한 뒤, 서쪽 {npc:10302}에게 돌아가세요.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "동쪽을 따라 북쪽으로 가세요. 채찍줄기 붉은꽃잎덩굴손과 덩이줄기 붉은꽃잎덩굴손이 정글에 가득합니다.",
		["Ride north back to {area:541}."] = "북쪽 {area:541}(으)로 돌아가세요.",
		["Ride south back to the road and follow it east across the whole zone to {area:2268}."] = "남쪽 길로 돌아가 지역을 가로질러 동쪽 {area:2268}까지 가세요.",
		["Ride south-west along the western cliffs. {npc:9167} fly over the west side, and Bloodpetal Trappers grow in the same jungle."] = "서쪽 절벽을 따라 남서쪽으로 가세요. {npc:9167}이(가) 서쪽 위를 날고, 같은 정글에 질긴뿌리 붉은꽃잎덩굴손이 자랍니다.",
		["Ride south-west to {area:537}, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot."] = "남서쪽, 분화구 한가운데의 화산인 {area:537}(으)로 가세요. 기슭에 칼날가시 붉은꽃잎덩굴손이 자랍니다.",
		["Ride west to the dig site. {npc:7039} golems (53) stomp around it and drop the shards often; the {quest:4296} stands in its middle among the Thaurissan dwarves. Copy it."] = "서쪽 발굴지로 가세요. {npc:7039} 골렘(53)이 주변을 돌아다니며 조각을 자주 떨어뜨립니다. {quest:4296}은(는) 발굴지 한가운데 타우릿산 드워프들 사이에 있습니다. 베껴 쓰세요.",
		["South of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales {npc:9998} wants. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon."] = "간헐천 남쪽에서 스테고돈이 풀을 뜯습니다. 공룡 뼈는 스테고돈이 떨어뜨리거나 땅에 놓여 있습니다. 근처 디메트로돈은 {npc:9998}이(가) 원하는 비늘을 지니고 있습니다. 라바사우루스는 남서쪽에서 무리 지어 사냥합니다. 발톱은 {npc:8659}에게 가져가며, 가끔 구겨진 일지를 지닌 개체가 있습니다(희귀 획득물: 얻었을 때만 퀘스트를 받으세요). 레벨 57 스테고돈인 그러프는 피하세요.",
		["Stegodons and ravasaurs"] = "스테고돈과 라바사우루스",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "{quest:5096}을(를) 위해 델링턴 옆 상자에서 {object:176092}을(를) 챙기세요. 돌아오는 길에 완료합니다. {quest:5401}을(를) 착용하세요. 착용 중에만 스컬지석이 나옵니다.",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "{area:340} 서쪽 고개를 넘어 {zone:1427}(으)로 간 뒤, 협곡을 가로질러 남쪽 {area:254}(으)로 이어지는 긴 다리로 가세요. 안에서는 사슬 통로를 따라 내려가 남쪽 출구로 나가세요. 던전 입구로 가는 길은 피하세요.",
		["Termite mounds"] = "흰개미집",
		["Thaurissan dig site"] = "타우릿산 발굴지",
		["The Gorishi hive"] = "고리쉬 벌집",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "라르코르위의 짝은 {npc:9619} 북서쪽 정글을 배회합니다.",
		["The Large Termite Mounds stand all over the hills east of {area:2627}. Use the {item:15042} on each mound you pass."] = "큰 흰개미집이 {area:2627} 동쪽 언덕 곳곳에 있습니다. 지나가는 흰개미집마다 {item:15042}을(를) 사용하세요.",
		["The book lies in the ruined inn of {area:2627}."] = "책은 {area:2627}의 무너진 여관에 있습니다.",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "수정 무더기는 분화구 곳곳에 있으며 {area:537} 주변에 많습니다. 수정탑용으로 색깔별로 몇 개씩 더 챙기세요.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "인형의 머리와 양쪽 몸통은 {npc:10926} 주변 집들에 있습니다. 가방에서 합치세요.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "원정대의 상자는 동쪽 정글의 버려진 야영지에 있습니다.",
		["The expedition's lost equipment lies in the south-west jungle."] = "원정대의 잃어버린 장비는 남서쪽 정글에 있습니다.",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "고릴라는 북동쪽 고원에 삽니다. 가장 깊은 동굴에는 들어가지 마세요. {npc:9622}이(가) 삽니다.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "산을 나오면 55-57 오크로 가득한 {area:252} 옆입니다. 북쪽 절벽을 따라 동쪽 길로 {area:251}의 호드 야영지로 가세요.",
		["The next guide starts here, at the chapel's flight master."] = "다음 가이드는 여기 예배당의 비행 조련사에서 시작합니다.",
		["The pylon stands on the slope east of the refuge."] = "수정탑은 야영지 동쪽 비탈에 있습니다.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "뗏목은 남동쪽 호숫가에 있고, 작은 배낭은 그 옆 물속에 있습니다.",
		["The silithid hive fills the south of the crater. Gorishi wasps and workers drop the scent gland; use the Scraping Vial on the egg mass inside the first chamber. The Hive Queen at the bottom is an elite boss: stay out of her chamber. {npc:9166} nest on the cliffs above the hive; their scales are for {npc:9998}."] = "실리시드 벌집이 분화구 남쪽을 채우고 있습니다. 병정 고리쉬와 일꾼 고리쉬가 향낭을 떨어뜨립니다. 첫 번째 방 안의 알 덩어리에 빈 채집 약병을 사용하세요. 맨 아래의 여왕 고리쉬는 정예 우두머리이니 그 방에는 들어가지 마세요. {npc:9166}은(는) 벌집 위 절벽에 둥지를 틉니다. 그 비늘은 {npc:9998}에게 갑니다.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "잿구덩이는 야영지 바로 남쪽에 있습니다. 송진괴물, 송진껍질괴물, 송진이끼괴물이 {item:11834}을(를) 떨어뜨립니다.",
		["The wooden sign beside {npc:9997}"] = "{npc:9997} 옆의 나무 표지판",
		["Theodora's next errand goes to Lotwil east of town and then into {area:1584}: skip it."] = "테오도라의 다음 심부름은 마을 동쪽의 로트윌을 거쳐 {area:1584}(으)로 이어집니다. 건너뛰세요.",
		["Theodora's quest in {area:340} needs level 52. The Tar Lurkers and Tar Lords just south of the refuge are the closest camp."] = "{area:340}의 테오도라 퀘스트는 레벨 52가 필요합니다. 야영지 바로 남쪽의 송진껍질괴물과 우두머리 송진괴물이 가장 가까운 사냥터입니다.",
		["Use the Mangled Journal to start it"] = "구겨진 일지를 사용해 시작하세요",
		["Western Pylon"] = "서쪽 수정탑",
		["Western jungle"] = "서쪽 정글",
		["With {npc:11063}'s quest in your log, slain Scourge sometimes leave a {npc:11064}; talk to it to free it. Kill undead on the ride south-west to {area:2262}."] = "{npc:11063}의 퀘스트가 있으면 처치한 스컬지가 가끔 {npc:11064}을(를) 남깁니다. 말을 걸어 풀어 주세요. 남서쪽 {area:2262}(으)로 가는 길에 언데드를 처치하세요.",
		["grind on Tar Lurkers at {area:538}, {zone:1449}"] = "{zone:1449}, {area:538}에서 송진껍질괴물 사냥",
		["{item:11116}, a rare drop"] = "{item:11116}, 희귀 획득물",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302}이(가) {zone:1452}의 {npc:9298}에게 보냅니다. 보관하세요.",
		["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "고블린 {npc:10302}은(는) 수정탑 바로 동쪽 {area:543}에 있습니다.",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{object:36078}, 박쥐 조련사 옆의 {npc:10879}",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "{npc:10926}의 유령은 남서쪽 {area:2262} 폐허에 있습니다.",
		["{npc:12250} lurks just west of {area:2262}."] = "{npc:12250}은(는) {area:2262} 바로 서쪽에 숨어 있습니다.",
		["{npc:6522}, the {object:36073}"] = "{object:36073}의 {npc:6522}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "연금술 실험실의 {npc:8390}: 약병은 나중에 {zone:1447}에서 채웁니다",
		["{npc:9117}, at the back of the cave"] = "동굴 안쪽의 {npc:9117}",
		["{npc:9618}, just outside"] = "바로 밖의 {npc:9618}",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619}은(는) 분화구 남동쪽 구석에 있습니다.",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "이제 {npc:9619}이(가) 북동쪽 동굴에 있는 {npc:9622}의 가죽을 요구합니다. 건너뛰세요.",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "그다음 {npc:9623}은(는) {skill:202} 아이템인 {item:10561}을(를) 원합니다. 가지고 있지 않으면 건너뛰세요.",
		["{npc:9623}, the robot on the plateau"] = "고원의 로봇 {npc:9623}",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "{npc:9684}의 소굴은 수정탑 바로 남쪽에 있습니다. 그곳에서 {npc:9619}의 미끼를 사용하세요. {npc:9684}은(는) 레벨 56이고 공격이 강하니 생명력을 가득 채우고 시작하세요.",
		["{npc:9998}, at the entrance"] = "입구의 {npc:9998}",
		["{npc:9998}, at the refuge entrance"] = "야영지 입구의 {npc:9998}",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999}이(가) 길을 잃고 지친 채 마루에 앉아 있습니다.",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822}은(는) {quest:3821}의 동굴과 갱도를 돌아다닙니다. 없으면 돌아올 때까지 입구 주변 오우거를 처치하세요.",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back at {area:1762}, the Deadwood furbolgs (53-54) are close to the tunnel and every kill raises your Timbermaw reputation."] = "{area:1762}에 돌아오면 마른가지일족 털보숭이(53-54)가 터널 가까이 있고, 처치할 때마다 나무구렁 평판이 오릅니다.",
		["Back north to {area:1763}. Fill {npc:10922}'s canteen at the corrupted moonwell in the middle of the southern camp."] = "북쪽의 {area:1763}(으)로 돌아가세요. 남쪽 야영지 한가운데의 오염된 달샘에서 {npc:10922}의 수통을 채우세요.",
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "데링턴의 감시탑, 반디스의 가마솥, {npc:11615}의 통은 나중에 들를 때 처리합니다. 보관하세요.",
		["Diseased Grizzlies"] = "오염된 불곰",
		["Diseased Wolves"] = "역병에 걸린 늑대",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "피멍울 초소 동쪽, 혼돈의 불길과 혼돈의 소산물이 돌아다니는 구덩이투성이 골짜기입니다. 각각 두 마리씩 처치한 뒤, 지옥 물 구덩이 세 곳을 모두 걸어서 찾아가세요.",
		["Fly to the {area:1497}"] = "{area:1497}(으)로 날아가기",
		["Follow the road north-east to {area:1767}. The Warpwood Moss Flayers and Shredders on the east side of the woods each carry a {item:11503}; Angerclaw Grizzlies and Felpaw Ravagers roam the same woods for Talo."] = "길을 따라 북동쪽의 {area:1767}(으)로 가세요. 숲 동쪽의 굽이나무 이끼늪괴물과 갈퀴늪괴물은 각각 {item:11503}을(를) 지니고 있습니다. 같은 숲에서 탈로를 위해 성난발톱불곰과 갈퀴발톱 악령발늑대를 처치하세요.",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "길을 따라 북서쪽으로 가세요. {area:1763} 남부, 오염된 달샘 주변은 어둠의 의회 이교도, 숙련사제, 수호병과 사냥개가 차지하고 있습니다.",
		["From {area:2268}'s flight master, fly to the {area:1497}."] = "{area:2268}의 비행 조련사에게서 {area:1497}(으)로 날아가세요.",
		["He camps by the {area:202}, south-east of {area:200}."] = "그는 {area:200} 남동쪽, {area:202} 옆에 야영하고 있습니다.",
		["Jadefire moonwell"] = "비취불꽃 달샘",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "가지를 보관하세요: {npc:5770}은(는) {zone:1456}에 있습니다.",
		["Keep the parcel: {npc:10781} is in the {area:1497}."] = "꾸러미를 보관하세요: {npc:10781}은(는) {area:1497}에 있습니다.",
		["Keep {quest:5142}: Pamela is in {area:2262}, visited again later."] = "{quest:5142}을(를) 보관하세요: 파멜라는 나중에 다시 들르는 {area:2262}에 있습니다.",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "{quest:5158}을(를) 보관하세요: {npc:5901}은(는) {zone:1413}에 있습니다.",
		["Keep {quest:8465} for {zone:1452}."] = "{zone:1452}을(를) 위해 {quest:8465}을(를) 보관하세요.",
		["Knights and magi work the {area:192}; the medics and hunters camp south of it."] = "기사와 학자는 {area:192}에서 일하고, 의무병과 사냥꾼은 그 남쪽에 야영하고 있습니다.",
		["Leave the {area:1497} and ride east along the road through {zone:1420}, past the {area:152}. Felstone Farm is the first farm along the road; {npc:10778} waits in the house."] = "{area:1497}을(를) 나와 길을 따라 동쪽으로 {zone:1420}을(를) 지나 {area:152}을(를) 지나가세요. 펠스톤 농장은 길을 따라 처음 나오는 농장이며, {npc:10778}은(는) 집 안에서 기다립니다.",
		["Northern crater"] = "북쪽 구덩이",
		["Only if a {item:13140} dropped: use it to start the quest, then free {npc:11018} in her cage in {area:1770}, the cave at the north end of {area:1763}, and escort her out."] = "{item:13140}을(를) 얻었을 때만: 사용해 퀘스트를 시작한 뒤, {area:1763} 북쪽 끝 동굴인 {area:1770}의 우리에 갇힌 {npc:11018}을(를) 풀어 주고 밖으로 호위하세요.",
		["Only if you rescued {npc:11018}: the succubus {npc:9518} waits in the middle of {area:1763}, beside the {npc:11020}."] = "{npc:11018}을(를) 구출했을 때만: 서큐버스 {npc:9518}이(가) {area:1763} 한가운데, {npc:11020} 옆에서 기다립니다.",
		["Only with 5 Deadwood Headdress Feathers"] = "마른가지일족 깃털 머리장식 5개가 있을 때만",
		["Radley and Durgen"] = "래들리와 더건",
		["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "남쪽으로 {area:1763}을(를) 지나 비취불꽃의 사티로스가 있는 오염된 달샘으로 돌아가, 그곳에서 {npc:9996}의 작은 병을 채우세요.",
		["Ride back south-east to the Sanctuary."] = "남동쪽의 성소로 돌아가세요.",
		["Ride back to the {area:1497}, take the zeppelin to {zone:1454} and fly to {area:431}. Follow the road west out of Splintertree and take the fork north into {zone:1448}."] = "{area:1497}(으)로 돌아가 {zone:1454}행 비행선을 타고 {area:431}(으)로 날아가세요. 길을 따라 토막나무 주둔지에서 서쪽으로 나가, 갈림길에서 북쪽 {zone:1448}(으)로 가세요.",
		["Ride north along the eastern hills; Tirion lives in a small house by the {area:2620}, at the border with the {zone:1423}."] = "동쪽 언덕을 따라 북쪽으로 가세요. 티리온은 {zone:1423}와(과)의 경계, {area:2620} 옆의 작은 집에 삽니다.",
		["Ride north up the road again."] = "다시 길을 따라 북쪽으로 가세요.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "북서쪽의 안돌할로 가세요. {npc:10667}은(는) 마을 서쪽의 무너진 여관에서 기다립니다. 안쪽의 해골은 54-57레벨이니 가장자리로만 다니세요.",
		["Ride south past the {area:202} to {area:197}; {npc:10927}'s house stands by the road, and {npc:10936}'s monument is in the graveyard behind it. Kill the Diseased Wolves you meet in the fields on the way."] = "남쪽으로 {area:202}을(를) 지나 {area:197}(으)로 가세요. {npc:10927}의 집은 길가에 있고, {npc:10936}의 기념비는 그 뒤 묘지에 있습니다. 가는 길에 들판에서 만나는 역병에 걸린 늑대를 처치하세요.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "남서쪽으로 펠스톤 농장을 지나 길을 따라 서쪽의 {area:152}(으)로 돌아가세요.",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "길을 따라 남쪽으로 {zone:1448}을(를) 지나 성소로 가세요.",
		["Ride west to the {area:192}; {npc:11610} hides on the hill north-east of it."] = "서쪽의 {area:192}(으)로 가세요. {npc:11610}은(는) 그 북동쪽 언덕에 숨어 있습니다.",
		["Ror stands at the far south end of {area:1761}."] = "로르는 {area:1761} 남쪽 끝에 서 있습니다.",
		["Scarlet Crusade"] = "붉은십자군",
		["Scarlet forward camp"] = "붉은십자군 전진 야영지",
		["Southern crater"] = "남쪽 구덩이",
		["Southern {area:1763}"] = "{area:1763} 남부",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "새끼 고양이를 같은 달샘에 데려가 풀어 주세요. {npc:10042}(으)로 변하면 {npc:9996}에게 데려가 클릭해서 건네세요.",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "연대기는 안돌할 시청의 곰팡이 슨 고서 사이에 있습니다. 맞는 것을 찾을 때까지 열어 보세요.",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "터널 바로 서쪽의 마른가지일족 털보숭이 마을입니다. {npc:9462}(56)이(가) 그들 사이에 서 있습니다. 우호적인 털보숭이 {npc:11557}은(는) 마을 북쪽 끝에 앉아 있습니다.",
		["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your {area:1769} reputation; keep the headdress feathers."] = "마른가지일족 털보숭이 마을은 성소 바로 남쪽에 있습니다. 마른가지일족을 처치할 때마다 {area:1769} 평판도 오릅니다. 깃털 머리장식은 보관하세요.",
		["The Horde camp just north of {area:1763}."] = "{area:1763} 바로 북쪽의 호드 야영지입니다.",
		["The Jadefire moonwell"] = "비취불꽃 달샘",
		["The Scarlet Crusade's tents stand between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner."] = "붉은십자군의 천막은 {area:199}와(과) {area:200} 사이에 있습니다. {object:176092}(으)로 지휘 천막을 불태우고 스컬지 깃발을 꽂으세요.",
		["The bears roam the hills north and east of the {area:202}."] = "곰은 {area:202} 북쪽과 동쪽 언덕을 돌아다닙니다.",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "일기는 농가 안에, 장식장은 그 안에, 변소는 그 뒤에 있습니다. {npc:10816}이(가) 변소 열쇠를 지니고 있습니다. 변소를 열면 {npc:10836}이(가) 나오며, 그가 장식장 열쇠를 지니고 있습니다.",
		["The druids' camp is just past the border."] = "드루이드 야영지는 경계를 막 지나서 있습니다.",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "길은 맨 북동쪽 {area:1769} 터널 밖의 {npc:15395}에서 끝납니다.",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east."] = "늑대는 안돌할, {area:200}, {area:202} 사이의 들판을 돌아다닙니다. 동쪽으로 돌아가는 길에 마저 처치하세요.",
		["The {area:1763} moonwell"] = "{area:1763} 달샘",
		["Through {area:1769}"] = "{area:1769} 통과",
		["Tirion's hunts are in the {zone:1423}: keep them for later."] = "티리온의 사냥은 {zone:1423}에서 합니다. 나중을 위해 보관하세요.",
		["To {zone:1448}"] = "{zone:1448}(으)로",
		["Walk into the {area:1769} tunnel beside {npc:15395} and never attack the Timbermaw furbolgs inside. The tunnel opens into {zone:1452}; follow the road east to {area:2255}, the goblin town where the next guide starts."] = "{npc:15395} 옆의 {area:1769} 터널로 들어가세요. 안쪽의 나무구렁 털보숭이는 절대 공격하지 마세요. 터널은 {zone:1452}(으)로 이어집니다. 길을 따라 동쪽으로 다음 가이드가 시작되는 고블린 마을 {area:2255}(으)로 가세요.",
		["Western crater"] = "서쪽 구덩이",
		["grind on Deadwood Avengers at {area:1762}, {zone:1448}"] = "{zone:1448} {area:1762}에서 마른가지일족 복수자 사냥",
		["grind on Scarlet Knights at {area:192}, {zone:1422}"] = "{zone:1422} {area:192}에서 붉은십자군 기사 사냥",
		["{area:190}'s Scarlets are level 58-60. Ride in to the high point marked on your map, look over the town, and get out."] = "{area:190}의 붉은십자군은 58-60레벨입니다. 지도에 표시된 높은 곳까지 들어가 마을을 살펴본 뒤 빠져나오세요.",
		["{area:200} farmhouse"] = "{area:200} 농가",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: 올빼미야수는 {zone:1452}에 있습니다",
		["{npc:10840}, at the graveyard's south end"] = "묘지 남쪽 끝의 {npc:10840}",
		["{npc:11554}, at the south edge of the camp"] = "야영지 남쪽 가장자리의 {npc:11554}",
		["{npc:11557}: keep 30 {quest:6031} for him; he trades only at Neutral with the Timbermaw"] = "{npc:11557}: {quest:6031} 30개를 보관하세요. 나무구렁 평판이 중립일 때만 거래합니다",
		["{npc:11558}, at the tunnel mouth"] = "터널 입구의 {npc:11558}",
		["{npc:11610}'s last task needs level 53. The Scarlet Knights and Magi (54-55) working the lumber camp just south-west of her are the closest camp."] = "{npc:11610}의 마지막 임무는 53레벨이 필요합니다. 그녀 바로 남서쪽 벌목지에서 일하는 붉은십자군 기사와 학자(54-55)가 가장 가까운 사냥터입니다.",
		["{npc:11613} stands east of the lumber camp; {npc:11611} guards the road north-east of {npc:11610}, toward {area:190}."] = "{npc:11613}은(는) 벌목지 동쪽에 서 있고, {npc:11611}은(는) {npc:11610} 북동쪽, {area:190}(으)로 가는 길을 지키고 있습니다.",
		["{npc:9529}, just west of the camp"] = "야영지 바로 서쪽의 {npc:9529}",
		["{npc:9529}, on the west side of the Sanctuary"] = "성소 서쪽의 {npc:9529}",
		["{npc:9996}'s kitten"] = "{npc:9996}의 새끼 고양이",
		["{object:175894}, beside the house"] = "집 옆의 {object:175894}",
		["{quest:5210} goes to {area:2268}: keep it for later."] = "{quest:5210}은(는) {area:2268}(으)로 갑니다. 나중을 위해 보관하세요.",
		["{quest:8470}, a rare drop"] = "드물게 떨어지는 {quest:8470}",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Any Winterfall furbolg can carry the beads; the camps just south of {npc:11556} are the closest."] = "눈사태일족 털보숭이는 누구나 구슬을 지니고 있을 수 있습니다. {npc:11556} 바로 남쪽 야영지가 가장 가깝습니다.",
		["Back at {area:1099}."] = "{area:1099}에 돌아왔습니다.",
		["Back to {area:2255}"] = "{area:2255}(으)로 돌아가기",
		["Chillwind chimaeras"] = "서리바람 키메라",
		["Fly to {area:1099}"] = "{area:1099}(으)로 날아가기",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Fly to {area:1638}"] = "{area:1638}(으)로 날아가기",
		["From Krakle in Un'Goro"] = "운고로 분화구의 크래클에게서",
		["Frostfire Winterfall camp"] = "얼음불꽃 눈사태일족 야영지",
		["Frostfire Winterfall camps"] = "얼음불꽃 눈사태일족 야영지",
		["Gregor's and Harlo's quests lead to other zones: keep them."] = "그레고르와 하를로의 퀘스트는 다른 지역으로 이어집니다. 보관하세요.",
		["Grind to 55"] = "55레벨까지 사냥",
		["He stands on {area:1641}. Each donation wants cloth from your bags; hand them in when you have it, later in the route."] = "그는 {area:1641}에 서 있습니다. 기부마다 가방 속 옷감이 필요합니다. 나중에 경로 중 옷감이 모이면 건네세요.",
		["Ice Thistle yetis"] = "얼음엉겅퀴설인",
		["In the {object:172958}."] = "{object:172958}에 있습니다.",
		["In the {object:172961}."] = "{object:172961}에 있습니다.",
		["Linken's letter"] = "링쿠의 편지",
		["Matriarchs and Patriarchs hit hard: pull them one at a time."] = "맹렬한 설인과 덩치큰 설인은 세게 때립니다. 한 번에 한 마리씩 끌어오세요.",
		["Pathfinders, Den Watchers and Totemics share the furbolg camps around the hot springs; Ragged Owlbeasts roam the slopes between them. Kill Totemics first. Save every {item:14047} you loot for Meilosh."] = "길잡이, 보초, 토템술사가 온천 주변 털보숭이 야영지에 함께 있고, 털복숭이 올빼미야수가 그 사이 비탈을 돌아다닙니다. 토템술사를 먼저 처치하세요. 얻는 {item:14047}은(는) 모두 메일로쉬를 위해 모아 두세요.",
		["Pristine Yeti Horns"] = "온전한 설인 뿔",
		["Raging Owlbeasts"] = "흉포한 올빼미야수",
		["Ride back west to {area:2246}."] = "서쪽의 {area:2246}(으)로 돌아가세요.",
		["Ride east, then south down {area:2249}. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of {area:2256}, at the south end."] = "동쪽으로 간 뒤 남쪽으로 {area:2249}을(를) 내려가세요. 그곳의 서리망치거인은 59레벨 정예입니다. 가운데로 다니며 멈추지 마세요. 이상한 근원은 남쪽 끝, {area:2256} 입구에 있습니다.",
		["Ride west along the road past {area:2251}; Raging Owlbeasts roam the hills north of it."] = "길을 따라 서쪽으로 {area:2251}을(를) 지나가세요. 흉포한 올빼미야수는 그 북쪽 언덕을 돌아다닙니다.",
		["The chimaeras roam the snowfields south and west of {area:2255}. Stay clear of {area:2245}'s cave: its blue dragonkin are elite."] = "키메라는 {area:2255} 남쪽과 서쪽의 설원을 돌아다닙니다. {area:2245} 동굴은 피하세요. 그곳의 푸른 용족은 정예입니다.",
		["The furbolg village fills the valley north-east of {area:2255}. Kill Shamans first; they heal. {npc:10738} in the cave at the back is elite: stay out."] = "털보숭이 마을이 {area:2255} 북동쪽 골짜기를 가득 메우고 있습니다. 치유하는 주술사를 먼저 처치하세요. 안쪽 동굴의 {npc:10738}은(는) 정예입니다. 들어가지 마세요.",
		["The yeti hills start just south-east of {area:2255}. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in."] = "설인 언덕은 {area:2255} 바로 남동쪽에서 시작합니다. 모든 설인이 털가죽을 떨어뜨리지만, 뿔은 맹렬한 설인과 덩치큰 설인만 떨어뜨리므로 완료 후를 위해 남겨 두세요.",
		["Umi's third prank targets goblins in {area:976} and Un'Goro: keep it for later."] = "우미의 세 번째 장난은 {area:976}와(과) 운고로 분화구의 고블린을 노립니다. 나중을 위해 보관하세요.",
		["grind on {npc:7440} at {area:2244}, {zone:1452}"] = "{zone:1452} {area:2244}에서 {npc:7440} 사냥",
		["{area:2255} is the goblin town on the east side of the valley."] = "{area:2255}은(는) 골짜기 동쪽의 고블린 마을입니다.",
		["{item:12771}, a rare drop from the Winterfall furbolgs"] = "눈사태일족 털보숭이가 드물게 떨어뜨리는 {item:12771}",
		["{npc:10307}, beside him"] = "그 옆의 {npc:10307}",
		["{npc:11556} stands by the {zone:1452} exit of {area:1769}'s tunnel, north of the hot springs."] = "{npc:11556}은(는) 온천 북쪽, {area:1769} 터널의 {zone:1452} 쪽 출구 옆에 서 있습니다.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}의 {npc:3033}, {npc:246344}",
		["{npc:7775}, a dwarf, camps in the {area:1137} north-west of {area:1099}; he has the elixir."] = "드워프 {npc:7775}은(는) {area:1099} 북서쪽 {area:1137}에 야영하고 있습니다. 그가 비약을 가지고 있습니다.",
		["{npc:9087} buys {item:11040} grown from your {quest:3761}."] = "{npc:9087}은(는) {quest:3761}(으)로 기른 {item:11040}을(를) 삽니다.",
		["{npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "{npc:9298}은(는) 골짜기 서쪽, {area:2246}의 김이 오르는 웅덩이 사이에 야영하고 있습니다.",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123}은(는) {zone:1450}에서 기다립니다. 나중을 위해 보관하세요.",
		["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909}은(는) 이 가이드 후반에 {zone:1444}의 {npc:7775}에게서 받습니다.",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084}은(는) 나중에 {zone:1448}에 갈 때 {object:176091}에서 완료합니다.",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "눈사태일족 털보숭이가 드물게 떨어뜨리는 {quest:8471}",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
		["Both {item:14047} donations are handed in later in the route: start saving {item:14047}."] = "{item:14047} 기부 두 개는 나중에 경로 중 완료합니다. {item:14047}을(를) 모으기 시작하세요.",
		["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "정화된 물은 {zone:1448}의 {area:2479}(으)로 갑니다. 나중을 위해 보관하세요.",
		["Fly to the {area:380}"] = "{area:380}(으)로 날아가기",
		["Fly to {area:1237}"] = "{area:1237}(으)로 날아가기",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Fly to {area:1637}; {npc:4485} is in the {object:172958}."] = "{area:1637}(으)로 날아가세요. {npc:4485}은(는) {object:172958}에 있습니다.",
		["Fly to {area:392}"] = "{area:392}(으)로 날아가기",
		["In the {object:172958}."] = "{object:172958}에 있습니다.",
		["In the {object:172961}. Have the Wool, Silk and Mageweave in your bags."] = "{object:172961}에 있습니다. 양모 옷감, 비단 옷감, 마법 옷감을 가방에 넣어 두세요.",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "리브의 작업장은 {area:392} 부두 북쪽 끝에 있으며, {object:149036}은(는) 그 안에 있습니다.",
		["Open {object:149036} for the {item:10556}"] = "{object:149036}을(를) 열어 {item:10556} 얻기",
		["Ride back west to {area:1237}."] = "서쪽의 {area:1237}(으)로 돌아가세요.",
		["Ride east to the ruins on the coast. Fill Cuely's four vials at the tide pools along the shore; Spitelash naga patrol between them."] = "동쪽 해안의 폐허로 가세요. 해안을 따라 있는 조수 웅덩이에서 큘리의 약병 네 개를 채우세요. 원한의꼬리일족 나가가 그 사이를 순찰합니다.",
		["Rimtori's camp is at the east end of the base camp. Read the {object:151286} there, then kill the Magus."] = "림토리의 야영지는 주 야영지 동쪽 끝에 있습니다. 그곳에서 {object:151286}을(를) 읽은 뒤 마법사를 처치하세요.",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}."] = "블러드 엘프는 북동쪽 {area:1227} 옆 절벽에 야영하고 있습니다.",
		["The zeppelin tower stands just north-east of {zone:1454}'s main gate; take the {zone:1458} zeppelin."] = "비행선 탑은 {zone:1454} 정문 바로 북동쪽에 있습니다. {zone:1458}행 비행선을 타세요.",
		["Zeppelin to the {zone:1458}"] = "{zone:1458}행 비행선",
		["Zeppelin tower"] = "비행선 탑",
		["{npc:11044}, in the Apothecarium"] = "연금술 실험실의 {npc:11044}",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{object:172957}의 {npc:15188}: {zone:1451}을(를) 위해 보관하세요",
		["{npc:256386} stands in the {area:380}. Open each crate she hands you and bring back what is inside."] = "{npc:256386}은(는) {area:380}에 서 있습니다. 그녀가 건네는 상자를 하나씩 열어 안에 든 것을 가져가세요.",
		["{npc:256386}'s crates"] = "{npc:256386}의 상자",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901}은(는) {area:392} 바로 북쪽 해안에 야영하고 있습니다.",
		["{npc:8393}, beside him"] = "그 옆의 {npc:8393}",
		["{npc:8403}, nearby"] = "근처의 {npc:8403}",
		["{npc:8578}'s camp"] = "{npc:8578}의 야영지",
		["{npc:8659}, the {object:172960}"] = "{object:172960}의 {npc:8659}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050}은(는) {zone:1422}의 {npc:10778}에게 돌아갑니다. 보관하세요.",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["A torn scroll lies at the entrance of the {area:2261}, the crypt south of the {area:2260}."] = "찢어진 두루마리는 {area:2260} 남쪽의 납골당인 {area:2261} 입구에 있습니다.",
		["Back through the tunnel and take the {zone:1452} exit, then ride south to {area:2246}."] = "터널로 돌아가 {zone:1452} 출구로 나간 뒤, 남쪽의 {area:2246}(으)로 가세요.",
		["Back to {area:1638}"] = "{area:1638}(으)로 돌아가기",
		["Both quests lead to {zone:1451}: keep them."] = "두 퀘스트 모두 {zone:1451}(으)로 이어집니다. 보관하세요.",
		["Fly to the {zone:1458}, take the zeppelin to {zone:1454} and fly on to {area:1638}."] = "{zone:1458}(으)로 날아가 {zone:1454}행 비행선을 탄 뒤 {area:1638}(으)로 날아가세요.",
		["Fly to {area:1099}. The hippogryph nests are in the south of {zone:1444}; each holds an egg for the {object:142071}."] = "{area:1099}(으)로 날아가세요. 히포그리프 둥지는 {zone:1444} 남부에 있으며, 둥지마다 {object:142071}에 쓸 알이 하나씩 있습니다.",
		["Fly to {area:1638}"] = "{area:1638}(으)로 날아가기",
		["Fly to {area:2268}"] = "{area:2268}(으)로 날아가기",
		["Fly to {area:541}, then ride south-west through Un'Goro to the pass into {zone:1451}. The next guide opens at {area:3077}, where the pass comes out."] = "{area:541}(으)로 날아간 뒤, 남서쪽으로 운고로 분화구를 지나 {zone:1451}(으)로 가는 고갯길로 가세요. 다음 가이드는 고갯길이 끝나는 {area:3077}에서 시작합니다.",
		["Frenzied Plaguehounds and Monstrous Plaguebats share the fields around {area:2272} and {area:2271}, south of {area:2273}."] = "광포한 역병사냥개와 기괴한 역병박쥐는 {area:2273} 남쪽, {area:2272}와(과) {area:2271} 주변 들판에 함께 있습니다.",
		["Go through {area:1769} and take the {zone:1450} branch of the tunnel. {npc:11801} is in {area:2361}."] = "{area:1769}을(를) 지나 터널의 {zone:1450} 갈래로 가세요. {npc:11801}은(는) {area:2361}에 있습니다.",
		["Hameya hides among the Mossflayer trolls of {area:2273}, in the north-east corner."] = "하메야는 북동쪽 구석, {area:2273}의 이끼껍질부족 트롤 사이에 숨어 있습니다.",
		["Hameya's mound"] = "하메야의 흙더미",
		["Hameya's scroll"] = "하메야의 두루마리",
		["Hippogryph eggs"] = "히포그리프 알",
		["Moontouched Owlbeasts"] = "달빛 깃든 올빼미야수",
		["On to {zone:1451}"] = "{zone:1451}(으)로",
		["On {area:1641}. Have the Wool, Silk and Mageweave in your bags."] = "{area:1641}에 있습니다. 양모 옷감, 비단 옷감, 마법 옷감을 가방에 넣어 두세요.",
		["Only if a {quest:8471} dropped for you: {npc:11558} waits at the {zone:1448} entrance of {area:1769}, and speaks to you only at Neutral with the Timbermaw."] = "{quest:8471}을(를) 얻었을 때만: {npc:11558}은(는) {area:1769}의 {zone:1448} 쪽 입구에서 기다리며, 나무구렁 평판이 중립일 때만 말을 겁니다.",
		["Only if you found a {item:12820} flask in {zone:1452}: ride north up the road. The cauldron stands in {area:1762}, just south-west of {area:1769}; the Deadwood furbolgs there are hostile."] = "{zone:1452}에서 {item:12820} 병을 찾았을 때만: 길을 따라 북쪽으로 가세요. 가마솥은 {area:1769} 바로 남서쪽의 {area:1762}에 있습니다. 그곳의 마른가지일족 털보숭이는 적대적입니다.",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "새끼 역병사냥개와 역병박쥐는 {area:2260} 북쪽 언덕을 돌아다니고, 청소부구더기가 그 사이를 기어다닙니다. 북쪽 {area:2627} 방향으로 나아가세요.",
		["Plaguehounds and their runts roam the shores of the lake south-west of the chapel."] = "역병사냥개와 새끼 역병사냥개는 예배당 남서쪽 호숫가를 돌아다닙니다.",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Pull them one at a time."] = "동쪽의 {area:2255}(으)로 가서 북쪽으로 나가세요. 달빛 깃든 올빼미야수는 {area:2241} 남쪽 비탈의 언덕을 돌아다닙니다. 한 번에 한 마리씩 끌어오세요.",
		["Ride west to the {area:2260}."] = "서쪽의 {area:2260}(으)로 가세요.",
		["Sword of Marduk"] = "마르두크의 검",
		["The high elf Rangers, Pathstriders and Woodsmen guard the lodge by {area:2275}; the Registry lies inside. Rangers reach 60: pull one at a time. Noxious Plaguebats fly over the fields on the way."] = "하이 엘프 순찰자, 길잡이, 수렵꾼이 {area:2275} 옆의 오두막을 지키고 있으며, 명부는 그 안에 있습니다. 순찰자는 60레벨까지 됩니다. 한 번에 한 명씩 끌어오세요. 가는 길에 맹독 역병박쥐가 들판 위를 날아다닙니다.",
		["The shattered sword lies on the ground north-west of the lake."] = "부서진 검은 호수 북서쪽 땅바닥에 있습니다.",
		["The skull sits in the {area:2622}, among Blighted Horrors and Plague Monstrosities."] = "해골은 {area:2622}의 황폐의 그림자와 역병의 괴수 사이에 있습니다.",
		["The western hills"] = "서쪽 언덕",
		["The {area:2622}"] = "{area:2622}",
		["The {object:142071} machine"] = "{object:142071} 기계",
		["The {object:177675} is just behind the {area:2261}."] = "{object:177675}은(는) {area:2261} 바로 뒤에 있습니다.",
		["Use {npc:10980} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "{area:976}의 고블린 소녀 {npc:7583}에게 {npc:10980}을(를) 사용하세요. {npc:10977}와(과) {npc:10978}은(는) 나중에 경로 중 놀래 줍니다.",
		["{item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once."] = "{item:15447}은(는) 10분 안에 상합니다. 마을의 스컬지를 빨리 처치하고, 일곱 조각을 바로 {item:15454}(으)로 빻으세요.",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner."] = "유령 {npc:11140}은(는) 북서쪽 구석, {area:2627}의 오두막 옆에 서 있습니다.",
		["{npc:15193}'s champion holds the {area:2260} farmhouse."] = "{npc:15193}의 용사가 {area:2260} 농가를 차지하고 있습니다.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}의 {npc:3033}, {npc:246344}",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771}은(는) {area:976} 남쪽, {area:1336}(으)로 가는 길가에 야영하고 있습니다.",
		["{npc:9299} is a ghost at the graveyard just north of {area:976}; the Conspicuous Gravestone is south of it, outside the town wall."] = "{npc:9299}은(는) {area:976} 바로 북쪽 묘지의 유령입니다. 눈에 띄는 묘비는 그 남쪽, 마을 성벽 밖에 있습니다.",
		["{object:1661}'s flight master is in the {object:36078}'s west tower, outside the walls."] = "{object:1661}의 비행 조련사는 성벽 밖, {object:36078}의 서쪽 탑에 있습니다.",
		["{quest:3914} goes back to Linken in Un'Goro: keep it."] = "{quest:3914}은(는) 운고로 분화구의 링쿠에게 돌아갑니다. 보관하세요.",
		["{quest:5086} are in {zone:1448}, on a later trip: keep it if you have it."] = "{quest:5086}은(는) 나중에 {zone:1448}에 갈 때 처리합니다. 가지고 있다면 보관하세요.",
		["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "{quest:5168}의 물품은 나중의 역병지대 지역에 있습니다. 보관하세요.",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["Andorhal watchtowers and silos"] = "안돌할 감시탑과 저장고",
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "마파람 마을로 돌아가 탑에 오르세요. 꼭대기의 벌집을 건드리면 잠복꾼 하이브아쉬가 나옵니다. 그중 하나가 {item:17346}을(를) 지니고 있습니다.",
		["Back to {area:3425}"] = "{area:3425}(으)로 돌아가기",
		["Dithers offers {item:14619} ({quest:838}). Skip it."] = "디더스가 {item:14619}({quest:838})을(를) 줍니다. 건너뛰세요.",
		["Dredge Crushers and Pincers"] = "망치미늘벌레와 집게전갈",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "작살미늘벌레, 돌꼬리전갈, 모래그물 바위거미가 요새 바로 북쪽 모래밭에 함께 있습니다.",
		["Dredge and scorpids"] = "미늘벌레와 전갈",
		["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "길을 따라 동쪽으로 가면 {npc:11077}이(가) {area:200}의 가마솥을 지키고 있습니다.",
		["Flayers and Rock Stalkers"] = "채찍전갈과 바위거미",
		["Fly to {area:1637} and train."] = "{area:1637}(으)로 날아가 기술을 배우세요.",
		["Fly to {area:976}. The {object:142071} stands in the middle of town."] = "{area:976}(으)로 날아가세요. {object:142071}은(는) 마을 한가운데에 있습니다.",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "서쪽 모래언덕을 따라 북쪽으로 가세요. 망치미늘벌레와 돌꼬리집게전갈은 여기서부터 요새 쪽까지 퍼져 있습니다.",
		["Keep {quest:3942}: {npc:9116} is at the {area:2479}, on the next guide's way through {zone:1448}."] = "{quest:3942}을(를) 보관하세요: {npc:9116}은(는) 다음 가이드에서 {zone:1448}을(를) 지나는 길의 {area:2479}에 있습니다.",
		["Mar'alith's Dearest Natalia needs level 58 and leads into {area:2744} among elites. Skip it."] = "마랄리스의 사랑하는 여군주 나탈리아는 58레벨이 필요하고 정예가 있는 {area:2744} 안으로 이어집니다. 건너뛰세요.",
		["Mark {npc:10902} with the {item:12815}"] = "{item:12815}(으)로 {npc:10902} 표시",
		["Mark {npc:10903} with the {item:12815}"] = "{item:12815}(으)로 {npc:10903} 표시",
		["Mark {npc:10904} with the {item:12815}"] = "{item:12815}(으)로 {npc:10904} 표시",
		["Mark {npc:10905} with the {item:12815}"] = "{item:12815}(으)로 {npc:10905} 표시",
		["North to the lumber camp; set the termite barrel down in the middle of the mill."] = "북쪽의 벌목지로 가서 흰개미 통을 제재소 한가운데에 내려놓으세요.",
		["Ride east across the plaguelands to the chapel."] = "동쪽으로 역병지대를 가로질러 예배당으로 가세요.",
		["Ride east along the road to the {area:152} on the border."] = "길을 따라 동쪽으로 경계의 {area:152}로 가세요.",
		["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "동쪽으로 {area:2619} 옆 {npc:1855}의 오두막으로 가서 그의 이야기를 들으세요.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "북동쪽의 {area:3077}(으)로 가세요. 그 옆의 고갯길로 {zone:1451}을(를) 떠납니다.",
		["Ride north-east to {area:3447}."] = "북동쪽의 {area:3447}(으)로 가세요.",
		["Ride north-west to {npc:1855}'s hut."] = "북서쪽의 {npc:1855} 오두막으로 가세요.",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "남쪽의 안돌할로 가세요. {npc:10667}은(는) 마을 서쪽의 무너진 여관에서 기다립니다. {item:12815}을(를) 들고 탑 네 개의 출입구에 각각 서서 표시하세요. 마을 가장자리로만 다니세요. 마을 한가운데의 저장고 옆에서 {item:12627}을(를) 사용하면 시간의 기생충이 나옵니다.",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "남동쪽으로 운고로 절벽 아래의 {area:3447}(으)로 가세요.",
		["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "남서쪽의 {area:2738} 폐허로 가세요. {npc:11801}을(를) 위한 {object:179565}은(는) 무너진 집 중 한 곳 안에 있습니다.",
		["Ride south-west to {npc:10667} in Andorhal."] = "남서쪽 안돌할의 {npc:10667}에게 가세요.",
		["Ride to {area:2262} in the south-west; {npc:10926} plays among the houses. {npc:11886} lurks in the {area:2261}, the crypt just west of the town."] = "남서쪽의 {area:2262}(으)로 가세요. {npc:10926}은(는) 집들 사이에서 놀고 있습니다. {npc:11886}은(는) 마을 바로 서쪽의 납골당인 {area:2261}에 숨어 있습니다.",
		["Ride west to the Horde camp north of {area:2744}."] = "서쪽으로 {area:2744} 북쪽의 호드 야영지로 가세요.",
		["Ride west to the walled hold in the middle of the desert."] = "서쪽으로 사막 한가운데의 성벽 두른 요새로 가세요.",
		["Scourge Champions"] = "스컬지 용사",
		["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "스컬지 용사는 예배당 북쪽 {area:2270}을(를) 돌아다닙니다. 처치한 용사마다 {npc:11063}의 {item:13156}을(를) 대 보세요. 공명하는 해골이 그가 원하는 것입니다.",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "남부 사막 곳곳에서 실리시스트 모래기둥이 솟아오릅니다. 모래기둥이 남긴 실리시스트 속으로 걸어 들어가, 키리카의 야영지에 있는 호드의 실리시스트 추출기까지 가져가세요. 싸우거나 탈것에 오르면 떨어뜨립니다.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "돌꼬리채찍전갈과 긴다리 바위거미는 키리카의 야영지 남서쪽 모래언덕을 돌아다닙니다.",
		["Take the zeppelin from the tower outside {area:1637} to {zone:1420} and ride into the {zone:1458}. Lady Sylvanas holds the {object:36126}."] = "{area:1637} 밖의 탑에서 {zone:1420}행 비행선을 타고 {zone:1458}(으)로 들어가세요. 실바나스는 {object:36126}에 있습니다.",
		["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "빛나는 서판 조각은 맨 북서쪽 황혼의 망치단 야영지 주변에 있습니다. 그곳의 먼지 폭풍과 우레의 모래정령도 조각을 떨어뜨립니다.",
		["The libram lies further north, on the way to {area:190}."] = "성서는 더 북쪽, {area:190}(으)로 가는 길에 있습니다.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "운고로 분화구에서 오는 고갯길은 {zone:1451} 북동쪽의 묘지인 {area:3077}(으)로 이어집니다. {npc:13220}은(는) 무덤 사이에 서 있습니다.",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "가방은 남쪽 끝 산속, 브론즈비어드 야영지 너머에 있습니다. 정예 전갈 죽음의 갈고리가 근처를 순찰합니다. 그가 떠나 있을 때 챙기세요.",
		["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "방패는 {npc:1855}의 오두막 남쪽 {area:201}에 있습니다.",
		["The spare texts from the cultists"] = "이교도에게서 얻은 남는 문서",
		["Through the pass and east along the northern cliffs to {area:541}. {npc:8737} stands by the cave; {npc:9117} is inside it."] = "고갯길을 지나 북쪽 절벽을 따라 동쪽의 {area:541}(으)로 가세요. {npc:8737}은(는) 동굴 옆에 서 있고, {npc:9117}은(는) 그 안에 있습니다.",
		["Twilight Vanguard"] = "황혼의 선봉대",
		["Use {npc:10980} on {npc:10977}"] = "{npc:10977}에게 {npc:10980} 사용",
		["West to the {area:152}. The next guide starts in the {zone:1458}, a short ride west."] = "서쪽의 {area:152}로 가세요. 다음 가이드는 조금 서쪽의 {zone:1458}에서 시작합니다.",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "{npc:10667}의 다로우샤이어 전투는 정예와 싸우며 끝납니다. 건너뛰세요.",
		["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field."] = "{npc:10778}의 농장은 {area:152} 동쪽으로 첫 번째 농장입니다. 농장의 비명소리 구울이 그녀의 부적 나머지 반쪽을 지니고 있고, {npc:11075}은(는) 들판의 가마솥을 지키고 있습니다.",
		["{npc:10926} and the {area:2261}"] = "{npc:10926}와(과) {area:2261}",
		["{npc:10926}'s own errand is not on this route. Skip it."] = "{npc:10926}의 심부름은 이 경로에 없습니다. 건너뛰세요.",
		["{npc:11803} walks the Vanguard camp in the far south-west. Every cultist here drops Encrypted Twilight Texts, quest or not: collect twenty, ten for {npc:15306} and ten for Ortell."] = "{npc:11803}은(는) 맨 남서쪽의 선봉대 야영지를 돌아다닙니다. 이곳의 이교도는 퀘스트와 상관없이 모두 암호화된 황혼의 문서를 떨어뜨립니다. {npc:15306}에게 열 개, 오르텔에게 열 개, 모두 스무 개를 모으세요.",
		["{npc:11804} stands in the outpost west of {area:3425}. Top your Encrypted Twilight Texts up to twenty on the cultists here."] = "{npc:11804}은(는) {area:3425} 서쪽 전초기지에 서 있습니다. 이곳 이교도에게서 암호화된 황혼의 문서를 스무 개까지 채우세요.",
		["{npc:11878}' errands are not on this route. Skip them."] = "{npc:11878}의 심부름은 이 경로에 없습니다. 건너뛰세요.",
		["{npc:15193}'s champion holds the {area:2260} farmhouse, north of the {area:2261}."] = "{npc:15193}의 용사가 {area:2261} 북쪽의 {area:2260} 농가를 차지하고 있습니다.",
		["{npc:15200} holds the camp in the west."] = "{npc:15200}은(는) 서쪽 야영지를 차지하고 있습니다.",
		["{npc:15306}, on the west side of the Hold"] = "요새 서쪽의 {npc:15306}",
		["{npc:1855}'s next task, Of Lost Honor, is not on this route. Skip it."] = "{npc:1855}의 다음 임무인 명예의 상징은 이 경로에 없습니다. 건너뛰세요.",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "다시 나무구렁일족 동굴로 들어가 {zone:1452} 쪽 출구로 나가세요. {npc:9298}은(는) 바로 밖 온천 옆에 있습니다.",
		["Back south to the Sanctuary, a short ride."] = "남쪽 성소로 돌아가세요. 금방입니다.",
		["Dungeon instead of grinding"] = "사냥 대신 던전",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "{area:431}(으)로 날아간 뒤 길을 따라 북서쪽으로 달려 {zone:1440}에서 {zone:1448}(으)로 가세요. {area:2479}은(는) 경계를 막 지난 곳의 드루이드 야영지입니다.",
		["From the {zone:1458}, take the zeppelin from the tower outside the city to {zone:1454}."] = "{zone:1458}에서 도시 밖 탑의 비행선을 타고 {zone:1454}(으)로 가세요.",
		["Grind to 60"] = "60까지 사냥",
		["In {zone:1454}: fly from {area:2255}"] = "{zone:1454}에서: {area:2255}에서 비행",
		["In {zone:1456}: fly from {area:2255}"] = "{zone:1456}에서: {area:2255}에서 비행",
		["Only if you carry {quest:5087}: the runners walk the road from {area:1769} toward {area:2244} in small groups; wait by the road near {npc:9298} and kill them as they pass. Each one carries a crate."] = "{quest:5087}이(가) 있을 때만: 정찰꾼들이 작은 무리로 {area:1769}에서 {area:2244}(으)로 길을 걷습니다. {npc:9298} 근처 길가에서 기다렸다가 지나갈 때 처치하세요. 각자 상자를 하나씩 들고 있습니다.",
		["Only if {npc:9298} gave you {quest:5086}: ride north up the {zone:1448} road to {area:1767}; the {quest:5086} ooze between the trees."] = "{npc:9298}에게 {quest:5086}을(를) 받았을 때만: {zone:1448} 길을 따라 북쪽 {area:1767}(으)로 가세요. {quest:5086}이(가) 나무 사이를 떠돕니다.",
		["Only with 30 {quest:6031}, and only at Neutral with the Timbermaw: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "{quest:6031} 30개가 있고 나무구렁일족과 중립일 때만: 길을 따라 북쪽 {area:1769}(으)로 가세요. {npc:11557}이(가) 입구 바로 안에서 거래합니다.",
		["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "선택 사항. 사냥 대신 파티로 {area:2279}, {area:2057}, 검은바위 첨탑 하층, {area:1584}을(를) 돌면 더 빨리 도달합니다.",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "선택 사항: 파티가 있으면 55-60 던전으로 아래 사냥을 대신하세요.",
		["Ride east along the road to {area:2255}."] = "길을 따라 동쪽 {area:2255}(으)로 가세요.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "길을 따라 북쪽으로 {area:1763}을(를) 지나 {area:1997}(으)로 가세요.",
		["Ride north-west to {area:1763}. The four braziers stand among the Shadow Council's buildings; use the Cleansed Water on each one."] = "북서쪽 {area:1763}(으)로 가세요. 화로 네 개가 어둠의 의회 건물들 사이에 있습니다. 각 화로에 정화된 물을 사용하세요.",
		["South to the Sanctuary once more."] = "다시 남쪽 성소로 가세요.",
		["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {zone:1452}, south of the road from {area:2255}."] = "여기서 퀘스트가 끝납니다. 광포한 톱니이빨곰이 {zone:1452} 남쪽, {area:2255}에서 오는 길 남쪽의 {area:2249}을(를) 돌아다닙니다.",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "나무구렁일족 동굴을 지나 {zone:1450}(으)로 가세요. {npc:11939}은(는) {area:2361}의 한 집에서 책을 읽고 있습니다.",
		["Zeppelin to {zone:1454}"] = "비행선 타고 {zone:1454}(으)로",
		["grind on {npc:7446} at {area:2249}, {zone:1452}"] = "{zone:1452}, {area:2249}에서 {npc:7446} 사냥",
		["{npc:10306}'s next {quest:4741} would bring you back here from {zone:1452}. Skip it."] = "{npc:10306}의 다음 퀘스트 {quest:4741}은(는) {zone:1452}에서 여기로 다시 와야 합니다. 건너뛰세요.",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "{npc:11801}의 악령덩굴 조각은 {area:2577}이(가) 필요합니다. 건너뛰세요.",
		["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "{npc:9116}의 은색 심장은 {zone:1448} 북쪽의 {item:11173}을(를) 가지고 여기로 돌아와야 합니다. 건너뛰세요.",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298}은(는) 다음으로 동굴 속 정예인 {npc:10738}을(를) 처치하라고 보냅니다. 건너뛰세요.",
		["{npc:9861}, {npc:9860} and {npc:9517} wait at the back of {area:1770}, the cave in {area:1763}'s north. Clear the tunnel as you go."] = "{npc:9861}, {npc:9860}, {npc:9517}은(는) {area:1763} 북쪽 동굴인 {area:1770} 안쪽 끝에 있습니다. 가는 길에 통로를 정리하세요.",
} end)()
t.guides["forever/horde/orc-troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "{npc:3126}은(는) {area:362} 서쪽 평원을 기어다닙니다. 하나를 길들인 뒤 {npc:3171}에게 돌아가세요.",
		["Back at the Den"] = "동굴 막사로 돌아오기",
		["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "동쪽으로 {npc:275657} 북쪽 해안에 돌아가세요. {npc:275662}와(과) 수행원이 {area:370} 아래 해변을 차지하고 있습니다. 사냥꾼: 해변에서 {npc:3107}을(를) 길들이세요.",
		["Back south to {area:362}."] = "남쪽 {area:362}(으)로 돌아가세요.",
		["Back to the Den"] = "동굴 막사로 돌아가기",
		["Back to {area:362}."] = "{area:362}(으)로 돌아가세요.",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "{object:172960}의 {npc:5875}에게 돌아가세요. 그곳 소환진에서 {item:7464}을(를) 사용하고 공허방랑자를 물리쳐 속박하세요.",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "불타는 칼날단 이교도가 {quest:827}의 동굴을 차지하고 있으며, 누구든 {item:4871}을(를) 떨어뜨립니다. 14레벨 흑마법사 {npc:3204}은(는) 깊숙한 곳에 서 있으며 {item:4903}을(를) 떨어뜨립니다.",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "하급 지옥사냥개는 골짜기 북쪽, 동굴 아래 비탈을 돌아다닙니다.",
		["Fizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way."] = "피즐은 {area:362} 북서쪽 {area:369}의 불타는 칼날단 야영지를 지킵니다. 사냥꾼: 가는 길에 {item:15908}(으)로 {npc:3099}을(를) 길들이세요.",
		["Follow the road east out of the valley to {area:367} on the coast."] = "길을 따라 동쪽으로 골짜기를 나가 해안의 {area:367}까지 가세요.",
		["Follow the road north from {area:362} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "길을 따라 {area:362}에서 북쪽 {area:817} 바로 서쪽의 {zone:1454} 정문까지 가세요. {npc:3352}은(는) {object:172958}에서 사냥꾼 상급자들과 함께 서 있습니다.",
		["Follow the road north to {area:362}."] = "길을 따라 북쪽 {area:362}(으)로 가세요.",
		["Follow the road north toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "길을 따라 북쪽 {zone:1454} 쪽으로 가세요. {npc:3293}이(가) 길 옆에 진을 치고 있고, 도둑맞은 자루는 그 남쪽 길가에 있습니다.",
		["Follow the road south-west from {area:379} to the {area:380}. {zone:1413} guide starts here."] = "{area:379}에서 길을 따라 남서쪽 {area:380}로 가세요. {zone:1413} 가이드는 여기서 시작합니다.",
		["Follow the road west from {area:362} over the {area:814} bridge; {area:379} sits just above it on the {zone:1413} side."] = "{area:362}에서 길을 따라 서쪽으로 {area:814} 다리를 건너세요. {area:379}은(는) 다리 바로 위 {zone:1413} 쪽에 있습니다.",
		["Free {npc:275811} and see her safely out of the crag"] = "{npc:275811}을(를) 풀어 주고 무사히 밖으로 데려가세요",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "섬들을 지나 남쪽으로 가세요. 로아 우상은 남쪽 섬 곳곳에 있으며, 부두교 트롤과 {npc:3207}이(가) 이를 지키고 {item:275724}을(를) 떨어뜨립니다. {quest:826}와(과) 민시나의 우리는 가장 남쪽 섬에 있습니다.",
		["Hit the sleeping peons north of the Den with the {item:16114}."] = "동굴 막사 북쪽에서 잠자는 일꾼을 {item:16114}(으)로 때리세요.",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "동굴 안에서 첫 갈림길은 직진하고, 이어서 오른쪽으로 가 왼편 개울을 따라 폭포까지 가세요. 곡괭이는 바위 기둥 뒤 물가에서 빛나고 있습니다.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "동굴 안에서 개울을 건너 오른쪽 벽을 따라 끝까지 돌아가세요. {npc:3183}이(가) 끝에서 기다립니다.",
		["Makrura and crawlers"] = "마크루라와 붉은톱니게",
		["Makrura and surf crawlers line the beaches north-east of Sen'jin."] = "마크루라와 붉은톱니게가 센진 북동쪽 해변에 늘어서 있습니다.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "미샤의 오두막은 도마뱀들의 남쪽에 있습니다. 서쪽 {area:814}을(를) 따라 있는 악어가 {item:4891}을(를) 가지고 있습니다.",
		["North end of the valley"] = "골짜기 북쪽 끝",
		["Prickly pears"] = "가시투성이 배",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "가시멧돼지와 정찰병이 마을 서쪽 오두막을, 사막길잡이와 전투호위병이 더 서쪽의 야영지를 차지하고 있습니다.",
		["Ridgeshade spiders"] = "능선그늘 거미",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}."] = "먼지바람일족 여전사와 폭풍마녀가 {npc:3293} 동쪽 {area:370}에 둥지를 틀고 있습니다. 폭풍마녀가 {item:277661}을(를) 떨어뜨립니다.",
		["South-east shore"] = "남동쪽 해안",
		["Spitelash naga"] = "원한의꼬리일족 나가",
		["Talk to {npc:3191}"] = "{npc:3191}와(과) 대화하세요",
		["Tame it with the {item:15908}"] = "{item:15908}(으)로 길들이세요",
		["The foreman stands at the lumber pile east of the Den."] = "작업반장은 동굴 막사 동쪽의 목재 더미 옆에 서 있습니다.",
		["The gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin."] = "노움 공구 상자는 {area:362} 동쪽과 남동쪽 해안의 잔해 속에 있습니다. 해안을 따라 남쪽 센진으로 가세요.",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "요새는 {area:362} 남동쪽 해안에 있습니다. 약탈자의 도끼, 활, 방패는 요새 외곽에 있습니다. 선원과 해병이 {item:4870}을(를) 떨어뜨립니다. {npc:3192}은(는) 요새 꼭대기에서 기다리며, 그의 열쇠로 옆 상자를 열면 {item:4881}이(가) 들어 있습니다.",
		["The prickly pears grow among the quilboar huts just west of town."] = "가시투성이 배는 마을 바로 서쪽의 멧돼지인간 오두막 사이에 자랍니다.",
		["The spiders lurk in the hills along the road north toward {area:362}."] = "거미는 {area:362}(으)로 가는 북쪽 길을 따라 언덕에 숨어 있습니다.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "무기는 동굴 막사와 훈련장 주변에 있고, {npc:3098}은(는) 골짜기 바닥 전체를 돌아다닙니다.",
		["The wreckage"] = "잔해",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595}은(는) 방금 싸운 이교도들 사이, {area:817} 안에 있습니다.",
		["The {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "{quest:792}이(가) 골짜기 북쪽 동굴인 {area:365} 아래 비탈에 우글거립니다.",
		["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "{npc:3130}와(과) {npc:3131}이(가) 다리 건너 {area:369}에서 풀을 뜯으며, 누구든 {item:6486}을(를) 떨어뜨릴 수 있습니다.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}."] = "{npc:3130}와(과) {npc:3131}이(가) {npc:3293} 바로 서쪽과 남서쪽의 {area:369}에서 풀을 뜯습니다.",
		["Thunder lizards"] = "천둥도마뱀",
		["Thunder lizards across the river"] = "강 건너 천둥도마뱀",
		["Training weapons and boars"] = "훈련용 무기와 멧돼지",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there."] = "물을 건너 북쪽 메아리 섬으로 가세요. 붉은발톱랩터 어미가 그곳 랩터들 사이를 어슬렁거립니다.",
		["Wade back west to the shore south of Sen'jin. Durotar Tigers roam it and the Taillasher eggs sit in nests along the beach."] = "물을 건너 서쪽으로 센진 남쪽 해안에 돌아가세요. {npc:3121}이(가) 그곳을 돌아다니고, 붉은발톱랩터 알은 해변의 둥지에 있습니다.",
		["Wake {quest:5441} with the {item:16114}"] = "{item:16114}(으)로 {quest:5441} 깨우기",
		["the {object:654925} on the ground beside her"] = "그녀 옆 땅바닥의 {object:654925}",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366}은(는) 센진 서쪽에 있습니다. 공격 계획서 세 개는 켄타우로스 천막 사이 땅바닥에 있습니다. {npc:275811}도 그곳에 붙잡혀 있습니다.",
		["{area:817}'s mouth"] = "{area:817} 입구",
		["{npc:10176}, where you start"] = "{npc:10176}, 시작 지점",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears."] = "{npc:265809}은(는) {area:362} 바로 남쪽에 진을 치고 있습니다. {spell:1229451} 효과가 나타날 때까지 그의 모닥불 옆에 앉으세요(/앉기).",
		["{npc:265809}'s campfire"] = "{npc:265809}의 모닥불",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: 마법부여사 전용, 잔여물은 {item:275724}을(를) 마력 추출해서 얻습니다",
		["{npc:266940}, on the east side of town"] = "{npc:266940}, 마을 동쪽",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657}은(는) {area:362} 동쪽 해안에 서 있습니다. 삼지창, 깃발, 단검은 그 주변 해변에 있습니다.",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "어린 바다 거인 {npc:275666}은(는) 나가 해변 북쪽, {zone:1411} 북쪽 해안을 걸어다닙니다. {npc:275666}은(는) 정예이니 파티를 권합니다.",
		["{npc:3102} hooves"] = "{npc:3102} 발굽",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, {area:362}에 돌아가서",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: 정예 바다 거인 {npc:275666}",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143}은(는) 동굴 입구 바로 안쪽에, {npc:3159}은(는) 그 뒤 동굴 안쪽에 서 있습니다.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143}은(는) {npc:10176} 바로 서쪽 건물인 동굴 막사 안에서 기다립니다.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, 감시탑 안",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, 동굴 막사 옆의 전사 상급자",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, 동굴 막사 옆의 사냥꾼 상급자",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, 동굴 막사의 도적 상급자",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, 동굴 안쪽의 흑마법사 상급자",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, 동굴 막사 옆의 주술사 상급자",
		["{npc:3159}, at the back of the cave"] = "{npc:3159}, 동굴 안쪽",
		["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171}: {zone:1454}의 {npc:3352}이(가) {spell:5149}을(를) 가르칩니다",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287}은(는) 동굴 막사 북서쪽 언덕 기슭에 부상당한 채 누워 있습니다.",
		["{npc:3294}, by the inn"] = "{npc:3294}, 여관 옆",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, {zone:1454}의 {npc:6018}에게 줄 것: 보관하세요",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, 동굴 막사의 사제 상급자",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, 동굴 막사 입구의 마법사 상급자",
		["{npc:5887} stands just outside the Den."] = "{npc:5887}은(는) 동굴 막사 바로 바깥에 서 있습니다.",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887}은(는) 동굴 막사 바깥에 서 있습니다. {area:639}은(는) 그 바로 남쪽 언덕입니다. 그곳에서 {item:6635}을(를) 마셔 {npc:5891}을(를) 보고, {item:6656}을(를) {npc:5887}에게 가져가세요.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873}, {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, {area:639} 위",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786}은(는) 골짜기 동쪽 출구의 길 위에 서 있습니다.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, 요리용 모닥불 옆",
		["{quest:790}, a large scorpid, prowls the slope south of {npc:3287} among the Scorpid Workers; pick the Cactus Apples by the cactuses on the way."] = "커다란 전갈 {quest:790}은(는) {npc:3287} 남쪽 비탈의 {npc:3124} 사이를 어슬렁거립니다. 가는 길에 선인장 옆의 {item:11583}을(를) 따세요.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828}은(는) 나가 해변 서쪽, {quest:827} 남쪽 언덕에 진을 치고 있습니다.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "{zone:1454} 정문은 {area:817} 바로 서쪽에 있습니다. {npc:5875}은(는) {object:172982} 아래 협곡인 {object:172960}에 서 있습니다.",
} end)()
t.guides["forever/horde/orc-troll/02-the-barrens"] = (function() return {
		["Back to the pirate camp: the boots are in the crate marked {object:3767} at the camp's south end, the lens in the Fragile crate just east of it."] = "해적 야영지로 돌아가세요. 장화는 야영지 남쪽 끝의 {object:3767} 표시 상자에, 렌즈는 그 바로 동쪽의 Fragile 상자에 있습니다.",
		["Back to the {area:380}"] = "{area:380}로 돌아가기",
		["Back to the {area:380}; the next guide starts here."] = "{area:380}로 돌아가세요. 다음 가이드는 여기서 시작합니다.",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}, by {area:370}; they drop the {item:6652}."] = "{npc:3199}이(가) {zone:1411} 북부 {area:370} 옆의 {area:1898}을(를) 차지하고 있으며, {item:6652}을(를) 떨어뜨립니다.",
		["Follow the road north to the {area:1703}; {npc:9316} stands just south of it."] = "길을 따라 북쪽 {area:1703}까지 가세요. {npc:9316}은(는) 그 바로 남쪽에 서 있습니다.",
		["Follow the road south-east to {area:392} on the coast."] = "길을 따라 남동쪽으로 해안의 {area:392}까지 가세요.",
		["Head east to the Venture Co. research site west of the {area:382}. Use the {object:4141}, close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471}."] = "동쪽으로 {area:382} 서쪽의 투자개발회사 연구 현장으로 가세요. {object:4141}을(를) 사용하고, 시추기 주변의 밸브 세 개를 잠근 뒤, 다시 제어판을 사용하고 {npc:3471}에게서 {item:5089}을(를) 가져가세요.",
		["Kolkar camps and the {area:386}"] = "콜카르 야영지와 {area:386}",
		["Oasis Snapjaws crowd the water of {area:387}, south-west of the {area:380}."] = "오아시스 무쇠턱거북이 {area:380} 남서쪽 {area:387}의 물에 가득합니다.",
		["On the way back to the {area:380}, the Razormane camp again: Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "{area:380}로 돌아가는 길에 다시 서슬갈기일족 야영지로: 흙점쟁이와 파수병이 동쪽 절반을 차지하고 있으며, {npc:3438}이(가) 그 사이를 걸어다닙니다.",
		["Plainstriders and Sunscale raptors roam the plains all around the {area:380}."] = "초원타조와 열대초원랩터가 {area:380} 주변 평원 곳곳을 돌아다닙니다.",
		["Plainstriders and raptors"] = "초원타조와 랩터",
		["Razormane camp"] = "서슬갈기일족 야영지",
		["Southsea beach"] = "남쪽바다 해변",
		["The Kolkar camps spread north-west of {npc:3389}; every Kolkar can drop {quest:855}. {area:386} lie in their middle, with Laden Mushrooms around the water. Savannah Prowlers roam the same plains."] = "콜카르 야영지는 {npc:3389} 북서쪽으로 퍼져 있습니다. 콜카르는 누구나 {quest:855}을(를) 떨어뜨릴 수 있습니다. {area:386}은(는) 그 한가운데에 있고, 물가에 독버섯이 있습니다. 굶주린 사바나 사자도 같은 평원을 돌아다닙니다.",
		["The Slayers hold the western end of the {area:383}, past the harpies you fought before; they drop the rings."] = "암살자는 전에 싸운 하피들 너머 {area:383} 서쪽 끝을 차지하고 있으며, 반지를 떨어뜨립니다.",
		["The Tool Buckets sit around the Venture Co. camp in the {area:382}, east of {npc:9316}."] = "연장통은 {npc:9316} 동쪽 {area:382}의 투자개발회사 야영지 주변에 있습니다.",
		["The harpies nest in the {area:383} north-west of the {area:386}; any of them can drop a talon."] = "하피는 {area:386} 북서쪽 {area:383}에 둥지를 틀고 있습니다. 누구든 발톱을 떨어뜨릴 수 있습니다.",
		["The oasis lies south-east of the {area:380}. Test the seeds at the bubbling fissure in the middle of the water."] = "오아시스는 {area:380} 남동쪽에 있습니다. 물 한가운데 거품이 이는 균열에서 씨앗을 시험하세요.",
		["The pirates camp along the beach south of {area:392}. The piles of complicated parts lie in and around their camp."] = "해적들이 {area:392} 남쪽 해변을 따라 진을 치고 있습니다. 복잡한 부품 더미는 야영지 안팎에 있습니다.",
		["The {area:1697} lie south-west of the oasis. Sunscale Scytheclaws drop the feathers you use on the three nests."] = "{area:1697}은(는) 오아시스 남서쪽에 있습니다. {npc:3256}이(가) 떨어뜨리는 깃털을 둥지 세 곳에 사용하세요.",
		["Wade into the pools to explore them"] = "웅덩이에 들어가 탐험하세요",
		["Walk back up the road to the {area:380}. Savannah Prowlers hunt along it and on the plains west of town: finish the claws before you hand them in."] = "길을 따라 {area:380}까지 걸어 돌아가세요. 굶주린 사바나 사자가 길가와 마을 서쪽 평원에서 사냥합니다. 제출하기 전에 발톱을 마저 모으세요.",
		["Water Seekers, Thornweavers and Hunters hold the camp east of the {area:380}. The supply crates sit at its eastern end. Warriors: the {object:58369} stands in the camp. Shamans: the quilboar drop the {item:5026}. Kill Savannah Prowlers you pass for their claws."] = "서슬갈기일족 풍수사, 가시마술사, 사냥꾼이 {area:380} 동쪽 야영지를 차지하고 있습니다. 보급품 상자는 야영지 동쪽 끝에 있습니다. 전사: {object:58369}은(는) 야영지 안에 있습니다. 주술사: 멧돼지인간이 {item:5026}을(를) 떨어뜨립니다. 지나가며 굶주린 사바나 사자를 처치해 발톱을 모으세요.",
		["Witchwing Slayers"] = "{npc:3278}",
		["Witchwing harpies"] = "칼날바람하피",
		["You arrive from {area:379}. {npc:3338} stands by the inn; {npc:3429} and {npc:3449} on the tower platform; Helbrim and {npc:3464} by the north gate; {npc:3448} at the south gate."] = "{area:379}에서 도착합니다. {npc:3338}은(는) 여관 옆에, {npc:3429}와(과) {npc:3449}은(는) 탑 위에, 헬브림과 {npc:3464}은(는) 북문 옆에, {npc:3448}은(는) 남문에 있습니다.",
		["Zhevra Runners graze on the same plains; finish the raptor heads as you go."] = "{npc:3242}도 같은 평원에서 풀을 뜯습니다. 가는 길에 랩터 머리도 마저 모으세요.",
		["Zhevra and raptors"] = "얼룩말과 랩터",
		["grind on Witchwing Slayers at the {area:383}, {zone:1413}"] = "{zone:1413} {area:383}에서 {npc:3278} 사냥",
		["{area:1898} cultists"] = "{area:1898} 이교도",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389}은(는) {area:380} 바로 서쪽의 콜카르 감시초소에 서 있습니다.",
		["{npc:3449}, on the tower platform: needs level 12"] = "{npc:3449}, 탑 위: 12레벨 필요",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878}은(는) {area:392}(으)로 가는 동쪽 길 옆에 진을 치고 있습니다.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900}이(가) 타르와 주머니로 {item:6636}을(를) 만들어 줍니다. 그 옆 화로에서 사용해 {npc:5893}을(를) 드러내고, 처치해 {item:6655}을(를) 얻은 뒤 잉걸불을 화로에 넣으세요.",
		["{npc:5900} waits on the {zone:1411} bank of the {area:814}, east of the Razormane camp."] = "{npc:5900}은(는) 서슬갈기일족 야영지 동쪽, {area:814}의 {zone:1411} 쪽 강둑에서 기다립니다.",
		["{npc:5907} stands on the ridge north of the Razormane camp, east of the {area:380}."] = "{npc:5907}은(는) {area:380} 동쪽, 서슬갈기일족 야영지 북쪽 능선에 서 있습니다.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, {item:5176}, {item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}, 부두 위",
		["{quest:881}'s lair lies south of the {area:382}, north-east of the {area:380}. Use the horn {npc:3338} gave you there to call the white lion out. Then hearth to {area:392}."] = "{quest:881}의 굴은 {area:382} 남쪽, {area:380} 북동쪽에 있습니다. 그곳에서 {npc:3338}이(가) 준 뿔피리를 불어 흰 사자를 불러내세요. 그런 다음 {area:392}(으)로 귀환하세요.",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "{spell:1229451}을(를) 얻을 때까지 {npc:263664}의 모닥불 옆에서 /앉기 하세요",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "하늘사제 앤더스와 쓰러진 경비병들은 탑 바로 남서쪽에 있습니다. 시신에서 라니의 행운의 깃털과 섀도송 가문 인장을 챙기세요.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "다시 {quest:92529}: 알아케스 폭풍소환사와 {npc:251662}이(가) 마을을 메우고 있고, {object:576179}은(는) 집들 사이에 있으며, {npc:251966}은(는) 남동쪽 끝에서 기다립니다.",
		["Back to {area:16624} with what you found."] = "찾은 것을 가지고 {area:16624}(으)로 돌아가세요.",
		["Back to {area:16635}"] = "{area:16635}(으)로 돌아가기",
		["Back to {area:16638}"] = "{area:16638}(으)로 돌아가기",
		["Back to {npc:268592}, then west into the {area:16623}: {npc:268605}'s home is in the hills south of the Windsong Crawlers' lakes."] = "{npc:268592}에게 돌아간 뒤 서쪽 {area:16623}(으)로 가세요. {npc:268605}의 집은 바람노래 집게발 호수 남쪽 언덕에 있습니다.",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "{npc:268592}에게 돌아가세요. 그가 {npc:268762}에 불을 붙이면, 시간이 끝나기 전에 불꽃을 곧장 {area:16638}의 {npc:252382} 옆 {npc:268679}(으)로 가져가세요.",
		["Bandit Highwaymen"] = "산적 노상강도",
		["Cast {spell:1259686} near the {object:460001}"] = "{object:460001} 근처에서 {spell:1259686}을(를) 시전하세요",
		["Climb the watchtower in the village, jump off the top and use {spell:1259416} to float down."] = "마을의 감시탑에 올라 꼭대기에서 뛰어내린 뒤 {spell:1259416}(으)로 천천히 내려오세요.",
		["Faladiel stands on the hill west of the falls, north of {area:16638}."] = "하늘사제 팔라디엘은 {area:16638} 북쪽, 폭포 서쪽 언덕에 있습니다.",
		["Find {npc:258130}"] = "{npc:258130}을(를) 찾으세요",
		["Follow the road south to {area:16624}, in the middle of the isle."] = "길을 따라 남쪽으로 섬 한가운데의 {area:16624}에 가세요.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "북쪽 {area:16631}(으)로 가세요. {npc:257944}이(가) 숲 남쪽 끝에서 야영합니다.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "남서쪽 {area:17674}(으)로 가세요. {npc:252155}은(는) 꼭대기에 있고, {item:254871}은(는) 그 옆에 있습니다.",
		["Heal the injured druids in the Nightfang Den"] = "밤송곳니 굴의 다친 드루이드를 치유하세요",
		["High Order Apprentices"] = "{npc:257521}",
		["Hippogryph nests"] = "히포그리프 둥지",
		["Horde airship"] = "호드 비행선",
		["Leave {zone:1456} by a lift and follow the road south past {area:222} and through the eastern pass into the {zone:1413}; from the pass, take the {area:458} north to the {area:380}, the Horde town in the middle of the {zone:1413}."] = "승강기로 {zone:1456}을(를) 내려가 남쪽 길을 따라 {area:222}을(를) 지나고 동쪽 고개를 넘어 {zone:1413}(으)로 가세요. 고개에서 {area:458}을(를) 따라 북쪽으로 {zone:1413} 한가운데의 호드 마을 {area:380}에 가세요.",
		["Leaving {area:16635}"] = "{area:16635} 떠나기",
		["Listen to {npc:252448}'s story"] = "{npc:252448}의 이야기를 들으세요",
		["Listen to {npc:256083}"] = "{npc:256083}의 이야기를 들으세요",
		["Northern {zone:1412}"] = "{zone:1412} 북부",
		["On the way north, back to {npc:255853} by the falls."] = "북쪽으로 가는 길에 폭포 옆의 {npc:255853}에게 돌아가세요.",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "성가신 구름벌레와 {npc:250873}이(가) 마을 바로 남동쪽 숲을 돌아다닙니다.",
		["Prideclaws and Galestriders"] = "무리발톱과 돌풍타조",
		["Prideclaws and Galestriders share the meadows south of the village. Keep the {item:5469} for {npc:251905}; the eggs come later from the hippogryphs."] = "무리발톱과 돌풍타조가 마을 남쪽 초원에 함께 있습니다. {item:5469}은(는) {npc:251905}에게 줄 것이니 챙겨 두세요. 알은 나중에 히포그리프에게서 얻습니다.",
		["Raw Windstones"] = "{object:613286}",
		["Ride north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "북동쪽 {area:17675}(으)로 가세요. 알아케스 야영지는 그 바로 서쪽에 있으며, {npc:252666}은(는) 야영지 북쪽 끝에 있습니다. 신도는 모두 알아케스 바람석 부적을 떨어뜨릴 수 있습니다.",
		["Sit by {npc:263664}'s campfire (type /sit) until you get the {spell:1229451} buff, then find {npc:251905} at the cook fire."] = "{spell:1229451} 효과를 얻을 때까지 {npc:263664}의 모닥불 옆에 앉은 뒤(/앉기 입력), 요리용 불가의 {npc:251905}을(를) 찾으세요.",
		["Skyhoppers"] = "하늘폴짝이",
		["Skyhoppers hop about the fields just west of Valennia."] = "하늘폴짝이는 발레니아 바로 서쪽 들판을 뛰어다닙니다.",
		["Spread the {item:278078} off {area:1641}"] = "{area:1641}에서 {item:278078}을(를) 피우세요",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "잘 익은 폭풍사과와 펄럭날개 가루가 과수원 곳곳에 있고, 굶주린 좀도둑이 과수원을 습격합니다. 돌풍타조는 과수원 동쪽 들판에서 풀을 뜯습니다. 부서진 피조물은 과수원 북쪽 끝에 떠 있습니다.",
		["Take the Torch of Dormant Flame to {npc:268592} at the Shrine of Flames, south-west of {area:16638} in the {area:16626}."] = "희미한 불씨의 횃불을 {area:16638} 남서쪽 {area:16626}에 있는 불꽃의 제단의 {npc:268592}에게 가져가세요.",
		["Take the portal up to the {area:16630} and join {npc:252475} and {npc:251968} against the High Priestess."] = "차원문을 타고 {area:16630}(으)로 올라가 {npc:252475}, {npc:251968}와(과) 함께 대여사제 로르투나와 싸우세요.",
		["Take the road south-east to {area:16638}, the Skyborne town on the south coast. {npc:257006} and {npc:252448} stand at its western edge."] = "남동쪽 길을 따라 남쪽 해안의 스카이본 마을 {area:16638}(으)로 가세요. {npc:257006}와(과) {npc:252448}이(가) 마을 서쪽 끝에 있습니다.",
		["Talk to {npc:251902}"] = "{npc:251902}와(과) 대화하세요",
		["Talk to {npc:251968}"] = "{npc:251968}와(과) 대화하세요",
		["Talk to {npc:252383}"] = "{npc:252383}와(과) 대화하세요",
		["Talk to {npc:252800}"] = "{npc:252800}와(과) 대화하세요",
		["Talk to {npc:253576}"] = "{npc:253576}와(과) 대화하세요",
		["Talk to {npc:254089}"] = "{npc:254089}와(과) 대화하세요",
		["Tell {npc:252800} you're ready"] = "{npc:252800}에게 준비되었다고 말하세요",
		["The Al'Aketh camp"] = "알아케스 야영지",
		["The Al'Aketh cultists in the camp beyond {npc:252095} carry the signet."] = "{npc:252095} 너머 야영지의 알아케스 신도들이 아키르의 인장을 지니고 있습니다.",
		["The Horde airship docks at the south-west edge of {area:16638}. Ride it to Kalimdor; it lands in northern {zone:1412}."] = "호드 비행선은 {area:16638} 남서쪽 끝에 정박합니다. 타고 칼림도어로 가세요. {zone:1412} 북부에 내립니다.",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "{object:613286}은(는) 마을 주변 비탈에 있는 파란 수정입니다.",
		["The Ursera den is west of the village. {npc:251115}, their matriarch, sits at its far end."] = "우르세라 굴은 마을 서쪽에 있습니다. 우르세라의 어미 {npc:251115}은(는) 굴 맨 안쪽에 있습니다.",
		["The airship"] = "비행선",
		["The apprentices practise north-east of the village."] = "수습생들은 마을 북동쪽에서 수련합니다.",
		["The bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones."] = "좀도둑 야영지는 마을 북동쪽에 있으며, \"사악한 바람\" 베닉이 가장 위쪽 야영지를 차지하고 있습니다. 좀도둑들이 훔친 바람석을 지니고 있습니다.",
		["The crawlers scuttle along the shore south-west of town."] = "게들은 마을 남서쪽 해안을 따라 종종걸음 칩니다.",
		["The hermit lives at {area:16625}'s west shore. {item:257128} cones grow south of him; the Wind Hollows drift east of the lake."] = "은둔자는 {area:16625} 서쪽 물가에 삽니다. {item:257128} 솔방울은 그 남쪽에 자라고, {npc:251676}은(는) 호수 동쪽을 떠다닙니다.",
		["The highland bandits"] = "고원 좀도둑",
		["The highwaymen hold the hills north-east of the orchard. More {object:616468} lie near the road to {area:16638}."] = "노상강도는 과수원 북동쪽 언덕을 차지하고 있습니다. {area:16638}(으)로 가는 길 근처에 {object:616468}이(가) 더 있습니다.",
		["The hippogryph nests are north-west of the tower, west of {quest:92529}; the Matriarch sits at the western end. {item:263493} lies on the ground around them, and the hippogryphs drop the Small Eggs."] = "히포그리프 둥지는 탑 북서쪽, {quest:92529} 서쪽에 있으며, 히포그리프 어미는 서쪽 끝에 있습니다. {item:263493}은(는) 둥지 주변 땅에 있고, 히포그리프가 {item:6889}을(를) 떨어뜨립니다.",
		["The orchard"] = "과수원",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "구름벌레 여왕은 선돌에서 돌아오는 길, 숲 남동쪽 끝에 떠 있습니다.",
		["The refugees' belongings lie along the north shore of {area:16625}; {npc:259013} is at its north-west end."] = "피난민의 소지품은 {area:16625} 북쪽 물가를 따라 놓여 있고, {npc:259013}은(는) 북서쪽 끝에 있습니다.",
		["The standing stones"] = "선돌",
		["The turncoat"] = "배신자",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}. {npc:273017} waits nearby; his assassins lurk around the house."] = "배신자의 집은 {area:16638} 북서쪽 {area:16626}에 있습니다. {npc:273017}이(가) 근처에서 기다리고, 그의 암살자들이 집 주변에 숨어 있습니다.",
		["The watchtower"] = "감시탑",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629}은(는) {area:16638} 북쪽에 있습니다. 경비병들을 뚫고 동쪽의 {npc:253576}에게 가세요.",
