		["{item:278083}, from {npc:3027}"] = "{npc:3027}에게서 {item:278083}",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363}은(는) 마을 동쪽 {area:17678}에 있습니다. {npc:251143}와(과) 알아케스 전향자가 그녀 바로 북쪽에 모여 있습니다. {object:460001}은(는) 그녀 바로 북동쪽에 있으니, 그 옆에서 종족 특성 {spell:1259686}을(를) 시전하세요.",
		["{npc:250926} prowl the slopes south-west of the village, on the way to {npc:252095}."] = "{npc:250926}은(는) {npc:252095}에게 가는 길, 마을 남서쪽 비탈을 배회합니다.",
		["{npc:251361}'s errands"] = "{npc:251361}의 심부름",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: 상급자가 보낸 쪽지",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}: {item:282418}을(를) 살펴보세요",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: {item:9547}을(를) 읽으세요",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "드루이드 상급자 {npc:251373}: {npc:251361} 뒤편 나무의 1층",
		["{npc:251374} sends you to the {area:16988}, just east of the village: drink the {item:6635} there to see the {npc:251166}, then take the {item:6656} back to him."] = "{npc:251374}이(가) 마을 바로 동쪽 {area:16988}(으)로 보냅니다. 그곳에서 {item:6635}을(를) 마셔 {npc:251166}을(를) 보고, {item:6656}을(를) 그에게 가져가세요.",
		["{npc:251374} stands in the village."] = "{npc:251374}은(는) 마을에 있습니다.",
		["{npc:251374}, at the village centre"] = "마을 한가운데의 {npc:251374}",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}: {npc:5873}와(과) {item:5175}",
		["{npc:251389}, in the watchtower"] = "감시탑 안의 {npc:251389}",
		["{npc:251964}, in the watchtower"] = "감시탑 안의 {npc:251964}",
		["{npc:252095} waits in {area:16622}, south-west of the village. The Al'Aketh camp is just beyond her; {npc:256935} leads it."] = "{npc:252095}은(는) 마을 남서쪽 {area:16622}에서 기다립니다. 알아케스 야영지는 그 바로 너머에 있으며, {npc:256935}이(가) 이끕니다.",
		["{npc:252359} stands on {area:16638}'s east side."] = "{npc:252359}은(는) {area:16638} 동쪽에 있습니다.",
		["{npc:252377} stands in the middle of {area:16638}."] = "{npc:252377}은(는) {area:16638} 한가운데에 있습니다.",
		["{npc:252382} stands on {area:16638}'s west side."] = "{npc:252382}은(는) {area:16638} 서쪽에 있습니다.",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {npc:2523}, {item:5176}, {item:263412}",
		["{npc:252389} in {area:16638} hands you a {item:15908} three times: tame a {npc:254588} by the lakes north-west of town, an {npc:251707} in the fields west of town and a {npc:250874} at {area:16663}, returning to her after each. {npc:254411} stands beside her."] = "{area:16638}의 {npc:252389}이(가) {item:15908}을(를) 세 번 줍니다. 마을 북서쪽 호숫가의 {npc:254588}, 마을 서쪽 들판의 {npc:251707}, {area:16663}의 {npc:250874}을(를) 길들이고, 매번 그녀에게 돌아가세요. {npc:254411}은(는) 그녀 옆에 있습니다.",
		["{npc:252448} and {npc:256083}"] = "{npc:252448}와(과) {npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130}, {npc:258134}은(는) {npc:257944} 동쪽 교단 야영지에 있습니다. {npc:254151}은(는) 야영지 가장자리에 있습니다. 할리엔은 {quest:94490}도 떨어뜨리니 읽어서 다음 퀘스트를 시작하세요. {quest:94489}은(는) 밤송곳니 굴에 들어가 다친 드루이드 7명을 치유하고 {npc:258130}을 찾으세요.",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589}은(는) 마을 남쪽 무리발톱 사이에 숨어 있습니다. {npc:254589}은(는) 정예이니 파티를 권장합니다.",
		["{npc:255853} waits by the falls just north of the watchtower."] = "{npc:255853}은(는) 감시탑 바로 북쪽 폭포 옆에서 기다립니다.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083}은(는) 마을 바로 북서쪽 {area:16626}에 있습니다.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247}은(는) {area:16629}(으)로 가는 {area:16638} 북쪽 길에서 기다립니다.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196}이(가) 제단 서쪽에서 {item:263993}을(를) 지니고 있습니다.",
		["{npc:257944} again"] = "다시 {npc:257944}",
		["{npc:257944}, last time"] = "마지막으로 {npc:257944}",
		["{npc:258443} roams the slopes just south of the turncoat's house."] = "{npc:258443}은(는) 배신자의 집 바로 남쪽 비탈을 배회합니다.",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "착륙장 옆의 {npc:259118}: {zone:1456}의 {npc:3033}에게",
		["{npc:259119}: keep it, Thrall in {zone:1454} comes two guides later"] = "{npc:259119}: 보관하세요. {zone:1454}의 스랄은 두 가이드 뒤에 나옵니다",
		["{npc:263664}'s campfire"] = "{npc:263664}의 모닥불",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}은(는) 타우렌 향을 원합{npc:3014}. 약초상 니다, 마법부여 상인 {npc:3012}, 가죽세공 상인 {npc:3005}, 요리 상인 {npc:3027}에게서 재료 네 가지를 사서 {item:278078}(으)로 합치세요.",
		["{npc:3033} trains druids on {area:1639}. He teaches you {spell:18960}; {npc:11802}'s welcome waits for your {spell:499} trip at about 23 (forever/horde/04-the-barrens)."] = "{npc:3033}은(는) {area:1639}에서 드루이드를 가르칩니다. 그에게서 {spell:18960}을(를) 배우세요. {npc:11802}의 환영 인사는 23레벨쯤 {spell:499} 여정 때 받습니다(forever/horde/04-the-barrens).",
		["{npc:3615}, the wind rider master"] = "와이번 조련사 {npc:3615}",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529}은(는) 셴다르 마을 남쪽에 있습니다. 마을 가장자리에서 {npc:257065}을(를) 만나고, 그 뒤편 집의 옷장을 뒤지세요.",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "{spell:1229451}을(를) 얻을 때까지 카가의 모닥불 옆에서 /앉기",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "동쪽의 {area:358}(으)로 돌아가세요. 뾰족털일족 주술사는 그곳 가시멧돼지 사이에 있습니다.",
		["Back south-east to the {area:396}."] = "남동쪽의 {area:396}(으)로 돌아가세요.",
		["Back to Bloodhoof"] = "블러드후프 마을로 돌아가기",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "야영지의 {npc:5888}에게 돌아가세요. {npc:5891}은(는) 야영지 동쪽 고원에서 기다립니다. 그곳에서 {item:6635}을(를) 마시면 보입니다. {item:6656}을(를) 예언자에게 가져가세요.",
		["Back west to the camp."] = "서쪽의 야영지로 돌아가세요.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "전투멧돼지는 제단 북쪽에서 풀을 뜯고, 뾰족털 가시멧돼지는 북동쪽 협곡을 차지하고 있습니다. {npc:8554}은(는) 협곡 동쪽 끝에 서 있고, {object:3076}은(는) 야영지 바닥에 있습니다.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있고, {quest:5930}은(는) 북서쪽 숲에 있습니다.",
		["Class turn-ins in {area:1638}"] = "{area:1638}에서 직업 퀘스트 완료",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "북서쪽으로 {zone:1456}을(를) 지나 {zone:1412} 맨 북쪽의 {area:398}(으)로 가세요.",
		["Finish the wolf heart, cougar femur, plainstrider scale and swoop gizzard on the plains around the village."] = "마을 주변 평원에서 늑대 심장, 퓨마 대퇴골, 초원타조 비늘, 검독수리 모래주머니를 마저 모으세요.",
		["Flatland Prowlers roam the plains around {area:225}"] = "굶주린 평원퓨마는 {area:225} 주변 평원을 돌아다닙니다",
		["Follow the path south out of camp to the Seer's tent at the foot of the hills."] = "길을 따라 야영지에서 남쪽으로 나가 언덕 기슭의 예언자 천막으로 가세요.",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}."] = "길을 따라 {area:220}에서 북쪽으로 나가세요. {npc:265810}은(는) {area:222} 바로 남쪽 길에서 기다립니다. {spell:1229451}을(를) 얻을 때까지 그녀의 모닥불 옆에서 /앉기 하세요.",
		["Galak centaurs and Prairie Wolf Alphas"] = "갈라크일족 켄타우로스와 우두머리 초원늑대",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "북쪽으로 {zone:1456} 동쪽의 {area:225}(으)로 가세요. {npc:3233}은(는) 바위 기슭에 서 있습니다. 뾰족털일족 약탈자는 매장지를 파헤치고 있고, {npc:2994}은(는) 꼭대기에서 기다립니다.",
		["Hearth to {area:222} and ride north to {area:1639}."] = "귀환석으로 {area:222}에 간 뒤 북쪽의 {area:1639}(으)로 가세요.",
		["Leave {zone:1412} by the south-eastern pass and follow the road to the {area:380}. {quest:860} stands by the inn, {npc:3448} at the south gate. {zone:1413} guide starts here."] = "남동쪽 고갯길로 {zone:1412}을(를) 나가 길을 따라 {area:380}(으)로 가세요. {quest:860}은(는) 여관 옆에, {npc:3448}은(는) 남문에 서 있습니다. {zone:1413} 가이드는 여기서 시작합니다.",
		["Plainstriders roam the grass all around the camp."] = "초원타조는 야영지 주변 풀밭 곳곳을 돌아다닙니다.",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "초원늑대와 다자란 초원타조가 마을 주변 평원을 돌아다닙니다.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "승강기를 타고 고원으로 올라가세요. {npc:2995}은(는) 중앙 고지에서 윈드라이더를 돌보고, {npc:3057}은(는) 그곳 큰 천막에 서 있습니다.",
		["Ride down to {area:222} and tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a Swoop to the north-west."] = "{area:222}(으)로 내려가 {item:15908}(으)로 길들이세요: 평원의 {npc:2956}, 마을 북쪽의 {npc:2959}, 북서쪽의 검독수리.",
		["Speak with {npc:3067}"] = "{npc:3067}와(과) 대화하기",
		["Spread the {item:278078} off {area:1641}"] = "{area:1641}에서 {item:278078} 뿌리기",
		["Swoops glide over the plains all around Bloodhoof."] = "검독수리는 블러드후프 마을 주변 평원 곳곳을 활공합니다.",
		["Tame it with the {item:15908}"] = "{item:15908}(으)로 길들이기",
		["The Galak centaurs camp on the plains north of the {area:821}; Herak leads them. Prairie Wolf Alphas roam among the wolves."] = "갈라크일족 켄타우로스는 {area:821} 북쪽 평원에 야영하고 있으며, 헤라크가 그들을 이끕니다. 우두머리 초원늑대는 늑대들 사이를 돌아다닙니다.",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "회색갈기일족 놀은 발굴지 남쪽, 블러드후프 마을 서쪽의 {area:818}을(를) 차지하고 있습니다. {npc:272203}은(는) 그들의 야영지에 붙잡혀 있습니다. 밖으로 데리고 나오세요.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "성난바람하피는 우물 북쪽과 서쪽의 {area:819}을(를) 차지하고 있습니다.",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the forge in {area:222}."] = "{area:404}의 드워프들이 발굴조사단장의 곡괭이를 지니고 있습니다. {area:222}의 대장간에서 부수세요.",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "고블린들은 우물 북동쪽 언덕의 광산에서 일합니다. {quest:765}은(는) 광산 안쪽에 서 있습니다. 그의 {item:281031}이(가) {quest:98424}을(를) 시작하며, 나머지 쪽은 광산 안에 있습니다.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "향은 10분 안에 다 탑니다. 남쪽 언덕을 따라 곧장 동쪽의 {object:660739}(으)로 달려가세요.",
		["The shrine of An'she and Mu'sha"] = "안셰와 무샤의 제단",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "돌은 동쪽으로 가는 길에 있는 {zone:1412} 출구 고갯길에 있습니다. 그곳에서 {item:15710}을(를) 사용하고 초승달발톱을 물리치세요.",
		["The well lies north of the village. Well Stones sit around the well, {item:4809} lies under the trees nearby. Kill wolves, cougars, plainstriders and swoops on the way for {quest:766} and {quest:761}."] = "우물은 마을 북쪽에 있습니다. 우물돌은 우물 주변에, {item:4809}은(는) 근처 나무 아래에 있습니다. 가는 길에 {quest:766}와(과) {quest:761}을(를) 위해 늑대, 퓨마, 초원타조, 검독수리를 처치하세요.",
		["The well lies south-east of the village."] = "우물은 마을 남동쪽에 있습니다.",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "부서진 대상단은 켄타우로스 북서쪽, {zone:1456}(으)로 가는 길 동쪽에 있습니다.",
		["The {object:177525}"] = "{object:177525}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "{area:1641}의 남쪽 절벽에 있는 의식용 깔개와 향로에서 {item:278078}을(를) 사용하세요.",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "{area:221}의 고원에서 시작합니다. {npc:2980}와(과) 족장은 한가운데 큰 천막 옆에 서 있습니다.",
		["{item:278079}, from {npc:3014}"] = "{npc:3014}에게서 사는 {item:278079}",
		["{item:278080}, from {npc:3012}"] = "{npc:3012}에게서 사는 {item:278080}",
		["{item:278081}, from {npc:3005}"] = "{npc:3005}에게서 사는 {item:278081}",
		["{item:278083}, from {npc:3027}"] = "{npc:3027}에게서 사는 {item:278083}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}은(는) 타우렌 향을 원합{npc:3014}. 약초 상인 니다, 마법부여 재료 상인 {npc:3012}, 가죽세공 재료 상인 {npc:3005}, 요리 재료 상인 {npc:3027}에게서 재료 네 가지를 사서 {item:278078}(으)로 합치세요.",
		["{npc:275789} stands on the {area:821} a little east of the well."] = "{npc:275789}은(는) 우물 조금 동쪽의 {area:821}에 서 있습니다.",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182}은(는) 마을 북쪽 가장자리에 서 있습니다. 카일은 초원타조에게서 얻는 {item:287505}을(를) 원합니다.",
		["{npc:277182}, at the north end of the village"] = "마을 북쪽 끝의 {npc:277182}",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{zone:1456}의 하물에게 갈 {npc:2948}",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984}은(는) 우물 남쪽, {area:404} 가장자리에 서 있습니다.",
		["{npc:2988} camps by the {area:396} south-east of Bloodhoof."] = "{npc:2988}은(는) 블러드후프 마을 남동쪽의 {area:396} 옆에 야영하고 있습니다.",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {item:4755} stands next to her."] = "{npc:2991}은(는) 야영지 동쪽 가장자리 천막 옆에 앉아 있으며, {item:4755}은(는) 그 옆에 있습니다.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{zone:1456}의 {npc:3057}에게 갈 {npc:2993}",
		["{npc:3059}, the warrior trainer"] = "전사 상급자 {npc:3059}",
		["{npc:3060}, the druid trainer beside him"] = "그 옆의 드루이드 상급자 {npc:3060}",
		["{npc:3061}, the hunter trainer"] = "사냥꾼 상급자 {npc:3061}",
		["{npc:3062}, the shaman trainer in camp"] = "야영지의 주술사 상급자 {npc:3062}",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "{npc:3063}의 퀘스트: 그 옆에서 풋내기 전사 세 명(또는 결투로 플레이어)을 이기세요.",
		["{npc:3209}, next to {npc:2980}"] = "{npc:2980} 옆의 {npc:3209}",
		["{npc:3441}: for {quest:860} at the {area:380}"] = "{npc:3441}: {area:380}의 {quest:860}에게",
		["{npc:5769}: for {npc:3448} at the {area:380}"] = "{npc:5769}: {area:380}의 {npc:3448}에게",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888}은(는) {area:221}에 서 있습니다. {quest:1516}에는 4레벨이 필요하며, 여기서 퀘스트를 완료하면 도달합니다.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}: {npc:5873}, {item:5175}",
		["{npc:6746} on the central rise sends you to {npc:3033} on {area:1639}."] = "중앙 고지의 {npc:6746}이(가) {area:1639}의 {npc:3033}에게 보냅니다.",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "{npc:6775}은(는) 야영지 서쪽 끝, 산지퓨마가 돌아다니는 언덕의 북서쪽 모퉁이에 서 있습니다. 그의 퀘스트를 받고, 거기서부터 남쪽과 동쪽으로 퓨마를 사냥한 뒤 {npc:2980}에게 돌아오세요.",
		["{quest:96130} and {quest:756}"] = "{quest:96130}와(과) {quest:756}",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "외로운 늑대 {quest:96130}은(는) 마을 서쪽 평원을 돌아다닙니다. 긴발톱 초원늑대와 평원퓨마는 그 북쪽과 서쪽 평원을 돌아다닙니다.",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["/sit by her campfire until you get {spell:1229451}"] = "{spell:1229451}을(를) 얻을 때까지 그녀의 모닥불 옆에서 /앉기 하세요",
		["Ask {npc:10666} for his report"] = "{npc:10666}에게 보고를 요청하세요",
		["Ask {npc:1496} for his report"] = "{npc:1496}에게 보고를 요청하세요",
		["Ask {npc:251001} for his report"] = "{npc:251001}에게 보고를 요청하세요",
		["Back to the church"] = "교회로 돌아가기",
		["Back to {area:154}"] = "{area:154}(으)로 돌아가기",
		["Back to {area:159}."] = "{area:159}(으)로 돌아가세요.",
		["Back up the road to {area:159}."] = "길을 따라 {area:159}(으)로 돌아가세요.",
		["Balnir graves"] = "발니르 농장 무덤",
		["Beat {npc:6784} in the duel"] = "결투에서 {npc:6784}을(를) 이기세요",
		["Crusader's Outpost"] = "붉은십자군 전초기지",
		["Dry Branches"] = "마른 가지",
		["Duskbats and Darkhounds roam all along the road back west; finish the wings and hides on the way."] = "서쪽으로 돌아가는 길 내내 그늘박쥐와 암흑사냥개가 돌아다닙니다. 가는 길에 날개와 가죽을 마저 모으세요.",
		["Eleanor camps just south-west of town."] = "엘리노어 섀클턴은 마을 바로 남서쪽에서 야영합니다.",
		["Escort {npc:275954} out of the outpost"] = "{npc:275954}을(를) 전초기지 밖으로 호위하세요",
		["Fields west of {area:159}"] = "{area:159} 서쪽 들판",
		["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "길을 따라 북쪽 {area:154}(으)로 가세요. 어둠의사제 사비스가 교회 앞에 서 있습니다.",
		["Follow the road east to {area:159}. {npc:10665} stands at the north-west edge of town; the {area:2119} is the big inn in the middle, with {npc:1515} in front of it."] = "길을 따라 동쪽 {area:159}(으)로 가세요. {npc:10665}은(는) 마을 북서쪽 끝에 있습니다. {area:2119}은(는) 마을 한가운데의 큰 여관이며, 그 앞에 {npc:1515}이(가) 있습니다.",
		["Follow the road east. Bleeding Horrors and Wandering Spirits haunt the graves on the east side of the farmstead, where the {quest:99142} grows."] = "길을 따라 동쪽으로 가세요. 피투성이 좀비와 떠도는 영혼이 농장 동쪽 무덤에 출몰하며, 그곳에 {quest:99142}이(가) 자랍니다.",
		["Follow the road north-east from {area:159} past {area:162}. {npc:1665} and his two Scarlet Bodyguards hold the Scarlet watchtower on the north-east coast, north of the {area:459}: pull the bodyguards first."] = "{area:159}에서 북동쪽 길을 따라 {area:162}을(를) 지나가세요. {npc:1665}와(과) 붉은십자군 경호원 2명이 {area:459} 북쪽, 북동쪽 해안의 붉은십자군 감시탑을 지킵니다. 경호원부터 끌어내세요.",
		["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}. From here on, kill the Duskbats and Darkhounds you pass: {npc:3549} wants their wings and hides."] = "길을 따라 북서쪽 {area:157}(으)로 가세요. {npc:1657}은(는) 방앗간 남쪽 묘지를 걸어 다니고, 니사, 그레고르, {npc:1656}은(는) 방앗간 안에 출몰합니다. 덜그럭거리는 해골병사와 금이간 해골병사는 갈비뼈를, 검은눈 해골마법사는 두개골을 떨어뜨리며, 누구든 {item:2839}을(를) 떨어뜨릴 수 있습니다. 지금부터 지나가며 그늘박쥐와 암흑사냥개를 처치하세요. {npc:3549}에게 날개와 가죽이 필요합니다.",
		["Follow the road south back to {area:159}."] = "길을 따라 남쪽 {area:159}(으)로 돌아가세요.",
		["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "{area:159}에서 남동쪽 길을 따라 비행선 탑을 지나가세요. 리니아, 크리스토프, {npc:3549}이(가) 길가에서 야영합니다.",
		["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "{area:159}에서 남서쪽 길을 따라 붉은십자군 야영지로 가세요. {npc:1662}은(는) 남쪽 끝에 있으며, 그곳의 붉은십자군은 모두 반지를 떨어뜨릴 수 있습니다.",
		["Follow the road west past {area:157} to the {area:16616}. Leonid stands just north of {npc:246389}'s camp."] = "길을 따라 서쪽으로 {area:157}을(를) 지나 {area:16616}(으)로 가세요. 리어니드 바돌로매는 {npc:246389}의 야영지 바로 북쪽에 있습니다.",
		["Free six Webbed Victims inside the cave for {npc:244808}"] = "{npc:244808}을(를) 위해 동굴 안에서 거미줄에 갇힌 희생자 6명을 구출하세요",
		["Greater Duskbats"] = "거대한 그늘박쥐",
		["Greater Duskbats fly over the fields around {area:159} and along the road north."] = "거대한 그늘박쥐는 {area:159} 주변 들판과 북쪽 길을 따라 날아다닙니다.",
		["Head west into the {area:16616}; {npc:246389} and {npc:259190} camp at its edge."] = "서쪽 {area:16616}(으)로 가세요. {npc:246389}와(과) {npc:259190}이(가) 숲 가장자리에서 야영합니다.",
		["Head west to the cave. The Young Night Web Spiders sit outside; the Night Web Spiders and the Webbed Victims are inside."] = "서쪽 동굴로 가세요. 새끼 검은그물거미는 밖에 있고, 검은그물거미와 거미줄에 갇힌 희생자는 안에 있습니다.",
		["Hearth to {area:159}"] = "귀환석으로 {area:159}에 가기",
		["Leave {area:154} by the road north-east. {npc:6784} stands by the farmhouse at the {area:156}."] = "북동쪽 길로 {area:154}을(를) 떠나세요. {npc:6784}은(는) {area:156}의 농가 옆에 서 있습니다.",
		["Listen to Leonid and {npc:246378}, then talk to him again"] = "리어니드와 {npc:246378}의 대화를 들은 뒤 그에게 다시 말을 거세요",
		["Mindless Zombies"] = "넋 나간 좀비",
		["More Vile Fin murlocs walk the shore just north of the outpost."] = "전초기지 바로 북쪽 해안에도 썩은지느러미멀록이 더 있습니다.",
		["Offer aid to the {npc:246143}"] = "{npc:246143}에게 도움을 주세요",
		["Only if the letter dropped"] = "편지를 얻었을 때만",
		["Paladin: {area:16616}"] = "성기사: {area:16616}",
		["Paladins: {quest:90902} is done once you have healed five {npc:259377} around the church with {spell:635}."] = "성기사: 교회 주변의 {npc:259377} 5명을 {spell:635}(으)로 치유하면 {quest:90902}이(가) 완료됩니다.",
		["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side."] = "덜그럭거리는 해골은 {area:154} 북쪽의 폐허가 된 집들을 배회합니다. 새끼 승냥이와 그늘박쥐는 마을 곳곳을 돌아다니고, 승냥이와 병든 그늘박쥐는 마을 동쪽에 있습니다.",
		["Rattlecage skulls"] = "덜그럭거리는 해골의 두개골",
		["Rattlecages, scavengers and duskbats"] = "해골, 승냥이, 그늘박쥐",
		["Rot Hide graveyards"] = "썩은가죽일족 묘지",
		["Scarlet Warriors guard the outpost just west of the pumpkin fields. {npc:275954} is held inside: talk to him and stay with him until he is out."] = "붉은십자군 전사가 호박밭 바로 서쪽 전초기지를 지킵니다. {npc:275954}이(가) 안에 갇혀 있습니다. 말을 걸고 빠져나올 때까지 함께 있으세요.",
		["Take the road south-east out of {area:159}; Terrence stands on it short of the zeppelin towers."] = "남동쪽 길로 {area:159}을(를) 나가세요. 죽음의경비병 테렌스가 비행선 탑 조금 못 미쳐 서 있습니다.",
		["Talk to {npc:265944}"] = "{npc:265944}와(과) 대화하세요",
		["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "마른 가지는 {area:159} 남서쪽 끝 주변 땅에 떨어져 있습니다.",
		["The Rattlecage Skeletons in the ruined houses drop the skulls."] = "폐허가 된 집의 덜그럭거리는 해골이 두개골을 떨어뜨립니다.",
		["The Rot Hide Graverobbers dig through the graveyards north of {area:159}; all the Rot Hides drop the ichor."] = "썩은가죽일족 도굴꾼이 {area:159} 북쪽 묘지를 파헤칩니다. 썩은가죽일족은 모두 체액을 떨어뜨립니다.",
		["The Rot Hide Mongrels hold the hills further north. {npc:1753} (level 11) stands in their camp on the hill south of the shore: clear the gnolls around him first."] = "썩은가죽일족 싸움꾼이 더 북쪽 언덕을 차지하고 있습니다. {npc:1753}(11레벨)은(는) 해안 남쪽 언덕의 야영지에 있습니다. 주변 놀부터 처치하세요.",
		["The Scarlet Converts and Initiates hold the farm east of {area:154}. {npc:1919} wanders between the farmhouses: his remains are for {quest:6395}."] = "붉은십자군 순례자와 견습마법사가 {area:154} 동쪽 농장을 차지하고 있습니다. {npc:1919}은(는) 농가 사이를 돌아다닙니다. 그의 유해는 {quest:6395}에 필요합니다.",
		["The Scarlet Friars camp just north-east of the graves; {npc:1664} stands among them."] = "붉은십자군 수사가 무덤 바로 북동쪽에서 야영하며, {npc:1664}이(가) 그들 사이에 있습니다.",
		["The Scarlet camp"] = "붉은십자군 야영지",
		["The Scarlet farm"] = "붉은십자군 농장",
		["The Vile Fin murlocs line the north shore."] = "썩은지느러미멀록이 북쪽 해안을 따라 늘어서 있습니다.",
		["The Wanted poster by the inn"] = "여관 옆의 현상수배 전단",
		["The pumpkins grow in the Scarlet-held fields north-west of Solliden."] = "호박은 솔리덴 농장 북서쪽, 붉은십자군이 차지한 들판에 자랍니다.",
		["The spiders lurk in the woods at the far east end of the glades. {npc:276020}, a rogue abomination, wanders just north-west of them. {npc:276020} is elite: grouping up is advised."] = "거미는 숲 동쪽 맨 끝의 수풀에 숨어 있습니다. 떠돌이 누더기골렘 {npc:276020}이(가) 그 바로 북서쪽을 배회합니다. {npc:276020}은(는) 정예이니 파티를 권장합니다.",
		["The zeppelin lands at the tower just north-east of {zone:1454}'s main gate. Follow the road south into {zone:1411}, cross the {area:815} bridge below {area:379} and follow the road west to the {area:380}."] = "비행선은 {zone:1454} 정문 바로 북동쪽 탑에 내립니다. 길을 따라 남쪽 {zone:1411}(으)로 가서, {area:379} 아래 {area:815} 다리를 건넌 뒤 서쪽 길을 따라 {area:380}로 가세요.",
		["The zombies shamble around the graveyard and the houses just east of the church."] = "좀비는 교회 바로 동쪽의 묘지와 집 주변을 배회합니다.",
		["The {area:154} trainers stand around the church"] = "{area:154}의 상급자들은 교회 주변에 있습니다",
		["The {area:159} trainers are in and around the inn"] = "{area:159}의 상급자들은 여관 안팎에 있습니다",
		["The {npc:1931}, in the town hall basement"] = "마을 회관 지하실의 {npc:1931}",
		["The {npc:2211}, in the town hall basement"] = "마을 회관 지하실의 {npc:2211}",
		["The {npc:246143}"] = "{npc:246143}",
		["The {object:164662} lie beside the ruined houses in the north of {area:154}."] = "{object:164662}은(는) {area:154} 북쪽의 폐허가 된 집 옆에 있습니다.",
		["The {quest:5482} grows in the graveyard fields just north of {area:159}."] = "{quest:5482}은(는) {area:159} 바로 북쪽의 묘지 들판에 자랍니다.",
		["Tirisfal Pumpkins"] = "티리스팔 호박",
		["Use the {item:286176} on five idle Deathguards around town"] = "마을 주변에서 빈둥거리는 죽음의경비병 5명에게 {item:286176}을(를) 사용하세요",
		["Vicious Night Web Spiders"] = "흉포한 검은그물거미",
		["Vile Fin murlocs"] = "썩은지느러미멀록",
		["Vile Fin shore"] = "썩은지느러미 물가",
		["Walk on west to {npc:6784} and talk to him: he wants a duel."] = "서쪽의 {npc:6784}에게 가서 말을 거세요. 결투를 원합니다.",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:4568} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "{area:159}에서 남쪽 {area:153}(으)로 가서 {zone:1458}(으)로 내려가세요. {npc:4568}은(는) {object:36082}에 있습니다. 붉은십자군 야영지는 폐허 바로 서쪽입니다.",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:5675} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "{area:159}에서 남쪽 {area:153}(으)로 가서 {zone:1458}(으)로 내려가세요. {npc:5675}은(는) {object:36082}에 있습니다. 붉은십자군 야영지는 폐허 바로 서쪽입니다.",
		["Walk south-east from {area:159} to the zeppelin towers outside the {area:153} and board the zeppelin to {zone:1454} (the other one goes to {object:3202})."] = "{area:159}에서 남동쪽으로 {area:153} 밖의 비행선 탑으로 가서 {zone:1454}행 비행선에 타세요(다른 하나는 {object:3202}(으)로 갑니다).",
		["Walk south-west to the {area:156}; Simmer stands at the farm."] = "남서쪽 {area:156}(으)로 가세요. 죽음의경비병 시머가 농장에 있습니다.",
		["Webbed Victims"] = "거미줄에 갇힌 희생자",
		["You rise in the crypt at the south end of {area:154}. {npc:1568} waits just outside."] = "{area:154} 남쪽 끝의 지하실에서 깨어납니다. {npc:1568}이(가) 바로 밖에서 기다립니다.",
		["Zeppelin to {zone:1411}"] = "비행선으로 {zone:1411}에 가기",
		["Zeppelin tower"] = "비행선 탑",
		["in the inn: ask him about cooking"] = "여관 안: 요리에 대해 물어보세요",
		["{area:16881} is the hollow at the west edge of the glades. The Shadowvale Lurchers and Mystics drop the bones; the bottles lie on the ground among them, and the {item:286269} is at the south end."] = "{area:16881}은(는) 숲 서쪽 끝의 분지입니다. {npc:260428}와(과) 비술사가 뼈를 떨어뜨리고, 병은 그들 사이 땅에 놓여 있으며, {item:286269}은(는) 남쪽 끝에 있습니다.",
		["{item:16333}, from {npc:1919}"] = "{npc:1919}에게서 {item:16333}",
		["{item:2320} from {npc:2118}, for Gretchen"] = "그레첸 데드마에게 줄 {item:2320}, {npc:2118}에게서 구입",
		["{item:2839}, a rare drop"] = "희귀 획득품 {item:2839}",
		["{item:286326}, from {npc:276020}"] = "{npc:276020}에게서 {item:286326}",
		["{item:7227}, in the farmstead's garden"] = "농장 정원의 {item:7227}",
		["{npc:10666}, the big abomination, walks the road a little further east. The {item:12737} grows along the road around him."] = "덩치 큰 누더기골렘 {npc:10666}은(는) 조금 더 동쪽 길을 걸어 다닙니다. {item:12737}은(는) 그 주변 길가에 자랍니다.",
		["{npc:1495}'s camp"] = "{npc:1495}의 야영지",
		["{npc:1495}: {npc:276020}, an elite abomination in the east"] = "{npc:1495}: 동쪽의 정예 누더기골렘 {npc:276020}",
		["{npc:1496} stands in {area:159}. {npc:6390} waits in the mausoleum on the hill just north of town: open the gate and fight him."] = "{npc:1496}은(는) {area:159}에 있습니다. {npc:6390}은(는) 마을 바로 북쪽 언덕의 묘지에서 기다립니다. 문을 열고 그와 싸우십시오.",
		["{npc:1499}, in the town hall"] = "마을 회관 안의 {npc:1499}",
		["{npc:1500}, in the inn"] = "여관 안의 {npc:1500}",
		["{npc:1525} and Ravaged Corpses shamble through the fields just west of {area:159}; Darkhounds roam a little further west, toward {npc:10666}."] = "{npc:1525}와(과) 심하게 훼손된 시체가 {area:159} 바로 서쪽 들판을 배회합니다. 암흑사냥개는 조금 더 서쪽, {npc:10666} 쪽에 돌아다닙니다.",
		["{npc:1560}, in the inn"] = "여관 안의 {npc:1560}",
		["{npc:1569}: the scroll for {npc:244808}"] = "{npc:1569}: {npc:244808}에게 줄 두루마리",
		["{npc:1570}, in the church"] = "교회 안의 {npc:1570}",
		["{npc:1661}, beside the church"] = "교회 옆의 {npc:1661}",
		["{npc:1667} stands at the south end of the Scarlet farm."] = "{npc:1667}은(는) 붉은십자군 농장 남쪽 끝에 서 있습니다.",
		["{npc:2119}, the warrior trainer"] = "전사 상급자 {npc:2119}",
		["{npc:2122}, the rogue trainer"] = "도적 상급자 {npc:2122}",
		["{npc:2123}, the priest trainer in the church"] = "교회 안의 사제 상급자 {npc:2123}",
		["{npc:2124}, the mage trainer, in the church"] = "교회 안의 마법사 상급자 {npc:2124}",
		["{npc:2126}, the warlock trainer"] = "흑마법사 상급자 {npc:2126}",
		["{npc:2128}: {npc:4568} in the {zone:1458} takes it"] = "{npc:2128}: {zone:1458}의 {npc:4568}에게 가져가세요",
		["{npc:2132}, beside Johaan"] = "연금술사 요한 옆의 {npc:2132}",
		["{npc:244808} and {npc:5667}"] = "{npc:244808}와(과) {npc:5667}",
		["{npc:244808} and {npc:5667} stand beside the church."] = "{npc:244808}와(과) {npc:5667}이(가) 교회 옆에 서 있습니다.",
		["{npc:246152}, the Paladin trainer"] = "성기사 상급자 {npc:246152}",
		["{npc:267009} stands at {npc:1495}'s camp."] = "{npc:267009}은(는) {npc:1495}의 야영지에 있습니다.",
		["{npc:3615}, the wind rider master"] = "와이번 조련사 {npc:3615}",
		["{object:1661} is under the {area:153}, beside the zeppelin towers. {npc:5675} is in the {object:36082}: use the {item:6284} on the summoning circle beside him and defeat the voidwalker. {npc:4606} is in the {object:36070}. {npc:4568} is in the {object:36082} too."] = "{object:1661}은(는) 비행선 탑 옆 {area:153} 아래에 있습니다. {npc:5675}은(는) {object:36082}에 있습니다. 그 옆의 소환진에서 {item:6284}을(를) 사용하고 공허방랑자를 물리치세요. {npc:4606}은(는) {object:36070}에 있습니다. {npc:4568}도 {object:36082}에 있습니다.",
		["{object:178090} is in the {area:154} graveyard, beside the church."] = "{object:178090}은(는) 교회 옆 {area:154} 묘지에 있습니다.",
		["{object:37098} stands beside {npc:1662} at the camp's south end."] = "{object:37098}은(는) 야영지 남쪽 끝 {npc:1662} 옆에 있습니다.",
		["{quest:91208}: the {npc:246143} fled into the hills just west of the church."] = "{quest:91208}: {npc:246143}은(는) 교회 바로 서쪽 언덕으로 도망쳤습니다.",
		["{quest:96897} holds the farm just south-east of the camp. The Necrotic Crystal Fragments lie on the ground among the cultists, and the cultists carry some too."] = "{quest:96897}이(가) 야영지 바로 남동쪽 농장을 차지하고 있습니다. 괴저 수정 파편은 신도들 사이 땅에 놓여 있고, 신도들도 일부 지니고 있습니다.",
} end)()
t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "모험: 세계 지도 탐험",
		["Adventure: {npc:16042}"] = "모험: {npc:16042}",
		["Adventure: {quest:8997} (Alliance)"] = "모험: {quest:8997} (얼라이언스)",
		["Adventure: {quest:8998} (Horde)"] = "모험: {quest:8998} (호드)",
		["All 13 Hyjal Summit bosses are a point. Hyjal Summit is a new Forever raid; its bosses are not in our data, so tick it off once all 13 are down."] = "Hyjal Summit 우두머리 13명을 모두 처치하면 1점입니다. Hyjal Summit은(는) Forever의 새 공격대이며 우두머리가 우리 데이터에 없으니, 13명을 모두 처치하면 직접 체크하십시오.",
		["All 8 Barrow Deeps bosses are a point. Barrow Deeps is a new Forever raid; its bosses are not in our data, so tick it off once all 8 are down."] = "Barrow Deeps 우두머리 8명을 모두 처치하면 1점입니다. Barrow Deeps은(는) Forever의 새 공격대이며 우두머리가 우리 데이터에 없으니, 8명을 모두 처치하면 직접 체크하십시오.",
		["Blizzard counts four battleground reputations, but our faction data has three per side ({zone:1460}, {zone:1461}, {zone:1459}). The fourth is likely tied to Forever's new PvP content; check the in-game Legacy panel."] = "블리자드는 전장 평판 4개를 계산하지만, 우리 세력 데이터에는 진영마다 3개({zone:1460}, {zone:1461}, {zone:1459})만 있습니다. 네 번째는 Forever의 새 PvP 콘텐츠와 관련된 것으로 보입니다. 게임 내 유산 창을 확인하십시오.",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "직업은 27점을 줍니다: 각 직업이 25, 45, 60레벨에 도달할 때마다 1점입니다. 계정 전체에서 직업마다 한 번만 계산되므로, 이미 키운 직업의 두 번째 캐릭터는 점수를 주지 않고 새 직업은 점수를 줍니다. 보통 처음으로 25레벨에 도달한 캐릭터가 유산 시스템 자체를 해금합니다.",
		["Classes: level 25"] = "직업: 레벨 25",
		["Classes: level 45"] = "직업: 레벨 45",
		["Classes: level 60"] = "직업: 레벨 60",
		["Dire Maul East"] = "혈투의 전장 동쪽",
		["Dire Maul North"] = "혈투의 전장 북쪽",
		["Dire Maul West"] = "혈투의 전장 서쪽",
		["Dungeons: level 15-25"] = "던전: 레벨 15-25",
		["Dungeons: level 26-45"] = "던전: 레벨 26-45",
		["Dungeons: level 46-60"] = "던전: 레벨 46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "제작 전문 기술은 각각 150, 225, 300에서 1점씩, 총 3점을 줍니다. 단계는 계정 전체에서 전문 기술마다 한 번만 계산됩니다. Polestar 가이드 \"{skill:171} 1-300\"(전문 기술)을 따르십시오. 제작 전문 기술 150 달성으로도 유산 시스템이 해금됩니다.",
		["Exalted with each battleground faction is worth a point (4 in all; this page shows three, see the note). Follow the Polestar Reputation guides Warsong Gulch Reputation, Arathi Basin Reputation and Alterac Valley Reputation. The Diplomat Legacy perk increases reputation gains."] = "각 전장 세력과 확고한 동맹이 되면 1점입니다(총 4점, 이 페이지에는 3개만 나옵니다. 참고를 보세요). Polestar 평판 가이드 전쟁노래 협곡 평판, 아라시 분지 평판, 알터랙 계곡 평판을 따르세요. 외교관 유산 특전은 평판 획득량을 늘려 줍니다.",
		["Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character."] = "한 캐릭터로 세계 지도 전체를 탐험하면 1점이며, 유산 시스템을 해금할 수도 있습니다. 모두 같은 캐릭터로 탐험해야 합니다.",
		["Follow the Polestar Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it."] = "Polestar 탐험 가이드를 따르십시오: 탐험: 동부 왕국 1-30, 30-45, 45-60과 탐험: 칼림도어 1-30, 30-45, 45-60. 발견하는 모든 지역을 추적합니다.",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "Polestar 가이드 \"{skill:164} 1-300\"(전문 기술)을 따르십시오.",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "Polestar 가이드 \"{skill:165} 1-300\"(전문 기술)을 따르십시오.",
		["Follow the Polestar guide \"{skill:197} 1-300\" (Professions)."] = "Polestar 가이드 \"{skill:197} 1-300\"(전문 기술)을 따르십시오.",
		["Follow the Polestar guide \"{skill:202} 1-300\" (Professions)."] = "Polestar 가이드 \"{skill:202} 1-300\"(전문 기술)을 따르십시오.",
		["Follow the Polestar guide \"{skill:333} 1-300\" (Professions)."] = "Polestar 가이드 \"{skill:333} 1-300\"(전문 기술)을 따르십시오.",
		["Forever adds the dungeons {area:16919} and {area:153}; their bosses and brackets are not in our data yet."] = "Forever는 던전 {area:16919}와(과) {area:153}을(를) 추가합니다. 그 우두머리와 레벨대는 아직 우리 데이터에 없습니다.",
		["Forever's new dungeons"] = "Forever의 새 던전",
		["Killing {npc:10184} is a point. In Classic her lair needs an attunement: {item:16309} for the Alliance, {item:16663} for the Horde."] = "{npc:10184}을(를) 처치하면 1점입니다. 클래식에서 그녀의 둥지에 들어가려면 입장 퀘스트가 필요합니다: 얼라이언스는 {item:16309}, 호드는 {item:16663}.",
		["Legacy Challenges"] = "유산 도전 과제",
		["Level 45 with this character's class."] = "이 캐릭터의 직업으로 레벨 45 달성.",
		["Level 60 with this character's class."] = "이 캐릭터의 직업으로 레벨 60 달성.",
		["Lower {area:1583}"] = "{area:1583} 하층",
		["PvP: Field of Honor"] = "PvP: Field of Honor",
		["PvP: battleground reputations (Alliance)"] = "PvP: 전장 평판 (얼라이언스)",
		["PvP: battleground reputations (Horde)"] = "PvP: 전장 평판 (호드)",
		["PvP: honor ranks"] = "PvP: 명예 계급",
		["Raids: Barrow Deeps"] = "공격대: Barrow Deeps",
		["Raids: Hyjal Summit"] = "공격대: Hyjal Summit",
		["Raids: {npc:10184}"] = "공격대: {npc:10184}",
		["Ranks 3, 7, 10, 13 and 14 are a point each. Polestar cannot read your highest rank yet, so tick each one off yourself. Forever's honor rules for reaching a rank have not been published in detail; in Classic, ranks come from your weekly honor standing, and 13-14 take many weeks of top standing."] = "계급 3, 7, 10, 13, 14는 각각 1점입니다. Polestar는 아직 최고 계급을 읽을 수 없으니 직접 하나씩 체크하십시오. Forever의 계급 달성 명예 규칙은 자세히 공개되지 않았습니다. 클래식에서는 주간 명예 순위로 계급이 정해지며, 13-14계급은 여러 주 동안 최상위 순위를 유지해야 합니다.",
		["The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself."] = "Field of Honor PvP 시즌에는 주간 여정 퀘스트가 있으며, 4, 7, 10주차 퀘스트를 마치면 각각 1점입니다. 이 퀘스트들은 Forever에 새로 추가되어 우리 데이터에 없으니 직접 하나씩 체크하십시오.",
		["The final boss of every level 15-25 dungeon earns one point together. Tick each boss off when you kill it; the grouping follows the usual Classic level ranges, so check the in-game Legacy panel for the exact list."] = "레벨 15-25 던전의 마지막 우두머리를 모두 처치하면 합쳐서 1점입니다. 우두머리를 처치할 때마다 체크하십시오. 분류는 일반적인 클래식 레벨대를 따르므로, 정확한 목록은 게임 내 유산 창에서 확인하십시오.",
		["The final boss of every level 26-45 dungeon earns one point together."] = "레벨 26-45 던전의 마지막 우두머리를 모두 처치하면 합쳐서 1점입니다.",
		["The final boss of every level 46-60 dungeon earns one point together."] = "레벨 46-60 던전의 마지막 우두머리를 모두 처치하면 합쳐서 1점입니다.",
		["The {npc:16042} questline is a point. It is the level 60 dungeon-set chain: {npc:16013} ({zone:1455}) or {npc:16012} ({zone:1454}) send you through In Search of Anthion and Anthion's Parting Words to {npc:16033} at {area:254}, whose Three Kings of Flame, the Left and Right Pieces of Lord Valthalak's Amulet, Final Preparations and Mea Culpa, {npc:16042} end with {quest:8996}. {quest:8997} then leads to the class Saving the Best for Last quests."] = "{npc:16042} 퀘스트 라인은 1점입니다. 레벨 60 던전 세트 연계 퀘스트입니다. {npc:16013}({zone:1455}) 또는 {npc:16012}({zone:1454})이(가) 안시온 찾기와 안시온의 작별 인사를 거쳐 {area:254}의 {npc:16033}에게 보냅니다. 그의 세 고위 정령의 불꽃, 군주 발타라크의 아뮬렛의 왼쪽 조각과 오른쪽 조각, 마지막 준비, 군주 발타라크여, 내 탓이오.를 거쳐 {quest:8996}(으)로 {npc:16042} 퀘스트 라인이 끝납니다. 그다음 {quest:8997}이(가) 직업별 은혜의 보답 퀘스트로 이어집니다.",
		["This step cannot check the whole map by itself yet; it becomes a tracked goal once the Legacy achievement ids are recorded."] = "이 단계는 아직 지도 전체를 스스로 확인할 수 없습니다. 유산 업적 ID가 기록되면 추적되는 목표가 됩니다.",
		["Tradeskills: {skill:164}"] = "전문 기술: {skill:164}",
		["Tradeskills: {skill:165}"] = "전문 기술: {skill:165}",
		["Tradeskills: {skill:171}"] = "전문 기술: {skill:171}",
		["Tradeskills: {skill:197}"] = "전문 기술: {skill:197}",
		["Tradeskills: {skill:202}"] = "전문 기술: {skill:202}",
		["Tradeskills: {skill:333}"] = "전문 기술: {skill:333}",
		["Upper {area:1583}"] = "{area:1583} 상층",
		["Which quest Blizzard counts as the end of the questline ({quest:8996} or your class's Saving the Best for Last) is unconfirmed until the Legacy data is recorded."] = "블리자드가 퀘스트 라인의 끝으로 어느 퀘스트({quest:8996} 또는 직업별 은혜의 보답)를 계산하는지는 유산 데이터가 기록될 때까지 확실하지 않습니다.",
		["{area:1517} (level 41-51; may count in the 46-60 bracket)"] = "{area:1517}(레벨 41-51, 46-60 구간에 계산될 수 있음)",
		["{area:16919} and {area:153} are new in Forever. Their bosses, levels and Legacy bracket are not in our data, so tick them off yourself."] = "{area:16919}와(과) {area:153}은(는) Forever에 새로 추가되었습니다. 우두머리, 레벨, 유산 구간이 우리 데이터에 없으니 직접 체크하십시오.",
		["{area:2279}, Live side"] = "{area:2279}, 산 자 구역",
		["{area:2279}, Undead side"] = "{area:2279}, 언데드 구역",
		["{area:717}: the usual last kill; the {area:717} has no fixed final boss"] = "{area:717}: 보통 마지막으로 처치하는 대상. {area:717}에는 정해진 마지막 우두머리가 없습니다",
		["{area:718} (appears after the {npc:3678}'s event)"] = "{area:718}({npc:3678} 이벤트 후에 나타남)",
		["{area:796}: Armory"] = "{area:796}: 무기고",
		["{area:796}: Cathedral"] = "{area:796}: 대성당",
		["{area:796}: Graveyard"] = "{area:796}: 묘지",
		["{area:796}: Library"] = "{area:796}: 도서관",
		["{npc:16012} then offers your class's Saving the Best for Last, the final upgrade of the dungeon set."] = "그다음 {npc:16012}이(가) 던전 세트의 마지막 강화인 직업별 마지막 보은을 줍니다.",
		["{npc:16013} then offers your class's Saving the Best for Last, the final upgrade of the dungeon set."] = "그다음 {npc:16013}이(가) 던전 세트의 마지막 강화인 직업별 은혜의 보답을 줍니다.",
		["{npc:16033} offers it once {quest:8996} is turned in"] = "{quest:8996}을(를) 제출하면 {npc:16033}이(가) 줍니다",
} end)()
t.guides["forever/professions/alchemy"] = (function() return {
		["Apprentice {skill:171}"] = "초급 {skill:171}",
