		["League of Arathor to Honored"] = "아라소르 연맹: 우호적까지",
		["League of Arathor to Revered"] = "아라소르 연맹: 매우 우호적까지",
		["{faction:509} fights for {zone:1461} from {area:320}. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:509}은(는) {area:320}에서 {zone:1461}을(를) 두고 싸웁니다. 평판은 전장에서 얻습니다. 팀이 모은 자원만큼 모두에게 평판이 주어지므로, 더 많은 거점을 더 오래 지킬수록 더 많이 얻습니다. 아무 전투 관리인에게서나 대기열에 참가하십시오. Forever의 외교관 유산 특전은 평판 획득량을 늘려 줍니다.",
		["{faction:510} fight for {zone:1461} from {area:321}. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:510}은(는) {area:321}에서 {zone:1461}을(를) 두고 싸웁니다. 평판은 전장에서 얻습니다. 팀이 모은 자원만큼 모두에게 평판이 주어지므로, 더 많은 거점을 더 오래 지킬수록 더 많이 얻습니다. 아무 전투 관리인에게서나 대기열에 참가하십시오. Forever의 외교관 유산 특전은 평판 획득량을 늘려 줍니다.",
		["{faction:510} to Exalted"] = "{faction:510}: 확고한 동맹까지",
		["{faction:510} to Friendly"] = "{faction:510}: 약간 우호적까지",
		["{faction:510} to Honored"] = "{faction:510}: 우호적까지",
		["{faction:510} to Revered"] = "{faction:510}: 매우 우호적까지",
		["{npc:14983}'s The Battle for {zone:1461}! (assault every base) and Control Four Bases / Control Five Bases are one-time quests; {npc:14984} beside him takes Arathi Resource Crates."] = "{npc:14983}의 {zone:1461}의 전투(모든 거점 공격)와 거점 네 곳 점령 / 거점 다섯 곳 점령은 한 번만 할 수 있는 퀘스트입니다. 그 옆의 {npc:14984}은(는) 아라시 보급품 상자를 받습니다.",
		["{npc:15021}'s The Battle for {zone:1461}! (assault every base) and Take Four Bases / Take Five Bases are one-time quests; {npc:15022} beside him takes Arathi Resource Crates."] = "{npc:15021}의 {zone:1461}의 전투(모든 거점 공격)와 거점 네 곳 점령 / 거점 다섯 곳 점령은 한 번만 할 수 있는 퀘스트입니다. 그 옆의 {npc:15022}은(는) 아라시 보급품 상자를 받습니다.",
		["{npc:15126} hands out one Defiler's care package by level"] = "{npc:15126}이(가) 레벨에 따라 파멸단 구급품 하나를 줍니다",
		["{npc:15127} hands out one Arathor care package by level"] = "{npc:15127}이(가) 레벨에 따라 아라소르 구급품 하나를 줍니다",
} end)()
t.guides["forever/reputation/argent-dawn"] = (function() return {
		["Argent Dawn Reputation"] = "은빛 여명회 평판",
		["Corruptor's Scourgestones and dungeons to Revered"] = "{item:12843}와(과) 던전: 매우 우호적까지",
		["Dark Adepts and Shadowmages (level 58-60) drop Invader's Scourgestones here, along with Minion's stones and {item:14047}. Hand Invader's in 10 at a time and Minion's 20 at a time to {npc:11039} at {area:2268}. In Classic both stop giving reputation at Honored."] = "{npc:8546}와(과) 어둠마법사(58-60레벨)가 이곳에서 {item:12841}을(를) 떨어뜨리며, 앞잡이의 스컬지석과 {item:14047}도 떨어뜨립니다. {area:2268}의 {npc:11039}에게 침입자의 스컬지석은 10개씩, 앞잡이의 스컬지석은 20개씩 제출하세요. 클래식에서는 둘 다 우호적부터 평판을 주지 않습니다.",
		["From Honored on, Corruptor's Scourgestones (one per turn-in) and Scourge kills in {area:2279} and {area:2057} carry the reputation. Corruptor's stones drop from the Scourge bosses there ({npc:1853}, {npc:10433}, Vectus) and from {npc:1852} and Putridius in {zone:1422}. Many dungeon runs pay off faster than any open-world farm."] = "우호적부터는 {item:12843}(제출당 1개)와(과) {area:2279}, {area:2057}의 스컬지 처치가 평판을 줍니다. 타락자의 스컬지석은 그곳의 스컬지 우두머리({npc:1853}, {npc:10433}, 벡투스)와 {zone:1422}의 {npc:1852}, 퓨트리디우스가 떨어뜨립니다. 던전을 여러 번 도는 편이 어떤 필드 사냥보다 빠릅니다.",
		["Ghouls and skeletons all over {zone:1422} drop Minion's Scourgestones about half the time; this cluster is dense. Hand them in 20 at a time to any Argent Officer (Pureheart at {area:3197}, Garush at {area:813}, {npc:11039} at {area:2268}). Each turn-in also pays an {item:12844} for the Argent quartermasters."] = "{zone:1422} 곳곳의 구울과 해골이 절반 정도의 확률로 {item:12840}을(를) 떨어뜨립니다. 이 무리는 밀집해 있습니다. 20개씩 은빛장교에게 제출하세요({area:3197}의 퓨어하트, {area:813}의 가루쉬, {area:2268}의 {npc:11039}). 제출할 때마다 은빛 병참장교에게 쓸 {item:12844}도 받습니다.",
		["Invader's Scourgestones to Honored"] = "{item:12841}: 우호적까지",
		["Keep running {area:2279} and {area:2057} and turning in every {item:12843} at {area:2268} until Exalted."] = "확고한 동맹이 될 때까지 {area:2279}와(과) {area:2057}을(를) 계속 돌고 {item:12843}을(를) 모두 {area:2268}에 제출하세요.",
		["Minion's Scourgestones to Friendly"] = "{item:12840}: 약간 우호적까지",
		["Run {area:2279} (both wings) and {area:2057}, killing every Scourge you pass."] = "{area:2279}(양쪽 구역)와(과) {area:2057}을(를) 돌며 지나가는 스컬지를 모두 처치하세요.",
		["{faction:529} to Exalted"] = "{faction:529}: 확고한 동맹까지",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10839} at {area:813} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160}은(는) 중립에서 시작합니다. {area:813}의 {npc:10839}에게서 위임장을 받아 착용하세요. 클래식에서는 {quest:5401} 장신구를 착용해야만 스컬지석이 떨어집니다. Forever의 외교관 유산 특전은 평판 획득량을 늘려 줍니다.",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10840} at {area:3197} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160}은(는) 중립에서 시작합니다. {area:3197}의 {npc:10840}에게서 위임장을 받아 착용하세요. 클래식에서는 {quest:5401} 장신구를 착용해야만 스컬지석이 떨어집니다. Forever의 외교관 유산 특전은 평판 획득량을 늘려 줍니다.",
		["{quest:5401} (Alliance)"] = "{quest:5401} (얼라이언스)",
		["{quest:5401} (Horde)"] = "{quest:5401} (호드)",
} end)()
t.guides["forever/reputation/cenarion-circle"] = (function() return {
		["Abyssal Crests, Abyssal Signets and Abyssal Scepters are repeatable at {npc:15306} once their opening quests are done."] = "심연의 문장, 심연의 인장, 심연의 홀은 시작 퀘스트를 마치면 {npc:15306}에게 반복해서 제출할 수 있습니다.",
		["Back to {area:3425}"] = "{area:3425}(으)로 돌아가기",
		["Cenarion Circle Reputation"] = "세나리온 의회 평판",
		["Encrypted Twilight Texts repeats: {npc:15306} takes more texts again and again. The cultist camps are the place to farm them."] = "암호화된 황혼의 문서는 반복 퀘스트입니다. {npc:15306}이(가) 문서를 계속 받습니다. 신도 야영지에서 모으십시오.",
		["Encrypted Twilight Texts to Friendly"] = "암호화된 황혼의 문서로 우호까지",
		["From here on, the {area:3454} raid and the Abyssal Council turn-ins (crests, signets, scepters) carry most of the reputation."] = "이제부터는 {area:3454} 공격대와 Abyssal Council 반납품(문장, 인장, 홀)이 평판 대부분을 줍니다.",
		["Keep farming the Twilight camps. Wearing the Twilight Trappings (the Twilight cultist set plus a Medallion of Station, from {npc:15282}'s Medallion of Station quest) lets you summon Abyssal Templars at the Wind Stones; their Abyssal Crests go to {npc:15306}."] = "황혼의 야영지에서 계속 사냥하십시오. Twilight Trappings(황혼의 신도 세트와 {npc:15282}의 황혼의 신도 계급장 퀘스트에서 얻는 계급장)를 착용하면 바람의 돌에서 Abyssal Templar를 소환할 수 있으며, 그들의 심연의 문장은 {npc:15306}에게 가져가십시오.",
		["Keep running the {area:3454} and turning in Abyssal Council insignia until Exalted."] = "확고한 동맹이 될 때까지 {area:3454}을(를) 계속 돌고 Abyssal Council 휘장을 제출하십시오.",
		["Twilight's Hammer cultists hold the camps in western {zone:1451}. {quest:8320} and Stonecallers mix here; any cultist can drop an {item:20404}. Every cultist kill also counts toward the {faction:609}. The Geolords count for {quest:8320} only if you are 60 and took it."] = "황혼의망치단 신도들이 {zone:1451} 서부의 야영지를 차지하고 있습니다. 이곳에는 {quest:8320}와(과) 황혼의 돌소환사가 섞여 있으며, 어느 신도든 {item:20404}을(를) 떨어뜨릴 수 있습니다. 신도를 처치할 때마다 {faction:609} 평판도 오릅니다. 대지술사는 60레벨이고 {quest:8320}을(를) 수락했을 때만 집계됩니다.",
		["{area:3425} is the walled town in north-central {zone:1451}. Bor and {npc:15270} stand together inside. The {faction:609} starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{area:3425}은(는) {zone:1451} 중북부의 성벽 마을입니다. 보르 와일드메인과 {npc:15270}이(가) 안에 함께 있습니다. {faction:609} 평판은 중립에서 시작합니다. Forever의 외교관 유산 특전은 평판 획득량을 늘려 줍니다.",
		["{faction:609} to Exalted"] = "{faction:609} 확고한 동맹까지",
		["{faction:609} to Honored"] = "{faction:609} 우대까지",
		["{faction:609} to Revered"] = "{faction:609} 존경까지",
		["{npc:15306}: Encrypted Twilight Texts"] = "{npc:15306}: 암호화된 황혼의 문서",
		["{quest:8320} needs level 60"] = "{quest:8320}은(는) 60레벨 필요",
} end)()
t.guides["forever/reputation/darkspear-trolls"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "암흑의 수행사제와 어둠마법사(레벨 58-60)가 여기서 떨어뜨립니다. 이곳에서 스컬지를 처치할 때마다 {object:92525} 평판도 오릅니다(해당 가이드 참고). 경매장에서도 구할 수 있습니다.",
		["Darkspear Trolls Reputation"] = "검은창 트롤 평판",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "모래망치 오우거(레벨 45-48)가 여기서 떨어뜨립니다. 경매장에서도 구할 수 있습니다.",
		["Keep handing in {quest:7837} until {faction:530} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{faction:530}와(과) 확고한 동맹이 될 때까지 {quest:7837}을(를) 계속 제출하세요. {item:14047}: {zone:1423}의 암흑의 수행사제와 어둠마법사(레벨 58-60) 또는 경매장.",
		["Keep handing in {quest:7837}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7837}을(를) {item:14047} 20개씩 계속 제출하세요. {item:14047}: {zone:1423}의 암흑의 수행사제와 어둠마법사(레벨 58-60) 또는 경매장.",
		["Kolkar centaur (level 30-33) drop it here. The Auction House works too."] = "콜카르 켄타우로스(레벨 30-33)가 여기서 떨어뜨립니다. 경매장에서도 구할 수 있습니다.",
		["Venture Co. Enforcers at the {area:381} (level 16-17) drop it here. The Auction House works too."] = "{area:381}의 투자개발회사 집행자(레벨 16-17)가 여기서 떨어뜨립니다. 경매장에서도 구할 수 있습니다.",
		["{npc:14727} takes cloth for {faction:530} in the {object:172961}, {zone:1454}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7837} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14727}이(가) {zone:1454}의 {object:172961}에서 {faction:530}을(를) 위해 옷감을 받습니다. 양모 옷감, 비단 옷감, 마법 옷감, {item:14047}의 첫 기부(각 60개)는 한 번만 할 수 있고 옷감당 평판을 가장 많이 줍니다. 그 후에는 {quest:7837}을(를) 확고한 동맹까지 반복합니다. 다른 종족 도시와 확고한 동맹이 되면 그 종족의 탈것을 살 수 있습니다. Forever의 외교관 유산 특전은 평판 획득량을 늘려 줍니다.",
		["{npc:14727}: {item:14047} delivered"] = "{npc:14727}: {item:14047} 전달",
		["{quest:7837} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7837}은(는) 한 번에 {item:14047} 20개를 받으며 원하는 만큼 반복할 수 있습니다. {item:14047}을(를) 20개 단위로 모아 한 번에 연달아 제출하세요. {item:14047}: {zone:1423}의 암흑의 수행사제와 어둠마법사(레벨 58-60) 또는 경매장.",
		["{quest:7837} to Exalted"] = "{quest:7837}: 확고한 동맹까지",
		["{quest:7837} to Honored"] = "{quest:7837}: 우호적까지",
		["{quest:7837} to Revered"] = "{quest:7837}: 매우 우호적까지",
} end)()
t.guides["forever/reputation/darnassus"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "{npc:8546}와(과) 어둠마법사(58-60레벨)가 이곳에서 떨어뜨립니다. 여기서 스컬지를 처치할 때마다 {object:92525} 평판에도 반영됩니다(해당 가이드 참고). 경매장도 이용할 수 있습니다.",
		["Darnassus Reputation"] = "다르나서스 평판",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "모래망치 오우거(45-48레벨)가 이곳에서 떨어뜨립니다. 경매장도 이용할 수 있습니다.",
		["Keep handing in {quest:7801} until {faction:69} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{faction:69}와(과) 확고한 동맹이 될 때까지 {quest:7801}을(를) 계속 제출하세요. {item:14047}: {zone:1423}의 {npc:8546}와(과) 어둠마법사(58-60레벨), 또는 경매장.",
		["Keep handing in {quest:7801}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7801}을(를) {item:14047} 20장씩 계속 제출하세요. {item:14047}: {zone:1423}의 {npc:8546}와(과) 어둠마법사(58-60레벨), 또는 경매장.",
		["Riverpaw Bandits and Taskmasters (level 16-18) drop it here. The Auction House works too."] = "{npc:452}와(과) 갈퀴발일족 전사(16-18레벨)이 이곳에서 떨어뜨립니다. 경매장도 이용할 수 있습니다.",
		["Syndicate Mercenaries at Stromgarde (level 31-32) drop it here. The Auction House works too."] = "스트롬가드의 비밀결사대 용병(31-32레벨)이 이곳에서 떨어뜨립니다. 경매장도 이용할 수 있습니다.",
		["{npc:14725} takes cloth for {faction:69} in {faction:69}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7801} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14725}은(는) {faction:69}을(를) 위해 {faction:69}에서 옷감을 받습니다. 양모, 비단, 마법 옷감, {item:14047}의 첫 기부(각 60장)는 한 번만 할 수 있으며 옷감당 평판이 가장 높습니다. 그 뒤에는 {quest:7801}을(를) 확고한 동맹까지 반복합니다. 다른 종족의 도시와 확고한 동맹이 되면 그 종족의 탈것을 살 수 있습니다. Forever의 외교관 유산 특전은 평판 획득량을 늘려 줍니다.",
		["{npc:14725}: {item:14047} delivered"] = "{npc:14725}: {item:14047} 기부 완료",
		["{quest:7801} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7801}은(는) 제출할 때마다 {item:14047} 20장을 받으며 원하는 만큼 반복할 수 있습니다. {item:14047}을(를) 20장 단위로 가져와 한 번에 연달아 모두 제출하세요. {item:14047}: {zone:1423}의 {npc:8546}와(과) 어둠마법사(58-60레벨), 또는 경매장.",
		["{quest:7801} to Exalted"] = "{quest:7801}: 확고한 동맹까지",
		["{quest:7801} to Honored"] = "{quest:7801}: 우호적까지",
